import{n as e}from"./rolldown-runtime-hePW80VL.js";var t=e({diyaloglar:()=>r,dosyalar:()=>n}),n=JSON.parse(`[{"ders":"global-otelcilik","sinif":9,"unite":1,"baslik":"Otelciliğin Evrensel Dili","onay":true,"kazanimlar":["Konuğun rezervasyondan ayrılış sonrasına uzanan yolculuğunun adımlarını ve her adımda otelin rolünü açıklar.","Doluluk, ortalama oda fiyatı ve RevPAR gibi dünyada ortak kullanılan temel otel ölçütlerini tanımlar.","Otelin odasını dünyaya hangi kanallarla sattığını ve gelir yönetiminin mantığını açıklar.","Uluslararası otel zincirlerinin, marka standartlarının ve dünyadaki derecelendirme sistemlerinin işleyişini açıklar.","Dünya otelciliğinde kullanılan unvanları ve sektörü yönlendiren uluslararası kuruluşları tanır."],"soz":"Dünyanın her otelinde aynı sayılar konuşulur; o dili bilen her yerde iş bulur.","dersler":[{"baslik":"Konuk Oteli Görmeden Tanır","ilk":"go-1-001"},{"baslik":"Kapıdan Girdikten Sonra","ilk":"go-1-005"},{"baslik":"Adını Hatırlayan Otel","ilk":"go-1-009"},{"baslik":"Yıldızlar Yorumdan Gelir","ilk":"go-1-012"},{"baslik":"Üç Sayı, Bir Otel","ilk":"go-1-015"},{"baslik":"Konuk Kaç Gece Kaldı?","ilk":"go-1-019"},{"baslik":"Rakiplerle Aynı Cetvel","ilk":"go-1-022"},{"baslik":"Oda Dünyaya Nasıl Satılır?","ilk":"go-1-025"},{"baslik":"Kontenjan, Anlaşma ve Komisyon","ilk":"go-1-029"},{"baslik":"Doğru Oda, Doğru Fiyat, Doğru An","ilk":"go-1-033"},{"baslik":"Fazla Rezervasyon Nasıl Yönetilir?","ilk":"go-1-036"},{"baslik":"Otelin Beyni: Yazılımlar","ilk":"go-1-038"},{"baslik":"Tabeladaki Ad Kimin?","ilk":"go-1-040"},{"baslik":"Adı Görünmeyen Marka","ilk":"go-1-044"},{"baslik":"Beş Yıldız Her Ülkede Aynı mı?","ilk":"go-1-046"},{"baslik":"Gizli Denetçi Geliyor","ilk":"go-1-048"},{"baslik":"Lüksten Ekonomiye","ilk":"go-1-051"},{"baslik":"Zirvedeki Masa","ilk":"go-1-056"},{"baslik":"Odadan Mutfağa Yöneticiler","ilk":"go-1-059"},{"baslik":"Altın Anahtarın Sırrı","ilk":"go-1-062"},{"baslik":"Otel Gece de Uyumaz","ilk":"go-1-065"},{"baslik":"Sektörü Yönlendirenler","ilk":"go-1-067"}],"kavramlar":[{"id":"go-1-001","konu":"1.1","terim":"Konuk yolculuğu","ingilizce":"Guest journey","tanim":"Bir kişinin oteli ilk duyduğu andan ayrıldıktan sonra yazdığı yoruma kadar otelle kurduğu bütün temasların sıralı bütünüdür.","ornek":"Ankara’da bir öğretmen şubatta telefonunda Kapadokya otellerine bakar, martta rezervasyon yapar, nisanda konaklar ve döndükten sonra yorum yazar; bu üç aylık akış tek bir konuk yolculuğudur.","sektor":"Dünya otelcilik okulları hizmeti bu yolculuk üzerinden öğretir: konuk otelin kapısından girmeden çok önce değerlendirmeye başlar ve çıktıktan sonra da sürdürür. Her adımı bilen çalışan, nerede iz bıraktığını da bilir.","iliskili":["go-1-002","go-1-005","go-1-008"],"kontrol":null,"kitapDisi":true},{"id":"go-1-002","konu":"1.1","terim":"İlham ve araştırma aşaması","ingilizce":"Inspiration and research stage","tanim":"Konuğun nereye gideceğini düşündüğü, otelleri karşılaştırdığı ve henüz karar vermediği yolculuk adımıdır.","ornek":"Akşam 22.00, İzmir’de bir aile kanepede oturmuş; biri Bodrum’daki otellerin fotoğraflarına, öteki yorumlarına bakıyor. Otel onlardan habersiz, ilk sınavını veriyor.","sektor":"Bu aşamada konukla konuşan çalışan değil, otelin fotoğrafları, internet sitesi ve eski konukların yorumlarıdır. Otel burada görünmezse öteki aşamalara hiç geçilmez.","iliskili":["go-1-001","go-1-003","go-1-012"],"kontrol":null,"kitapDisi":true,"gorsel":"g1-tatil-planlama"},{"id":"go-1-003","konu":"1.1","terim":"Rezervasyon aşaması","ingilizce":"Booking stage","tanim":"Konuğun seçimini yapıp tarih, oda tipi ve fiyatı belirleyerek otelle ilk anlaşmayı yaptığı yolculuk adımıdır.","ornek":"Öğlen 12.30, İstanbul’da bir şehir oteli: rezervasyon görevlisi telefonda “İki gece, deniz manzaralı, kahvaltı dâhil; onay numaranızı mesajla gönderiyorum” der.","sektor":"Burada verilen her bilgi varışta kontrol edilir: yanlış tarih ya da yanlış oda tipi check-in’de krize dönüşür. Dünya otelciliğinde rezervasyonun hangi kanaldan geldiği de kaydedilir; çünkü kanalın maliyeti farklıdır.","iliskili":["go-1-001","go-1-004","go-1-025"],"kontrol":null,"kitapDisi":true},{"id":"go-1-004","konu":"1.1","terim":"Varış öncesi iletişim","ingilizce":"Pre-arrival communication","tanim":"Rezervasyon ile varış arasındaki sürede otelin konuğa ulaşım bilgisi, giriş saati ve ek hizmet teklifi gibi mesajlar göndermesidir.","ornek":"Varıştan iki gün önce Antalya’daki resortun gönderdiği e-postada havalimanı transferi, giriş saati ve “Özel bir isteğiniz var mı?” sorusu yer alır; konuk çocuk yatağı ister.","sektor":"Konuğun beklentisi bu mesajlarla şekillenir ve özel istekler varıştan önce öğrenilir. Böylece otel hazırlıklı karşılar; konuk da kapıdan girerken kendini tanınmış hisseder.","iliskili":["go-1-003","go-1-005","go-1-009"],"kontrol":null,"kitapDisi":true},{"id":"go-1-005","konu":"1.1","terim":"Varış ve giriş aşaması","ingilizce":"Arrival and check-in stage","tanim":"Konuğun otele fiziksel olarak geldiği, karşılandığı ve odasına yerleştirildiği yolculuk adımıdır.","ornek":"Saat 15.00, lobi: kapı görevlisi bavulu alır, resepsiyonist konuğu adıyla karşılar, kimlik kontrolü iki dakikada biter ve oda kartı uzatılır.","sektor":"Dünya otelciliğinde ilk izlenimin kurulduğu an sayılır; uzun kuyruk ya da hazır olmayan oda bütün konaklamayı gölgeler. Birçok otel bu yüzden giriş işlemini kısaltmak için çevrim içi check-in sunar.","iliskili":["go-1-004","go-1-006","go-1-001"],"kontrol":null,"kitapDisi":true,"cizim":"resepsiyon"},{"id":"go-1-006","konu":"1.1","terim":"Konaklama aşaması","ingilizce":"Stay stage","tanim":"Konuğun odada kaldığı, otelin restoranını, havuzunu ve hizmetlerini kullandığı yolculuk adımıdır.","ornek":"İkinci gün sabah 08.00: konuk kahvaltıya iner, öğlen havuzda kalır, akşam resepsiyondan ütü ister; her biri otelin ayrı bir ekibini devreye sokar.","sektor":"En uzun aşamadır ve bütün departmanlar burada sınanır: temizlik, yemek, teknik servis, güvenlik. Konuğun yorumunda yazacağı cümlelerin çoğu bu günlerde oluşur.","iliskili":["go-1-005","go-1-007","go-1-021"],"kontrol":null,"kitapDisi":true},{"id":"go-1-007","konu":"1.1","terim":"Çıkış ve ayrılış aşaması","ingilizce":"Check-out and departure stage","tanim":"Konuğun hesabını kapatıp odayı teslim ettiği ve otelden uğurlandığı yolculuk adımıdır.","ornek":"Saat 11.30, resepsiyon: görevli ekstreyi konukla birlikte gözden geçirir, “Konaklamanız nasıldı?” diye sorar ve taksisi gelene kadar bavulların lobide bekletilmesini sağlar.","sektor":"Son temas çok hatırlanan temaslardan biridir: faturada açıklanamayan bir kalem ya da sıkıcı bir bekleme, güzel geçen üç günü unutturabilir. Dünyada iyi oteller uğurlamayı karşılama kadar ciddiye alır.","iliskili":["go-1-006","go-1-008","go-1-065"],"kontrol":null,"kitapDisi":true},{"id":"go-1-008","konu":"1.1","terim":"Ayrılış sonrası aşama","ingilizce":"Post-stay stage","tanim":"Konuk otelden çıktıktan sonra teşekkür mesajı, anket, yorum ve yeni teklif gibi temaslarla ilişkinin sürdürüldüğü yolculuk adımıdır.","ornek":"Konuk Bodrum’dan döndükten iki gün sonra otelden “Bizi tercih ettiğiniz için teşekkürler” e-postası ve kısa bir memnuniyet anketi alır.","sektor":"Yolculuk kapıda bitmez: bu aşamada konuk ya yorum yazarak yeni konuklar getirir ya da sessizce rakibe gider. Sadakat programları ve kişiye özel teklifler burada devreye girer.","iliskili":["go-1-007","go-1-010","go-1-012"],"kontrol":null,"kitapDisi":true},{"id":"go-1-009","konu":"1.1","terim":"Konuk profili","ingilizce":"Guest profile","tanim":"Otelin bir konuk hakkında tuttuğu, iletişim bilgisi, geçmiş konaklamalar ve tercihler gibi verilerin toplandığı kayıttır.","ornek":"Sabah 09.00, ön büro: görevli bugün gelecek konuğun profilini açar; “yüksek kat ister, tüy yastığa alerjisi var” notunu görür ve kat hizmetlerine iletir.","sektor":"Dünya otelciliğinde kişiye özel hizmetin temelidir: konuk tercihini her gelişinde yeniden söylemek zorunda kalmaz. Profil otelin yönetim sisteminde tutulur; kişisel veriler yasalara uygun biçimde korunur ve yalnız işi gereği olanlar görür.","iliskili":["go-1-004","go-1-010","go-1-039"],"kontrol":null,"kitapDisi":true,"cizim":"belge-form"},{"id":"go-1-010","konu":"1.1","terim":"Sadakat programı","ingilizce":"Loyalty programme","tanim":"Konuğun her konaklamasında puan ya da ayrıcalık kazandığı, onu aynı markaya yeniden gelmeye özendiren üyelik sistemidir.","ornek":"İstanbul’da sık seyahat eden bir mühendis, aynı zincirin otellerinde kaldıkça biriken puanlarla yaz tatilinde ailesine ücretsiz iki gece ayırtır.","sektor":"Büyük zincirlerin en güçlü silahıdır: üye konuk çoğu zaman aracıya değil otelin kendi sitesine gelir, bu da komisyon maliyetini düşürür. Çalışan için üye konuğu tanımak ve ayrıcalığını eksiksiz vermek standarttır.","iliskili":["go-1-009","go-1-011","go-1-026"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"go-1-011","konu":"1.1","terim":"Tekrar konuk","ingilizce":"Repeat guest","tanim":"Aynı otele ya da aynı markaya daha önce en az bir kez gelmiş olan ve yeniden konaklayan kişidir.","ornek":"Antalya’daki resorta beşinci yazında gelen aileyi resepsiyonist adıyla karşılar ve “Geçen yıl beğendiğiniz blokta bir oda ayırdık” der.","sektor":"Yeni konuk kazanmak reklam ve komisyon ister; tekrar konuk ise çoğu zaman kendiliğinden gelir ve otelin kurallarını zaten bilir. Dünya otelciliğinde tekrar konuk oranı bir otelin ne kadar sevildiğinin göstergesi sayılır.","iliskili":["go-1-010","go-1-009","go-1-021"],"kontrol":null,"kitapDisi":true},{"id":"go-1-012","konu":"1.1","terim":"Çevrim içi konuk yorumu","ingilizce":"Online guest review","tanim":"Konuğun konaklamadan sonra internetteki yorum sitelerinde ya da rezervasyon platformlarında yazdığı puan ve değerlendirmedir.","ornek":"Kapadokya’daki bir butik otelin sayfasında “Kahvaltı çok iyiydi ama sıcak su geç geldi” yazan yorumu bir hafta içinde yüzlerce kişi okur.","sektor":"Araştırma aşamasındaki konuk otelin kendi anlatımından çok başka konukların yazdığına inanır. Puanı yüksek otelin daha çok rezervasyon alma ve fiyatını yükseltme şansı artar; bu yüzden her çalışanın hizmeti bir sonraki yoruma yansır.","iliskili":["go-1-002","go-1-013","go-1-014"],"kontrol":null,"kitapDisi":true},{"id":"go-1-013","konu":"1.1","terim":"Çevrim içi itibar yönetimi","ingilizce":"Online reputation management","tanim":"Otelin internetteki yorumlarını ve puanlarını düzenli izleyip bunlara yanıt vermesi ve çıkan sorunları gidermesi işidir.","ornek":"Sabah 09.30, satış ofisi: görevli gece gelen yorumları okur, “oda soğuktu” diyen üç yorumu teknik müdüre iletir ve otel müdürüne haftalık puan raporunu sunar.","sektor":"Dünya otelciliğinde yorumlar artık ayrı bir ölçüt olarak izlenir; birçok otelde bu iş bir çalışanın görev tanımındadır. Tekrarlayan şikâyet bir kusur değil, düzeltilmesi gereken bir süreç olarak görülür.","iliskili":["go-1-012","go-1-014","go-1-021"],"kontrol":null,"kitapDisi":true},{"id":"go-1-014","konu":"1.1","terim":"Yoruma yanıt","ingilizce":"Management response","tanim":"Otel yönetiminin bir konuk yorumuna, herkesin okuyabileceği biçimde teşekkür ederek ya da özür dileyip çözümü anlatarak verdiği karşılıktır.","ornek":"Otel müdürü olumsuz yoruma “Sıcak su gecikmesi için özür dileriz; kazan arızası giderildi, sizi yeniden ağırlamak isteriz” diye yanıt yazar.","sektor":"Yanıtı yalnız yorumu yazan değil, oteli araştıran herkes okur. Sakin, kısa ve çözüm odaklı yanıt oteli savunmaktan çok daha etkilidir; tartışan ya da suçlayan yanıt ise ikinci bir kötü yorum gibi çalışır.","iliskili":["go-1-012","go-1-013"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"},{"id":"go-1-015","konu":"1.2","terim":"Gecelik doluluk oranı","ingilizce":"Occupancy rate","tanim":"Bir gecede satılan oda sayısının satılabilir toplam oda sayısına bölünmesiyle bulunan ve yüzdeyle söylenen ölçüttür.","ornek":"Sabah 07.00, İstanbul’da 100 odalı bir otel: gece raporunda 60 oda satılmış görünür; o gecenin doluluğu %60’tır.","sektor":"Dünyanın her otelinde sabah ilk bakılan sayıdır ve bütün departmanları etkiler: doluluk kat hizmetlerinin kaç oda temizleyeceğini, mutfağın kaç kahvaltı hazırlayacağını belirler. Tek başına yetmez; ucuza satılan dolu otel kazançlı olmayabilir.","iliskili":["go-1-016","go-1-017","go-1-036"],"kontrol":null,"kitapDisi":true},{"id":"go-1-016","konu":"1.2","terim":"Ortalama oda fiyatı (ADR)","ingilizce":"Average daily rate (ADR)","tanim":"Bir dönemde elde edilen oda gelirinin satılan oda sayısına bölünmesiyle bulunan, bir odanın ortalama kaça satıldığını gösteren ölçüttür.","ornek":"Bir gecede 60 oda satılmış ve oda geliri 120.000 lira olmuşsa ADR 2.000 liradır; bazı odalar daha pahalı, bazıları daha ucuz satılmış olabilir.","sektor":"Doluluğun ikizidir: biri kaç oda sattığını, öteki kaça sattığını söyler. Gelir müdürü fiyat kararlarını bu iki sayıyı birlikte izleyerek verir; ADR yükselirken doluluk düşüyorsa fiyat fazla gelmiş olabilir.","iliskili":["go-1-015","go-1-017","go-1-061"],"kontrol":null,"kitapDisi":true,"cizim":"oda"},{"id":"go-1-017","konu":"1.2","terim":"Oda başına gelir (RevPAR)","ingilizce":"Revenue per available room (RevPAR)","tanim":"Oda gelirinin satılabilir toplam oda sayısına bölünmesiyle, yani doluluk ile ortalama oda fiyatının çarpılmasıyla bulunan ölçüttür.","ornek":"100 odalı otelde %60 doluluk ve 2.000 lira ADR varsa RevPAR 1.200 liradır: boş kalan 40 oda da hesaba girer, çünkü onlar da satılabilirdi.","sektor":"Dünya otelciliğinin ortak dilidir; iki otel ya da iki yıl bu sayıyla karşılaştırılır. Doluluk ve fiyatı tek sayıya indirdiği için “ucuza dolu” ile “pahalı ama boş” otelin hangisinin daha iyi olduğunu gösterir.","iliskili":["go-1-015","go-1-016","go-1-024"],"kontrol":null,"kitapDisi":true},{"id":"go-1-018","konu":"1.2","terim":"Oda başına brüt işletme kârı (GOPPAR)","ingilizce":"Gross operating profit per available room (GOPPAR)","tanim":"Otelin bütün gelirlerinden işletme giderleri çıktıktan sonra kalan kârın satılabilir oda sayısına bölünmesiyle bulunan ölçüttür.","ornek":"İki otelin RevPAR’ı aynı olabilir; ama biri daha az personel ve enerji gideriyle çalışıyorsa GOPPAR’ı daha yüksektir ve sahibine daha çok kazandırır.","sektor":"RevPAR yalnız oda gelirine bakar; GOPPAR restoran ve spa gelirini de, işletme giderlerini de hesaba katar. Otel sahipleri ve yatırımcılar bu yüzden kârı gösteren GOPPAR’a bakar; öğrenci için yalnız ne olduğunu bilmek yeterlidir.","iliskili":["go-1-017","go-1-056"],"kontrol":null,"kitapDisi":true,"cizim":"oda"},{"id":"go-1-019","konu":"1.2","terim":"Ortalama konaklama süresi","ingilizce":"Average length of stay","tanim":"Satılan toplam gece sayısının rezervasyon sayısına bölünmesiyle bulunan, bir konuğun ortalama kaç gece kaldığını gösteren ölçüttür.","ornek":"İstanbul’da bir şehir oteline gelen iş insanı çoğu zaman bir ya da iki gece kalır; Antalya’daki resorta gelen aile ise bir hafta kalır. İki otelin ortalama süresi bu yüzden çok farklıdır.","sektor":"Uzun kalan konuk daha az giriş-çıkış işlemi ve daha az oda değişimi demektir; kat hizmetleri ve ön büro iş yükü buna göre planlanır. Gelir yönetimi de kısa konaklamaların doldurmadığı boşlukları bu sayıya bakarak görür.","iliskili":["go-1-015","go-1-035","go-1-006"],"kontrol":null,"kitapDisi":true},{"id":"go-1-020","konu":"1.2","terim":"Gelmeyen konuk oranı","ingilizce":"No-show rate","tanim":"Rezervasyon yaptırdığı hâlde iptal etmeden otele gelmeyen konukların bütün rezervasyonlara oranıdır.","ornek":"Gece 23.00, resepsiyon: bugün beklenen 80 konuktan 4’ü gelmemiş ve haber vermemiştir; gece görevlisi bunları sistemde “no-show” olarak kapatır.","sektor":"Gelmeyen konuk, satılabilecek odanın boş kalması demektir. Oteller bu oranı geçmiş verilerden izler; fazla rezervasyon kararı ve iptal kuralları buna göre belirlenir.","iliskili":["go-1-036","go-1-015","go-1-065"],"kontrol":null,"kitapDisi":true,"gorsel":"g1-rezerve-masa"},{"id":"go-1-021","konu":"1.2","terim":"Konuk memnuniyet puanı","ingilizce":"Guest satisfaction score","tanim":"Konukların anketlerde ve yorumlarda verdiği puanların toplanmasıyla elde edilen ve hizmet kalitesini sayıya çeviren ölçüttür.","ornek":"Pazartesi 10.00, haftalık toplantı: genel müdür “Bu hafta temizlik puanı yükseldi, kahvaltı puanı düştü” der ve mutfak şefi nedenini araştırır.","sektor":"Dünya zincirleri her otelini bu puanla izler ve yöneticilerin başarısını buna göre değerlendirir. Puan düştüğünde sayıya değil nedenine bakılır: hangi departman, hangi saat, hangi konuk tipi.","iliskili":["go-1-013","go-1-022","go-1-006"],"kontrol":null,"kitapDisi":true,"cizim":"kalite-yildiz"},{"id":"go-1-022","konu":"1.2","terim":"Net tavsiye puanı (NPS)","ingilizce":"Net promoter score (NPS)","tanim":"Konuğa “Bu oteli bir yakınınıza tavsiye eder misiniz?” sorusunu 0’dan 10’a kadar bir ölçekle sorup 9 ve 10 verenlerin oranından 0 ile 6 arası verenlerin oranını çıkararak bulunan ölçüttür.","ornek":"Çıkış sonrası ankette konuk “tavsiye eder misiniz” sorusuna 9 vermiştir; o konuk otel için “tavsiye eden” sayılır.","sektor":"Memnun olmak ile başkasına anlatacak kadar memnun olmak aynı şey değildir; NPS ikincisini ölçer. Birçok sektörde aynı soru kullanıldığı için otel kendini başka işletmelerle de karşılaştırabilir.","iliskili":["go-1-021","go-1-011","go-1-008"],"kontrol":null,"kitapDisi":true,"cizim":"otel-bina"},{"id":"go-1-023","konu":"1.2","terim":"Rakip set","ingilizce":"Competitive set","tanim":"Bir otelin kendini karşılaştırmak için seçtiği, benzer konum, büyüklük ve sınıftaki birkaç otelden oluşan gruptur.","ornek":"Taksim’deki beş yıldızlı bir şehir oteli rakip setine yine Taksim ve çevresindeki beş yıldızlı beş oteli alır; Antalya’daki resortu almaz, çünkü aynı konuk için yarışmazlar.","sektor":"Doluluğun %70 olması tek başına iyi mi kötü mü, ancak rakiplere bakınca anlaşılır. Rakip set yanlış seçilirse karşılaştırma da yanlış çıkar; bu yüzden set gelir müdürü tarafından özenle kurulur.","iliskili":["go-1-024","go-1-017","go-1-061"],"kontrol":null,"kitapDisi":true},{"id":"go-1-024","konu":"1.2","terim":"STR kıyaslaması","ingilizce":"STR benchmarking","tanim":"Otellerin doluluk, ADR ve RevPAR verilerini bir kıyaslama şirketine gönderip karşılığında rakip setinin ortalamasıyla kendi sonuçlarını karşılaştırdığı rapor sistemidir.","ornek":"Her sabah İstanbul’daki otelin gelir müdürü raporu açar: “Dün gece rakiplerimizin doluluğu bizden yüksek, ama fiyatımız daha iyi” der ve haftanın fiyatını buna göre ayarlar.","sektor":"Dünya otelciliğinde ortak dil STR raporlarıyla kurulur: her otel kendi verisini verir, karşılığında rakiplerin adsız ortalamasını görür. Raporda endeksler 100 üzerinden okunur (örn. RevPAR endeksi, RGI); 100 “pazardan adil payını alıyorsun” demektir; üstü rakipten iyi, altı rakipten kötü anlamına gelir.","iliskili":["go-1-023","go-1-017","go-1-015"],"kontrol":null,"kitapDisi":true},{"id":"go-1-025","konu":"1.3","terim":"Dağıtım kanalı","ingilizce":"Distribution channel","tanim":"Otelin odasını konuğa ulaştırdığı ve rezervasyonun geldiği her bir satış yoludur.","ornek":"Aynı gün aynı otele bir konuk otelin sitesinden, bir konuk rezervasyon platformundan, bir grup da tur operatörü aracılığıyla gelir; üçü üç ayrı kanaldır.","sektor":"Her kanalın maliyeti ve getirdiği konuk tipi farklıdır. Otel hangi kanaldan ne kadar sattığını bilmezse hangi odayı kaça sattığını da bilemez; kanal karması gelir yönetiminin ilk konusudur.","iliskili":["go-1-026","go-1-027","go-1-031"],"kontrol":null,"kitapDisi":true,"cizim":"acente"},{"id":"go-1-026","konu":"1.3","terim":"Doğrudan rezervasyon","ingilizce":"Direct booking","tanim":"Konuğun aracı kullanmadan otelin kendi internet sitesi, telefonu ya da e-postası üzerinden yaptığı rezervasyondur.","ornek":"Bodrum’daki otel kendi sitesinden rezervasyon yapana ücretsiz kahvaltı ya da geç çıkış sunar; konuk aynı odayı platformdan değil otelden alır.","sektor":"Komisyon ödenmediği için genellikle otelin en kârlı kanalıdır ve konuğun bilgisi doğrudan otele gelir. Dünya otelciliğinde “doğrudan rezervasyonu artırmak” her otelin hedefleri arasındadır; sadakat programları bunun için vardır.","iliskili":["go-1-025","go-1-027","go-1-010"],"kontrol":null,"kitapDisi":true},{"id":"go-1-027","konu":"1.3","terim":"Çevrim içi seyahat acentesi (OTA)","ingilizce":"Online travel agency (OTA)","tanim":"Binlerce otelin odasını tek bir internet sitesinde listeleyen ve her satıştan komisyon alan aracı platformdur.","ornek":"Hafta sonu için Eskişehir’de otel arayan bir öğrenci, bir rezervasyon platformunda on oteli yan yana karşılaştırır ve birini seçer; otel rezervasyonu alır, platform da komisyonunu keser.","sektor":"Oteli dünyanın her yerinden görünür kılar; küçük otel için vazgeçilmezdir. Karşılığı komisyondur ve konuk çoğu zaman oteli değil platformu hatırlar. Otel bu yüzden platformdan gelen konuğu bir sonraki sefer doğrudan gelmeye ikna etmeye çalışır.","iliskili":["go-1-026","go-1-031","go-1-032"],"kontrol":null,"kitapDisi":true},{"id":"go-1-028","konu":"1.3","terim":"Küresel dağıtım sistemi (GDS)","ingilizce":"Global distribution system (GDS)","tanim":"Seyahat acentelerinin ve kurumsal seyahat ofislerinin uçak, otel ve araç kiralamayı tek ekrandan aradığı ve rezerve ettiği dünya çapındaki bilgisayar ağıdır.","ornek":"Londra’daki bir seyahat acentesi, müşterisinin İstanbul toplantısı için uçak biletiyle birlikte otel odasını aynı sistemden dakikalar içinde ayırtır.","sektor":"Kurumsal iş seyahatinin önemli bir bölümü bu yoldan yapılır; otel GDS’te görünmezse kurumsal konuk onu bulamaz. Amadeus, Sabre ve Travelport bu ağın bilinen örnekleridir; otel bunlara bağlanmak için ayrı bir ücret öder.","iliskili":["go-1-025","go-1-030","go-1-038"],"kontrol":null,"kitapDisi":true,"cizim":"doga"},{"id":"go-1-029","konu":"1.3","terim":"Tur operatörü kontenjanı","ingilizce":"Tour operator allotment","tanim":"Otelin sezon başında belirli sayıda odayı belli bir fiyatla bir tur operatörüne ayırması ve operatörün bu odaları kendi paket turlarında satmasıdır.","ornek":"Antalya’daki resort, mayıs–ekim arasında her gün 80 odayı bir Avrupalı tur operatörüne ayırır; operatör bu odaları uçak ve transferle birlikte paket olarak satar.","sektor":"Türkiye’nin kıyı resortlarında çok kullanılan bir kanaldır: sezonu önceden garantiye almaya yarar. Karşılığı düşük fiyattır ve satılmayan odalar belirli bir tarihe kadar iade edilir; bu tarihe “release” denir ve ön büro onu yakından izler.","iliskili":["go-1-025","go-1-030","go-1-031"],"kontrol":null,"kitapDisi":true},{"id":"go-1-030","konu":"1.3","terim":"Kurumsal anlaşma","ingilizce":"Corporate rate agreement","tanim":"Bir şirketin çalışanlarının yıl boyunca aynı otelde önceden belirlenmiş özel bir fiyatla kalması için otel ile şirket arasında yapılan sözleşmedir.","ornek":"İstanbul’daki bir şehir oteli, yakınındaki bankanın merkeziyle anlaşır: bankanın çalışanları her gelişte aynı indirimli fiyatla konaklar, otel de hafta içi dolu kalır.","sektor":"Şehir otellerinin hafta içi dolulukta güvencesidir; iş konuğu düzenli gelir, az sorun çıkarır ve genellikle restoranı da kullanır. Satış müdürü bu anlaşmaları her yıl yeniler ve şirketin gerçekten söz verdiği kadar gece kalıp kalmadığına bakar.","iliskili":["go-1-025","go-1-028","go-1-029"],"kontrol":null,"kitapDisi":true},{"id":"go-1-031","konu":"1.3","terim":"Kanal komisyonu","ingilizce":"Channel commission","tanim":"Otelin bir aracı kanaldan gelen her satış için o aracıya ödediği, çoğu zaman oda fiyatının yüzdesi olarak belirlenen bedeldir.","ornek":"Konuk platformdan 2.000 liraya oda alır; otel bunun bir bölümünü platforma komisyon olarak öder, kalan kısmı otelde kalır. Aynı konuk otelin sitesinden gelseydi tamamı otelde kalırdı.","sektor":"Dünya otelciliğinde kanal tartışmasının özü komisyondur: aracı oteli görünür kılar ama gelirin bir parçasını alır. Hangi kanalın hangi komisyonu aldığını bilmek gelir müdürünün ve ön büronun ortak sorumluluğudur.","iliskili":["go-1-027","go-1-026","go-1-025"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"go-1-032","konu":"1.3","terim":"Oran paritesi","ingilizce":"Rate parity","tanim":"Aynı odanın aynı tarih ve koşullar için bütün satış kanallarında aynı fiyatla görünmesi ilkesidir.","ornek":"Konuk Kapadokya’daki otelin odasını platformda 3.000, otelin sitesinde 3.400 lira görürse otelin kendi sitesinden alması için bir neden kalmaz; parite bozulmuştur.","sektor":"Platformlar bazı sözleşmelerinde bunu şart koşmuştur, kimi ülkelerde ise bu tür şartlar yasayla sınırlandırılmıştır; otel ise kendi sitesini kahvaltı ya da geç çıkış gibi fiyat dışı avantajlarla öne çıkarır. Parite bozulduğunda konuk güveni ve kanal ilişkisi birlikte zarar görür.","iliskili":["go-1-027","go-1-026","go-1-038"],"kontrol":null,"kitapDisi":true,"cizim":"grafik"},{"id":"go-1-033","konu":"1.3","terim":"Gelir yönetimi","ingilizce":"Revenue management","tanim":"Doğru odayı doğru konuğa doğru zamanda doğru fiyatla ve doğru kanaldan satarak otelin toplam gelirini en yükseğe çıkarma disiplinidir.","ornek":"Gelir müdürü nisandaki fuar haftasını görür, o günler için fiyatı yükseltir ve en ucuz tarifeyi kapatır; sakin geçen şubat haftasında ise erken rezervasyon indirimi açar.","sektor":"Havayollarından otelciliğe geçen bu düşünce dünyada birçok büyük otelde ayrı bir görev ve departman hâline geldi. Mantığı basittir: oda bozulabilen bir üründür; bu gece satılmayan oda yarın satılamaz.","iliskili":["go-1-034","go-1-035","go-1-061"],"kontrol":null,"kitapDisi":true,"gorsel":"g1-dizustu-istatistik"},{"id":"go-1-034","konu":"1.3","terim":"Dinamik fiyatlama","ingilizce":"Dynamic pricing","tanim":"Oda fiyatının talep, tarih, doluluk ve rakiplerin fiyatına göre sürekli değiştirilmesidir.","ornek":"Aynı deniz manzaralı oda İstanbul’da sakin bir salı gecesi 2.500 lira, büyük bir konserin olduğu cumartesi gecesi 4.500 liradır; odanın kendisi değişmemiştir, talep değişmiştir.","sektor":"Sabit fiyat listesi birçok otelde yerini talebe göre değişen fiyata bıraktı. Konuk “Dün daha ucuzdu” diyebilir; görevli bunun bir hata değil, talebe göre değişen fiyat olduğunu sakin ve dürüst biçimde açıklar.","iliskili":["go-1-033","go-1-016","go-1-038"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"go-1-035","konu":"1.3","terim":"Minimum konaklama şartı","ingilizce":"Minimum length of stay","tanim":"Yoğun tarihlerde otelin tek geceyle gelen rezervasyonu kabul etmeyip belirli bir gece sayısının altındaki talebi kapatmasıdır.","ornek":"Bayram haftasında Bodrum’daki otel “en az üç gece” şartı koyar; böylece tek geceliğine gelip araya boşluk bırakacak rezervasyonlar yerine haftayı dolduran konuklar alınır.","sektor":"Gelir yönetiminin fiyat dışındaki araçlarından biridir; buna benzer kısıtlarla belirli günlerde giriş ya da çıkış da kapatılabilir. Şart fazla sıkı olursa oda boş kalır; bu yüzden geçmiş yılların verisine bakılarak konur.","iliskili":["go-1-033","go-1-019","go-1-038"],"kontrol":null,"kitapDisi":true,"cizim":"otel-bina"},{"id":"go-1-036","konu":"1.3","terim":"Gelir yönetiminde fazla rezervasyon","ingilizce":"Overbooking","tanim":"İptal olacağını ve konukların gelmeyeceğini hesaplayan otelin, sahip olduğundan biraz daha fazla oda için bilerek rezervasyon almasıdır.","ornek":"100 odalı otel, geçmişte her gece birkaç konuğun gelmediğini bildiği için fuar haftasında 104 oda satar; akşam dört iptal gelince otel tam dolu kapanır.","sektor":"Dünya otelciliğinde yaygın ve bilinçli bir risk yönetimidir; amaç geliri boş odaya kaptırmamaktır. Hesap tutmazsa konuk kapıda kalır; bu yüzden kaç fazla satılacağı geçmiş verilerle ve iptal kurallarına bakılarak belirlenir.","iliskili":["go-1-020","go-1-037","go-1-015"],"kontrol":null,"kitapDisi":true,"cizim":"resepsiyon"},{"id":"go-1-037","konu":"1.3","terim":"Konuğu başka otele yerleştirme","ingilizce":"Walking a guest","tanim":"Otelin fazla rezervasyon yüzünden oda veremediği onaylı konuğu, masrafı kendisine ait olmak üzere benzer ya da daha iyi bir otele yerleştirmesidir.","ornek":"Gece 22.00, resepsiyon: son gelen konuğa oda kalmamıştır; nöbetçi müdür yakındaki eşdeğer otelde oda ayırtır, taksiyi öder, özür diler ve ertesi gece için konuğu geri davet eder.","sektor":"Fazla rezervasyonun bedelidir ve genellikle konaklama ile ulaşım otel tarafından karşılanır. Hangi konuğun gönderileceğine yönetim karar verir: sadık ya da tekrar konuk mümkünse hiç gönderilmez. İşlem dürüst, hızlı ve özürle yapılırsa konuk bazen otele daha bağlı döner.","iliskili":["go-1-036","go-1-066","go-1-011"],"kontrol":null,"kitapDisi":true},{"id":"go-1-038","konu":"1.3","terim":"Kanal yöneticisi","ingilizce":"Channel manager","tanim":"Otelin oda sayısını ve fiyatlarını bütün satış kanallarına tek seferde gönderen ve bir kanalda satılan odayı öteki kanallardan anında düşen yazılımdır.","ornek":"Saat 14.00: platformdan son deniz manzaralı oda satılır; kanal yöneticisi saniyeler içinde bu odayı otelin sitesinden ve öteki platformlardan kaldırır, aynı oda iki kez satılmaz.","sektor":"Kanal sayısı arttıkça elle güncelleme imkânsızlaştı; bu yazılım olmadan çifte satış ve parite hataları kaçınılmazdır. Küçük bir otelde bile fiyat ve müsait oda sayısı buradan girilir.","iliskili":["go-1-039","go-1-032","go-1-025"],"kontrol":null,"kitapDisi":true},{"id":"go-1-039","konu":"1.3","terim":"Otel yönetim sistemi (PMS)","ingilizce":"Property management system (PMS)","tanim":"Rezervasyon, giriş-çıkış, oda durumu, konuk hesabı ve konuk profillerinin tutulduğu, otelin bütün departmanlarının birlikte kullandığı ana yazılımdır.","ornek":"Sabah 10.00: kat görevlisi 305’i temizleyip sistemde “hazır” işaretler; resepsiyonist aynı anda ekranında odanın yeşile döndüğünü görür ve bekleyen konuğu odasına gönderir.","sektor":"Dünyanın hangi otelinde çalışırsan çalış, ilk öğreneceğin şey oradaki PMS’tir; markası değişse de mantığı aynıdır. Gece raporu, doluluk ve ADR gibi bütün ölçütler bu sistemden çıkar.","iliskili":["go-1-038","go-1-009","go-1-065"],"kontrol":null,"kitapDisi":true},{"id":"go-1-040","konu":"1.4","terim":"Uluslararası otel zinciri","ingilizce":"International hotel chain","tanim":"Aynı marka adı, aynı standartlar ve ortak rezervasyon sistemi altında çalışan çok sayıda otelden oluşan işletme grubudur.","ornek":"İstanbul’da bir uluslararası zincir otelinde kalan konuk, aynı markanın Dubai’deki otelinde de benzer bir oda, aynı sadakat programı ve tanıdık bir karşılama bulur.","sektor":"Zincirin gücü tanınırlık ve güvendir: konuk yabancı bir şehirde bildiği markayı seçer. Çalışan için ise dünyanın her yerinde geçerli bir eğitim ve kariyer yolu demektir; birçok zincir içinde ülkeler arası görev değişimi vardır.","iliskili":["go-1-041","go-1-042","go-1-045"],"kontrol":null,"kitapDisi":true},{"id":"go-1-041","konu":"1.4","terim":"Bağımsız otel","ingilizce":"Independent hotel","tanim":"Hiçbir zincire ya da markaya bağlı olmadan, sahibinin kendi adı ve kendi kurallarıyla işlettiği oteldir.","ornek":"Kapadokya’da bir aile, kayadan oyma odalarıyla kendi adını taşıyan bir otel işletir; menüden karşılamaya her şeye kendileri karar verir.","sektor":"Özgürlük ve kişilik bağımsız otelin gücüdür; zayıf yanı ise dünya çapında tanınırlığı ve rezervasyon ağı olmamasıdır. Bu yüzden bağımsız oteller görünür olmak için çoğu zaman platformlara daha çok ihtiyaç duyar.","iliskili":["go-1-040","go-1-044","go-1-054"],"kontrol":null,"kitapDisi":true},{"id":"go-1-042","konu":"1.4","terim":"Franchise","ingilizce":"Franchise","tanim":"Otel sahibinin ücret karşılığında bir zincirin marka adını, standartlarını ve rezervasyon sistemini kullanıp oteli kendisinin işlettiği modeldir.","ornek":"Ankaralı bir yatırımcı yeni yaptırdığı otele uluslararası bir markanın adını alır; personeli kendisi çalıştırır, ama tabeladan oda düzenine kadar markanın kitabına uyar.","sektor":"Dünya zincirlerinin büyümesinin başlıca yollarından biridir: marka bina yapmadan büyür, sahip ise tanınmış bir ad ve konuk ağı kazanır. Sahip, marka standardına uymazsa sözleşmesini kaybedebilir; bu yüzden denetimler sıkıdır.","iliskili":["go-1-040","go-1-043","go-1-045"],"kontrol":null,"kitapDisi":true,"cizim":"girisim-isletme"},{"id":"go-1-043","konu":"1.4","terim":"Yönetim sözleşmesi","ingilizce":"Management contract","tanim":"Otelin binasının sahibinde kaldığı, işletmesinin ise ücret karşılığında bir zincir ya da yönetim şirketi tarafından yürütüldüğü modeldir.","ornek":"İstanbul’da bir holding otel binasını yaptırır; genel müdürü ve işletme kurallarını uluslararası zincir getirir, zincir yönetim ücreti alır, bina holdingin kalır.","sektor":"Franchise’dan farkı budur: franchise’da oteli sahibi işletir, yönetim sözleşmesinde zincir işletir. Çalışanlar genellikle zincirin eğitim sisteminden geçer; genel müdür markanın temsilcisidir ve sahibe karşı sorumludur.","iliskili":["go-1-042","go-1-040","go-1-056"],"kontrol":null,"kitapDisi":true},{"id":"go-1-044","konu":"1.4","terim":"Yumuşak marka","ingilizce":"Soft brand","tanim":"Bağımsız bir otelin kendi adını ve kişiliğini koruyarak büyük bir zincirin rezervasyon ağına ve sadakat programına katıldığı koleksiyon türü markadır.","ornek":"Bodrum’da kendi adıyla tanınan bir otel, bir dünya zincirinin koleksiyonuna katılır: tabelada otelin adı kalır, sitesinde küçük bir koleksiyon işareti belirir, zincirin üyeleri puanla gelebilir.","sektor":"Bu model, zincire “standart bir kutu” istemeyen konuğu, bağımsız otele ise dünya çapında dağıtım gücünü kazandırır. Autograph Collection ve Curio Collection gibi koleksiyonlar bu modelin bilinen örnekleridir; otel standartların bir kısmına uyar, tasarım özgürlüğünü korur.","iliskili":["go-1-041","go-1-040","go-1-054"],"kontrol":null,"kitapDisi":true},{"id":"go-1-045","konu":"1.4","terim":"Marka standardı","ingilizce":"Brand standard","tanim":"Bir zincirin bütün otellerinde aynı olmasını istediği, odadaki yastık sayısından telefona kaçıncı çalışta cevap verileceğine kadar yazılı olarak belirlenmiş kurallardır.","ornek":"Zincirin denetçisi İzmir’deki otele habersiz gelir; kahvaltının açılış saatini, yatak örtüsünün katlanışını ve karşılama cümlesini listedeki maddelerle tek tek karşılaştırır.","sektor":"Konuğun dünyanın her yerinde aynı deneyimi bulmasını sağlayan şey budur; marka vaadi standarda dayanır. Çalışan için standart ezber değil güvencedir: ne yapacağını bilir ve denetimde kendini savunabilir.","iliskili":["go-1-040","go-1-042","go-1-048"],"kontrol":null,"kitapDisi":true},{"id":"go-1-046","konu":"1.4","terim":"Ülkeye göre yıldız sınıflandırması","ingilizce":"Star classification","tanim":"Otelin odası, tesisleri ve hizmetleri belirli ölçütlere göre değerlendirilerek genellikle bir ile beş yıldız arasında bir dereceyle gösterilmesidir.","ornek":"Antalya’daki bir otelin kapısındaki beş yıldız, Türkiye’de Kültür ve Turizm Bakanlığının belirlediği ölçütlere göre verilmiştir; başka bir ülkede aynı yıldızı başka bir kurum, başka ölçütlerle verir.","sektor":"Dünya çapında tek bir yıldız sistemi yoktur: kimi ülkede devlet, kimi ülkede otelciler birliği verir, kimi ülkede ise resmî sistem hiç yoktur. Bu yüzden iki ülkenin beş yıldızı aynı anlama gelmeyebilir; konuğa bunu bilerek bilgi verilir.","iliskili":["go-1-047","go-1-048","go-1-049"],"kontrol":null,"kitapDisi":true},{"id":"go-1-047","konu":"1.4","terim":"Hotelstars Union","ingilizce":"Hotelstars Union","tanim":"Birçok Avrupa ülkesinin otelciler birliklerinin aynı ölçüt listesiyle yıldız vermek için kurduğu ortak sınıflandırma sistemidir.","ornek":"Almanya’da üç yıldızlı bir otelde kalan konuk, Avusturya’da aynı sisteme bağlı üç yıldızlı bir otelde benzer bir donanım bulacağını bilir.","sektor":"Katılan birlikler çoğunlukla Avrupa’nın otelcilik çatı kuruluşu HOTREC’in de üyesidir; amaç, sınırlar arasında karşılaştırılabilir yıldız vermektir.","iliskili":["go-1-046","go-1-070","go-1-048"],"kontrol":null,"kitapDisi":true,"gorsel":"g1-hotelstars-plaketi"},{"id":"go-1-048","konu":"1.4","terim":"Forbes Travel Guide","ingilizce":"Forbes Travel Guide","tanim":"Gizli denetçilerinin otel, restoran ve spaları konuk gibi kullanıp ölçütlere göre puanladığı ve beş yıldız, dört yıldız ya da “tavsiye edilen” derece verdiği uluslararası değerlendirme kuruluşudur.","ornek":"İstanbul’daki bir lüks otelin personeli, lobideki herhangi bir konuğun bir denetçi olabileceğini bilir; bu yüzden karşılama cümlesi ve konuğa adıyla hitap her gün aynı özenle yapılır.","sektor":"Dünya lüks otelciliğinin bilinen derecelerinden biridir ve farkı hizmete büyük ağırlık vermesidir: yalnız mermer lobi değil, çalışanın davranışı da puan getirir. Eskiden Mobil Travel Guide adını taşıyordu; derecesini alan otel bunu kapısında ve sitesinde gururla gösterir.","iliskili":["go-1-049","go-1-050","go-1-051"],"kontrol":null,"kitapDisi":true},{"id":"go-1-049","konu":"1.4","terim":"AAA Diamond derecesi","ingilizce":"AAA Diamond designation","tanim":"Kuzey Amerika’daki otomobil kulübü AAA’nın, denetçilerinin yerinde yaptığı değerlendirmelerle otel ve restoranlara verdiği, bir ile beş elmas arasındaki derecedir.","ornek":"Amerika Birleşik Devletleri’nden gelen bir konuk İstanbul’daki resepsiyoniste “Burası kaç elmas?” diye sorar; görevli bu derecenin esas olarak Kuzey Amerika’daki işletmelere verildiğini nazikçe açıklar.","sektor":"Amerika Birleşik Devletleri’nde devletin verdiği yıldız sistemi yoktur; bu boşluğu AAA elmasları ve Forbes yıldızları gibi özel kuruluşların dereceleri doldurur. Öğrenci için yalnız ne olduğunu bilmek yeterlidir: Amerikalı konuk “elmas” dediğinde ne kastettiğini anlamak.","iliskili":["go-1-048","go-1-046","go-1-050"],"kontrol":null,"kitapDisi":true,"cizim":"kalite-yildiz"},{"id":"go-1-050","konu":"1.4","terim":"Michelin Rehberi","ingilizce":"Michelin Guide","tanim":"Lastik üreticisi Michelin’in yayımladığı, kimliğini gizleyen denetçilerin restoranlara bir, iki ya da üç yıldız verdiği dünyaca tanınan yeme içme rehberidir.","ornek":"İstanbul’da bir otel restoranının Michelin yıldızı aldığı duyulunca akşam rezervasyonları haftalar öncesinden dolar; otelin adı da restoranla birlikte anılır.","sektor":"Yıldızlar otele değil restorana verilir; denetçi hesabını kendi öder ve kimse onu tanımaz. Rehber son yıllarda otellere de ayrı bir “anahtar” derecesi vermeye başladı. Otelin yiyecek içecek ekibi için yıldız, dünya ölçeğinde bir itibar demektir.","iliskili":["go-1-048","go-1-060","go-1-049"],"kontrol":null,"kitapDisi":true},{"id":"go-1-051","konu":"1.4","terim":"Lüks segment","ingilizce":"Luxury segment","tanim":"En yüksek fiyat düzeyinde, kişiye özel hizmet, geniş odalar, concierge ve seçkin restoranlarla çalışan otel sınıfıdır.","ornek":"Boğaz kıyısındaki tarihî bir sarayda konaklayan konuğu kapıda adıyla karşılayan bir görevli, odasına kadar eşlik eden bir butler ve tek telefonla her şeyi ayarlayan bir concierge bekler.","sektor":"Dünya otelciliği otelleri fiyat ve hizmet düzeyine göre segmentlere ayırır; lüks en üsttedir. Burada iş yalnız güzel bina değil, konuğun söylemeden önce isteğini anlamaktır; oda başına en çok personel bu segmentte çalışır ve standartlar burada en ayrıntılı yazılır.","iliskili":["go-1-052","go-1-053","go-1-048"],"kontrol":null,"kitapDisi":true,"gorsel":"luks-otel"},{"id":"go-1-052","konu":"1.4","terim":"Orta segment","ingilizce":"Midscale segment","tanim":"Makul fiyatla rahat oda, kahvaltı ve temel hizmetleri sunan, lüks ile ekonomi arasında yer alan otel sınıfıdır.","ornek":"Konya’ya iş için gelen bir satış temsilcisi, şehir merkezinde kahvaltısı ve otoparkı olan üç yıldızlı bir zincir otelinde kalır; concierge aramaz, temiz oda ve hızlı internet ister.","sektor":"Dünyada çok sayıda otel bu segmentte yer alır; STR gibi kıyaslama şirketleri bu aralığı “orta” ve “üst-orta” diye daha da böler. Burada başarı, az personelle tutarlı ve hatasız hizmettir.","iliskili":["go-1-051","go-1-053","go-1-024"],"kontrol":null,"kitapDisi":true,"cizim":"kalite-yildiz"},{"id":"go-1-053","konu":"1.4","terim":"Ekonomi segmenti","ingilizce":"Economy segment","tanim":"Düşük fiyatla temiz ve güvenli bir oda sunan, restoran ya da oda servisi gibi ek hizmetleri en aza indiren otel sınıfıdır.","ornek":"Otoyol kenarındaki bir ekonomi otelinde gece geç gelen sürücü, kendi kendine giriş yapan bir kiosktan oda kartını alır; lobide tek görevli vardır.","sektor":"Ucuz demek kalitesiz demek değildir: ekonomi zincirleri temizlik ve güvenlikte ödün vermez. Fark, hizmetin sayısındadır; az personelle çok oda çevirmek bu segmentin ustalığıdır.","iliskili":["go-1-052","go-1-051","go-1-046"],"kontrol":null,"kitapDisi":true,"gorsel":"g1-yol-kenari-motel"},{"id":"go-1-054","konu":"1.4","terim":"Butik otel segmenti","ingilizce":"Boutique hotel","tanim":"Az odalı, her odası ve ortak alanı özgün biçimde tasarlanmış, bulunduğu yerin karakterini yansıtan küçük oteldir.","ornek":"Alaçatı’da taş bir evden dönüştürülmüş on iki odalı bir otelde sahibi konukları kendisi karşılar, kahvaltı bahçedeki tek uzun masada yenir.","sektor":"Zincirlerin aynılığından sıkılan konuğun aradığı şeydir; gücü kişilik ve samimiyettir. Türkiye’de Kapadokya, Alaçatı ve Bodrum butik otelleriyle bilinir; küçük ekipte her çalışan birkaç iş birden yapar.","iliskili":["go-1-055","go-1-041","go-1-044"],"kontrol":null,"kitapDisi":true,"gorsel":"sektor-butik-otel-odasi"},{"id":"go-1-055","konu":"1.4","terim":"Yaşam tarzı oteli","ingilizce":"Lifestyle hotel","tanim":"Tasarımı, müziği, yemeği ve sosyal alanlarıyla belirli bir yaşam biçimine seslenen, çoğu zaman bir zincire bağlı olan modern otel türüdür.","ornek":"İstanbul’da bir yaşam tarzı otelinin lobisi akşamları mahalleden gelen gençlerle dolar; resepsiyon bankosu yerine kahve barı vardır, görevli de konukla aynı rahat üslupla konuşur.","sektor":"Butik otelin özgünlüğünü zincir gücüyle birleştirme denemesidir; büyük zincirlerin çoğunun böyle bir markası vardır. Çalışandan beklenen resmî mesafe değil, markanın tarzına uygun doğal bir samimiyettir; standart yine vardır, ama görünmezdir.","iliskili":["go-1-054","go-1-040","go-1-044"],"kontrol":null,"kitapDisi":true,"gorsel":"f3b-yasam-tarzi-otel-lobisi"},{"id":"go-1-056","konu":"1.5","terim":"Genel müdür","ingilizce":"General manager","tanim":"Otelin bütün departmanlarından, gelirinden, konuk memnuniyetinden ve çalışanlarından sorumlu olan en üst yöneticidir.","ornek":"Sabah 09.00, toplantı odası: genel müdür departman müdürleriyle dünkü doluluğu, bugünkü girişleri ve gece gelen bir şikâyeti on beş dakikada gözden geçirir, sonra lobiye inip konuklarla selamlaşır.","sektor":"Dünya otelciliğinde “GM” kısaltmasıyla anılır; otel sahibine ya da zincire karşı sonuçtan o sorumludur. Birçok genel müdür kariyerine ön büro ya da yiyecek içecekte stajyer olarak başlamıştır; bu meslekte zirve mutfaktan ve bankodan geçer.","iliskili":["go-1-057","go-1-043","go-1-018"],"kontrol":null,"kitapDisi":true,"cizim":"lider"},{"id":"go-1-057","konu":"1.5","terim":"Odalar bölümü müdürü","ingilizce":"Rooms division manager","tanim":"Ön büro, kat hizmetleri ve çoğu otelde concierge ile rezervasyonu tek çatı altında yöneten, odayla ilgili her işten sorumlu yöneticidir.","ornek":"Saat 13.00: ön büro “yüz giriş var, odalar yetişmiyor” der; odalar bölümü müdürü kat hizmetleriyle konuşup temizlik sırasını girişlere göre değiştirir, iki ekip tek plana bağlanır.","sektor":"Oda satmak ile odayı hazırlamak birbirine bağlı işlerdir; bu unvan ön büro ile kat hizmetlerini tek yöneticiye bağlayarak ikisinin uyumlu çalışmasını sağlar. Genel müdürlüğe giden yollardan biri olarak görülür.","iliskili":["go-1-056","go-1-058","go-1-059"],"kontrol":null,"kitapDisi":true},{"id":"go-1-058","konu":"1.5","terim":"Ön büro yöneticisi (FOM)","ingilizce":"Front office manager (FOM)","tanim":"Resepsiyon, santral ve bellboy ekiplerini ve çoğu otelde rezervasyonu da yöneten; giriş, çıkış ve konuk hesaplarının doğru yürümesinden sorumlu yöneticidir.","ornek":"Saat 15.30: lobide kuyruk uzayınca ön büro müdürü ofisinden çıkıp bankoya geçer, ikinci bilgisayarı açar ve ekibine “Önce bekleyen çocuklu aileleri alalım” der.","sektor":"Sektörde kısaca “FOM” diye anılır; konuğun ilk ve son karşılaştığı ekibin başıdır. Vardiya planı, doluluk tahmini ve fazla rezervasyon günündeki kararlar bu masadan çıkar.","iliskili":["go-1-057","go-1-065","go-1-066"],"kontrol":null,"kitapDisi":true},{"id":"go-1-059","konu":"1.5","terim":"Kat hizmetleri yöneticisi (Executive housekeeper)","ingilizce":"Executive housekeeper","tanim":"Odaların, koridorların ve genel alanların temizliğinden, çamaşırhaneden ve kat ekibinin planlanmasından sorumlu yöneticidir.","ornek":"Sabah 08.00, kat ofisi: kat hizmetleri yöneticisi günün çıkışlarını ve girişlerini görür, otuz oda görevlisine katları dağıtır ve “VIP geliyor, 710’u kendim kontrol edeceğim” der.","sektor":"Dünya otelciliğinde “Executive housekeeper” diye anılır; temizlik puanı konuk memnuniyetinin ilk maddelerinden biri olduğu için önemli bir masadır. Çoğu otelde en kalabalık ekiplerden birini yönetir ve otelin en değerli varlığını, odayı korur.","iliskili":["go-1-057","go-1-021","go-1-060"],"kontrol":null,"kitapDisi":true},{"id":"go-1-060","konu":"1.5","terim":"Yiyecek ve içecek müdürü","ingilizce":"Food and beverage manager","tanim":"Otelin restoranlarını, barlarını, oda servisini ve ziyafet hizmetlerini yöneten, mutfak ile servis ekiplerini tek hedefte buluşturan yöneticidir.","ornek":"Cumartesi 17.00: üç yüz kişilik düğün için yiyecek içecek müdürü mutfak şefi ve servis şefiyle son kez toplanır; menü sırası, servis saati ve masa planı dakikasına kadar belirlenir.","sektor":"Dünyada “F&B Manager” diye anılır; çoğu tam hizmet veren otelde oda gelirinden sonra gelen büyük gelir kalemi onun sorumluluğundadır. Otel restoranının başarısında şefle birlikte bu müdürün de payı vardır.","iliskili":["go-1-056","go-1-050","go-1-059"],"kontrol":null,"kitapDisi":true,"cizim":"icecek-bar"},{"id":"go-1-061","konu":"1.5","terim":"Gelir müdürü","ingilizce":"Revenue manager","tanim":"Talep tahmini yapıp oda fiyatlarını, kanal dağılımını ve kısıtları belirleyerek otelin oda gelirini en yükseğe çıkarmakla görevli yöneticidir.","ornek":"Her sabah 09.00: gelir müdürü kıyaslama raporunu, gelecek doksan günün rezervasyonlarını ve rakip fiyatlarını inceler; iki hafta sonraki fuar için fiyatı yükseltir, boş kalan salı için kampanya açar.","sektor":"Havayollarından gelen yöntemlerle çalışan, görece yeni bir otelci unvanıdır; birçok büyük otelde ya da zincirin merkezinde bulunur. Sayılarla ve tablolarla uğraşmayı seven öğrenci için açık bir kariyer kapısıdır.","iliskili":["go-1-033","go-1-016","go-1-024"],"kontrol":null,"kitapDisi":true},{"id":"go-1-062","konu":"1.5","terim":"Lüks otel concierge’i","ingilizce":"Hotel concierge","tanim":"Lobide ayrı bir masada oturan, konuğun otel dışındaki her isteğini, yani restoran rezervasyonu, bilet, ulaşım ve şehir önerilerini çözen uzman görevlidir.","ornek":"Saat 18.00, lobi: konuk “Bu akşam Boğaz’da yemek istiyorum, yer bulamadım” der; concierge iki telefonla masa bulur, tekneyi ayarlar ve konuğa hangi kapıdan çıkacağını anlatır.","sektor":"Dünya lüks otelciliğinin simgesi unvandır; “imkânsız” kelimesini kullanmaz, şehri ayrıntılı tanır. Gücü ilişki ağıdır: restoranlar, şoförler, biletçiler onu adıyla tanır.","iliskili":["go-1-063","go-1-064","go-1-051"],"kontrol":null,"kitapDisi":true,"gorsel":"f3c-concierge-masa"},{"id":"go-1-063","konu":"1.5","terim":"Les Clefs d’Or","ingilizce":"Les Clefs d'Or","tanim":"Fransa’da doğan ve dünyaya yayılan, üyelerinin yakasında çapraz iki altın anahtar taşıdığı uluslararası otel concierge’leri birliğidir.","ornek":"İstanbul’daki bir otelin concierge’i yakasındaki altın anahtarları gösterir ve stajyere “Bunu takmak için yıllarca lobide çalışmak ve sınavdan geçmek gerekir” der.","sektor":"Adı Fransızca “altın anahtarlar” demektir; sloganı “arkadaşlık yoluyla hizmet”tir. Üyeler dünyanın başka şehirlerindeki üyelerle birbirinin konuğuna yardım eder; altın anahtar konuğa “bu kişi işini bilir” mesajı verir.","iliskili":["go-1-062","go-1-064"],"kontrol":null,"kitapDisi":true},{"id":"go-1-064","konu":"1.5","terim":"Konuk ilişkileri görevlisi (GRO)","ingilizce":"Guest relations officer (GRO)","tanim":"Lobide konuğu karşılayan, VIP ve tekrar konuklarla özel olarak ilgilenen, şikâyetleri dinleyip çözüme ulaştıran ekip ve bu ekibin görevlisidir.","ornek":"Saat 16.00, lobi: konuk ilişkileri görevlisi bugün gelen tekrar konuğu adıyla karşılar, odasına meyve tabağı gönderildiğini kontrol eder ve ikinci gün “Her şey yolunda mı?” diye arar.","sektor":"Resepsiyon işlemi yapar, konuk ilişkileri ilişkiyi kurar; ikisi aynı şey değildir. Dünya otelciliğinde bu görevli (GRO) çoğu zaman birkaç dil bilir ve memnuniyet puanının yüzü sayılır.","iliskili":["go-1-062","go-1-011","go-1-021"],"kontrol":null,"kitapDisi":true},{"id":"go-1-065","konu":"1.5","terim":"Gece denetçisi","ingilizce":"Night auditor","tanim":"Resepsiyon görevini gece vardiyasında sürdürürken günün bütün hesaplarını kontrol eden, hataları düzelten ve günü sistemde kapatıp sabah raporlarını hazırlayan görevlidir.","ornek":"Gece 02.00, resepsiyon: gece denetçisi restoran ve oda ücretlerinin doğru odalara işlendiğini kontrol eder, gelmeyen konukları kapatır ve “günü kapat” işlemiyle doluluk raporunu üretir.","sektor":"Dünya otelciliğinde sabah herkesin baktığı doluluk ve ADR sayıları gece denetçisinin işinden çıkar; onun hatası sabah müdürün masasına yanlış rakam olarak gelir. Gece tek başına karar verebilen, dikkatli ve dürüst kişiler için biçilmiş bir unvandır.","iliskili":["go-1-039","go-1-020","go-1-058"],"kontrol":null,"kitapDisi":true},{"id":"go-1-066","konu":"1.5","terim":"Nöbetçi müdür","ingilizce":"Duty manager","tanim":"Genel müdürün ve departman müdürlerinin otelde olmadığı saatlerde, özellikle akşam ve gece, yönetim adına karar verme yetkisini taşıyan görevlidir.","ornek":"Gece 23.30: bir konuk odasında su baskını olduğunu bildirir; nöbetçi müdür konuğu hemen başka bir odaya taşıtır, teknik servisi çağırır ve sabah genel müdüre yazılı rapor bırakır.","sektor":"Dünyada “Manager on Duty” ya da “MOD” kısaltmasıyla da anılır; otel yirmi dört saat açıktır ama müdürler değildir. Yetkisi vardır; otelin kurallarına göre özür için ücret düzeltebilir, konuğu başka otele yerleştirebilir; stajyer gece sorun yaşadığında ilk ona gider.","iliskili":["go-1-037","go-1-058","go-1-056"],"kontrol":null,"kitapDisi":true},{"id":"go-1-067","konu":"1.5","terim":"UN Tourism (BM turizm kuruluşu)","ingilizce":"UN Tourism","tanim":"Birleşmiş Milletlerin turizmden sorumlu uzman kuruluşu olan, ülkelerin turizm politikalarına yön veren ve dünya turizm istatistiklerini toplayan merkezi Madrid’deki örgüttür.","ornek":"Türkiye Kültür ve Turizm Bakanlığı, yıllık ziyaretçi verilerini bu örgütün belirlediği ortak tanımlarla hesaplar; böylece Türkiye’nin sayıları İspanya’nın sayılarıyla karşılaştırılabilir.","sektor":"Eski adı Dünya Turizm Örgütü (UNWTO) idi; “turist” ve “ziyaretçi” gibi temel tanımların dünyada aynı anlaşılmasını bu kuruluşun sözlüğü sağlar. Sürdürülebilir turizm ve turizm etiği konularında da ülkeleri yönlendirir.","iliskili":["go-1-068","go-1-070"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-unwto-merkezi"},{"id":"go-1-068","konu":"1.5","terim":"WTTC","ingilizce":"World Travel & Tourism Council (WTTC)","tanim":"Dünyanın büyük otel, hava yolu, kruvaziyer ve seyahat şirketlerinin üst yöneticilerini bir araya getiren, turizmin ekonomiye katkısını ölçüp hükûmetlere anlatan özel sektör kuruluşudur.","ornek":"Büyük bir otel zincirinin başkanı, WTTC’nin yıllık zirvesinde turizmin kaç kişiye iş sağladığını anlatan raporu hükûmet temsilcilerine sunar.","sektor":"UN Tourism devletleri temsil eder, WTTC ise şirketleri; ikisi birlikte sektörün dünya ölçeğindeki sesidir. Yayımladığı ekonomik etki raporları sektörün büyüklüğünü anlatmak için en çok başvurulan kaynaklardandır.","iliskili":["go-1-067","go-1-069"],"kontrol":null,"kitapDisi":true,"cizim":"bavul"},{"id":"go-1-069","konu":"1.5","terim":"AHLA ve AHLEI","ingilizce":"American Hotel & Lodging Association and its Educational Institute","tanim":"Amerika Birleşik Devletleri otelcilerinin meslek birliğine (AHLA) ve onun otelcilik eğitimi, ders kitabı ve mesleki sertifika veren eğitim koluna (AHLEI) verilen addır.","ornek":"Antalya’daki bir otelin ön büro müdürü, AHLEI’nin uzaktan eğitim programıyla aldığı sertifikayı özgeçmişine ekler; sertifika birçok ülkede tanınır.","sektor":"Türk öğrenci için önemi eğitimdir: dünyanın birçok otelcilik okulu AHLEI’nin ders kitaplarını kullanır ve sertifikaları kariyerde basamak sayılır. Birlik ayrıca Amerika’daki otellerin sesi olarak yasa yapıcılarla konuşur.","iliskili":["go-1-068","go-1-070"],"kontrol":null,"kitapDisi":true,"cizim":"otel-bina"},{"id":"go-1-070","konu":"1.5","terim":"HOTREC","ingilizce":"HOTREC","tanim":"Avrupa ülkelerinin otel, restoran ve kafe birliklerini bir araya getiren ve sektörü Avrupa Birliği kurumları karşısında temsil eden çatı kuruluştur.","ornek":"Avrupa Birliği çevrim içi rezervasyon platformlarıyla ilgili yeni bir kural hazırlarken HOTREC, Avrupa otellerinin görüşünü Brüksel’de tek ağızdan dile getirir.","sektor":"Hotelstars Union’a katılan birlikler çoğunlukla bu çatının da üyesidir. Avrupa, Türkiye’ye gelen turistlerin başlıca kaynak bölgelerinden biri olduğu için orada alınan kararlar Türk otellerini de dolaylı etkiler.","iliskili":["go-1-047","go-1-067","go-1-069"],"kontrol":null,"kitapDisi":true,"cizim":"otel-bina"}],"sorular":[{"id":"go-1-s01","tur":"coktan-secmeli","soru":"Bir aile akşam kanepede Bodrum’daki otellerin fotoğraflarına ve konuk yorumlarına bakıyor; henüz tarih ya da oda seçmedi. Otel konuk yolculuğunun hangi aşamasındadır?","secenekler":["Rezervasyon aşaması","İlham ve araştırma aşaması","Varış öncesi iletişim","Konaklama aşaması"],"dogru":1,"aciklama":"Konuk henüz karar vermediği için otel adına yalnız fotoğraflar, site ve yorumlar konuşur. Rezervasyon aşaması ise konuk tarih, oda tipi ve fiyatı belirleyip otelle anlaşınca başlar."},{"id":"go-1-s02","tur":"coktan-secmeli","soru":"Antalya’daki bir resort, varıştan iki gün önce konuğa “Özel bir isteğiniz var mı?” diye soruyor. Bu mesajın otel için asıl yararı nedir?","secenekler":["Konuğun fiyat konusunda pazarlık yapmasını önlemek","Konuğun rezervasyonunu yeniden onaylamasını sağlamak","Konuğa çıkış sonrası yorum yazma hatırlatması yapmak","Özel istekleri konuk gelmeden öğrenip hazırlıklı karşılamak"],"dogru":3,"aciklama":"Varış öncesi iletişimde (örneğin çocuk yatağı isteği) özel istekler önceden öğrenilir; konuk da kapıdan girerken tanınmış hisseder. Yorum hatırlatması ise ayrılış sonrası aşamanın işidir."},{"id":"go-1-s03","tur":"coktan-secmeli","soru":"Bir otel sadakat programı kuruyor. Programın otele sağladığı başlıca yarar hangisidir?","secenekler":["Üye konuk otelin kendi sitesinden rezervasyon yapar, komisyon maliyeti düşer.","Aynı oda bütün kanallarda aynı fiyatla görünür, parite bozulmaz.","Otel, rakip setinin ortalama doluluğunu her sabah görebilir.","Seyahat acenteleri odayı tek ekrandan ayırtabilir."],"dogru":0,"aciklama":"Sadakat programı konuğu aynı markaya yeniden gelmeye özendirir; üye konuk çoğu zaman aracıya değil otele gelir. Parite, STR kıyaslaması ve GDS başka işlevlerdir."},{"id":"go-1-s04","tur":"dogru-yanlis","soru":"Olumsuz bir yoruma verilecek en etkili karşılık otelin haklı olduğunu açıkça savunan ve konuğun hatasını gösteren yanıttır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanıtı yalnız yorumu yazan değil, oteli araştıran herkes okur. Sakin, kısa ve çözüm odaklı yanıt etkilidir; savunan ya da suçlayan yanıt ikinci bir kötü yorum gibi çalışır."},{"id":"go-1-s05","tur":"coktan-secmeli","soru":"120 odalı bir otelde bir gece 90 oda satılmış, oda geliri 180.000 lira olmuştur. Doluluk oranı ve ADR sırasıyla nedir?","secenekler":["%75 ve 1.500 lira","%90 ve 2.000 lira","%75 ve 2.000 lira","%90 ve 1.500 lira"],"dogru":2,"aciklama":"Doluluk 90 / 120 = %75’tir. ADR, geliri satılan odalara böler: 180.000 / 90 = 2.000 lira. 1.500 lira, geliri satılabilir odalara bölmekten çıkar; o RevPAR’dır."},{"id":"go-1-s06","tur":"coktan-secmeli","soru":"Aşağıdaki ölçüt tanımlarından hangisi yanlıştır?","secenekler":["Doluluk oranı, satılan oda sayısının satılabilir oda sayısına bölünmesiyle bulunur.","ADR, oda gelirinin satılan oda sayısına bölünmesiyle bulunur.","RevPAR, oda gelirinin satılabilir oda sayısına bölünmesiyle bulunur.","Ortalama konaklama süresi, satılan gece sayısının toplam oda sayısına bölünmesiyle bulunur."],"dogru":3,"aciklama":"Ortalama konaklama süresi satılan toplam gece sayısını rezervasyon sayısına böler; toplam oda sayısı bu hesapta kullanılmaz. Öteki üç tanım doğrudur."},{"id":"go-1-s07","tur":"coktan-secmeli","soru":"A oteli 100 odalı, doluluğu %90, ADR’si 1.000 liradır. B oteli de 100 odalı, doluluğu %50, ADR’si 2.400 liradır. RevPAR’a göre hangisi daha iyi iş yapmıştır?","secenekler":["A; doluluğu yüksek olduğu için RevPAR’ı da yüksektir.","B; RevPAR’ı 1.200 lira, A’nınki 900 liradır.","İkisi eşit; çünkü ikisinin de oda sayısı aynıdır.","B; ADR’si yüksek olduğu için doluluğa bakmak gerekmez."],"dogru":1,"aciklama":"RevPAR doluluk ile ADR’nin çarpımıdır: A için 0,90 x 1.000 = 900, B için 0,50 x 2.400 = 1.200. Doluluk tek başına fiyatı göstermez; ADR de tek başına boş odayı göstermez."},{"id":"go-1-s08","tur":"coktan-secmeli","soru":"İki otelin RevPAR’ı aynıdır, ama biri sahibine daha çok kazandırmaktadır. Farkı hangi ölçüt gösterir?","secenekler":["GOPPAR","Doluluk oranı","Ortalama konaklama süresi","Gelmeyen konuk oranı"],"dogru":0,"aciklama":"RevPAR yalnız oda gelirine bakar; GOPPAR bütün gelirlerden işletme giderleri çıktıktan sonra kalan kârı oda başına gösterir. Doluluk ise gider hakkında bilgi vermez."},{"id":"go-1-s09","tur":"dogru-yanlis","soru":"Taksim’deki beş yıldızlı bir şehir oteli rakip setini kurarken konum, büyüklük ve sınıfa bakar; bu yüzden Antalya’daki bir resortu setine almaz.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Rakip set, aynı konuk için yarışan benzer otellerden kurulur; yanlış set kurulursa karşılaştırma da yanlış çıkar."},{"id":"go-1-s10","tur":"coktan-secmeli","soru":"Gelir müdürü STR raporunda otelin RevPAR endeksinin (RGI) 112 olduğunu görüyor. Bu sonuç ne anlama gelir?","secenekler":["Otelin o gece 112 odası satılmıştır.","Otel pazardan adil payını tam olarak almıştır.","Otel pazardan adil payından fazlasını almıştır, rakiplerinin üstündedir.","Otel rakiplerinin gerisinde kalmış, adil payından azını almıştır."],"dogru":2,"aciklama":"Raporda RevPAR endeksi (RGI) 100 “adil pay” demektir; üstü rakip setinin ortalamasından iyi, altı kötü anlamına gelir. 112 endeks adil paydan fazladır."},{"id":"go-1-s11","tur":"coktan-secmeli","soru":"Aynı fiyatla satılan bir odada otelin elinde genellikle en çok para kalan kanal hangisidir?","secenekler":["Rezervasyon platformundan gelen rezervasyon","Küresel dağıtım sistemi üzerinden acentenin yaptığı rezervasyon","Tur operatörünün kontenjanından gelen rezervasyon","Konuğun otelin kendi sitesinden yaptığı rezervasyon"],"dogru":3,"aciklama":"Doğrudan rezervasyonda aracı yoktur, komisyon ödenmez ve gelirin tamamı otelde kalır. Platform ve GDS komisyon, kontenjan ise çoğunlukla düşük fiyat ister."},{"id":"go-1-s12","tur":"coktan-secmeli","soru":"Londra’daki bir seyahat acentesi, müşterisi için uçak biletiyle birlikte İstanbul’daki otel odasını aynı ekrandan ayırtıyor. Otel odası hangi kanaldan satılmıştır?","secenekler":["Küresel dağıtım sistemi (GDS)","Çevrim içi seyahat acentesi (OTA)","Doğrudan rezervasyon","Tur operatörü kontenjanı"],"dogru":0,"aciklama":"GDS, acentelerin uçak, otel ve araç kiralamayı tek ekrandan rezerve ettiği dünya çapındaki ağdır. OTA ise tüketicinin kendi eliyle otel karşılaştırıp rezervasyon yaptığı platformdur."},{"id":"go-1-s13","tur":"coktan-secmeli","soru":"Konuk aynı tarih ve aynı koşullar için aynı odayı platformda 3.000, otelin kendi sitesinde 3.400 lira görüyor. Bu durumda hangi ilke bozulmuştur?","secenekler":["Minimum konaklama şartı","Oran paritesi","Marka standardı","Fazla rezervasyon"],"dogru":1,"aciklama":"Oran paritesi, aynı odanın aynı koşullarda bütün kanallarda aynı fiyatla görünmesidir. Bozulduğunda konuk otelin sitesinden almak için neden bulamaz ve kanal ilişkisi zarar görür."},{"id":"go-1-s14","tur":"coktan-secmeli","soru":"İstanbul’daki bir otelde aynı oda sakin bir salı gecesi 2.500 liraya, büyük bir konserin olduğu cumartesi gecesi 4.500 liraya satılıyor. Fiyat farkının nedeni nedir?","secenekler":["Odanın daha büyük ya da daha iyi donatılmış olması","Kanal komisyonunun cumartesi günü artması","Odanın değil, o geceki talebin değişmesi","Oran paritesi gereği fiyatın her hafta sonu artması"],"dogru":2,"aciklama":"Dinamik fiyatlamada oda fiyatı talebe, tarihe ve doluluğa göre değişir; oda aynı kalır. Komisyon ve parite fiyatı tarihe göre değiştirmez."},{"id":"go-1-s15","tur":"dogru-yanlis","soru":"Bir otelin sahip olduğundan fazla oda için rezervasyon alması rezervasyon görevlisinin yanlış saymasından doğan bir hatadır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Fazla rezervasyon, geçmişteki iptal ve gelmeyen konuk verilerine bakılarak bilerek alınan hesaplı bir risktir. Hesap tutmazsa konuk kapıda kalır; bu yüzden fazla satılacak oda sayısı dikkatle belirlenir."},{"id":"go-1-s16","tur":"coktan-secmeli","soru":"Bir otel hem kendi sitesinde hem üç platformda satış yapıyor ve fiyat ile müsait oda sayısını her kanalda elle güncelliyor. Çifte satışı ve fiyat hatalarını hangi araç önler?","secenekler":["Otel yönetim sistemi (PMS)","Küresel dağıtım sistemi (GDS)","Sadakat programı","Kanal yöneticisi"],"dogru":3,"aciklama":"Kanal yöneticisi oda sayısını ve fiyatı bütün kanallara tek seferde gönderir, satılan odayı hepsinden düşer. PMS otelin iç kayıtlarını tutar ama kanalları güncellemez."},{"id":"go-1-s17","tur":"coktan-secmeli","soru":"Ankaralı bir yatırımcı yeni otelini uluslararası bir markanın adı ve rezervasyon sistemiyle açıyor; ücret öder, personeli kendisi çalıştırır, markanın standart kitabına uyar. Bu hangi modeldir?","secenekler":["Yönetim sözleşmesi","Franchise","Bağımsız otel","Yumuşak marka"],"dogru":1,"aciklama":"Franchise’da sahip markanın adını ve sistemini ücret karşılığı kullanır, oteli kendisi işletir. Yönetim sözleşmesinde işletmeyi zincir yürütür; bağımsız otel ise hiçbir markaya bağlı değildir."},{"id":"go-1-s18","tur":"coktan-secmeli","soru":"Franchise ve yönetim sözleşmesiyle ilgili aşağıdakilerden hangisi yanlıştır?","secenekler":["Yönetim sözleşmesinde otelin binası zincire geçer.","Franchise’da oteli sahibi işletir.","Yönetim sözleşmesinde işletmeyi zincir yürütür ve ücret alır.","Franchise’da sahip markanın standartlarına uymak zorundadır."],"dogru":0,"aciklama":"İki modelde de bina sahipte kalır; fark işletmeyi kimin yürüttüğüdür. Yönetim sözleşmesinde zincir işletir, binanın sahibi değişmez."},{"id":"go-1-s19","tur":"coktan-secmeli","soru":"Bodrum’da kendi adıyla tanınan bir otel, tabelada adını koruyarak bir dünya zincirinin koleksiyonuna katılıyor ve zincirin sadakat üyeleri puanla gelebiliyor. Bu hangi modeldir?","secenekler":["Franchise","Yönetim sözleşmesi","Yumuşak marka","Bağımsız otel"],"dogru":2,"aciklama":"Yumuşak markada otel kendi adını ve kişiliğini korur, zincirin dağıtım ağına ve sadakat programına katılır. Franchise’da ise otel zincirin marka adını ve standartlarını taşır."},{"id":"go-1-s20","tur":"coktan-secmeli","soru":"Bir lüks otelin çalışanları, lobideki her konuğun gizli bir denetçi olabileceğini bilir. Çalışanın davranışına en büyük ağırlığı veren derece hangisidir?","secenekler":["Hotelstars Union","Michelin Rehberi","Bakanlığın verdiği yıldız","Forbes Travel Guide"],"dogru":3,"aciklama":"Forbes Travel Guide’ın gizli denetçileri konuk gibi kalır ve yalnız binaya değil hizmete, yani çalışanın davranışına büyük ağırlık verir. Michelin ise restoranlara yıldız verir."},{"id":"go-1-s21","tur":"dogru-yanlis","soru":"Bir otelin restoranı Michelin yıldızı alırsa yıldız otele değil, o restorana verilmiş olur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Michelin Rehberi restoranlara bir, iki ya da üç yıldız verir; otelin adı restoranla birlikte anılır ama yıldız restorana aittir."},{"id":"go-1-s22","tur":"coktan-secmeli","soru":"Saat 13.00’te ön büro “yüz giriş var, odalar yetişmiyor” diyor. Ön büro ile kat hizmetlerini tek plana bağlayıp temizlik sırasını girişlere göre değiştirecek yönetici hangisidir?","secenekler":["Ön büro yöneticisi (FOM)","Odalar bölümü müdürü","Gelir müdürü","Yiyecek ve içecek müdürü"],"dogru":1,"aciklama":"Odalar bölümü müdürü ön büro ile kat hizmetlerini birlikte yönetir. FOM yalnız ön büro ekibinin başındadır, kat ekibine plan veremez."},{"id":"go-1-s23","tur":"senaryo","durum":"Gece 23.00, resepsiyonda stajyersin ve gece denetçisiyle birliktesin. Onaylı rezervasyonu olan bir konuk geliyor; ama fazla rezervasyon yüzünden otelde boş oda kalmamış. Konuk yorgun ve gergin.","soru":"Ne yaparsın?","secenekler":["Durumu açıklayıp odalardan biri çıkabilir diye konuğu lobide beklemeye davet ederim.","Yakındaki otelleri listeleyip konuğun kendi aramasını, masrafı sonra getirmesini söylerim.","Durumu açıklayıp nöbetçi müdürü çağırırım; müdürün eşdeğer bir otelde oda ayırtmasını isterim.","Ertesi gece için indirim önerip bu gece başka çare bulmasını rica ederim."],"dogru":2,"aciklama":"Konuğu başka otele yerleştirme kararı yönetimindir; nöbetçi müdür bu yetkiye sahiptir ve masraf otele aittir. Konuğu bekletmek, masrafı ona yüklemek ya da işi geçiştirmek güveni kaybettirir."},{"id":"go-1-s24","tur":"senaryo","durum":"Sabah 10.00, satış ofisinde staj yapıyorsun. Gece gelen yorumlar arasında “Oda soğuktu, kalorifer çalışmadı, kimse ilgilenmedi” diyen puanı düşük bir yorum var. Yorum herkese açık ve otel müdürü henüz görmedi.","soru":"İlk adımın ne olur?","secenekler":["Yorumu amirime iletir, kalorifer sorununun teknik servise bildirilmesini isterim.","Yorumu görmezden gelir, tek yorum ortalamayı pek değiştirmez diye düşünürüm.","Yoruma kendi adıma “Özür dileriz, hemen çözeceğiz” diye herkese açık yanıt yazarım.","Konuğa platformdan ulaşıp yorumunu silmesini rica ederim."],"dogru":0,"aciklama":"Çevrim içi itibar yönetiminde yorum önce sorunun kaynağına iletilir, sonra yönetim sakin bir yanıt yazar. Yorumu sildirmeye çalışmak güveni zedeler; görmezden gelmek tekrarlayan sorunu gizler; yanıt vermek stajyerin yetkisi değildir."},{"id":"go-1-s25","tur":"senaryo","durum":"Saat 16.00, resepsiyondasın. Bir konuk kızgın: “Dün aynı odayı sitede 2.500 lira gördüm, bugün 4.000 lira; beni kandırıyorsunuz.” Bugün şehirde büyük bir konser var ve fiyat dinamik olarak yükseltilmiş.","soru":"Konuğa nasıl karşılık verirsin?","secenekler":["Konuğu yatıştırmak için fiyatta bir hata olduğunu söylerim.","Fiyatları gelir müdürü belirlediği için konuyu ona havale edip bankoya dönerim.","Konuğu kaybetmemek için fiyatı kendi başıma dünkü düzeye indiririm.","Fiyatın talebe göre değiştiğini sakince anlatır, başka tarih seçeneklerini gösteririm."],"dogru":3,"aciklama":"Dinamik fiyatlama bir hata değil, talebe göre değişen fiyattır; bunu dürüstçe açıklamak güven verir. Hata var demek yalan olur, fiyatı kendi başına değiştirmek yetkiyi aşar, konuyu havale etmek konuğu çözümsüz bırakır."},{"id":"go-1-s26","tur":"senaryo","durum":"Sabah 09.00, ön büroda staj yapıyorsun. Bugün gelecek bir tekrar konuğun profilinde “yüksek kat ister, tüy yastığa alerjisi var” notunu görüyorsun. Oda henüz atanmamış.","soru":"Ne yaparsın?","secenekler":["Notu saklarım; konuk gelince tercihlerini yeniden sorarım.","Notu ön büro görevlisine gösterir, yüksek kat ve yastık değişimini isterim.","Konuk gelince alerjisini lobide yüksek sesle doğrulatırım.","Notu kendi dosyama alır, standart odanın atanmasını beklerim."],"dogru":1,"aciklama":"Konuk profili, konuğun tercihini her gelişinde yeniden söylemek zorunda kalmaması ve hazırlıklı karşılanması için tutulur. Notu kullanmamak amacı boşa çıkarır; sağlık bilgisi lobide yüksek sesle konuşulmaz."},{"id":"go-1-s27","tur":"senaryo","durum":"Saat 14.30, lobideki concierge masasında stajyersin. Bir konuk bu akşam için Boğaz’da ünlü bir restoranda masa istiyor; restoran dolu olduğunu söylüyor. Concierge o sırada başka bir konukla ilgileniyor.","soru":"Ne yaparsın?","secenekler":["Benzer birkaç seçenek araştırır, konuğa sunar, concierge’e de bilgi veririm.","Restoran dolu olduğu için konuğa başka seçenek sunmadan özür dilerim.","Restoranı tekrar arayıp otelin adını öne sürerek masa için ısrar ederim.","Restoranın telefon numarasını konuğa verip kendisinin denemesini söylerim."],"dogru":0,"aciklama":"Concierge hizmetinin özü seçenek üretmektir; deneyimli concierge’in ilişki ağı da devreye girer. Konuğu çözümsüz bırakmak ya da işi ona devretmek hizmet sayılmaz; ısrar otelin itibarını zedeler."},{"id":"go-1-s28","tur":"senaryo","durum":"Gece 01.30, gece denetçisinin yanında staj yapıyorsun. Günü kapatmadan önce restoranın 600 liralık hesabının 412 yerine 421 numaralı odaya işlendiğini fark ediyorsun. 421’deki konuk sabah erken çıkış yapacak.","soru":"Ne yaparsın?","secenekler":["Tutar küçük olduğu için dokunmam, sabah kimse fark etmez diye düşünürüm.","Hesabı kendi başıma 412 numaralı odaya taşırım, kimseye söylemem.","421’deki konuğu arayıp restoran hesabını ödemesini rica ederim.","Gece denetçisine gösterir, kayıtla düzeltilmesini isterim."],"dogru":3,"aciklama":"Gece denetçisinin işi hataları günü kapatmadan bulup kayıtla düzeltmektir. Hatayı gizlemek konuğa yanlış fatura çıkarır; kayıtsız düzeltme yetkiyi aşar; konuğa yanlış hesabı ödetmeye çalışmak kabul edilemez."},{"id":"go-1-s29","tur":"senaryo","durum":"Saat 11.00, Antalya’daki resortta ön büroda stajyersin. Tur operatörü kontenjanından gelen bir grup, operatörün broşüründe “deniz manzaralı oda” yazdığını söylüyor; sistemde ise kontenjan odaları bahçe manzaralı görünüyor.","soru":"Ne yaparsın?","secenekler":["Konuklara “Operatör broşüre yanlış yazmış, bizim suçumuz değil” derim.","Konuklardan özür diler, durumun kontrol edilmesi için ön büro müdürüne iletirim.","Konuklara boş deniz manzaralı odaları verir, kimseye haber vermem.","Konuklara operatörün acil hattını arayıp sorunu kendilerinin çözmesini söylerim."],"dogru":1,"aciklama":"Kontenjan odaları otel ile operatör arasındaki sözleşmeyle belirlenir; stajyer bu anlaşmayı bilmeden oda vermez ya da suçlu ilan etmez. Doğru yol konuğu dinleyip konuyu yetkiliye iletmektir."},{"id":"go-1-s30","tur":"senaryo","durum":"Saat 15.00, İstanbul’da bir zincir otelde resepsiyonda stajyersin. Zincirin marka standardına göre konuk kapıdan girince göz teması kurulup selam verilir. Yoğun bir anda bir meslektaşın “Boş ver, denetçi bugün gelmez” diyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Yoğunlukta standardın askıya alındığını düşünüp meslektaşıma uyarım.","Meslektaşımı hemen ön büro müdürüne şikâyet edip işimi bırakırım.","Standardı denetçi olsun olmasın uygular, konuğa selam veririm.","Yoğunken selam vermem, konuk şikâyet ederse sonradan özür dilerim."],"dogru":2,"aciklama":"Marka standardı denetçi için değil konuk için vardır; her konuk gizli bir denetçi de olabilir. Yoğunluk standardı kaldırmaz; yapılacak şey kendi işini doğru yapmaktır."},{"id":"go-1-s31","tur":"coktan-secmeli","soru":"Genel müdür ile nöbetçi müdür arasındaki fark hangisidir?","secenekler":["Genel müdür bütün otelden sorumludur; nöbetçi müdür yokluklarında karar verir.","Genel müdür yalnız ön büroyu yönetir; nöbetçi müdür bütün oteli yönetir.","Nöbetçi müdür otelin sahibidir; genel müdür onun yanında çalışır.","Genel müdür yalnız geceleri, nöbetçi müdür yalnız gündüz çalışır."],"dogru":0,"aciklama":"Genel müdür bütün departmanlardan, gelirden ve konuk memnuniyetinden sorumlu en üst yöneticidir. Nöbetçi müdür ise genel müdür ve departman müdürleri otelde olmayan saatlerde, özellikle akşam ve gece, yönetim adına karar verir."},{"id":"go-1-s32","tur":"coktan-secmeli","soru":"Saat 11.30, resepsiyon: görevli ekstreyi konukla birlikte gözden geçiriyor, oda kartını teslim alıyor ve taksi gelene kadar bavulların lobide bekletilmesini sağlıyor. Konuk yolculuğunun hangi aşamasıdır?","secenekler":["Ayrılış sonrası aşama","Varış ve giriş aşaması","Çıkış ve ayrılış aşaması","İlham ve araştırma aşaması"],"dogru":2,"aciklama":"Hesabın kapatılması, odanın teslimi ve uğurlama çıkış ve ayrılış aşamasının işidir. Ayrılış sonrası aşama ise konuk otelden çıktıktan sonra gelen teşekkür mesajı ve anketle başlar."},{"id":"go-1-s33","tur":"dogru-yanlis","soru":"Konuk yolculuğu, konuk hesabını kapatıp otelin kapısından çıktığı anda sona erer.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yolculuk kapıda bitmez: ayrılış sonrası aşamada teşekkür mesajı, anket ve yeni tekliflerle ilişki sürer. Konuk bu aşamada ya yorum yazıp yeni konuk getirir ya da sessizce rakibe gider."},{"id":"go-1-s34","tur":"coktan-secmeli","soru":"Antalya’daki bir resort, beşinci yazında yine gelen aileyi adıyla karşılıyor. Dünya otelciliğinde bu tür konukların bütün konuklar içindeki oranı neyin göstergesi sayılır?","secenekler":["Otelin fazla rezervasyon riskinin","Otelin konuklarınca ne kadar sevildiğinin","Otelin platformlara ne kadar komisyon ödediğinin","Otelin ortalama oda fiyatının"],"dogru":1,"aciklama":"Daha önce gelmiş konuğun yeniden gelmesi oteli sevdiğini gösterir; bu yüzden tekrar konuk oranı otelin ne kadar sevildiğinin ölçüsü sayılır. Komisyon ise çoğu zaman aracıdan gelen yeni konuk için ödenir; tekrar konuk çoğu zaman kendiliğinden gelir."},{"id":"go-1-s35","tur":"coktan-secmeli","soru":"Gece 23.00, resepsiyon: gece görevlisi, bugün beklenen 80 konuktan iptal etmeden ve haber vermeden gelmeyen 4’ünü sistemde kapatıyor. Otel bu tür konukların oranını geçmiş verilerden izleyerek özellikle neye karar verir?","secenekler":["Rakip sete hangi otellerin alınacağına","Konuk profiline hangi notların yazılacağına","Otelin hangi yıldız sınıfında olacağına","Kaç oda için fazla rezervasyon alınacağına"],"dogru":3,"aciklama":"Gelmeyen konuk, satılabilecek odanın boş kalması demektir; otel fazla rezervasyon kararını ve iptal kurallarını bu orana göre belirler. Rakip set ise konum, büyüklük ve sınıfa göre kurulur."},{"id":"go-1-s36","tur":"coktan-secmeli","soru":"Net tavsiye puanını (NPS) konuk memnuniyet puanından ayıran temel özellik hangisidir?","secenekler":["Konuğun oteli başkasına önerme isteğini ölçmesi","Cevapları otelin kendi çalışanlarından alması","Konuğa beş yıldızlı bir ölçekle sorulması","Yalnız odanın temizliğini ve kahvaltısını ölçmesi"],"dogru":0,"aciklama":"Memnun olmak ile başkasına anlatacak kadar memnun olmak aynı şey değildir; NPS ikincisini ölçer. Soru çalışana değil konuğa sorulur ve 0’dan 10’a kadar bir ölçekle tek bir tavsiye sorusuna dayanır; temizlik ya da kahvaltı gibi tek tek hizmetleri ölçmez."},{"id":"go-1-s37","tur":"coktan-secmeli","soru":"İstanbul’daki bir şehir oteli, yakınındaki bir bankayla sözleşme yapıyor: bankanın çalışanları yıl boyunca her gelişte aynı indirimli fiyatla konaklayacak. Bu anlaşma otele en çok ne kazandırır?","secenekler":["Paket turlarla yaz sezonunu doldurma","Dünyanın her yerinden görünür olma","Hafta içinde doluluğu güvenceye alma","Bütün kanallarda aynı fiyatla görünme"],"dogru":2,"aciklama":"Kurumsal anlaşma şehir otellerinin hafta içi dolulukta güvencesidir; iş konuğu düzenli gelir. Paket turlarla sezonu doldurmak ise tur operatörü kontenjanının işidir."},{"id":"go-1-s38","tur":"dogru-yanlis","soru":"Gelir yönetimi mantığına göre otel odası bozulabilen bir üründür: bu gece satılmayan oda, yarın satılarak geri kazanılamaz.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Gelir yönetiminin temel düşüncesi budur: geçen gecenin boş odası bir daha satılamaz. Bu yüzden doğru oda doğru konuğa, doğru zamanda ve doğru fiyatla satılmaya çalışılır."},{"id":"go-1-s39","tur":"coktan-secmeli","soru":"Yılbaşı haftasında Kapadokya’daki bir otel, araya boşluk bırakacak tek gecelik talepleri kapatıyor ve yalnız en az üç gece kalacak konukların rezervasyonunu kabul ediyor. Otel hangi gelir yönetimi aracını kullanıyor?","secenekler":["Dinamik fiyatlama","Fazla rezervasyon","Oran paritesi","Minimum konaklama şartı"],"dogru":3,"aciklama":"Belirli bir gece sayısının altındaki talebi kapatmak minimum konaklama şartıdır ve gelir yönetiminin fiyat dışı araçlarındandır. Dinamik fiyatlamada ise talep kapatılmaz, fiyat değiştirilir."},{"id":"go-1-s40","tur":"coktan-secmeli","soru":"Bir otelde rezervasyonlar, giriş-çıkışlar, oda durumu ve konuk hesapları tek yazılımda tutuluyor; kat görevlisinin “hazır” işaretlediği oda resepsiyon ekranında anında yeşile dönüyor. Bu yazılım hangisidir?","secenekler":["Kanal yöneticisi","Otel yönetim sistemi (PMS)","Küresel dağıtım sistemi (GDS)","Otelin kapı kartı kilit sistemi"],"dogru":1,"aciklama":"Bütün departmanların birlikte kullandığı, oda durumunu ve konuk hesabını tutan ana yazılım PMS’tir. Kanal yöneticisi ise fiyatı ve müsait oda sayısını satış kanallarına gönderir."},{"id":"go-1-s41","tur":"coktan-secmeli","soru":"Kapadokya’da bir aile, kendi adını taşıyan ve hiçbir markaya bağlı olmayan bir otel işletiyor. Bu otelin uluslararası zincir otellerine göre zayıf yanı hangisidir?","secenekler":["Dünyada tanınırlığının az olması","Kendi menüsüne karar verememesi","Sık sık marka denetimine girmesi","Fiyatını kendisinin belirleyememesi"],"dogru":0,"aciklama":"Bağımsız otelin zayıf yanı dünya çapında tanınırlığı ve rezervasyon ağı olmamasıdır; bu yüzden platformlara daha çok ihtiyaç duyar. Menüye ve kurallara ise kendisi karar verir, marka denetimi zincire bağlı otellere özgüdür."},{"id":"go-1-s42","tur":"coktan-secmeli","soru":"Antalya’daki beş yıldızlı bir otelde konaklayan yabancı bir konuk, otelin kendi ülkesindeki beş yıldızlı otellerle aynı ölçütlerle sınıflandırıldığını düşünüyor. Görevlinin vereceği doğru bilgi hangisidir?","secenekler":["Her ülkede yıldızı UN Tourism’in verdiğini","Yıldız ölçütlerinin ülkeden ülkeye değiştiğini","Yıldızları dünyada Michelin Rehberi’nin verdiğini","Beş yıldızın her yerde aynı donanım demek olduğunu"],"dogru":1,"aciklama":"Dünya çapında tek bir yıldız sistemi yoktur; kimi ülkede devlet, kimi ülkede otelciler birliği farklı ölçütlerle yıldız verir. Michelin yıldızları ise otele değil restorana verilir."},{"id":"go-1-s43","tur":"dogru-yanlis","soru":"Les Clefs d’Or üyelerinin yakasındaki çapraz iki altın anahtar, o kişinin otelin ön büro yöneticisi olduğunu gösterir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Les Clefs d’Or uluslararası otel concierge’leri birliğidir; altın anahtar konuğa bu kişinin işini bilen bir concierge olduğunu anlatır. Anahtarı takmak için yıllarca lobide çalışmak ve sınavdan geçmek gerekir."},{"id":"go-1-s44","tur":"coktan-secmeli","soru":"UN Tourism ile WTTC arasındaki temel fark hangisidir?","secenekler":["UN Tourism devletleri, WTTC ise şirketleri temsil eder.","UN Tourism otellere yıldız, WTTC restoranlara yıldız verir.","UN Tourism Avrupa’yı, WTTC Amerika’yı temsil eder.","UN Tourism sertifika verir, WTTC ders kitabı yayımlar."],"dogru":0,"aciklama":"UN Tourism Birleşmiş Milletlerin turizm kuruluşudur ve devletleri temsil eder; WTTC büyük seyahat şirketlerinin yöneticilerini bir araya getirir. Sertifika ve ders kitabı ise AHLEI’nin işidir."}],"siralamalar":[{"id":"go-1-r01","konu":"1.1","baslik":"Telefondaki fotoğraftan yoruma: bir konuğun yolculuğu","yonerge":"Bir konuğun otel araştırmasından, otelden ayrıldıktan sonraki temasına kadar konuk yolculuğunun aşamalarını doğru sıraya koy.","adimlar":["Konuk tatil yerini düşünür; otellerin fotoğraflarını ve eski konukların yorumlarını karşılaştırır.","Konuk tarihi, oda tipini ve fiyatı belirleyerek otelle ilk anlaşmayı yapar.","Otel konuğa ulaşım bilgisini ve giriş saatini e-postayla gönderir; konuğun özel istekleri öğrenilir.","Konuk otele gelir; resepsiyonist onu karşılar ve odasına yerleştirir.","Konuk odada kalır, restoranı ve havuzu kullanır; temizlik, yemek ve teknik servis sınanır.","Konuk hesabını kapatır, odayı teslim eder ve otelden uğurlanır.","Otel teşekkür mesajı ve anket gönderir; konuk internette yorumunu yazar."],"aciklama":"Konuk yolculuğu ilham ve araştırmayla başlar; rezervasyon, varış öncesi iletişim, varış, konaklama ve çıkış aşamalarıyla sürer. Otelden ayrıldıktan sonra yazılan yorum da bir sonraki konuğun araştırma aşamasına girer."},{"id":"go-1-r02","konu":"1.3","baslik":"Fazla rezervasyon: hesap tutmazsa ne olur?","yonerge":"Fazla rezervasyon kararından konuğun başka otele yerleştirilmesine kadar olayları doğru sıraya koy.","adimlar":["Otel, geçmiş verilerden gelmeyen konuk ve iptal oranını izler.","Bu orana ve iptal kurallarına bakılarak kaç oda fazla satılacağı belirlenir.","Otel, sahip olduğundan biraz daha fazla oda için bilerek rezervasyon alır.","Beklenenden çok konuk gelir ve onaylı bir konuk için oda kalmaz.","Yönetim hangi konuğun gönderileceğine karar verir; sadık konuk mümkünse gönderilmez.","Konuktan özür dilenir; konuk, konaklaması ve ulaşımı genellikle otelce karşılanarak benzer ya da daha iyi bir otele yerleştirilir."],"aciklama":"Fazla rezervasyon bir hesaba dayanır: önce gelmeyen konuk oranı ölçülür, sonra fazla satış yapılır. Hesap tutmazsa bedeli otel öder; konuğu dürüst, hızlı ve özürle başka otele yerleştirir."},{"id":"go-1-r03","konu":"1.5","baslik":"Gece denetçisi: sabahın sayıları nasıl doğar?","yonerge":"Gece denetçisinin günü kapatma işinin adımlarını doğru sıraya koy.","adimlar":["Günün bütün konuk hesaplarını ve kayıtlarını tek tek kontrol et.","Kontrolde bulduğun hataları düzelt.","Günü otel yönetim sisteminde kapat ve doluluk ile ortalama oda fiyatını gösteren sabah raporlarını hazırla.","Müdürler sabah toplantısında doluluk ve ADR sayılarını bu raporlardan okur."],"aciklama":"Hesaplar kontrol edilmeden hata bulunamaz, hatalar düzeltilmeden gün kapatılmaz; raporlar kapanan günün sayılarından çıkar. Gece denetçisinin bir hatası sabah müdürün masasına yanlış rakam olarak gelir."}],"acikSorular":[{"id":"go-1-y01","konu":"1.2","soru":"Bir otelde 100 oda vardır. Bir gecede 70 oda satılmış ve satılan odaların ortalama fiyatı 2.000 TL olmuştur. Bu gecenin doluluk oranını, ortalama oda fiyatını (ADR) ve oda başına gelirini (RevPAR) hesaplayarak yazınız; RevPAR’ın otel yönetimine neden doluluktan tek başına daha fazla bilgi verdiğini açıklayınız.","olcut":[{"metin":"Doluluk oranını doğru hesaplar (70 / 100 = %70).","puan":15},{"metin":"ADR’yi doğru belirtir (2.000 TL) ve neyi gösterdiğini söyler.","puan":15},{"metin":"RevPAR’ı doğru hesaplar (%70 x 2.000 = 1.400 TL).","puan":25},{"metin":"RevPAR’ın doluluk ile ortalama oda fiyatını birlikte gösterdiğini belirtir.","puan":15},{"metin":"Doluluk yüksek olsa bile fiyat düşükse gelirin az kalabileceğini örnekle nedenini açıklar.","puan":30}],"ornek":"Doluluk oranı satılan oda sayısının toplam odaya bölünmesidir: 70 / 100 = %70. ADR satılan odaların ortalama fiyatıdır, yani 2.000 TL. RevPAR oda gelirinin satılabilir toplam oda sayısına bölünmesidir; doluluk ile ADR çarpılırsa da bulunur: %70 x 2.000 = 1.400 TL. RevPAR hem doluluğu hem fiyatı tek sayıda gösterir. Örneğin otel odalarını çok ucuza satıp %95 doluluk yapabilir ama RevPAR’ı düşük kalır; bu yüzden yalnız doluluğa bakmak yanıltıcıdır.","ipucu":"Doluluk ile fiyat birbirinden bağımsız değişebilir; RevPAR’ın bu ikisini nasıl birleştirdiğini düşünün."},{"id":"go-1-y02","konu":"1.3","soru":"Bir otel, odalarını hem kendi internet sitesinden hem de bir çevrim içi seyahat acentesi (OTA) üzerinden satmaktadır. Otel yönetiminin doğrudan rezervasyonu neden tercih ettiğini ve oran paritesi ilkesinin bu iki kanalda neyi gerektirdiğini yazarak açıklayınız.","olcut":[{"metin":"Doğrudan rezervasyonun ve OTA’nın ne olduğunu kısaca ayırt eder.","puan":20},{"metin":"OTA’nın her satıştan komisyon aldığını belirtir.","puan":20},{"metin":"Doğrudan rezervasyonda komisyon ödenmediği için otelin elinde daha çok gelir kaldığını açıklar.","puan":25},{"metin":"Oran paritesini tanımlar (aynı oda, aynı tarih ve koşul, her kanalda aynı fiyat).","puan":15},{"metin":"Parite varken fiyatın aynı kaldığını, otelin doğrudan kanala çekmek için fiyat dışı avantajlar (kahvaltı, geç çıkış gibi) sunması gerektiğini açıklar.","puan":20}],"ornek":"Doğrudan rezervasyon, konuğun otelin kendi sitesi, telefonu ya da e-postası üzerinden yaptığı rezervasyondur; OTA ise birçok otelin odasını listeleyen aracı platformdur. OTA her satıştan komisyon alır, doğrudan rezervasyonda ise bu komisyon ödenmez. Bu yüzden aynı fiyata satılan oda otelin cebinde doğrudan kanaldan daha fazla gelir bırakır. Oran paritesi, aynı odanın aynı tarih ve koşullar için bütün kanallarda aynı fiyatla görünmesi ilkesidir. Yani otel sitesinde ve OTA’da fiyat aynı olur; otel konuğu doğrudan kanala çekmek isterse fiyatı düşürmek yerine kahvaltı ya da geç çıkış gibi fiyat dışı avantajlar sunmalıdır.","ipucu":"Aynı fiyata satılan bir odadan otelin kanala göre eline ne kaldığını karşılaştırın."}]},{"ders":"global-otelcilik","sinif":9,"unite":2,"baslik":"Lüks Hizmet ve Konuk Deneyimi","onay":true,"kazanimlar":["Dünya lüks otelciliğinde hizmet standardı kavramını ve standartların neden yazılı olduğunu açıklar.","Konuğun söylemeden önce ihtiyacını fark etmenin ve hizmeti kişiye göre uyarlamanın yollarını açıklar.","Hata olduğunda konuğu yeniden kazanmanın adımlarını ve çalışanın karar yetkisinin önemini açıklar.","Farklı kültürlerden konuklara hizmet ederken dikkat edilecek görgü ve iletişim ilkelerini uygular.","Konuğun hatırlayacağı anların nasıl tasarlandığını ve ölçüldüğünü açıklar."],"soz":"Lüks, konuk istemeden önce fark etmek ve hata olunca ilk sen koşmaktır.","dersler":[{"baslik":"Yazılı Söz","ilk":"go-2-001"},{"baslik":"Gizli Denetçi Kapıda","ilk":"go-2-004"},{"baslik":"Cebindeki Kart","ilk":"go-2-009"},{"baslik":"Konuk Söylemeden Önce","ilk":"go-2-014"},{"baslik":"Seni Tanıyorlar","ilk":"go-2-019"},{"baslik":"Görünmeyen Hizmet","ilk":"go-2-022"},{"baslik":"Wow’un Sırrı","ilk":"go-2-026"},{"baslik":"Hata Olunca","ilk":"go-2-028"},{"baslik":"Dinle, Anla, Özür Dile","ilk":"go-2-032"},{"baslik":"Kim Karar Verir?","ilk":"go-2-036"},{"baslik":"Dünya Lobide","ilk":"go-2-041"},{"baslik":"Selam, El, Jest","ilk":"go-2-044"},{"baslik":"Tabakta ve Takvimde İnanç","ilk":"go-2-048"},{"baslik":"Herkesin Dili, Herkese Yer","ilk":"go-2-051"},{"baslik":"Oda Değil, Anı Satmak","ilk":"go-2-055"},{"baslik":"Üç Saniyelik Sınav","ilk":"go-2-058"},{"baslik":"Son Akılda Kalır","ilk":"go-2-061"},{"baslik":"Söz Verirken Dikkat","ilk":"go-2-065"},{"baslik":"Konuğa Kulak Vermek","ilk":"go-2-067"}],"kavramlar":[{"id":"go-2-001","konu":"2.1","terim":"Lüks hizmet standardı","ingilizce":"Luxury service standard","tanim":"Bir hizmetin her konuğa, her gün ve her çalışan tarafından aynı kalitede verilmesi için önceden yazılmış, ölçülebilir beklentidir.","ornek":"Sabah 08.00, İstanbul’da uluslararası bir zincirin oteli: stajyer, kapı görevlisinin her gelen arabaya aynı adımlarla yaklaştığını fark eder; kapıyı açar, göz teması kurar, “Hoş geldiniz” der, bavulu bellboya devreder. Bu bir alışkanlık değil, yazılı standarttır.","sektor":"Lüks otelde iyi hizmet tesadüfe bırakılmaz. Standart yazılı olmasaydı hizmet, o gün kimin vardiyada olduğuna bağlı kalırdı. Dünya zincirleri bu yüzden en küçük davranışı bile yazar, öğretir ve ölçer; stajyer için iş, bu standartları ezberlemekle değil, nedenini anlamakla başlar.","iliskili":["go-2-002","go-2-009","go-2-003"],"kontrol":null,"kitapDisi":true},{"id":"go-2-002","konu":"2.1","terim":"Standart işletim prosedürü (SOP)","ingilizce":"Standard operating procedure (SOP)","tanim":"Bir işin adım adım nasıl yapılacağını, hangi sırayla ve hangi ölçüde yapılacağını anlatan yazılı talimattır.","ornek":"Saat 14.00, Antalya’da bir resort: kat görevlisinin elindeki SOP, odaya girişten çıkışa kadar on iki adımı sıralar; stajyer ilk hafta listeye bakarak çalışır, ikinci hafta ezbere.","sektor":"SOP, “bana kimse söylemedi” mazeretini ortadan kaldırır. Yeni çalışan ilk günden doğru yapar, denetçi neyi ölçeceğini bilir, hata olduğunda hangi adımın atlandığı görülür. Dünya zincirlerinde her departmanın kendi SOP dosyası vardır.","iliskili":["go-2-001","go-2-004","go-2-003"],"kontrol":null,"kitapDisi":true,"gorsel":"m9-hand-washing-instructions-si"},{"id":"go-2-003","konu":"2.1","terim":"Tutarlılık","ingilizce":"Consistency","tanim":"Konuğun hangi gün gelirse gelsin, hangi çalışana denk gelirse gelsin aynı kalitede hizmet almasıdır.","ornek":"Konuk mart ayında Bodrum’daki otelde kaldı, ağustosta aynı zincirin İzmir’deki oteline gitti; ikisinde de aynı karşılama cümlesini duydu ve aynı özenle uğurlandı. “Bu zincire güveniyorum” dedi.","sektor":"Lüks, bir kez mükemmel olmak değil, her seferinde iyi olmaktır. Tutarsız otel konuğu her seferinde belirsizlikte bırakır: “Bu sefer iyi mi olacak?” Zincir markaların değeri, dünyanın her yerinde aynı deneyimi vaat edebilmelerinden gelir; bunu sağlayan şey yazılı standart ve günlük eğitimdir.","iliskili":["go-2-001","go-2-002","go-2-007"],"kontrol":null,"kitapDisi":true},{"id":"go-2-004","konu":"2.1","terim":"Ölçülebilir davranış","ingilizce":"Measurable behaviour","tanim":"“Yapıldı mı, yapılmadı mı?” sorusuna evet ya da hayır diye cevap verilebilen, bu yüzden denetlenebilen hizmet davranışıdır.","ornek":"Denetçinin listesinde “Personel güler yüzlüydü” yazmaz; “Karşılamada göz teması kuruldu”, “Konuğa adıyla hitap edildi”, “Telefon üç çalışta açıldı” yazar. Stajyer bu listeyi görünce “iyi hizmet” sözünün nasıl somutlaştığını anlar.","sektor":"Ölçülemeyen şey yönetilemez. Lüks otelcilik “nazik olun” gibi belirsiz öğütleri davranışa çevirir; böylece eğitim verilebilir, denetlenebilir ve eksik düzeltilebilir. Forbes gibi derecelendirme kuruluşlarının çok maddelik listeleri bu mantıkla yazılır.","iliskili":["go-2-002","go-2-006","go-2-005"],"kontrol":null,"kitapDisi":true},{"id":"go-2-005","konu":"2.1","terim":"Telefonu üç çalışta açma","ingilizce":"Answering within three rings","tanim":"Çalan telefonun bekletilmeden, genellikle en geç üçüncü çalışta ve otelin belirlediği karşılama cümlesiyle açılmasıdır.","ornek":"Saat 11.00, rezervasyon ofisi: telefon çalar çalmaz stajyer elindeki dosyayı bırakır, ikinci çalışta açar ve “Günaydın, rezervasyon, ben Elif, nasıl yardımcı olabilirim?” der.","sektor":"Dünya lüks otelciliğinde telefon standardı en kolay ölçülen davranışlardan biridir: telefon kaç çalışta açıldı, karşılama cümlesi söylendi mi, konuk bekletildi mi. Konuk için her çalış “Burada kimse yok mu?” sorusudur; hızlı açılan telefon, konuğun oteli görmeden edindiği ilk izlenimdir.","iliskili":["go-2-004","go-2-006","go-2-024"],"kontrol":null,"kitapDisi":true,"gorsel":"telefonlar"},{"id":"go-2-006","konu":"2.1","terim":"Forbes hizmet standartları","ingilizce":"Forbes Travel Guide service standards","tanim":"Lüks otelleri yıldızla derecelendiren Forbes Travel Guide’ın, hizmeti çok sayıda ölçütle değerlendirdiği ve ölçülebilir davranışlara dayandığı standartlar bütünüdür.","ornek":"Stajyer, genel müdürün duvarındaki yıldız sertifikasının nasıl alındığını sorar; amiri anlatır: kimliğini söylemeyen bir denetçi otelde kaldı, karşılamadan uğurlamaya her davranışı listesiyle karşılaştırdı.","sektor":"Bu tür derecelendirmelerde binanın ve eşyanın yanında çalışanın davranışı da puanlanır; yani yalnız mermer değil, insan da ölçülür. Ölçütlerin mantığı bellidir: göz teması, isimle hitap, hızlı telefon, öngörülü hizmet. Otelde çalışan herkes, o gün denetçinin gelebileceğini bilerek çalışır.","iliskili":["go-2-004","go-2-007","go-2-008"],"kontrol":null,"kitapDisi":true},{"id":"go-2-007","konu":"2.1","terim":"Anonim denetçi","ingilizce":"Anonymous inspector","tanim":"Kim olduğunu söylemeden sıradan bir konuk gibi otelde kalan ve hizmeti bir ölçüt listesine göre puanlayan değerlendiricidir.","ornek":"Perşembe 15.00, resepsiyon: tek başına giriş yapan, çok soru soran ve her şeyi dikkatle izleyen konuğun denetçi olup olmadığını kimse bilmez; stajyer ona da herkese davrandığı gibi davranır.","sektor":"Denetçinin kimliği gizlidir, çünkü otelin “denetçi günü” değil “her günkü” hâlini görmek ister. Bu yüzden lüks otelde hizmetin tek güvencesi, her konuğa aynı özenle davranmaktır; kimin denetçi olduğunu tahmin etmeye çalışmak işe yaramaz.","iliskili":["go-2-006","go-2-008","go-2-003"],"kontrol":null,"kitapDisi":true},{"id":"go-2-008","konu":"2.1","terim":"Gizli müşteri denetimi","ingilizce":"Mystery guest audit","tanim":"İşletmenin kendi isteğiyle görevlendirdiği bir kişinin konuk gibi davranarak hizmeti deneyip ayrıntılı rapor yazdığı iç denetim yöntemidir.","ornek":"Ay sonu, genel müdür toplantısı: gizli müşteri raporunda “Havuz barı siparişi on iki dakikada geldi, garson adımı hiç kullanmadı” yazar; F&B müdürü ekibiyle bir eğitim planlar.","sektor":"Dış denetimden farkı, raporun otelin kendi isteğiyle yazılmasıdır; amaç ceza değil, eksiği konuk gözüyle görmektir. Dünya zincirleri bu raporları eğitim malzemesi olarak kullanır. Rapor kişiyi değil, standardın nasıl uygulandığını ölçer.","iliskili":["go-2-007","go-2-006","go-2-002"],"kontrol":null,"kitapDisi":true,"cizim":"kurallar-liste"},{"id":"go-2-009","konu":"2.1","terim":"Hizmet kültürü","ingilizce":"Service culture","tanim":"Bir işletmede çalışanların, kimse bakmazken bile konuğu nasıl ağırladığını belirleyen ortak değer ve alışkanlıklar bütünüdür.","ornek":"Gece 02.00, lobi boş: güvenlik görevlisi yerde gördüğü bir peçeteyi, kameraya değil konuğa saygısından eğilip alır. Stajyer ertesi gün bunu duyar ve kültürün ne olduğunu anlar.","sektor":"Standart kâğıtta yazılıdır, kültür kalpte taşınır. İkisi birlikte çalışır: standart “ne yapılacağını”, kültür “neden yapıldığını” söyler. Güçlü hizmet kültürü olan otelde yeni gelen çalışan, kurallardan önce çevresinden öğrenir.","iliskili":["go-2-001","go-2-010","go-2-013"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"go-2-010","konu":"2.1","terim":"İnanç kartı","ingilizce":"Credo card","tanim":"Bir otel zincirinin hizmet inancını, sloganını ve temel değerlerini özetleyen, çalışanların üniforma cebinde taşıdığı küçük karttır.","ornek":"İlk staj günü, personel girişi: amir stajyere üniformayla birlikte katlanmış bir kart verir; üstünde otelin konuğa verdiği söz ve çalışanın uyacağı değerler yazılıdır. “Bunu her gün okuyacaksın” der.","sektor":"Bu uygulamayla anılan zincirlerden biri Ritz-Carlton’dur; “Altın Standartlar” adını verdiği değerleri kartla çalışanına taşır ve “Hanımefendilere ve beyefendilere hizmet eden hanımefendiler ve beyefendileriz” sözüyle özetler. Burada yalnız kartın ne olduğunu anlatmak için örnek verilmiştir. Kart, hizmet kültürünü soyut bir fikir olmaktan çıkarıp her çalışanın cebine koyar.","iliskili":["go-2-009","go-2-011","go-2-012"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"go-2-011","konu":"2.1","terim":"Hizmetin üç adımı","ingilizce":"Three steps of service","tanim":"Sıcak ve içten karşılama, konuğun ihtiyacını önceden sezip karşılama ve isimle sıcak uğurlama olmak üzere her konuk temasında izlenen üç adımlık düzendir.","ornek":"Saat 12.30, otel restoranı: garson masaya yaklaşırken gülümser ve “Hoş geldiniz” der; konuğun menüde vejetaryen yemek aradığını fark edip önerir; kalkarken “Teşekkürler, Ayşe Hanım; akşam yine bekleriz” diye uğurlar.","sektor":"Ritz-Carlton’ın Altın Standartları’nda “hizmetin üç adımı” diye yer alan bu düzen, birçok otelin eğitiminde benzer biçimde kullanılır: karşıla, öngör, uğurla. Stajyer için hatırlaması kolay bir pusuladır; hangi departmanda olursa olsun her konuk temasını bu üç adımla kurar.","iliskili":["go-2-010","go-2-014","go-2-018"],"kontrol":null,"kitapDisi":true},{"id":"go-2-012","konu":"2.1","terim":"Günlük hizmet toplantısı (line-up)","ingilizce":"Daily line-up","tanim":"Her vardiya başında ekibin kısa süre ayakta toplanıp günün konuklarını, özel durumları ve bir hizmet değerini konuştuğu toplantıdır.","ornek":"Sabah 07.45, ön büro arka ofisi: şef on dakika içinde günün VIP gelişlerini, dün yaşanan bir aksaklığı ve “bugünün değeri”ni anlatır; stajyer de o gün hangi konuğun doğum günü olduğunu öğrenir.","sektor":"Birçok zincirde günlük rutinin parçasıdır. Standartlar bir kez öğretilip unutulmaz; her gün birkaç dakika tazelenir. Ekip aynı bilgiyle güne başlayınca konuk hangi çalışana rastlarsa rastlasın aynı hizmeti alır.","iliskili":["go-2-010","go-2-003","go-2-020"],"kontrol":null,"kitapDisi":true,"cizim":"toplanti-sunum"},{"id":"go-2-013","konu":"2.1","terim":"Standart ve içtenlik","ingilizce":"Standards and sincerity","tanim":"Yazılı standardın ezberlenmiş bir cümle gibi değil, o anki konuğa uygun, sıcak ve doğal biçimde uygulanmasıdır.","ornek":"İki resepsiyonist aynı karşılama cümlesini söyler: biri ekrana bakarak, hızlıca; öteki başını kaldırıp gülümseyerek. Standart ikisinde de “yapıldı”, ama konuk yalnız ikincisinde karşılandığını hisseder.","sektor":"Lüks otelcilikte liste davranışı yazar, duyguyu çalışan katar. Robot gibi uygulanan standart, konuğun aklında “ezberlenmiş nezaket” diye kalır. Dünya otelcilik okulları bu yüzden önce standardı, sonra onun arkasındaki insanı eğitir.","iliskili":["go-2-009","go-2-001","go-2-017"],"kontrol":null,"kitapDisi":true,"cizim":"kurallar-liste"},{"id":"go-2-014","konu":"2.2","terim":"Öngörülü hizmet","ingilizce":"Anticipatory service","tanim":"Konuğun söylemesini beklemeden ihtiyacını fark edip karşılamaya dayanan hizmet anlayışıdır.","ornek":"Saat 19.00, resort lobisi: konuk elinde bir harita ve telefonla etrafa bakınıyor; stajyer beklemeden yaklaşır, “Bir yer mi arıyorsunuz? Size yardımcı olayım” der.","sektor":"İstek üzerine yapılan hizmet beklentiyi karşılar; istenmeden yapılan hizmet beklentiyi aşar. Dünya lüks otelciliğinde konuk “şunu rica edebilir miyim?” demek zorunda kaldıysa hizmet bir adım geç kalmıştır. Bu beceri konuğu izlemekle başlar.","iliskili":["go-2-015","go-2-019","go-2-011"],"kontrol":null,"kitapDisi":true,"gorsel":"m9-turndown-service-9285555655"},{"id":"go-2-015","konu":"2.2","terim":"Konuğu okuma","ingilizce":"Reading guest cues","tanim":"Konuğun söylemediği ihtiyacını beden dilinden, bakışından, eşyasından ve içinde bulunduğu durumdan anlamaktır.","ornek":"Saat 23.30, resepsiyon: gece uçuşundan gelen konuk gözlerini ovuşturuyor, küçük çocuğu kucağında uyuyor. Stajyer tanıtım konuşmasını kısa keser, anahtarı verir, “Kahvaltı saatlerini odanıza not bırakırım” der.","sektor":"Öngörülü hizmetin hammaddesi gözlemdir. Lüks otel çalışanı konuğa bakar, ekrana değil: elinde bebek arabası olan konuk asansörü, kol saatine bakan konuk hızı, menüyü uzun süre inceleyen konuk bir öneriyi bekliyor olabilir. Doğru okunan konuk, istemeden alır.","iliskili":["go-2-014","go-2-022","go-2-016"],"kontrol":null,"kitapDisi":true},{"id":"go-2-016","konu":"2.2","terim":"10-5 kuralı","ingilizce":"The 10 and 5 rule","tanim":"Yaklaşan konukla yaklaşık üç metre kala göz teması kurup gülümsemeyi, yaklaşık bir buçuk metre kala sözlü selam vermeyi öngören karşılama kuralıdır.","ornek":"Lobi koridoru, saat 10.00: stajyer çamaşır arabasını iterken karşıdan bir konuk gelir; uzaktan başını kaldırıp gülümser, yanından geçerken “Günaydın, efendim” der ve arabayı kenara çeker.","sektor":"Adı İngilizce ayak ölçüsünden gelir (10 feet ve 5 feet). Kural, konuğun otelde “görünmez” hissetmemesi içindir. Lüks otelde her çalışan, departmanı ne olursa olsun karşılama görevlisidir; teknik servisteki usta da, bahçıvan da. Ölçülebilir bir davranış olduğu için eğitimlerde ve denetim listelerinde yer alır.","iliskili":["go-2-015","go-2-017","go-2-004"],"kontrol":null,"kitapDisi":true},{"id":"go-2-017","konu":"2.2","terim":"İsimle hitap standardı","ingilizce":"Addressing the guest by name","tanim":"Konuğun adının ilk fırsatta öğrenilip konaklama boyunca doğal ve abartısız biçimde kullanılmasıdır.","ornek":"Giriş işleminde pasaporttan adı gören resepsiyonist, “Odanız hazır, Mehmet Bey” der; bellboy anahtarı alırken adı duyar ve asansörde “Buyurun, Mehmet Bey” diye devam eder.","sektor":"Konuk için kendi adı en güzel sestir; adıyla anılan konuk kalabalıktan çıkar, kişi olur. Ölçü doğallıktır: her cümlede ad geçerse yapay olur. İsmin doğru söylenişinden emin olunmazsa sorulur; yanlış söylenen ad, hiç söylenmemesinden kötüdür.","iliskili":["go-2-016","go-2-011","go-2-013"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"go-2-018","konu":"2.2","terim":"Sıcak uğurlama","ingilizce":"Fond farewell","tanim":"Konuğun ayrılırken adıyla ve içten bir dilekle, aceleye getirilmeden uğurlanması; hizmetin üç adımının sonuncusudur.","ornek":"Saat 11.00, çıkış: kasa işlemi bitince resepsiyonist bankodan çıkıp “Yolunuz açık olsun, Zeynep Hanım; bir dahaki gelişinizde deniz manzaralı odanız yine hazır olur” der; kapı görevlisi aracı çağırmıştır.","sektor":"Konuk oteli son anıyla hatırlar; soğuk bir fatura teslimi bütün konaklamanın tadını kaçırabilir. Uğurlama, bir sonraki konaklamanın ilk davetidir. Dünya zincirleri bu yüzden çıkış işlemini de karşılama kadar ciddiye alır ve süresini ölçer.","iliskili":["go-2-011","go-2-017","go-2-061"],"kontrol":null,"kitapDisi":true},{"id":"go-2-019","konu":"2.2","terim":"Kişiselleştirme","ingilizce":"Personalisation","tanim":"Hizmetin herkese aynı biçimde değil, konuğun bilinen tercihine ve o anki durumuna göre uyarlanmasıdır.","ornek":"Odaya giren konuk, geçen gelişinde istediği ekstra yastığın hazır olduğunu ve mini bardaki gazlı içeceklerin sevdiği markayla değiştirildiğini görür; kimseye bir şey söylememiştir.","sektor":"Lüks otelde konuk “müşteri numarası” değil, tercihleri bilinen bir kişidir. Kişiselleştirme pahalı hediyelerle değil, doğru bilgiyle yapılır: hangi gazeteyi okur, hangi kattan hoşlanmaz, kahvesini nasıl içer. Bu bilgi tek bir çalışanın hafızasında değil, otelin profilinde durur.","iliskili":["go-2-020","go-2-014","go-2-021"],"kontrol":null,"kitapDisi":true},{"id":"go-2-020","konu":"2.2","terim":"Konuk tercih profili","ingilizce":"Guest preference profile","tanim":"Konuğun hoşlandığı ve hoşlanmadığı şeylerin, alerjilerinin ve geçmiş isteklerinin otel sisteminde tutulduğu kişiye özel kayıttır.","ornek":"Sabah 09.00, ön büro: stajyer günün gelişlerini açar; bir konuğun profilinde “fındık alerjisi, yüksek kat, sessiz oda, geç çıkış sever” yazar. Oda buna göre seçilir, mutfağa not düşülür.","sektor":"Bazı zincirlerde profil, aynı zincirin otelleri arasında da paylaşılır: Londra’da kaydedilen tercih Türkiye’deki otelde karşılanabilir. Profil yalnız bilgi değil, bir sözdür: konuk “beni tanıyorlar” hisseder. Bilgi kişisel olduğu için gizlilikle ve yasalara uygun biçimde korunur, yalnız hizmet için kullanılır.","iliskili":["go-2-019","go-2-021","go-2-012"],"kontrol":null,"kitapDisi":true,"cizim":"belge-form"},{"id":"go-2-021","konu":"2.2","terim":"Tercih aktarımı","ingilizce":"Preference handover","tanim":"Bir çalışanın konukta fark ettiği tercihi kendine saklamayıp profile işlemesi ve ekiple paylaşmasıdır.","ornek":"Kahvaltıda garson, konuğun her sabah süt yerine yulaf sütü istediğini fark eder; vardiya sonunda profile yazar. Ertesi sabah başka garson masaya yulaf sütüyle gelir.","sektor":"Kişiselleştirme ekip işidir. Bir çalışanın bildiği ama paylaşmadığı tercih, o çalışan izinli olduğu gün kaybolur. Lüks otelde “ben biliyordum” yetmez; bilgi sisteme ve vardiya devrine girer. Stajyerin fark ettiği küçük ayrıntı da bu zincirin halkasıdır.","iliskili":["go-2-020","go-2-019","go-2-023"],"kontrol":null,"kitapDisi":true,"cizim":"el-yikama"},{"id":"go-2-022","konu":"2.2","terim":"Sessiz hizmet","ingilizce":"Unobtrusive service","tanim":"Konuğu rahatsız etmeden, göze batmadan ve araya girmeden ihtiyacı karşılayan hizmet biçimidir.","ornek":"Havuz başı, saat 15.00: konuğun boş bardağı, kendisi kitabını okurken sessizce alınır, yerine dolusu bırakılır; garson tek kelime etmeden uzaklaşır.","sektor":"Lüks, hizmetin görünmez olmasıdır: her şey olur ama kimse konuğun dinlenmesini bölmez. Fazla ilgi de ilgisizlik kadar rahatsız eder. Konuğu okuyan çalışan ne zaman konuşacağını, ne zaman sessiz kalacağını bilir.","iliskili":["go-2-015","go-2-023","go-2-014"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"go-2-023","konu":"2.2","terim":"Ayrıntıya özen","ingilizce":"Attention to detail","tanim":"Konuğun belki hiç fark etmeyeceği küçük şeylerin bile eksiksiz ve düzgün olmasına gösterilen titizliktir.","ornek":"Kat görevlisi odayı bitirmiştir; stajyer son kontrolde tuvalet kâğıdının ucunu katlar, uzaktan kumandayı televizyona paralel koyar, pencereden bakıp perdeyi düzeltir. Konuk bunları tek tek görmez; bütününü hisseder.","sektor":"Lüks otelde ayrıntı küçük değildir, çünkü konuk lüksü ayrıntıdan okur. Dünya zincirleri “konuk fark ederse geç kalmışız” der: eğri duran bir tablo, lekeli bir bardak bütün özeni gölgeler. Titizlik bir karakter özelliği değil, öğrenilen bir alışkanlıktır.","iliskili":["go-2-022","go-2-021","go-2-026"],"kontrol":null,"kitapDisi":true,"gorsel":"m9-folded-napkin-01"},{"id":"go-2-024","konu":"2.2","terim":"Bekletme süresi standardı","ingilizce":"Waiting time standard","tanim":"Konuğun bankoda, telefonda ya da masada ne kadar bekleyebileceğini belirleyen ve geçildiğinde özür gerektiren süre sınırıdır.","ornek":"Saat 16.00, resepsiyon kuyruğu uzamış: stajyer sıradaki konuklara dönüp “Birkaç dakika içinde sizinleyim, bu arada su ikram edebilir miyim?” der. Bekleyen konuk artık bekliyor değil, ağırlanıyordur.","sektor":"Bekleyen konuk için dakika uzundur; hele kimse ona bakmıyorsa. Lüks otelde sürenin kendisi kadar beklerken yapılanlar da ölçülür: göz teması, bilgi verme, ikram. Telefonda bekletme, bagajın odaya ulaşması ve çıkış işlemi için de süre standartları vardır.","iliskili":["go-2-005","go-2-004","go-2-025"],"kontrol":null,"kitapDisi":true},{"id":"go-2-025","konu":"2.2","terim":"Alternatif sunma","ingilizce":"Offering an alternative","tanim":"Konuğun isteği karşılanamadığında “hayır” demek yerine yapılabilecek en yakın seçeneği önermektir.","ornek":"Saat 22.10, oda servisi mutfağı kapanmış; konuk sıcak çorba istiyor. Stajyer “Kapalı” demez: “Mutfak kapandı, efendim; ancak size sıcak bir sandviç ve çay hazırlatabilirim, ister misiniz?” der.","sektor":"Lüks otelcilikte “hayır” cümlenin sonu değil, başı olmalıdır: “Bunu yapamıyorum, ama şunu yapabilirim.” Konuk çoğu zaman isteğinin kendisinden çok, çaba görmek ister. Yetkiyi aşan istekler ise amire iletilir; “yapamam” yerine “sorup döneceğim” denir.","iliskili":["go-2-024","go-2-014","go-2-037"],"kontrol":null,"kitapDisi":true},{"id":"go-2-026","konu":"2.2","terim":"“Wow” anı","ingilizce":"Wow moment","tanim":"Konuğun beklemediği, küçük ama kişiye özel bir jestle şaşırıp sevindiği ve sonradan anlattığı andır.","ornek":"Konuk çıkış günü lobide “Keşke o portakal reçelinden alsaydım” diye mırıldanır; garson duyar, mutfağa koşar. Araç kalkarken konuğun eline küçük bir kavanoz tutuşturulur.","sektor":"Wow anı pahalı olmak zorunda değildir; tek şartı beklenmedik ve kişisel olmasıdır. Herkese verilen hediye beklenti olur, bir kişiye özel olan hikâye olur. Bazı zincirler çalışanlarına böyle anlar yaratması için küçük bir bütçe ve yetki tanır.","iliskili":["go-2-023","go-2-019","go-2-062"],"kontrol":null,"kitapDisi":true},{"id":"go-2-027","konu":"2.2","terim":"Omotenashi","ingilizce":"Omotenashi (Japanese hospitality)","tanim":"Konuğun ihtiyacını önceden sezerek, karşılık beklemeden ve gösterişsiz biçimde ağırlamayı anlatan Japon konukseverlik anlayışıdır.","ornek":"Akşam 19.00, resort resepsiyonu: yolculuktan yeni gelen bir konuk baş ağrısını söylemez ama ışıktan kaçınır. Stajyer bunu fark eder ve sormadan odayı sessiz bir koridora yakın, perdeleri kalın bir kattan seçer.","sektor":"Kökeni çoğu zaman Japon çay seremonisine dayandırılan bu anlayış, otelcilik okullarında öngörülü hizmetin tanınmış örneklerinden biri olarak anlatılır. Japonya’da bahşiş geleneğinin olmaması da çoğu zaman bu anlayışla ilişkilendirilir. Her kültürün kendi konukseverlik geleneği vardır; Türk misafirperverliği de dünyada aynı saygıyla anılır.","iliskili":["go-2-014","go-2-022","go-2-047"],"kontrol":null,"kitapDisi":true,"gorsel":"m9-33421771032"},{"id":"go-2-028","konu":"2.3","terim":"Hizmet aksaklığı","ingilizce":"Service failure","tanim":"Konuğa verilen sözün ya da beklediği standardın yerine getirilemediği her durumdur.","ornek":"Saat 14.30, resepsiyon: “Odanız 14.00’te hazır” denen konuk hâlâ lobide bekliyor; kat hizmetlerinden haber gelmemiştir. Konuk şikâyet etmese de ortada bir aksaklık vardır.","sektor":"Aksaklık her otelde olur; lüks otelin farkı, onu konuktan önce fark etmesidir. Aksaklığı tanımak, telafinin ilk adımıdır: “konuk bir şey demedi” sözü, sorunun olmadığı anlamına gelmez. Sessizce giden konuk şikâyet eden konuktan daha tehlikelidir.","iliskili":["go-2-029","go-2-035","go-2-040"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"go-2-029","konu":"2.3","terim":"Lüks otelde hizmet telafisi","ingilizce":"Service recovery in luxury hotels","tanim":"Aksaklık yaşayan konuğun güvenini ve memnuniyetini yeniden kazanmak için hızla, içtenlikle ve planlı biçimde yapılan düzeltmedir.","ornek":"Odası geç hazırlanan konuğa resepsiyonist özür diler, bekleme süresinde lobide ikram sunar, yetkisi dâhilinde odayı bir üst kategoriye alır ve akşam odaya bir not bırakır. Konuk ertesi gün “Sorun oldu ama iyi ilgilendiler” der.","sektor":"Dünya otelcilik okullarında telafi, hizmetin kendisi kadar ciddi bir ders konusudur. Hatanın büyüklüğünü çoğu zaman hatanın kendisi değil, sonrasındaki tutum belirler. Telafi tek bir özür değil bir süreçtir: dinle, anla, çöz, takip et; üstelik hızlı olmalıdır, çünkü aynı sorun beş dakikada çözülürse küçük bir aksaklık, bir saatte çözülürse kötü bir anıdır.","iliskili":["go-2-028","go-2-032","go-2-033"],"kontrol":null,"kitapDisi":true},{"id":"go-2-030","konu":"2.3","terim":"Telafi paradoksu","ingilizce":"Service recovery paradox","tanim":"İyi telafi edilen bir aksaklığın, konuğu hiç sorun yaşamamış hâlinden daha memnun ve daha bağlı bırakabilmesi durumudur.","ornek":"Klima arızası yaşayan konuk, teknik ekibin on dakikada gelmesi, odasının değiştirilmesi ve müdürün bizzat özür dilemesi üzerine çevrim içi yorumuna “Böyle ilgi görmemiştim” yazar.","sektor":"Paradoks, hata yapmak için bir bahane değildir; her zaman da gerçekleşmez, araştırmaların sonuçları karışıktır. Ders şudur: aksaklık kaçınılmazdır, telafi ise tamamen otelin elindedir. İyi telafi, en azından konuğu kaybetmemenin en sağlam yoludur.","iliskili":["go-2-029","go-2-031","go-2-039"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"go-2-031","konu":"2.3","terim":"Şikâyeti fırsata çevirme","ingilizce":"Turning complaints into opportunities","tanim":"Memnuniyetsizlik bildiren konuğu bir saldırı olarak değil, onu kazanmak ve hizmeti düzeltmek için verilmiş bir şans olarak görmektir.","ornek":"Konuk, kahvaltı salonunun gürültülü olduğunu söyler. Müdür teşekkür eder, konuğa ertesi gün teras masası ayırtır; bir hafta sonra salondaki ses düzeni değiştirilir.","sektor":"Memnun olmayan konukların birçoğu şikâyet etmez; sessizce gider ve çevresine anlatır. Şikâyet eden konuk ise otele hem ikinci bir şans hem ücretsiz bir denetim raporu verir. Lüks otelcilikte şikâyet, savunulacak değil teşekkür edilecek bir şeydir.","iliskili":["go-2-030","go-2-033","go-2-070"],"kontrol":null,"kitapDisi":true},{"id":"go-2-032","konu":"2.3","terim":"LEARN şikâyet çözüm modeli","ingilizce":"LEARN complaint-handling model","tanim":"Şikâyeti çözmek için dinle (listen), anla (empathise), özür dile (apologise), harekete geç (react) ve bildir (notify) adımlarını sıralayan telafi modelidir.","ornek":"Konuk gürültüden uyuyamadığını anlatır. Stajyer sözünü kesmeden dinler, “Uykusuz bir gece gerçekten zor” der, özür diler, sessiz bir odaya geçişi amiriyle ayarlar ve durumu hem profile hem şefine yazar.","sektor":"Otelcilik eğitiminde yaygın kullanılan bu model, panik anında çalışana bir sıra verir; kaynağa göre adımların sözcükleri biraz değişebilir. Son adım olan “bildir” çoğu zaman unutulur; oysa yazılmayan aksaklık yarın yeniden olur. Stajyer için en değerli adımlar ilk ikisidir: dinle ve anla.","iliskili":["go-2-029","go-2-033","go-2-034"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"go-2-033","konu":"2.3","terim":"HEART şikâyet çözüm modeli","ingilizce":"HEART complaint-handling model","tanim":"Şikâyette dinle (hear), anla (empathise), özür dile (apologise), çöz (resolve) ve teşekkür et (thank) adımlarını izleyen telafi modelidir.","ornek":"Spa randevusu unutulan konuk resepsiyona gelir. Görevli dinler, “Haklısınız, bu bizim hatamız” der, özür diler, bir saat sonrasına yeni randevu ve ikram ayarlar; sonunda “Bize söylediğiniz için teşekkür ederim” der.","sektor":"LEARN ile neredeyse aynı yolu izler; farkı, son adımın teşekkür olmasıdır. Kaynağa göre dördüncü adım “çöz” (resolve) yerine “karşılık ver” (respond) diye de geçer. Şikâyet eden konuk otele bir iyilik yapar: sessizce gitmek yerine düzeltme şansı verir. Bunu bir teşekkürle karşılamak, konuğu “sorun çıkaran” değil “yardım eden” konumuna koyar.","iliskili":["go-2-032","go-2-029","go-2-031"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"go-2-034","konu":"2.3","terim":"İçten özür","ingilizce":"Sincere apology","tanim":"Hatayı bahane göstermeden, “ama” demeden ve suçu başkasına atmadan kabul eden kısa ve samimi özürdür.","ornek":"Bagajı geç gelen konuğa stajyer “Bellboy yoğundu, o yüzden” demez; “Beklettiğimiz için özür dilerim, bagajınız şu anda yolda” der.","sektor":"Özrün arkasına eklenen bahane, özrü siler: “Özür dilerim ama bugün çok yoğunuz” cümlesini konuk “suçlu sizsiniz” diye duyar. Özür, hatanın kimde olduğunu tartışmak değil, konuğun yaşadığını kabul etmektir. Yetkisi olmayan stajyer bile özür dileyebilir; bu hiç kimsenin yetkisini aşmaz.","iliskili":["go-2-032","go-2-033","go-2-038"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"go-2-035","konu":"2.3","terim":"Departman ayırmadan sahiplenme","ingilizce":"Owning a guest problem across departments","tanim":"Konuğun sorununu “benim bölümüm değil” demeden üstlenip çözülene kadar takip etmektir.","ornek":"Restoranda çalışan stajyere konuk “Odamdaki kasa açılmıyor” der. Stajyer “Resepsiyona söyleyin” demez; “Hemen teknik servise ileteyim, oda numaranızı alabilir miyim?” der ve on dakika sonra çözüldüğünü öğrenip konuğa haber verir.","sektor":"Konuk için otel tek bir bütündür; departman sınırlarını bilmez ve bilmek zorunda değildir. Dünya zincirlerinin hizmet değerleri arasında “konuğun sorununu sahiplenir ve hemen çözerim” cümlesi yer alır. Sahiplenmek, her şeyi kendin yapmak değil, doğru kişiye ulaştırıp sonucu izlemektir.","iliskili":["go-2-028","go-2-036","go-2-037"],"kontrol":null,"kitapDisi":true,"cizim":"ekip"},{"id":"go-2-036","konu":"2.3","terim":"Yetkilendirme","ingilizce":"Empowerment","tanim":"Çalışana, konuğun sorununu amirine sormadan belirli bir sınır içinde kendi başına çözme yetkisinin verilmesidir.","ornek":"Saat 21.00, resepsiyonda şef yok: konuk odasının manzarasından memnun değil. Yetkilendirilmiş resepsiyonist boş olan deniz manzaralı odayı hemen verir; sabah şefine bilgi notu bırakır.","sektor":"Dünya lüks otelciliğinin en bilinen ilkelerinden biridir; bazı zincirler her çalışanına konuk için belirli bir tutara kadar harcama yetkisi tanır ve bunu sorgulamaz. Mantık basittir: konuk beklerken “müdüre sormam lazım” demek telafiyi geciktirir. Yetki, güvenle gelir; güven de eğitimle.","iliskili":["go-2-037","go-2-035"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"go-2-037","konu":"2.3","terim":"Yetki sınırı","ingilizce":"Limit of authority","tanim":"Çalışanın kendi başına karar verebileceği alanın nerede bittiğini ve hangi kararın amire taşınacağını belirleyen çizgidir.","ornek":"Stajyer, çorbası soğuk gelen konuğa yenisini ve bir tatlı ikram edebilir; “bu gece ücretsiz olsun” diyemez. Konuk ısrar ederse “Bunu müdürümle hemen görüşüp size döneceğim” der.","sektor":"Yetkilendirme sınırsız değildir; sınırını bilmeyen çalışan ya korkup hiçbir şey yapmaz ya da tutamayacağı söz verir. İkisi de konuğu kaybettirir. Lüks otelde stajyerin de bir yetkisi vardır: özür dilemek, dinlemek, küçük ikram, hızlı iletmek. Gerisi için doğru cümle “sorup döneceğim”dir.","iliskili":["go-2-036","go-2-038","go-2-025"],"kontrol":null,"kitapDisi":true,"cizim":"pasaport"},{"id":"go-2-038","konu":"2.3","terim":"Orantılı telafi","ingilizce":"Proportionate recovery","tanim":"Sunulan jestin büyüklüğünün yaşanan sorunun büyüklüğüne uygun olmasıdır.","ornek":"Kahvesi soğuk gelen konuğa yenisi ve küçük bir tatlı yeter; bütün gece su basan odada kalan konuğa ise oda değişimi, o gecenin ücretsiz sayılması ve müdürün özrü gerekir. İkincisine kurabiye vermek alay gibi olur.","sektor":"Küçük soruna büyük jest otelin bütçesini boşa harcar ve konuğa “burada bir şeyler ters” hissi verir; büyük soruna küçük jest konuğu daha da kırar. Orantıyı kurmak için çalışan kendi yetki sınırını bilir: sınır içinde kendi karar verir, üstünü amirine taşır.","iliskili":["go-2-034","go-2-037","go-2-029"],"kontrol":null,"kitapDisi":true,"cizim":"doga"},{"id":"go-2-039","konu":"2.3","terim":"Telafi takibi","ingilizce":"Recovery follow-up","tanim":"Sorun çözüldükten sonra konuğa yeniden dönüp her şeyin yolunda olup olmadığını sormaktır.","ornek":"Saat 18.00: öğlen klima arızası giderilen konuğun odası aranır: “Ayşe Hanım, ben resepsiyondan Can; odanızın sıcaklığı şimdi nasıl?” Konuk, kendisini unutmadıklarını anlar.","sektor":"Telafi, sorunun çözüldüğü anda değil, konuğun “çözüldü” dediği anda biter. Takip, otelin konuğu bir sorun numarası olarak değil, kişi olarak gördüğünü gösterir. Konuk unutulduğunu düşünürken aranmak, çoğu zaman en güçlü telafi jestidir.","iliskili":["go-2-030","go-2-032","go-2-040"],"kontrol":null,"kitapDisi":true,"cizim":"doga"},{"id":"go-2-040","konu":"2.3","terim":"Aksaklık kaydı","ingilizce":"Incident log","tanim":"Yaşanan her aksaklığın ne olduğu, nasıl çözüldüğü ve konuğa ne sunulduğunun yazıldığı kayıttır.","ornek":"Gece raporuna stajyer yazar: “23.10, oda 512, sıcak su yok; teknik servis 23.35’te giderdi; konuğa özür ve sabah kahvaltısında ikram; profil güncellendi.”","sektor":"Yazılmayan aksaklık unutulur ve tekrarlanır; yazılan aksaklık derse dönüşür. Kayıt, bir sonraki vardiyanın konuğu “dün sorun yaşayan konuk” olarak tanımasını da sağlar; ona ertesi gün bir kez daha özür dilenir. Günlük toplantıda konuşulan aksaklıklar bu kayıttan gelir.","iliskili":["go-2-028","go-2-039","go-2-067"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"go-2-041","konu":"2.4","terim":"Kültürel zekâ (CQ)","ingilizce":"Cultural intelligence (CQ)","tanim":"Farklı kültürlerden insanlarla etkili ve saygılı biçimde çalışabilme becerisidir; istek, bilgi, strateji ve davranış olmak üzere dört parçası vardır.","ornek":"Stajyer, yeni gelen grubun bazı üyelerinin dinî ya da kültürel nedenle et yemeyebileceğini bilir (bilgi), kahvaltıda ne sunacağını önceden düşünür (strateji), sorarken kibar ve dikkatli davranır (davranış) ve bunu bir yük değil merak olarak görür (istek).","sektor":"Kavramı bilim dünyasına Earley ve Ang adlı iki araştırmacı kazandırmıştır; otelcilik eğitiminde sık işlenir. Lüks otel lobisi küçük bir dünyadır: aynı sabah farklı ülkelerden konuklar aynı bankoya gelir. Kültürel zekâ, hepsine aynı davranmak değil, her birine uygun davranmaktır.","iliskili":["go-2-042","go-2-043","go-2-044"],"kontrol":null,"kitapDisi":true,"cizim":"dunya-global"},{"id":"go-2-042","konu":"2.4","terim":"Bireyi görme","ingilizce":"Avoiding stereotypes","tanim":"Kültür bilgisini bir tahmin olarak kullanıp karşıdaki konuğa yine de tek bir birey olarak davranmaktır.","ornek":"Stajyer eğitimde “bazı ülkelerde insanlar kahvaltıyı erken yapar” diye öğrenmiştir; ama o sabah yabancı bir aile geç kalkar ve kahvaltıyı uzun ister. Stajyer şaşırmaz, aileye bakar, öğrendiği genellemeye değil.","sektor":"Kültür bilgisi haritadır, konuk ise yoldur. “Şu ülkeden gelenler hep şöyle yapar” diye düşünen çalışan, önündeki kişiyi görmez; konuk da bunu hemen hisseder. Dünya okulları kültürel zekâyı “genelleme ezberi” değil, “merak ve gözlem” diye öğretir.","iliskili":["go-2-041","go-2-015","go-2-053"],"kontrol":null,"kitapDisi":true,"cizim":"dunya-global"},{"id":"go-2-043","konu":"2.4","terim":"Doğrudan ve dolaylı iletişim","ingilizce":"Direct and indirect communication","tanim":"Bazı kültürlerde isteklerin açıkça söylenmesi, bazılarında ise ima ve nezaketle dolaylı anlatılmasıdır.","ornek":"Bir konuk “Oda gürültülü, değiştirin” der; bir başkası “Oda çok güzel, yalnız sokak biraz hareketli galiba” der. İkincisi de oda değişikliği istiyor olabilir; stajyer tonu ve yüzü okur, nazikçe “Size daha sessiz bir oda ayarlayabilirim” diye teklif eder.","sektor":"Dolaylı konuşmaya alışkın bir konuğun “sorun yok” demesi her zaman sorun olmadığı anlamına gelmez; açıkça şikâyet etmek ona zor gelebilir. Doğrudan konuşan konuk ise kaba değil, kendi alışkanlığında nazik davranıyordur. Bunlar eğilimdir, kural değildir; her kültürde iki tarzda konuşanlar vardır. Çalışan, sözün yanında ses tonunu ve yüzü de okur.","iliskili":["go-2-041","go-2-045","go-2-052"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"go-2-044","konu":"2.4","terim":"Uluslararası selamlaşma","ingilizce":"International greetings","tanim":"El sıkma, hafif eğilme, yanak öpme ya da yalnız söz ve baş selamı gibi kültüre göre değişen karşılama biçimleridir.","ornek":"Lobi, saat 15.00: hafifçe eğilerek selam veren konuğa stajyer de hafifçe eğilerek, “Bonjour” diyen konuğa güler yüzle, el uzatmayan konuğa ise elini uzatmadan baş selamıyla “Hoş geldiniz” der. Her birinde konuğun kendi seçtiği selamlaşma biçimine uyar.","sektor":"Otelde güvenli kural: el uzatmayı konuk başlatır, çalışan karşılık verir. Bazı konuklar dinî ya da kültürel nedenle karşı cinsle tokalaşmaz; bu bir reddediş değil, gelenektir. Örneğin Japonya’da kartvizit genellikle iki elle verilir ve alınır, bir an bakılıp özenle saklanır. Konuğun dilinde tek bir “hoş geldiniz” sözü bile kapıyı açar.","iliskili":["go-2-046","go-2-041","go-2-045"],"kontrol":null,"kitapDisi":true,"gorsel":"sektor-el-sikisma"},{"id":"go-2-045","konu":"2.4","terim":"Jestlerin anlamı","ingilizce":"Meaning of gestures","tanim":"Aynı el ya da beden hareketinin bir ülkede dostça, başka bir ülkede kaba ya da saygısız sayılabilmesidir.","ornek":"Stajyer konuğa yolu gösterirken işaret parmağı yerine açık elini kullanır; “tamam” anlamında baş parmak ya da OK işareti yapmaz, çünkü bu işaretler bazı ülkelerde hakaret sayılır. Oturan konuğa ayak tabanını da göstermez.","sektor":"Dünya otelciliğinde “güvenli jest” kuralı vardır: açık el, hafif baş eğme ve gülümseme hemen her kültürde iyi anlaşılır; parmakla gösterme, baş parmak ve OK işareti ise risklidir. Jest yanlış anlaşıldığında konuk bunu söylemez, yalnız soğur. Bu yüzden en az risklisi seçilir.","iliskili":["go-2-043","go-2-044","go-2-041"],"kontrol":null,"kitapDisi":true,"cizim":"beden-dili"},{"id":"go-2-046","konu":"2.4","terim":"İsim ve unvan kullanımı","ingilizce":"Names and titles","tanim":"Konuğa hitap ederken ad-soyad sırasının, “Bay / Bayan” karşılıklarının ve doktor, profesör gibi unvanların kültüre göre doğru kullanılmasıdır.","ornek":"Rezervasyonda “Wang Li” yazan konuğun soyadı, birçok Çince adda olduğu gibi önce yazılmış olabilir; bunu bilen stajyer tahmin yürütmez, nazikçe sorar: “Size nasıl hitap etmemi istersiniz?” Rezervasyonda “Dr. Müller” yazan konuğa da kendisi aksini söylemedikçe “Doktor Müller” der.","sektor":"Bazı kültürlerde soyadı önce yazılır, bazılarında kadın evlenince soyadını değiştirmez, bazılarında unvanın söylenmemesi saygısızlık sayılır. Emin olunmadığında tahmin etmek yerine sormak kibarlıktır; yanlış isim, hiç isim söylememekten kötüdür. İsmi doğru söylemek lüks hizmetin en ucuz ama en etkili parçasıdır.","iliskili":["go-2-044","go-2-017","go-2-051"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"go-2-047","konu":"2.4","terim":"Bahşiş kültürü farkları","ingilizce":"Tipping cultures","tanim":"Bahşişin bazı ülkelerde beklenen, bazılarında isteğe bağlı, bazılarında ise alışılmamış ya da yadırganan bir davranış olmasıdır.","ornek":"Bavulu taşıyan stajyere bir konuk bahşiş uzatır, bir başkası uzatmaz; stajyer hiçbirini beklemez ve kimseye kırgın davranmaz. İkisine de aynı içtenlikle “İyi tatiller” der.","sektor":"Bahşiş beklemek, istemek ya da az verene yüz asmak lüks otelde kabul edilmez; hizmet bahşiş için değil, konuk için verilir. Çalışan, bahşiş verilmeyen kültürden gelen konuğu hizmeti beğenmemiş sanmaz. Bazı otellerde bahşiş ortak havuzda toplanıp paylaşılır; kurallarını otel belirler.","iliskili":["go-2-027","go-2-044","go-2-041"],"kontrol":null,"kitapDisi":true,"cizim":"dunya-global"},{"id":"go-2-048","konu":"2.4","terim":"Yemek alışkanlıkları ve kısıtlamalar","ingilizce":"Dietary habits and restrictions","tanim":"Konukların dinî, sağlık ya da tercih nedeniyle belirli yiyecekleri yememesi ve mutfağın buna uygun seçenek sunmasıdır.","ornek":"Kahvaltı salonu, saat 08.30: stajyer, açık büfede helal, vejetaryen ve glütensiz ürünlerin etiketli olduğunu görür. Bir konuk fındık alerjisini söyler; stajyer “Şefimize hemen soruyorum” deyip mutfağa gider, tahmin yürütmez.","sektor":"Helal, koşer, vejetaryen, vegan, alerji: lüks otelde bunların her biri bilinir, etiketlenir ve sorulur. Yemekle ilgili soru sormak ayıp değil, özendir; yanlış tabak ise sağlık riski ya da inanç ihlalidir. Alerjide tek güvenli cevap mutfaktan gelir.","iliskili":["go-2-049","go-2-050","go-2-020"],"kontrol":null,"kitapDisi":true,"gorsel":"t13e-bitkisel-mezeler"},{"id":"go-2-049","konu":"2.4","terim":"Dinî hassasiyetler","ingilizce":"Religious sensitivities","tanim":"Konukların ibadet, oruç, giyim ve yiyecek gibi inançtan gelen ihtiyaçlarının bilinip saygıyla karşılanmasıdır.","ornek":"Konuk, odada kıble yönünü ve en yakın ibadet yerini sorar; stajyer bilmiyorsa uydurmaz, resepsiyondan öğrenip döner. Ramazanda iftar saatine göre restoran düzeni değişir; şabat gününü gözeten bazı konuklar o gün elektronik cihaz kullanmak istemeyebilir, bu yüzden oda anahtarı ve asansör konusunda bir çözüm sormak gerekebilir.","sektor":"İnanç konusunda hata, konuğun yalnız gününü değil otelle bağını bozar. Lüks otel farklı inançların takvimini ve ihtiyacını önceden bilir; çalışan ise soruyu yargılamadan dinler ve bilmediğini öğrenip söyler. Kendi inancı ne olursa olsun, konuğunkine saygı meslek gereğidir.","iliskili":["go-2-048","go-2-050","go-2-053"],"kontrol":null,"kitapDisi":true,"gorsel":"m9-qiblamat"},{"id":"go-2-050","konu":"2.4","terim":"Kültürel takvim","ingilizce":"Cultural calendar","tanim":"Farklı ülke ve inançların bayram, oruç ve özel günlerinin otel tarafından önceden bilinip hazırlık yapılmasıdır.","ornek":"Çin Yeni Yılı haftasında İstanbul’daki şehir oteli lobiye kırmızı fenerler asar ve bu bayramı kutlayan konuklara “Yeni yılınız kutlu olsun” yazan küçük bir kart bırakır; kapıdan giren konuklar bunu fark edip gülümser.","sektor":"Konuğun bayramını bilmek, onu kendi evindeymiş gibi hissettirir; bilmemek ise “burada yabancıyım” duygusu verir. Dünya zincirleri yıl boyunca farklı kültürlerin özel günlerini takip eder; stajyer bunu günlük toplantıda öğrenir ve gelen konuğa küçük bir sözle bile yansıtır.","iliskili":["go-2-049","go-2-048","go-2-019"],"kontrol":null,"kitapDisi":true,"gorsel":"m9-lantern-festival-in-taiwan"},{"id":"go-2-051","konu":"2.4","terim":"Çok dilli hizmet","ingilizce":"Multilingual service","tanim":"Konuğa kendi dilinde ya da ortak bir dilde yardım edebilmek için dil bilen personel, çeviri araçları ve çok dilli yazılı malzeme kullanılmasıdır.","ornek":"Resepsiyonistin yakasında konuştuğu dillerin küçük bayrakları vardır. Rusça bilen kimse yokken stajyer, çeviri uygulamasını açıp konuğa “Anlaşabilmemiz için bunu kullanabilir miyiz?” diye sorar.","sektor":"Konuğun dilinden birkaç sözcük bile (“hoş geldiniz”, “teşekkürler”) ilişkiyi değiştirir. Dil yetmediğinde çare bağırmak ya da tekrarlamak değil, araç kullanmak ve dil bilen arkadaşı çağırmaktır. Dünya otelciliğinde yabancı dil, kariyerin kapısını açan ilk anahtardır.","iliskili":["go-2-052","go-2-046","go-2-053"],"kontrol":null,"kitapDisi":true,"gorsel":"f3c-dnd-cokdilli"},{"id":"go-2-052","konu":"2.4","terim":"Konukla sade İngilizce","ingilizce":"Plain English for guests","tanim":"Ana dili İngilizce olmayan konukla yavaş, kısa cümlelerle, deyim ve kısaltma kullanmadan konuşmaktır.","ornek":"Stajyer, ana dili İngilizce olmayan bir konuğa “Breakfast is from seven to ten, in the restaurant on the ground floor” der; “grab a bite”, “F&B outlet” gibi deyim ve kısaltma kullanmaz, gerekirse saati kâğıda yazar.","sektor":"Uluslararası otelde İngilizce ortak dildir ama çoğu konuğun ikinci dilidir. Hızlı ve deyimli İngilizce, konuğu anlamıyormuş gibi hissettirir ve soru sormaktan alıkoyar. Sade konuşmak bilgisizlik değil, ustalıktır.","iliskili":["go-2-051","go-2-043","go-2-042"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"go-2-053","konu":"2.4","terim":"Kapsayıcılık","ingilizce":"Inclusivity","tanim":"Yaşı, cinsiyeti, engeli, kökeni ya da inancı ne olursa olsun her konuğun kendini eşit derecede hoş karşılanmış hissetmesidir.","ornek":"Tek başına seyahat eden yaşlı konuk, restoranda pencere kenarına alınır ve “tek kişilik” diye kenara itilmez; işitme engelli konukla stajyer yüz yüze, yavaş ve gerekirse yazarak konuşur.","sektor":"Lüks, herkese lüks olduğunda lükstür. Kapsayıcı otel bazı konuklara “ekstra” bir şey yapmaz; herkesi aynı özenin içine alır. Çalışanın bakışı, ses tonu ve küçük tercihleri, konuğa “burası benim için de” duygusunu verir ya da alır.","iliskili":["go-2-054","go-2-042","go-2-049"],"kontrol":null,"kitapDisi":true,"gorsel":"m9-tactile-paving-in-a"},{"id":"go-2-054","konu":"2.4","terim":"Erişilebilir hizmet","ingilizce":"Accessible service","tanim":"Engelli, yaşlı ya da geçici hareket kısıtı olan konuğun otelin her hizmetinden yardım istemek zorunda kalmadan yararlanabilmesidir.","ornek":"Tekerlekli sandalyeli konuk giriş yapar: resepsiyonist bankonun alçak bölümüne geçer, anahtarı eğilerek değil göz hizasından verir, asansöre kadar eşlik etmeyi teklif eder ama ısrar etmez.","sektor":"Erişilebilirlik yalnız rampa ve geniş kapı değildir; çalışanın tutumudur. Yardımı sormak ama dayatmamak, yanındakine değil konuğun kendisine konuşmak, aceleye getirmemek temel kurallardır. Dünya zincirlerinde erişilebilirlik bir hayır işi değil, hizmet standardıdır.","iliskili":["go-2-053","go-2-014","go-2-058"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-erisilebilir-giris"},{"id":"go-2-055","konu":"2.5","terim":"Deneyim ekonomisi","ingilizce":"Experience economy","tanim":"İşletmelerin yalnız ürün ya da hizmet değil, konuğun hatırlayacağı bir yaşantı sattığı ekonomi anlayışıdır.","ornek":"Kapadokya’da bir butik otel yalnız oda satmaz: sabah balonların kalkışının izlendiği teras, taş fırında ekmek yapımı ve köy kahvaltısı birlikte bir yaşantı olarak sunulur; konuk eve “bir odada kaldım” diye değil, “şunu yaşadım” diye döner.","sektor":"Kavramı Pine ve Gilmore adlı iki yazar ortaya attı: hammadde satılır, sonra ürün, sonra hizmet; en değerlisi ise deneyimdir, çünkü hatıra olarak kalır. Bu yüzden birçok otel artık yalnız “oda satıyoruz” demez; sattığı şey konuğun eve götürdüğü anıdır.","iliskili":["go-2-056","go-2-057","go-2-062"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"go-2-056","konu":"2.5","terim":"Konuk deneyimi","ingilizce":"Guest experience","tanim":"Konuğun oteli ilk duyduğu andan ayrıldıktan sonra anlattığı ana kadar yaşadığı ve hissettiği her şeyin toplamıdır.","ornek":"Konuk için deneyim internet sitesine girdiği saniye başlar: rezervasyon kolay mıydı, taksici oteli biliyor muydu, kapıda kim karşıladı, oda nasıl kokuyordu, çıkışta ne hissetti. Hepsi tek bir anıya dönüşür.","sektor":"Deneyim, otelin kontrol ettiği ve etmediği her şeyi kapsar; bu yüzden tek bir departmanın değil herkesin işidir. Lüks otel konuğun ne aldığına değil, ne hissettiğine bakar. Ölçülen, iyileştirilen ve rakiple yarışılan şey artık deneyimdir.","iliskili":["go-2-055","go-2-058","go-2-059"],"kontrol":null,"kitapDisi":true},{"id":"go-2-057","konu":"2.5","terim":"Deneyim tasarımı","ingilizce":"Experience design","tanim":"Konuğun yaşayacağı anların rastlantıya bırakılmayıp önceden düşünülerek planlanması ve sahneye konmasıdır.","ornek":"Otel, kış konukları için girişte tarçınlı sıcak içecek, odada hazır battaniye ve akşam şöminede müzik dinletisi planlar; her ayrıntı “konuk soğuktan gelince ne hissetmek ister?” sorusuyla seçilmiştir.","sektor":"Tiyatro gibi düşünülür: lobi sahnedir, çalışan oyuncudur, konuk hem seyirci hem baş roldür. İyi tasarlanmış deneyim konuğa tasarlanmış gibi gelmez; doğal gelir. Stajyer, bir otelde “tesadüf” sandığı güzel anların çoğunun önceden düşünüldüğünü öğrenir.","iliskili":["go-2-055","go-2-063","go-2-058"],"kontrol":null,"kitapDisi":true},{"id":"go-2-058","konu":"2.5","terim":"Temas noktası","ingilizce":"Touchpoint","tanim":"Konuğun otelle karşılaştığı ve bir izlenim edindiği her an ya da yerdir; internet sitesi, telefon, kapı, oda ve fatura bunlara örnektir.","ornek":"Stajyer bir günde kaç temas noktasında olduğunu sayar: kapıda karşılama, bagaj taşıma, asansörde sohbet, odayı tanıtma. Her biri konuğun aklında ayrı bir not bırakır.","sektor":"Konuk oteli bütün olarak değil, temas noktalarının toplamı olarak değerlendirir; tek bir kötü nokta on iyi noktayı gölgeler. Bu yüzden lüks oteller temas noktalarını tek tek listeler ve her birine bir standart yazar. Çalışanın girdiği her temas bir sınavdır.","iliskili":["go-2-056","go-2-059","go-2-060"],"kontrol":null,"kitapDisi":true,"gorsel":"m9-hk-disneyland-hotel-room"},{"id":"go-2-059","konu":"2.5","terim":"Konuk yolculuğu haritası","ingilizce":"Guest journey map","tanim":"Konuğun rezervasyondan ayrılış sonrasına kadar geçtiği her adımın ve her adımda ne hissettiğinin tek bir şema üstünde gösterilmesidir.","ornek":"Konuk ilişkileri ekibi duvara büyük bir şema asar: “arama → geliş → giriş → oda → yemek → çıkış → yorum”. Her adımın altına konuğun o anki duygusu ve otelin yapması gerekenler yazılır; girişteki uzun kuyruk haritada kırmızıyla işaretlenir.","sektor":"Harita, sorunu konuğun gözünden gösterir: departmanlar kendi işini iyi yapabilir ama konuk aradaki boşluklara düşer. Zayıf halkalar bu şemada görünür. Deneyim tasarımı bu haritayla başlar, ölçüm de bu haritayla biter.","iliskili":["go-2-058","go-2-056","go-2-061"],"kontrol":null,"kitapDisi":true},{"id":"go-2-060","konu":"2.5","terim":"Hizmette gerçek an","ingilizce":"Moment of truth","tanim":"Konuğun bir çalışanla ya da hizmetle karşılaşıp otel hakkında kanı edindiği, iyi ya da kötü yönde belirleyici olan kısa andır.","ornek":"Asansörde stajyerle göz göze gelen konuk, bir “günaydın” duyup duymamasına göre oteli “sıcak” ya da “soğuk” diye etiketler. Bu an üç saniye sürer, etkisi bütün gün kalır.","sektor":"Kavramı bir hava yolu yöneticisi olan Jan Carlzon yaygınlaştırdı: şirket her gün binlerce kısa karşılaşmada ya kazanılır ya kaybedilir. Lüks otelde her çalışan günde onlarca gerçek an yaşar; büyük yatırımlar bu küçük anlarda kaybedilebilir ya da kazanılabilir.","iliskili":["go-2-058","go-2-061","go-2-062"],"kontrol":null,"kitapDisi":true,"cizim":"zil-hizmet"},{"id":"go-2-061","konu":"2.5","terim":"Zirve-son kuralı","ingilizce":"Peak-end rule","tanim":"İnsanın bir yaşantıyı en yoğun anıyla ve bitişiyle hatırladığını, aradaki ortalamayı ise büyük ölçüde unuttuğunu söyleyen kuraldır.","ornek":"Beş gün boyunca her şey kusursuz giden konuk, çıkışta faturada yanlış bir kalemle kırk dakika uğraşırsa tatili “o fatura” diye hatırlar; tersi de olur, sorunlu başlayan tatil güzel bir uğurlamayla kurtulur.","sektor":"Kuralı psikolog Daniel Kahneman’ın çalışmaları ortaya koydu; dünya otelciliği bunu deneyim tasarımında kullanır: unutulmaz bir zirve anı yarat ve konaklamayı mutlaka iyi bitir. Çıkış işleminin lüks otelde bu kadar önemsenmesinin nedeni budur.","iliskili":["go-2-018","go-2-062","go-2-060"],"kontrol":null,"kitapDisi":true,"cizim":"kurallar-liste"},{"id":"go-2-062","konu":"2.5","terim":"Hatırlanan an","ingilizce":"Memorable moment","tanim":"Konuğun konaklamadan yıllar sonra bile anlattığı, duygusu güçlü ve kişiye özel olduğu için hafızada kalan andır.","ornek":"Çocuğunun doğum gününü otelde kutlayan aile, odaya döndüğünde yatağın üstünde havludan yapılmış bir pasta ve çocuğun adıyla yazılmış bir kart bulur. Yıllar sonra bile “o oteli hatırlıyor musun?” derler.","sektor":"Konuk otelin halısını, perdesini unutur; ona nasıl hissettirildiğini unutmaz. Hatırlanan an çoğu zaman pahalı değil, kişiseldir ve bir çalışanın dikkatinden doğar. Lüks otel, bu anları tesadüfe bırakmaz; çalışanlarına bunları yaratacak zaman ve yetki verir.","iliskili":["go-2-026","go-2-061","go-2-065"],"kontrol":null,"kitapDisi":true},{"id":"go-2-063","konu":"2.5","terim":"İmza deneyim","ingilizce":"Signature experience","tanim":"Bir otelin ya da zincirin yalnız kendisine özgü, her konuğa yaşattığı ve markasıyla özdeşleşen deneyimdir.","ornek":"Boğaz kıyısındaki bir otel her konuğu girişte lobide canlı kanun sesiyle ve gül şerbetiyle karşılar; konuklar yıllar sonra “o şerbet” diye anar. Başka otel bunu kopyalasa bile aynı tadı veremez.","sektor":"İmza deneyim, otelin “bizi bizden başkası yapamaz” dediği şeydir; kokusu, ikramı, ritüeli olabilir. Zincirler bunu dünyanın her otelinde aynı yapar ki marka tanınsın. Stajyer, kendi otelinin imza anını bilir ve onu her seferinde aynı özenle sahneler.","iliskili":["go-2-057","go-2-064","go-2-055"],"kontrol":null,"kitapDisi":true},{"id":"go-2-064","konu":"2.5","terim":"Akşam oda hazırlığı (turndown)","ingilizce":"Turndown service","tanim":"Konuk yemekteyken ya da dışarıdayken odaya girilip yatağın açılması, perdelerin kapatılması, ışıkların kısılması ve küçük bir ikram bırakılmasıdır.","ornek":"Saat 19.30: konuk akşam yemeğindeyken kat görevlisi odaya girer, yatak örtüsünü katlayıp açar, terlikleri yatağın yanına koyar, komodine bir çikolata ve yarınki hava durumu kartını bırakır, ışığı loş bırakır.","sektor":"Lüks otelin klasik imza deneyimlerinden biridir: konuk odaya döndüğünde “biri beni düşünmüş” hisseder. Hizmet görünmezdir; konuk görevliyi görmez, yalnız sonucu görür. Çoğu lüks otelde turndown bir SOP ile adım adım yapılır.","iliskili":["go-2-063","go-2-022","go-2-023"],"kontrol":null,"kitapDisi":true,"gorsel":"t14za-turndown-yatak"},{"id":"go-2-065","konu":"2.5","terim":"Duygusal bağ","ingilizce":"Emotional connection","tanim":"Konuğun otele yalnız memnun olduğu için değil, kendini orada tanınmış ve önemsenmiş hissettiği için bağlanmasıdır.","ornek":"Her yıl aynı resorta gelen aile, kapı görevlisinin çocuklarının adını hatırlamasına fiyattan daha çok değer verir; başka otel indirim yapsa da gitmezler.","sektor":"Memnun konuk tekrar gelebilir; bağ kurmuş konuk başka yere bakmaz ve oteli çevresine anlatır. Bağ, tesisin büyüklüğüyle değil, insanların dikkatiyle kurulur. Sadakat programları puan verir; duygusal bağ ise hatırlanmakla kurulur.","iliskili":["go-2-062","go-2-019","go-2-067"],"kontrol":null,"kitapDisi":true,"gorsel":"f3c-havlu-kuguler"},{"id":"go-2-066","konu":"2.5","terim":"Söz verirken beklenti ayarı","ingilizce":"Setting expectations when promising","tanim":"Konuğa yerine getirilebilecekten fazlasının vaat edilmemesi ve mümkünse vaat edilenden biraz fazlasının verilmesidir.","ornek":"Resepsiyonist “Odanız en geç 15.00’te hazır” der ve 14.30’da arar: “Odanız hazır, dilerseniz çıkabilirsiniz.” Aynı oda 14.00 diye söz verilip 14.30’da hazır olsaydı konuk yarım saat geç kalındığını düşünürdü.","sektor":"Memnuniyet, aldığın ile beklediğin arasındaki farktır. Tanıtımda abartılan havuz, gerçekte güzel olsa da hayal kırıklığı yaratır. Dünya otelciliğinde ilke şudur: az söz ver, çok yap. Tutamayacağın sözü hiç vermemek, telafi gerekmemesi için en ucuz yoldur.","iliskili":["go-2-025","go-2-056","go-2-028"],"kontrol":null,"kitapDisi":true,"cizim":"fikir-inovasyon"},{"id":"go-2-067","konu":"2.5","terim":"Geri bildirim döngüsü","ingilizce":"Feedback loop","tanim":"Konuktan toplanan görüşün ekibe iletilmesi, hizmetin buna göre düzeltilmesi ve sonucun yeniden ölçülmesiyle kapanan çevrimdir.","ornek":"Anketlerde “kahvaltı sırası uzun” yorumu birikir; F&B müdürü ikinci bir omlet istasyonu açar; bir ay sonraki anketlerde yorum kaybolur. Döngü kapanmıştır.","sektor":"Toplanan ama okunmayan anket, konuğun zamanını çalmaktır. Döngünün kıymeti “ölç” adımında değil, “düzelt ve yeniden ölç” adımındadır. Lüks oteller konuğa, görüşünün ne değiştirdiğini de söyler; böylece konuk bir dahaki sefere yine yazar.","iliskili":["go-2-068","go-2-069","go-2-040"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"go-2-068","konu":"2.5","terim":"Konaklama sonrası anket","ingilizce":"Post-stay survey","tanim":"Konuk ayrıldıktan kısa süre sonra e-posta ya da mesajla gönderilen, konaklamanın her adımını puanlatan kısa soru formudur.","ornek":"Konuk çıkıştan iki gün sonra telefonunda bir mesaj görür: “Konaklamanızı 0-10 arası puanlar mısınız? Sizi en çok ne mutlu etti?” Üç dakikada doldurur; cevabı ertesi sabah toplantıda okunur.","sektor":"Anket kısa ve zamanında olmalıdır; uzun anket doldurulmaz, geç gelen anket unutulmuş bir tatili sorar. Soruların çoğu konuk yolculuğunun adımlarını izler ki hangi temas noktasının zayıf olduğu görülsün. Anketlerden çıkan göstergelerden biri Ünite 1’de görülen net tavsiye puanıdır (NPS). Çalışanın adının ankette olumlu geçmesi lüks otelde bir takdir sebebidir.","iliskili":["go-2-067","go-2-069","go-2-059"],"kontrol":null,"kitapDisi":true},{"id":"go-2-069","konu":"2.5","terim":"Puan ve açık yorum","ingilizce":"Rating and open comment","tanim":"Anketlerde konuğun hem sayıyla puan verdiği hem de kendi cümleleriyle neden öyle düşündüğünü yazdığı iki tür geri bildirimdir.","ornek":"Konuk anketin ilk sorusuna 6 verir, açık kutuya “Kahvaltıda sıcak yemek çabuk bitti” yazar. Puan sorunun varlığını, yorum ise nerede olduğunu gösterir; F&B müdürü ertesi sabah büfeyi buna göre doldurur.","sektor":"Puan hızlı karşılaştırma sağlar ama nedeni söylemez; açık yorum nedeni söyler ama saymak zordur. İyi geri bildirim sistemi ikisini birlikte okur. Çalışan için en değerli bilgi çoğu zaman yorumun içindeki küçük ayrıntıdır.","iliskili":["go-2-068","go-2-067","go-2-070"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"},{"id":"go-2-070","konu":"2.5","terim":"Yorum cevabında hizmet telafisi","ingilizce":"Service recovery in review responses","tanim":"Olumsuz çevrim içi yoruma, telafi adımlarını izleyerek, yani teşekkür, özür, çözüm ve yeniden davetle herkesin okuyacağı biçimde yanıt vermektir.","ornek":"Bir konuk “Oda temizdi ama kahvaltı geç açıldı” yazmıştır. Müdür ertesi gün yanıtlar: adıyla teşekkür eder, kahvaltı için özür diler, saat düzeninin değiştiğini söyler ve yeniden davet eder. Yanıtı oteli araştıran pek çok aday konuk okur.","sektor":"Cevap tek bir konuğa değil, o yorumu okuyan herkese yazılır. Savunmaya geçen, kalıp cümle kullanan ya da hiç cevap vermeyen otel aday konukları kaybeder. Yorum, otelin eline geçmiş bir hizmet telafisi fırsatıdır; yönetimin yanıt yazması Ünite 1’de görülen yoruma yanıt kavramıyla birlikte çalışır.","iliskili":["go-2-031","go-2-067","go-2-068"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"}],"sorular":[{"id":"go-2-s01","tur":"coktan-secmeli","soru":"Yeni başlayan bir kat görevlisi, odanın hangi adımlarla, hangi sırayla ve hangi ölçüde temizleneceğini öğrenmek istiyor. Hangi belgeye bakmalıdır?","secenekler":["Konuk tercih profiline","Aksaklık kaydına","Oda temizliği SOP’sine","Günlük toplantı notuna"],"dogru":2,"aciklama":"SOP işin adımlarını, sırasını ve ölçüsünü yazar. Tercih profili konuğun isteklerini, aksaklık kaydı yaşanmış sorunları tutar; ikisi de bir işin nasıl yapılacağını anlatmaz."},{"id":"go-2-s02","tur":"coktan-secmeli","soru":"Dünya zincirleri en küçük hizmet davranışını bile neden yazılı standarda bağlar?","secenekler":["Hizmet, vardiyadaki kişiye göre değişmesin diye","Denetçi geldiği gün hazırlıklı olunsun diye","Çalışanlar konukla konuşmak yerine listeye baksın diye","Konuğun kişisel isteklerine hiç yer kalmasın diye"],"dogru":0,"aciklama":"Yazılı standart kaliteyi kişiden bağımsız tutar; konuk hangi gün gelirse gelsin aynı hizmeti alır. Denetçi günü hazırlığı tutarlılığa değil gösterişe hizmet eder; standart ayrıca kişiselleştirmeyi engellemez, onun zeminidir."},{"id":"go-2-s03","tur":"coktan-secmeli","soru":"Hizmetin üç adımında, konuğu sıcak karşıladıktan hemen sonra gelen adım hangisidir?","secenekler":["İsimle sıcak uğurlama","Konuk tercihini profile işleme","Anketle görüş toplama","İhtiyacı önceden sezip karşılama"],"dogru":3,"aciklama":"Sıra karşılama, ihtiyacı önceden sezip karşılama ve isimle uğurlamadır. Uğurlama üçüncü adımdır; profil ve anket ise üç adımın parçası değil, onları destekleyen uygulamalardır."},{"id":"go-2-s04","tur":"coktan-secmeli","soru":"Bir otel “Konuklarımıza içten davranırız” ilkesini denetlenebilir hâle getirmek istiyor. Hangi yeniden yazım bunu sağlar?","secenekler":["Çalışanlar konuklara karşı çok nazik ve ilgili davranır.","Telefon üçüncü çalışta, karşılama cümlesiyle açılır.","Telefondaki ses tonu her zaman sıcak ve hoş olur.","Konuk telefonda kendini değerli ve önemli hisseder."],"dogru":1,"aciklama":"Ölçülebilir davranış “yapıldı mı, yapılmadı mı?” sorusuna evet ya da hayırla cevap verilebilen davranıştır. Diğer üç cümle duygu ya da genel bir niteliktir; bir denetçi onları puanlayamaz."},{"id":"go-2-s05","tur":"dogru-yanlis","soru":"Anonim denetçi otele kimliğini baştan açıklarsa otelin gerçek günlük hizmetini daha doğru görür.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Denetçinin amacı otelin her günkü hâlini görmektir. Kimliği bilinirse otel o gün özel hazırlık yapar; anonimlik tarafsız ölçümün şartıdır."},{"id":"go-2-s06","tur":"coktan-secmeli","soru":"Bir konuk salı günü kapıda çok sıcak karşılanıyor; perşembe günü başka bir görevli aynı kapıda onu fark etmiyor bile. Hangi hizmet ilkesinde sorun vardır?","secenekler":["Kişiselleştirme","Sessiz hizmet","Tutarlılık","Yetkilendirme"],"dogru":2,"aciklama":"Aynı konuk günden güne farklı kalite görüyorsa tutarlılık yoktur. Kişiselleştirme hizmeti tercihe göre uyarlamaktır; buradaki sorun uyarlama eksikliği değil, kalitenin kişiye göre değişmesidir."},{"id":"go-2-s07","tur":"coktan-secmeli","soru":"10-5 kuralındaki sıra hangisidir?","secenekler":["Üç metrede göz teması ve gülümseme, bir buçuk metrede sözlü selam","Üç metrede sözlü selam, bir buçuk metrede göz teması","Üç metrede el sıkma, bir buçuk metrede gülümseme","Üç metrede gülümseme, bir buçuk metrede adıyla hitap"],"dogru":0,"aciklama":"Konuk uzaktayken önce sessiz bir jest (göz teması, gülümseme), yaklaşınca sözlü selam gelir. Adıyla hitap karşılamanın sonraki aşamasıdır ve el sıkmayı konuk başlatır."},{"id":"go-2-s08","tur":"coktan-secmeli","soru":"Gece 01.00’de bir konuk, kapalı olan spa’da masaj istiyor. “Alternatif sunma” ilkesine en uygun cevap hangisidir?","secenekler":["“Spa şu saatte kapalı, efendim; ne yazık ki yardımcı olamıyorum.”","“Spa sabah dokuzda açılıyor, o saatte tekrar sorabilirsiniz.”","“Gece masaj hizmeti vermiyoruz, dışarıda açık bir yer arayabilirsiniz.”","“Spa kapalı; sabah için randevu ayarlar, şimdi odaya sıcak çay gönderirim.”"],"dogru":3,"aciklama":"Alternatif sunma, hayırla bitirmeyip en yakın yapılabilir seçeneği önermektir: sabaha randevu ve şimdi rahatlatan bir ikram. İkinci şık yalnız bilgi verir, konuğa bir çözüm kurmaz."},{"id":"go-2-s09","tur":"dogru-yanlis","soru":"Konuk toplantı için masasında yoğun çalışırken görevlinin sessizce su koyup konuşmayı bölmeden uzaklaşması sessiz hizmete örnektir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Sessiz hizmet, ihtiyacı konuğu rahatsız etmeden ve araya girmeden karşılamaktır. Fazla ilgi de ilgisizlik kadar rahatsız eder."},{"id":"go-2-s10","tur":"coktan-secmeli","soru":"Japon bir otelde görevli, yağmurda ıslanan konuğun ayakkabılarını fark edip kimse istemeden gece kurutur ve sabah sessizce kapıya bırakır; övgü de bahşiş de beklemez. Bu anlayışın adı nedir?","secenekler":["Hizmet telafisi","Omotenashi","Gizli müşteri denetimi","Kişiselleştirme"],"dogru":1,"aciklama":"Omotenashi ihtiyacı önceden sezmek, karşılık beklememek ve gösterişsiz davranmaktır. Kişiselleştirme tercihe göre uyarlamayı anlatır ama karşılık beklememe ve Japon konukseverliği vurgusu taşımaz."},{"id":"go-2-s11","tur":"coktan-secmeli","soru":"Bir görevli konuğun yastık alerjisini fark ediyor ama yalnız aklında tutuyor. Konuk bir sonraki konaklamasında başka bir görevlinin önünde aynı sorunu yaşıyor. Hangi uygulama eksik kalmıştır?","secenekler":["Konuğu okuma","Telafi takibi","Ayrıntıya özen","Tercih aktarımı"],"dogru":3,"aciklama":"Fark eden görevli bilgiyi profile işleyip ekiple paylaşmadığı için tercih aktarımı yapılmamıştır. Konuğu okuma (fark etme) gerçekleşmiştir; eksik olan, bilginin paylaşılmasıdır."},{"id":"go-2-s12","tur":"coktan-secmeli","soru":"LEARN modelinde çözümü uygulayan çalışan son adım olan “bildir” (notify) aşamasında ne yapar?","secenekler":["Aksaklığı hangi çalışanın yaptığını konuğa açıklar","Amirine ve kayda ileterek hizmetin düzelmesini sağlar","Konuktan yazılı memnuniyet formu doldurmasını ister","Konuğun yaşadığı sorunu diğer konuklara da duyurur"],"dogru":1,"aciklama":"Bildirmek, aksaklığın kayda geçmesini ve aynı hatanın tekrar etmemesini sağlar. Memnuniyet formu geri bildirim döngüsüne aittir; konuğun sorununu başkalarına duyurmak ise gizliliğe aykırıdır."},{"id":"go-2-s13","tur":"coktan-secmeli","soru":"HEART şikâyet çözüm modelinin adım sırası hangisidir?","secenekler":["Dinle, anla, özür dile, çöz, teşekkür et","Dinle, özür dile, anla, çöz, teşekkür et","Dinle, anla, çöz, özür dile, teşekkür et","Anla, dinle, özür dile, çöz, teşekkür et"],"dogru":0,"aciklama":"HEART: hear, empathise, apologise, resolve, thank. Önce dinlenir ve duygu anlaşılır, özürden sonra çözüm gelir; teşekkür sona kalır. Özürden önce çözüme atlamak konuğa duygusunun görülmediğini hissettirir."},{"id":"go-2-s14","tur":"coktan-secmeli","soru":"Bir otelde resepsiyon görevlisi, geç hazırlanan oda için amirine sormadan konuğa küçük bir ikram sunabiliyor. Bunu mümkün kılan düzenin adı nedir?","secenekler":["Sahiplenme","Telafi takibi","Yetkilendirme","Tutarlılık"],"dogru":2,"aciklama":"Yetkilendirme, çalışana belirli bir sınır içinde kendi başına karar verme hakkı vermektir. Sahiplenme sorunu üstlenmektir ama yetkiyi tanımlamaz; telafi takibi çözümden sonraki kontrolü anlatır."},{"id":"go-2-s15","tur":"dogru-yanlis","soru":"Telafi paradoksuna göre iyi çözülen bir aksaklık konuğu bağlayabilir; bu yüzden bir otel hata yapmayı bilinçli olarak göze alabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Paradoks, hatanın iyi bir şey olduğunu değil, iyi telafinin hatanın zararını aşabildiğini söyler. Her telafi başarılı olmaz ve hatanın kendisi her zaman güven zedeler; hata hedef değil, kurtarılması gereken bir durumdur."},{"id":"go-2-s16","tur":"coktan-secmeli","soru":"Hangi cümle içten özür tanımına uyar?","secenekler":["“Beklettiğimiz için özür dilerim; bagajınızı şimdi odanıza getiriyorum.”","“Özür dilerim ama bugün otelimiz çok dolu, herkes bekliyor.”","“Kat hizmetleri geç kalmış, onların yerine özür dilerim.”","“Üzgünüm, bunu yaşayan tek konuk siz değilsiniz.”"],"dogru":0,"aciklama":"İçten özür hatayı bahanesiz kabul eder ve çözüme bağlanır. “Ama” bahane getirir, kat hizmetlerini işaret etmek suçu başkasına atar, “tek siz değilsiniz” ise konuğun yaşadığını küçültür."},{"id":"go-2-s17","tur":"coktan-secmeli","soru":"Bir otel çalışanlarına farklı kültürlerden konuklarla çalışmak için istek, bilgi, strateji ve davranış becerilerini birlikte kazandırmayı hedefliyor. Bu bütünün adı nedir?","secenekler":["Hizmet kültürü","Kapsayıcılık","Çok dilli hizmet","Kültürel zekâ (CQ)"],"dogru":3,"aciklama":"Kültürel zekâ bu dört parçanın birleşimidir. Kapsayıcılık herkesi eşit karşılamayı, çok dilli hizmet dil desteğini, hizmet kültürü ise işletmenin ortak alışkanlıklarını anlatır."},{"id":"go-2-s18","tur":"coktan-secmeli","soru":"Dolaylı iletişimi tercih eden bir konuk yemekten sonra “Çorba biraz tuzluydu galiba, belki bana öyle geldi” diyor. En olası anlamı nedir?","secenekler":["Yemeğin çok lezzetli olduğunu söylüyor.","Nazikçe şikâyet ediyor, çözüm bekliyor.","Şefin tebrik edilmesini istiyor.","Tuzluğu masadan kaldırmanızı istiyor."],"dogru":1,"aciklama":"Dolaylı iletişimde istek ima ve nezaketle söylenir; konuk “belki bana öyle geldi” diyerek şikâyetini yumuşatır. Çalışan bunu fark edip nazikçe özür dilemeli ve telafi önermelidir."},{"id":"go-2-s19","tur":"coktan-secmeli","soru":"Bir konuk lobide asansörün yerini soruyor. Farklı kültürlerden konuklar için en az riskli hareket hangisidir?","secenekler":["İşaret parmağıyla yönü göstermek","OK işaretiyle “şuradan” demek","Açık eli ve gülümsemeyle yönü göstermek","Baş parmağını kaldırarak yönü belirtmek"],"dogru":2,"aciklama":"Açık el ve hafif gülümseme hemen her kültürde iyi anlaşılır. Parmakla göstermek, baş parmak ve OK işareti bazı ülkelerde kaba ya da hakaret sayılabilir; yanlış anlaşılan konuk bunu söylemez, yalnız soğur."},{"id":"go-2-s20","tur":"dogru-yanlis","soru":"Bahşişin alışılmış olmadığı bir ülkeden gelen konuğun bahşiş bırakmaması, tek başına hizmeti beğenmediği anlamına gelmez.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Bahşiş kültürü ülkeden ülkeye değişir; bazı yerlerde beklenen, bazı yerlerde yadırganan bir davranıştır. Memnuniyeti bahşişle değil, konuğun sözü ve tavrıyla okumak gerekir."},{"id":"go-2-s21","tur":"coktan-secmeli","soru":"Tekerlekli sandalyeli bir konuk resepsiyonda işlem yapıyor. En doğru tutum hangisidir?","secenekler":["Hemen sandalyeyi itmeye başlamak","Yardım isteyip istemediğini konuğa sormak","Yanındaki refakatçiye hitap edip ona cevap vermek","İşlemi olabildiğince hızlandırıp konuğu yolcu etmek"],"dogru":1,"aciklama":"Yardımı sormak ama dayatmamak ve konuğun kendisine konuşmak temel kuraldır. İzinsiz itmek özerkliği zedeler, refakatçiyle konuşmak konuğu yok sayar, acele ettirmek ise değersizlik duygusu yaratır."},{"id":"go-2-s22","tur":"coktan-secmeli","soru":"Bir otel sınırlı bütçesini en etkili yere harcamak istiyor. Zirve-son kuralına göre bütçe nereye ayrılmalıdır?","secenekler":["Odadaki bütün eşyaları yenilemeye","Her günün ortalama kalitesini yükseltmeye","Güçlü bir an ile veda anını özenle tasarlamaya","Fiyat listesini sadeleştirmeye"],"dogru":2,"aciklama":"İnsan bir yaşantıyı en yoğun anı ve bitişiyle hatırlar; aradaki ortalama büyük ölçüde unutulur. Bu yüzden zirve anı ve ayrılış özenle tasarlanır, ortalamayı yükseltmek aynı etkiyi vermez."},{"id":"go-2-s23","tur":"coktan-secmeli","soru":"Bir otel, konukların en çok hangi adımda sıkıldığını görmek için rezervasyondan ayrılış sonrasına kadar her adımda ne hissettiklerini tek şemada çiziyor. Bu şemanın adı nedir?","secenekler":["Konuk yolculuğu haritası","Temas noktası listesi","Geri bildirim döngüsü","Konuk tercih profili"],"dogru":0,"aciklama":"Yolculuk haritası adımları ve her adımdaki duyguyu bir arada gösterir. Temas noktası listesi yalnız karşılaşma yerlerini sayar, duyguyu göstermez; geri bildirim döngüsü ise görüşün toplanıp düzeltmeye dönüşmesidir."},{"id":"go-2-s24","tur":"coktan-secmeli","soru":"Olumsuz bir çevrim içi yoruma telafi adımlarıyla herkesin okuyacağı biçimde cevap vermenin asıl hedefi nedir?","secenekler":["Yorumu yazan konuğu haksız çıkarmak","Yorumun sitede görünmesini engellemek","Yalnız konuğa özel mesajla dönmek","Aday konuklara hizmet anlayışını göstermek"],"dogru":3,"aciklama":"Cevap yalnız bir konuğa değil, yorumu okuyan herkese yazılır. Haksız çıkarmak ve susmak aday konukları kaybettirir; özel mesaj ise okuyanlara hiçbir şey göstermez."},{"id":"go-2-s25","tur":"senaryo","durum":"Sabah 10.00, kat görevlisi stajyerisin. Çamaşır arabasıyla dar bir koridordasın. Karşıdan telefonla konuşan bir konuk geliyor; seni görünce hafifçe kenara çekiliyor.","soru":"Ne yaparsın?","secenekler":["Arabayı itmeye devam eder, geçerken “pardon” der, işime bakarım.","Arabayı kenara çeker, yol verir, göz teması kurup kısaca gülümseyerek selam veririm.","Başımı eğer, konuk geçene kadar göz teması kurmadan beklerim.","Konuğa dönüp “Yardım edebilir miyim?” diye telefon görüşmesini bölerim."],"dogru":1,"aciklama":"Yol vermek, göz teması ve kısa selam 10-5 kuralının özüdür; telefonu bölmediği için sessiz hizmete de uyar. Hiç oralı olmamak karşılamayı atlar, görüşmeyi bölmek ise araya girmektir."},{"id":"go-2-s26","tur":"senaryo","durum":"Saat 15.00, resepsiyondasın. Giriş yapan konuk odasında deniz manzarası olmadığını görüp sinirleniyor: “Ben deniz manzarası için para ödedim!” Rezervasyonda böyle bir not yok; amirin öğle arasında, yarım saat sonra dönecek.","soru":"İlk adımın ne olur?","secenekler":["Ekranı çevirip “Rezervasyonda deniz manzarası notu yok” diye kanıt gösteririm.","Hemen “Bu gece ücretsiz olsun” diyerek konuğu sakinleştiririm.","Konuğu odasına gönderir, amirim dönünce kendisini arayacağımı söylerim.","Sözünü kesmeden dinler, özür diler, deniz manzaralı boş oda var mı diye bakarım."],"dogru":3,"aciklama":"Dinleme, özür ve harekete geçme sırası konuğu yatıştırır; boş oda bakmak çözüme yöneliktir. Kanıt göstermek savunmaya geçmek, ücretsiz gece yetki ve orantı dışı bir jest, konuğu göndermek ise sorunu ertelemektir."},{"id":"go-2-s27","tur":"senaryo","durum":"Akşam 20.00, restoranda servise yardım ediyorsun. Bir konuğun siparişi yanlış gelmiş; konuk “Önemli değil, bunu yerim” diyor ama yüzü asık. Garson başka bir masayla meşgul.","soru":"Ne yaparsın?","secenekler":["Özür diler, isterse doğru yemeği hemen getirteceğimi söyler, garsona haber veririm.","Konuk “önemli değil” dediği için konuyu kapatır, servise devam ederim.","Garson boşalana kadar bekler, o gelince konuyu ona anlatırım.","Mutfağa gidip hatanın kimde olduğunu öğrenir, konuğa “Mutfak karıştırmış” derim."],"dogru":0,"aciklama":"Konuğu okuyan çalışan sözle değil yüz ifadesiyle de anlar; sorunu sahiplenir, seçeneği konuğa bırakır ve ekibi haberdar eder. Konuyu kapatmak ya da beklemek memnuniyetsizliği büyütür, suçu mutfağa atmak ise bahane üretmektir."},{"id":"go-2-s28","tur":"senaryo","durum":"Saat 12.30, lobidesin. Yurt dışından bir iş grubunun lideri yaklaşıp hafifçe eğiliyor ve iki eliyle kartvizitini uzatıyor. El uzatmıyor.","soru":"Nasıl davranırsın?","secenekler":["Elimi uzatıp tokalaşmayı başlatır, kartı alıp hemen cebime koyarım.","Hafifçe eğilir, kartı tek elimle alıp selamlaşmaya devam ederim.","Hafifçe eğilerek selam verir, kartı iki elimle alır, bir an bakıp özenle saklarım.","Kartı almadan “Lütfen resepsiyona bırakın” der, grubu bankoya yönlendiririm."],"dogru":2,"aciklama":"Güvenli kural, el uzatmayı konuğun başlatması ve çalışanın onun seçtiği selamlaşma biçimine uymasıdır. Kartı iki elle almak, bakmak ve özenle saklamak saygı gösterir; tek elle alıp cebe koymak kabalık sayılabilir."},{"id":"go-2-s29","tur":"senaryo","durum":"Kahvaltı salonu, saat 08.30. Bir konuk sana “Bu böreğin içinde et var mı? Ben domuz eti yemiyorum” diye soruyor. Börek sana peynirli gibi görünüyor ama emin değilsin; şef mutfakta.","soru":"Ne yaparsın?","secenekler":["Böreğin görünüşüne bakıp “Peynirli görünüyor, rahat yiyebilirsiniz” derim.","“Kesin bilgiyi şefe soruyorum” der, mutfağa gider, kesin cevapla dönerim.","Şef mutfaktan dönene kadar konuğa “Sonra bakarız” der, diğer masalara geçerim.","“Bilmiyorum, malzemeler yazılı değil” deyip konuğun kendisinin karar vermesini isterim."],"dogru":1,"aciklama":"Dinî nedenle kısıtı olan konuğa tahminle cevap verilmez; kesin bilgi şefe sorularak öğrenilir. Tahmin güveni zedeler; konuyu ertelemek ya da kararı bilgisi olmayan konuğa bırakmak da çözüm sunmaz."},{"id":"go-2-s30","tur":"senaryo","durum":"Saat 11.00, çıkış saati. Bir konuk faturada tanımadığı bir mini bar kalemi görüp itiraz ediyor; sıra uzuyor, konuk uçağına yetişmek için acele ediyor. Amirin başka bir konukla ilgileniyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Özür diler, kalemi hemen kontrol edeceğimi söyler, amirime haber verip konuğu bilgilendiririm.","“Sistemde yazıyorsa konuk almıştır, sıra bekleyen var, lütfen ödemeyi yapın” der, ödemeyi isterim.","Kalemi kimseye sormadan kendi yetkimle silip, konuk uçağını kaçırmasın diye hızlıca yolcu ederim.","Konuğa kat hizmetlerini arayıp kalemi bizzat kendisinin sormasını, o arada sıranın yürümesini söylerim."],"dogru":0,"aciklama":"Konuğun itirazı dinlenir, sorun sahiplenilir ve yetki sınırı aşılmadan hızlıca çözüme bağlanır. Ödemeyi dayatmak konuğu suçlar, kalemi tek başına silmek yetki sınırını aşar, konuğu başka bölüme yollamak sahiplenmeyi bırakmaktır."},{"id":"go-2-s31","tur":"senaryo","durum":"Saat 17.00, konuk ilişkileri masasındasın. Günlük toplantıda bir konuğun bugün doğum günü olduğunu öğrendin. Konuk henüz odaya çıkmadı; bütçen küçük bir jestle sınırlı. Profilinde “çikolata sevmez” yazıyor.","soru":"Ne yaparsın?","secenekler":["Konuk gelince, tercihini bilmeden lobide herkesin önünde yüksek sesle kutlar, alkış başlatırım.","Çikolatalı küçük bir pasta hazırlatır, adını pastanın üstüne yazdırırım.","Bütçe küçük olduğu için bir şey yapmam; “nasılsa fark etmez” diye düşünürüm.","Amirime haber verir, odaya adıyla yazılmış kart ve meyve tabağı hazırlatırım."],"dogru":3,"aciklama":"Küçük ama kişiye özel jest, profile uyan ve orantılı olduğu için “wow” anı yaratır. Çikolatalı pasta tercih bilgisini yok sayar, herkesin önünde alkış konuğu rahatsız edebilir, hiçbir şey yapmamak fırsatı kaçırır."},{"id":"go-2-s32","tur":"senaryo","durum":"Saat 21.00, ön büro arka ofisindesin. Sosyal medyaya bakan görevliyle birliktesin. Bir seyahat sitesinde konuk şöyle yazmış: “Oda temiz, ama havuz kapalıydı, kimse haber vermedi; bir daha gelmem.” Görevli senden cevap taslağı istiyor.","soru":"Hangi taslağı yazarsın?","secenekler":["Havuz bakımının sitede duyurulduğunu belirtip konuğun dikkatsiz davrandığını anlatan bir taslak yazarım.","Olumsuz yorumlara cevap vermemeyi, yalnız iyi yorumlara teşekkür etmeyi öneririm.","Teşekkür eden, bahanesiz özür dileyen, çözüm söyleyen ve yeniden davet eden bir taslak yazarım.","Bakımın her otelde olağan olduğunu söyleyen kısa bir taslak yazarım."],"dogru":2,"aciklama":"Cevap, yorumu okuyan herkese yazıldığı için teşekkür, bahanesiz özür, çözüm ve yeniden davetten oluşur. Konuğu suçlamak ya da bakımı olağan göstermek savunmadır; cevap vermemek ise aday konukları kaybettirir."},{"id":"go-2-s33","tur":"coktan-secmeli","soru":"Bir otel, kendi isteğiyle görevlendirdiği bir kişiyi sıradan bir konuk gibi otelde ağırlıyor. Kişi ay sonunda havuz barındaki sipariş süresini ve garsonun konuğun adını kullanıp kullanmadığını raporluyor. Bu yöntemin adı nedir?","secenekler":["Anonim denetçi değerlendirmesi","Konaklama sonrası anket","Gizli müşteri denetimi","Günlük hizmet toplantısı"],"dogru":2,"aciklama":"Gizli müşteri denetiminde kişiyi otelin kendisi görevlendirir; amaç ceza değil, eksiği konuk gözüyle görmektir. Anonim denetçiden farkı, raporun otelin kendi isteğiyle yazılan bir iç denetim olmasıdır."},{"id":"go-2-s34","tur":"coktan-secmeli","soru":"Ön büro ekibi her sabah vardiya başında on dakika ayakta toplanıyor; şef günün VIP gelişlerini, dünkü bir aksaklığı ve günün hizmet değerini anlatıyor. Bu kısa toplantının hizmete en önemli katkısı nedir?","secenekler":["Konuk hangi çalışana denk gelse aynı hizmeti alır.","Vardiya sonundaki kasa sayımı daha hızlı biter.","Yazılı SOP dosyalarına artık gerek kalmaz.","Çalışanların yetki sınırı her sabah yeniden çizilir."],"dogru":0,"aciklama":"Günlük hizmet toplantısında ekip güne aynı bilgiyle başlar; bu yüzden konuk kime rastlarsa rastlasın aynı hizmeti alır. Toplantı standartları her gün tazeler, yazılı SOP’nin yerini tutmaz."},{"id":"go-2-s35","tur":"dogru-yanlis","soru":"Resepsiyonist karşılama cümlesini ekrana bakarak ve hızlıca söylese de standart yerine getirildiği için konuk kendini içtenlikle karşılanmış hisseder.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Standart davranışı yazar, sıcaklığı ise çalışan katar. Ezberlenmiş gibi söylenen cümlede standart “yapıldı” sayılır ama konuk karşılandığını hissetmez."},{"id":"go-2-s36","tur":"coktan-secmeli","soru":"Saat 16.00’da resepsiyon kuyruğu uzamıştır. Bekletme süresi standardına göre görevlinin sırada bekleyen konuklar için yapması gereken nedir?","secenekler":["Göz temasından kaçınıp işlemi olabildiğince hızlandırmak","Konukları bilgi vermeden lobide oturmaya göndermek","Telefonları sessize alıp yalnız bankodakiyle ilgilenmek","Sıradakilere dönüp süre bilgisi vermek, su ikram etmek"],"dogru":3,"aciklama":"Lüks otelde yalnız bekleme süresi değil, beklerken yapılanlar da ölçülür: göz teması, bilgi verme ve ikram. Böylece bekleyen konuk ağırlandığını hisseder."},{"id":"go-2-s37","tur":"coktan-secmeli","soru":"Bir konuk kahvaltıda sohbet arasında kızının o gün doğum günü olduğunu söylüyor. Akşam odaya kızın adı yazılı küçük bir pasta bırakılıyor. Bu jesti “wow” anı yapan asıl özellik hangisidir?","secenekler":["Pahalı ve gösterişli bir hediye olması","Her konuğa aynı biçimde verilmesi","Beklenmedik ve kişiye özel olması","Konuğun önceden talep etmiş olması"],"dogru":2,"aciklama":"Wow anının pahalı olması gerekmez; tek şartı beklenmedik ve kişisel olmasıdır. Herkese verilen hediye zamanla beklentiye dönüşür, kişiye özel olan ise hikâye olur."},{"id":"go-2-s38","tur":"coktan-secmeli","soru":"Çorbası soğuk gelen konuk, stajyerden o akşamki yemeğinin ücretsiz sayılmasını istiyor. Bu kararı verme yetkisi olmayan stajyerin en doğru cevabı hangisidir?","secenekler":["“Tamam, bu akşam yemeğiniz bizden.”","“Bunu müdürümle hemen görüşüp size döneceğim.”","“Maalesef bu konuda yapabileceğim bir şey yok.”","“Şikâyetinizi yazılı olarak resepsiyona bırakın.”"],"dogru":1,"aciklama":"Yetki sınırını bilen çalışan tutamayacağı söz vermez, konuğu çaresiz de bırakmaz; kararı amirine taşır ve konuğa döner. “Yemeğiniz bizden” demek stajyerin yetkisini aşar."},{"id":"go-2-s39","tur":"coktan-secmeli","soru":"Bütün gece odasını su basan bir konuğa sunulacak telafilerden hangisi orantılıdır?","secenekler":["Oda değişimi, ücretsiz gece ve müdürün özrü","Odaya not ile bir tabak kurabiye bırakmak","Kahvaltıda ücretsiz bir fincan kahve sunmak","Çıkışta sözlü özür ve teşekkür kartı vermek"],"dogru":0,"aciklama":"Orantılı telafide jestin büyüklüğü sorunun büyüklüğüne uyar. Büyük bir soruna küçük bir ikramla karşılık vermek konuğu daha da kırar."},{"id":"go-2-s40","tur":"dogru-yanlis","soru":"Klima arızası giderilen bir konuğu birkaç saat sonra arayıp odasının şimdi nasıl olduğunu sormak gereksizdir; telafi, arıza giderildiği anda biter.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Telafi, sorun giderildiğinde değil, konuk “çözüldü” dediğinde biter. Sonradan aramak, otelin konuğu unutmadığını gösteren güçlü bir jesttir."},{"id":"go-2-s41","tur":"coktan-secmeli","soru":"Rezervasyonda adı “Wang Li” olarak yazılan bir konuk resepsiyona geliyor. Görevli adın hangi kısmının soyadı olduğundan emin değil. Ne yapmalıdır?","secenekler":["İkinci kelimeyi soyadı sayıp “Bay Li” demek","Hiç isim kullanmadan yalnız “efendim” demek","İlk kelimeyi ad sayıp samimi biçimde hitap etmek","Nasıl hitap edilmek istediğini nazikçe sormak"],"dogru":3,"aciklama":"Bazı kültürlerde soyadı önce yazılır; emin olunmadığında tahmin yürütmek yerine sormak kibarlıktır. Yanlış isim söylemek, hiç isim söylememekten de kötüdür."},{"id":"go-2-s42","tur":"coktan-secmeli","soru":"Ana dili İngilizce olmayan bir konuk kahvaltı saatini soruyor. Hangi cevap konukla sade İngilizce ilkesine en uygundur?","secenekler":["“Feel free to grab a bite at our F&B outlet downstairs.”","“Breakfast is from seven to ten, on the ground floor.”","“B’fast is 7–10 at the GF resto, can’t miss it.”","“Just pop down to the restaurant whenever you fancy.”"],"dogru":1,"aciklama":"Sade İngilizcede kısa ve açık cümle kurulur; deyim ve kısaltma kullanılmaz. Öteki cevaplar “grab a bite”, “F&B”, “GF” gibi ifadelerle ya da saat vermeyen bir deyimle konuğu zorlar."},{"id":"go-2-s43","tur":"coktan-secmeli","soru":"Lüks oteller kapıda karşılamadan faturaya kadar her temas noktasını tek tek listeleyip her birine ayrı bir standart yazar. Bunun nedeni hangisidir?","secenekler":["Konuk yalnız odada geçirdiği zamana bakarak karar verir.","Listelenen her adım otelin yıldız sayısını artırır.","Standart yazılınca konukla yüz yüze temas azalır.","Tek bir kötü an, birçok iyi anın etkisini gölgeler."],"dogru":3,"aciklama":"Konuk oteli temas noktalarının toplamıyla değerlendirir ve tek bir kötü nokta on iyi noktayı gölgeleyebilir. Bu yüzden her temas ayrı ayrı ele alınıp standarda bağlanır."},{"id":"go-2-s44","tur":"dogru-yanlis","soru":"Odanın 14.30’da hazır olacağını bilen resepsiyonistin konuğa “Odanız en geç 15.00’te hazır” deyip 14.30’da araması, söz verirken beklenti ayarına uygun bir davranıştır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Beklenti ayarında tutulabilecek kadar söz verilir ve mümkünse fazlası yapılır. Konuk erken haber alınca memnun kalır; 14.00 deyip 14.30’da arasaydı geç kalındığını düşünürdü."}],"siralamalar":[{"id":"go-2-r01","konu":"2.1","baslik":"Restoranda bir konuk: kapıdan uğurlamaya","yonerge":"Restorana gelen bir konuğa hizmetin üç adımını uygularken izlediğin adımları doğru sıraya koy.","adimlar":["Masaya doğru gelen konukla göz teması kur ve gülümse.","Konuk yanına geldiğinde “Hoş geldiniz” diyerek sözlü selam ver.","Menüde vejetaryen yemek aradığını fark et ve ona uygun bir yemek öner.","Konuk kalkarken adıyla teşekkür et ve yeniden bekleyeceğini söyle."],"aciklama":"Hizmetin üç adımı karşıla, öngör, uğurla diye ilerler; karşılamada 10-5 kuralı gereği göz teması ve gülümseme uzaktan, sözlü selam yakından gelir."},{"id":"go-2-r02","konu":"2.2","baslik":"Yulaf sütünün yolculuğu","yonerge":"Bir konuk tercihinin fark edilip ertesi gün karşılanmasına kadar geçen adımları doğru sıraya koy.","adimlar":["Garson, kahvaltıda konuğun her sabah süt yerine yulaf sütü istediğini fark eder.","Garson vardiya sonunda bu tercihi konuğun profiline işler.","Ertesi sabah başka bir garson vardiyaya başlar ve profili görür.","Konuk hiçbir şey söylemeden kahvesini yulaf sütüyle alır."],"aciklama":"Kişiselleştirme ekip işidir: fark edilen tercih profile yazılmadıkça başka çalışana ulaşmaz, yazıldığında ise konuk istemeden karşılanır."},{"id":"go-2-r03","konu":"2.3","baslik":"Uykusuz geçen gece: LEARN ile çözüm","yonerge":"Gürültüden uyuyamadığını söyleyen konuğun şikâyetini LEARN modeline göre çözerken adımları doğru sıraya koy.","adimlar":["Konuğun anlattıklarını sözünü kesmeden sonuna kadar dinle.","Uykusuz bir gecenin onun için ne kadar zor olduğunu anladığını göster.","Bahane göstermeden içtenlikle özür dile.","Amirinle konuşup konuğun sessiz bir odaya geçişini ayarla.","Yaşananı ve yapılan çözümü konuğun profiline yaz, şefine bildir."],"aciklama":"LEARN modelinin sırası dinle, anla, özür dile, harekete geç ve bildir şeklindedir; son adım unutulursa aynı aksaklık yarın yeniden yaşanır."},{"id":"go-2-r04","konu":"2.5","baslik":"Konuk yolculuğu haritasını çiz","yonerge":"Konuk yolculuğu haritasındaki adımları, konuğun yaşadığı sırayla doğru sıraya koy.","adimlar":["Konuk internette otelleri araştırır ve rezervasyon yapar.","Konuk otele ulaşır ve kapıda karşılanır.","Konuk resepsiyonda giriş işlemini tamamlar.","Konuk odasına yerleşir, otelin restoranında yemek yer.","Konuk çıkış işlemini yapar ve uğurlanır.","Konuk eve döndükten sonra konaklama anketini doldurur ya da çevrim içi yorum yazar."],"aciklama":"Konuk yolculuğu haritası rezervasyondan ayrılış sonrasına kadar her adımı konuğun gözünden sıralar; deneyim konuk oteli ilk aradığında başlar, ayrıldıktan sonra yazdığı yorumla da sürer."}],"acikSorular":[{"id":"go-2-y01","konu":"2.3","soru":"Bir lüks otelde akşam yemeği için ayrılan masa konuğa verilen saatte hazır değildir ve konuk yirmi dakika bekletilmiştir. Karşılayan çalışanın konuğu yeniden kazanmak için izleyeceği adımları yazınız ve bu adımların neden gerekli olduğunu açıklayınız.","olcut":[{"metin":"Olayı bir hizmet aksaklığı olarak tanımlar (verilen söz ya da beklenen standart yerine getirilmemiştir).","puan":10},{"metin":"Konuğu kesmeden dinleyip duygusunu anladığını gösterir.","puan":15},{"metin":"Bahane göstermeden ve “ama” demeden içten özür dilemeyi belirtir.","puan":15},{"metin":"Soruna uygun (orantılı) bir çözüm ya da telafi jesti önerir.","puan":15},{"metin":"Çözümden sonra konuğa dönüp takip ettiğini ya da olayı amire bildirdiğini belirtir.","puan":15},{"metin":"Telafinin neden gerekli olduğunu, konuğun güveninin yeniden kazanılmasıyla ilişkilendirerek açıklar.","puan":30}],"ornek":"Konuğun beklemesi, otelin verdiği sözün yerine getirilememesidir; yani bir hizmet aksaklığıdır. Çalışan önce konuğu kesmeden dinler ve bekleme yüzünden sinirlendiğini anladığını söyler. Sonra bahane göstermeden, “ama” demeden içten özür diler. Ardından sorunun büyüklüğüne uygun bir çözüm sunar; örneğin masayı hemen hazırlar ve yemeğe küçük bir ikramla başlar. Son olarak yemek sırasında konuğa dönüp memnun olup olmadığını sorar ve olayı amire bildirir. Bu adımlar gereklidir, çünkü iyi telafi edilen bir aksaklık konuğun güvenini geri kazandırır ve hatta onu hiç sorun yaşamamış konuktan daha bağlı yapabilir.","ipucu":"Konuğun yaşadığı duyguyu önce ele almakla çözümü sunmak arasındaki sırayı düşünün."},{"id":"go-2-y02","konu":"2.5","soru":"Bir otel müdürü, konuğun odaya girdiği ilk dakikayı ve otelden ayrılırkenki son anı özel olarak tasarlamak istiyor. Bu iki anı tasarlamanın konuğun otel hakkındaki anısını nasıl etkilediğini zirve-son kuralı ve temas noktası kavramlarını kullanarak açıklayınız ve her an için bir örnek veriniz.","olcut":[{"metin":"Temas noktasını doğru tanımlar (konuğun otelle karşılaştığı ve izlenim edindiği her an ya da yer).","puan":20},{"metin":"Zirve-son kuralını doğru açıklar (yaşantı en yoğun anı ve bitişiyle hatırlanır).","puan":25},{"metin":"Odaya giriş (karşılama) anı için somut bir tasarım örneği verir.","puan":15},{"metin":"Uğurlama anı için somut bir tasarım örneği verir.","puan":15},{"metin":"Bu anların konuğun genel anısını ve otele bağlılığını neden belirlediğini bağlantı kurarak açıklar.","puan":25}],"ornek":"Temas noktası, konuğun otelle karşılaştığı ve izlenim edindiği her andır; karşılama ve uğurlama da birer temas noktasıdır. Zirve-son kuralına göre insan bir yaşantıyı en yoğun anıyla ve bitişiyle hatırlar, aradaki ortalamayı büyük ölçüde unutur. Bu yüzden karşılamada konuğu adıyla selamlamak ve odada ona özel küçük bir not bırakmak güçlü bir ilk izlenim yaratır. Uğurlamada ise konuğu adıyla ve içten bir dilekle aceleye getirmeden yolcu etmek, anının son kısmını güzelleştirir. Konuk bu iki anı hatırlayacağı için tüm konaklamayı olumlu anlatır ve otele duygusal olarak bağlanır.","ipucu":"İnsanın bir konaklamanın hangi kısımlarını hatırlayıp hangilerini unuttuğunu düşünün."}]},{"ders":"global-otelcilik","sinif":9,"unite":3,"baslik":"Dünyada Turizm Eğitimi ve Kariyer","onay":true,"kazanimlar":["Dünyanın önde gelen otelcilik ve turizm okullarını ve onların eğitim anlayışını tanır.","Otelcilik ve turizmde stajyerlikten üst yönetime uzanan kariyer yollarını ve departmanlar arası geçişleri açıklar.","Dünya otelciliğinde aranan beceri ve tutumları kendi gelişim planıyla ilişkilendirir.","Dünya otelciliğinde sürdürülebilirlik ve teknoloji eğilimlerinin mesleğe etkisini yorumlar."],"soz":"Bu meslekte merdiven vardır; ama her basamağı sahada öğrenen çıkar.","dersler":[{"baslik":"Önce Hizmet, Sonra Yönetim","ilk":"go-3-001"},{"baslik":"Üç Kıtadan Üç Okul","ilk":"go-3-005"},{"baslik":"Alplerden Lahey’e","ilk":"go-3-008"},{"baslik":"Sınıftan Otele","ilk":"go-3-011"},{"baslik":"Senin Yolun Nereye?","ilk":"go-3-015"},{"baslik":"Merdivenin Basamakları","ilk":"go-3-019"},{"baslik":"Basamak Atlatan Rotalar","ilk":"go-3-024"},{"baslik":"Bavulunu Hazırla","ilk":"go-3-028"},{"baslik":"Otelin Dışındaki Kapılar","ilk":"go-3-030"},{"baslik":"Komşu Meslekler","ilk":"go-3-033"},{"baslik":"Mülakat Kapısından Önce","ilk":"go-3-036"},{"baslik":"Beceri Çantası","ilk":"go-3-040"},{"baslik":"Zor Günün Becerileri","ilk":"go-3-044"},{"baslik":"Görünmeyen Güç","ilk":"go-3-047"},{"baslik":"Hatadan Öğrenmek","ilk":"go-3-050"},{"baslik":"Öğrenmenin Sonu Yok","ilk":"go-3-054"},{"baslik":"Doğaya Saygılı Otel","ilk":"go-3-057"},{"baslik":"Su, Enerji ve Yöre","ilk":"go-3-061"},{"baslik":"Dijital Konuk, İnsan Kalbi","ilk":"go-3-065"},{"baslik":"Teknoloji Gelse de","ilk":"go-3-068"}],"kavramlar":[{"id":"go-3-001","konu":"3.1","terim":"Otelcilik okulu","ingilizce":"Hospitality school","tanim":"Otel, restoran ve turizm işletmelerinde çalışacak kişileri hem derste hem uygulamada yetiştiren eğitim kurumudur.","ornek":"Mayıs ayında Antalya’daki bir resortun insan kaynakları görevlisi, yaz stajına gelen öğrencilere ilk hafta restoranda, ikinci hafta kat hizmetlerinde çalışacaklarını anlatır.","sektor":"Dünyadaki otelcilik okullarının ortak özelliği, sınıfta öğrenileni gerçek işletmede denemektir. Sektör bu yüzden mezunun işi hem kuramdan hem sahadan bildiğini bekler; senin okulundaki staj da aynı mantığın parçasıdır.","iliskili":["go-3-002","go-3-003","go-3-004"],"kontrol":null,"kitapDisi":true},{"id":"go-3-002","konu":"3.1","terim":"Uygulamalı eğitim","ingilizce":"Hands-on learning","tanim":"Öğrencinin bilgiyi yalnız dinleyerek değil, işi bizzat yaparak öğrendiği eğitim biçimidir.","ornek":"Salı sabahı okulun uygulama mutfağında öğrenci kahvaltı büfesini sunum kurallarına göre kurar; yanlış dizdiği tabağı şefi görmeden önce kendisi düzeltir.","sektor":"Otelcilikte hata konuğun önünde görünür. Uygulamalı eğitim, hatayı konuk yokken yapıp düzeltmeyi sağlar; bu yüzden dünyadaki otelcilik okullarında eğitimin önemli bir bölümü atölye ve stajdır.","iliskili":["go-3-001","go-3-003","go-3-011"],"kontrol":null,"kitapDisi":true},{"id":"go-3-003","konu":"3.1","terim":"Önce hizmet etmeyi öğrenme","ingilizce":"Learning to serve before leading","tanim":"Yönetici olmak isteyen kişinin önce servis, oda temizliği ya da resepsiyon gibi işleri kendi eliyle yapması gerektiğini savunan eğitim anlayışıdır.","ornek":"İstanbul’daki bir şehir otelinde stajyer ilk ayını kahvaltı servisinde geçirir; ileride müdür olmak istese de önce tepsi taşımayı ve konuğun çay isteğini fark etmeyi öğrenir.","sektor":"Lozan’daki EHL gibi okullar eğitimin başında mutfak ve servis gibi uygulamalara yer verir. Ekibinin yaptığı işi bilen yönetici gerçekçi istekte bulunur ve ekibinin saygısını kazanır.","iliskili":["go-3-002","go-3-005","go-3-011"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-kahve-tepsisi"},{"id":"go-3-004","konu":"3.1","terim":"Uygulama oteli","ingilizce":"Teaching hotel","tanim":"Bir okulun öğrencileri yetiştirmek için sahip olduğu ya da işlettiği, gerçek konuk ağırlayan oteldir.","ornek":"Cumartesi öğleden sonra bir turizm okulunun uygulama otelinde öğrenci, gelen gerçek konuğun kaydını öğretmeninin gözetiminde yapar.","sektor":"Cornell (Statler Otel) ve Hong Kong PolyU (Hotel ICON) bu fikrin bilinen örnekleridir: otel hem sınıf hem laboratuvardır. Öğrenci gerçek konukla çalıştığı için işe başlamadan önce yoğunluğu ve şikâyeti nasıl karşılayacağını görür.","iliskili":["go-3-002","go-3-006","go-3-007"],"kontrol":null,"kitapDisi":true},{"id":"go-3-005","konu":"3.1","terim":"Lozan Otelcilik Okulu (EHL)","ingilizce":"EHL Hospitality Business School","tanim":"İsviçre’nin Lozan kentinde bulunan, uygulamalı eğitimi ve staj düzeniyle tanınan uluslararası bir otelcilik ve işletme okuludur.","ornek":"Antalya’daki bir resortun müdürü, yeni yönetici adayının özgeçmişinden EHL’de okurken mutfak ve servis uygulamalarında da çalıştığını okur ve ona önce saha görevi verir.","sektor":"Okulun anlayışı “önce operasyonu bil, sonra yönet” çizgisindedir; stajın bir bölümü sahada, bir bölümü yönetim görevinde yapılır. Dünya otelciliğinde okulun adı tanıdıktır, ama iş her zaman sahadaki performansla kazanılır.","iliskili":["go-3-003","go-3-011","go-3-012"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-ehl-ana-giris"},{"id":"go-3-006","konu":"3.1","terim":"Cornell Nolan Otelcilik Okulu","ingilizce":"Nolan School of Hotel Administration, Cornell University","tanim":"ABD’de Cornell Üniversitesi içinde otelcilik yönetimini üniversite düzeyinde öğreten ve bu alanda araştırma yapan okuldur.","ornek":"İzmir’de bir otelin satış müdürü, bu okulun herkese açık araştırma yazılarından birini okur ve fiyat toplantısında ekibine özetler.","sektor":"Kampüsteki Statler Otel, öğrencilerin hem çalışıp hem öğrendiği bir uygulama otelidir. Okulda yetişenler kararlarını yalnız sezgiyle değil araştırma ve veriyle de desteklemeyi öğrenir.","iliskili":["go-3-004","go-3-007","go-3-005"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-cornell-statler"},{"id":"go-3-007","konu":"3.1","terim":"Hong Kong PolyU Otel ve Turizm Yönetimi Okulu","ingilizce":"School of Hotel and Tourism Management, The Hong Kong Polytechnic University","tanim":"Asya’da, Hong Kong’daki Politeknik Üniversitesi içinde otelcilik ve turizm yönetimi eğitimi veren ve bu alanda araştırma yapan okuldur.","ornek":"İstanbul’daki bir otelin eğitim sorumlusu, Asyalı konuk gruplarını daha iyi ağırlamak için Asya turizmi üzerine yazılmış bir akademik özeti ekibiyle paylaşır.","sektor":"Okul, kendisine ait Hotel ICON adlı otelle bilinir; otel hem eğitim hem araştırma aracıdır. Asya turizmini anlamak isteyenlerin başvurduğu kaynaklar arasında bu okulun çalışmaları da vardır.","iliskili":["go-3-004","go-3-006","go-3-005"],"kontrol":null,"kitapDisi":true},{"id":"go-3-008","konu":"3.1","terim":"Les Roches Otelcilik Okulu","ingilizce":"Les Roches","tanim":"İsviçre’nin Alp bölgesinde kurulu, birden fazla ülkede yerleşkesi bulunan ve uygulamalı otelcilik eğitimi veren özel bir okuldur.","ornek":"Kapadokya’da bir butik otelin müdürü, yeni gelen ön büro görevlisinin Les Roches’ta okuduğunu özgeçmişinden görür ve ondan yabancı konuklarla yazışmaları üstlenmesini ister.","sektor":"Öğrencileri birçok ülkeden gelir; derslerin yanında uygulama ve staj da programın içindedir. Bu çok kültürlü ortam, otelcilikte sık karşılaşacağın konuk çeşitliliğine erkenden alıştırır.","iliskili":["go-3-009","go-3-005","go-3-010"],"kontrol":null,"kitapDisi":true,"cizim":"otel-bina"},{"id":"go-3-009","konu":"3.1","terim":"Glion Yüksek Eğitim Enstitüsü","ingilizce":"Glion Institute of Higher Education","tanim":"İsviçre’de Montreux yakınında kurulu, lüks otelcilik ve hizmet yönetimi alanlarıyla tanınan bir yükseköğretim okuludur.","ornek":"Bodrum’daki bir otelde işe yeni başlayan yönetici adayı, Glion’da okuduğunu anlatır; şef ona önce kat hizmetleri turu yaptırır ve işi sahada görmesini ister.","sektor":"Okul lüks otelcilik ve hizmet yönetimi alanlarına odaklanır; derslerin yanında uygulama ve staj da programın içindedir. “İşi yaparak öğren” anlayışının bir başka örneğidir. Lüks hizmette ayrıntıya dikkat, mezundan en çok beklenen özelliklerdendir.","iliskili":["go-3-008","go-3-003","go-3-011"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-glion-enstitusu"},{"id":"go-3-010","konu":"3.1","terim":"Hotelschool The Hague (Lahey Otelcilik Okulu)","ingilizce":"Hotelschool The Hague","tanim":"Hollanda’da Lahey ve Amsterdam’da yerleşkeleri bulunan, otelcilik yönetimine odaklanan uygulamalı bilimler okuludur.","ornek":"Antalya’da meslek lisesinde okuyan bir öğrenci, Avrupa’daki otelcilik okullarının internet sitelerine bakar ve Hotelschool The Hague’in hangi programları sunduğunu ileride yurt dışında lisans için bir seçenek olarak not eder.","sektor":"Dünya otelciliğinde otelcilik okulu yalnız İsviçre’de aranmaz; Hollanda gibi başka ülkelerdeki okullar da yönetimi uygulamayla birleştirir. Birçok ülkeden gelen öğrencileriyle bu okullar sektöre uluslararası bir tanışıklık ağı kazandırır.","iliskili":["go-3-008","go-3-014","go-3-005"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-hotelschool-lahey-girisi"},{"id":"go-3-011","konu":"3.1","terim":"Operasyon stajı","ingilizce":"Operational internship","tanim":"Öğrencinin ön büro, kat hizmetleri, mutfak ya da servis gibi sahadaki işleri bir otelde bizzat yaptığı staj türüdür.","ornek":"Haziranda Fethiye’deki bir tatil köyünde stajyer sabah resepsiyonda anahtar teslim eder, öğleden sonra restoranda masa kurar.","sektor":"Dünya otelcilik okulları ilk stajı çoğunlukla bu türden ister; çünkü yöneticilik, işi yapanın zorluklarını bilmekle başlar. Bu stajda öğrendiğin saha bilgisi sonraki her kararın temelidir.","iliskili":["go-3-012","go-3-003","go-3-013"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-012","konu":"3.1","terim":"Yönetim stajı","ingilizce":"Management internship","tanim":"Öğrencinin bir bölümü yöneterek ya da yönetime destek vererek planlama ve ekip yönetimi işlerine yaklaştığı ikinci aşama stajdır.","ornek":"Kuşadası’ndaki bir otelde lisans öğrencisi, ön büro müdürünün yanında vardiya çizelgesi hazırlar ve haftalık doluluk raporunu sunar.","sektor":"Bazı okullarda bu staj otelcilik dışındaki bir sektörde de yapılabilir; çünkü otelde öğrenilen yönetim becerileri başka alanlarda da geçerlidir. Bu esneklik mezuna yeni kariyer kapıları açar.","iliskili":["go-3-011","go-3-019","go-3-033"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-013","konu":"3.1","terim":"İşletmede mesleki eğitim","ingilizce":"Work-based vocational training","tanim":"Meslek lisesi öğrencilerinin eğitimlerinin bir bölümünü okulda değil, gerçek bir işletmede iş yaparak tamamladıkları eğitim düzenidir.","ornek":"Meslek lisesi öğrencisi Elif, eğitim yılının bir bölümünü Alanya’daki bir otelin kat hizmetlerinde geçirir; kalan zamanda okulda ders görür.","sektor":"Dünyanın birçok ülkesinde meslek eğitimi okul ve işletmenin birlikte yürüttüğü bir düzendir. Öğrenci gerçek iş disiplinini görür ve bazen aynı işletmede çalışmaya devam etme fırsatı bulur.","iliskili":["go-3-015","go-3-011","go-3-020"],"kontrol":null,"kitapDisi":true},{"id":"go-3-014","konu":"3.1","terim":"Uluslararası öğrenci değişimi","ingilizce":"International student exchange","tanim":"Öğrencinin eğitiminin ya da stajının bir bölümünü başka bir ülkede yapmasına olanak veren programlardır.","ornek":"Ankara’da meslek lisesi öğrencisi Ayşe, Erasmus+ duyurusunu okulunun panosunda görür ve sorumlu öğretmenine yurt dışında staj için başvuru koşullarını sorar.","sektor":"Erasmus+, Avrupa Birliğinin eğitim, gençlik ve spor alanındaki programıdır; kapsamındaki hareketlilik desteği, Türkiye’deki meslek lisesi ve üniversite öğrencilerine yurt dışında öğrenim ya da staj fırsatı sunabilir. Katılım koşulları ve kontenjanlar her dönem okulun sorumlu öğretmeninden öğrenilir. Başka ülkede öğrenmek dil, kültür ve iş yapma biçimi konusunda çok şey öğretir.","iliskili":["go-3-013","go-3-028","go-3-010"],"kontrol":null,"kitapDisi":true},{"id":"go-3-015","konu":"3.1","terim":"Turizm meslek lisesi","ingilizce":"Vocational high school for tourism","tanim":"Ortaöğretimde öğrenciye genel kültür derslerinin yanında otelcilik ve seyahat alanında meslek dersleri ve işletme eğitimi veren okul türüdür.","ornek":"9. sınıftaki Mert bu yıl Genel Turizm ile Otelcilik ve Seyahat Hizmetleri derslerini alıyor; öğretmeni ona ileride hangi alanlarda ilerleyebileceğini anlatır.","sektor":"Dünya otelciliğinde de çalışmaya başlamanın bir kapısıdır: lisede aldığın temel hizmet bilgisi, yabancı dil ve staj deneyimi seni ilk işe hazırlar. İstersen okula devam edip yükseköğretime de geçebilirsin.","iliskili":["go-3-016","go-3-017","go-3-013"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-karaman-otelcilik-lisesi"},{"id":"go-3-016","konu":"3.1","terim":"Önlisans (meslek yüksekokulu)","ingilizce":"Associate degree","tanim":"Liseden sonra genellikle iki yıl süren, uygulama ağırlıklı yükseköğretim programıdır; turizmde ön büro, aşçılık, seyahat gibi dalları vardır.","ornek":"Lise ikinci sınıftaki Zeynep, yakınındaki meslek yüksekokulunun otel hizmetleri bölümünü ve oradaki uygulama derslerini inceler.","sektor":"Önlisans çoğu zaman sahada çalışmaya daha hızlı geçmeyi sağlar; mezun bir alanda uzmanlaşıp süpervizör basamağına yönelebilir. Dersle uygulamayı birleştirdiği için dünyadaki uygulamalı otelcilik okullarının mantığına benzer.","iliskili":["go-3-015","go-3-017","go-3-018"],"kontrol":null,"kitapDisi":true},{"id":"go-3-017","konu":"3.1","terim":"Turizm fakültesi (lisans)","ingilizce":"Tourism faculty (bachelor's degree)","tanim":"Üniversitede genellikle dört yıl süren, turizm ve otel işletmeciliğini planlama, yönetim ve araştırma boyutuyla öğreten lisans eğitimidir.","ornek":"Üniversite ikinci sınıf öğrencisi Can, gelir yönetimi dersinde 100 odalı bir otelin doluluğunu ve oda başına gelirini hesaplar.","sektor":"Lisans diploması, zincirlerin yönetici adayı programlarına başvurmayı kolaylaştırır; markalı otel şirketleri otelcilik ya da işletme lisansı olan adayları tercih edebilir. Yine de sahayı bilmeyen yönetici zorlanır; bu yüzden çoğu fakültede staj da vardır.","iliskili":["go-3-016","go-3-018","go-3-024"],"kontrol":null,"kitapDisi":true},{"id":"go-3-018","konu":"3.1","terim":"Dikey geçiş","ingilizce":"Transfer from associate to bachelor's degree","tanim":"Önlisans mezununun belirli koşulları sağlayarak lisans programına geçip eğitimine devam edebilmesidir.","ornek":"Önlisansı bitiren Selin, çalışırken lisans eğitimine geçmek için dikey geçiş koşullarını üniversitenin öğrenci işlerinden öğrenir.","sektor":"Bu yol, meslek lisesinden üst yönetime uzanan yolu kapatmaz: lise, önlisans ve lisans basamakları art arda gidilebilir. Dünya otelciliğinde de çalışıp sonra okumak, okuyup sonra çalışmak yaygındır.","iliskili":["go-3-016","go-3-017","go-3-019"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-019","konu":"3.2","terim":"Kariyer merdiveni","ingilizce":"Career ladder","tanim":"Bir çalışanın stajyerlikten başlayıp süpervizörlük, bölüm yöneticiliği ve genel müdürlük gibi daha sorumlu görevlere ilerlediği basamaklar dizisidir.","ornek":"Marmaris’te bir tatil köyünün genel müdürü, yeni stajyerlere kariyerine çocuk kulübü ekibinde başladığını anlatır ve her basamakta ne öğrendiğini sıralar.","sektor":"Dünya otelciliğinde yükselme çoğunlukla sahadan gelir: ön büro, kat hizmetleri ya da yiyecek içecek bölümünden yükselenler genel müdürlüğe kadar çıkabilir. Her basamakta işin bir yönünü öğrenirsin; basamak atlamak yerine her basamağa sağlam basmak kalıcı yükselmenin yoludur.","iliskili":["go-3-020","go-3-021","go-3-023"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-020","konu":"3.2","terim":"Stajyer","ingilizce":"Intern","tanim":"Mesleği öğrenmek için belirli bir süre, deneyimli çalışanların gözetiminde bir işletmede çalışan kişidir.","ornek":"Sabah 07.00, Bodrum’daki otelin resepsiyonunda stajyer Deniz çıkış listesini hazırlar ve ön büro şefinin gözetiminde bir konuğun hesabını kapatmaya yardım eder.","sektor":"Zincirler genç yeteneği çoğu zaman stajda fark eder. İyi bir stajyer işin yalnız görünen yüzünü değil, gece vardiyasını ve arka tarafını da öğrenir; referansı da sonraki iş başvurularında onunla gelir.","iliskili":["go-3-019","go-3-021","go-3-011"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-021","konu":"3.2","terim":"Giriş seviyesi görev","ingilizce":"Entry-level position","tanim":"Mesleğe yeni başlayanın, uzun deneyim aranmadan alınabildiği resepsiyon görevlisi, oda görevi ya da servis yardımcılığı gibi ilk iş pozisyonudur.","ornek":"Antalya’da bir otelin ilanında “ön büro görevlisi, deneyim şart değildir” yazar; meslek lisesinden yeni mezun Burak bu ilana başvurur.","sektor":"Giriş görevi engel değil, kapıdır. Burada vardiya düzenini, konuk türlerini ve bölümlerin birbirine nasıl bağlandığını öğrenirsin; bu temel sonraki basamakların hepsinde işine yarar.","iliskili":["go-3-020","go-3-022","go-3-019"],"kontrol":null,"kitapDisi":true},{"id":"go-3-022","konu":"3.2","terim":"Süpervizör","ingilizce":"Supervisor","tanim":"Bir vardiyada ya da küçük bir ekipte işin akışını izleyen, görev dağıtan ve sorun çıkınca ilk başvurulan kişidir.","ornek":"Gece 02.00’de ön büroda vardiya süpervizörü asansörün arızalandığını fark eder, teknik servisi arar ve bagaj görevlisinden konuklara merdivende yardım etmesini ister.","sektor":"Yöneticiliğin ilk basamağıdır: artık yalnız kendi işinden değil ekibin işinden de sorumlusun. Bu aşamada terfi, iyi çalışmaktan çok başkalarının da iyi çalışmasını sağlamakla ilgili hâle gelir.","iliskili":["go-3-021","go-3-023","go-3-043"],"kontrol":null,"kitapDisi":true,"cizim":"lider"},{"id":"go-3-023","konu":"3.2","terim":"Bölüm yöneticisi","ingilizce":"Head of department","tanim":"Ön büro, kat hizmetleri, mutfak ya da satış gibi bir bölümün bütün işleyişinden, bütçesinden ve ekibinden sorumlu yöneticidir.","ornek":"İstanbul’da bir otelin kat hizmetleri müdürü, haftalık doluluk raporuna bakarak yarın kaç oda görevlisinin çalışacağını belirler.","sektor":"Bu basamakta konuktan çok ekibi ve rakamları yönetirsin. Bölüm yöneticisi genellikle genel müdüre bağlıdır; dünya otelciliğinde genel müdür adayları çoğunlukla önce bir bölümü başarıyla yönetmiş kişilerdir.","iliskili":["go-3-022","go-3-019","go-3-025"],"kontrol":null,"kitapDisi":true},{"id":"go-3-024","konu":"3.2","terim":"Yönetici adayı programı","ingilizce":"Management trainee programme","tanim":"Büyük otel gruplarının yeni mezunları ya da başarılı çalışanları kısa sürelerle birkaç bölümde çalıştırarak yönetici olarak yetiştirdiği düzenli eğitim programıdır.","ornek":"İstanbul’daki bir zincirin yönetici adayı programına katılan Ece, sırayla ön büro, yiyecek içecek ve satış bölümlerinde birkaç ay çalışır.","sektor":"Bu programlar adayı bölümlerde döndürür; aday her bölümde işi öğrenir ve bir bölümün ötekini nasıl etkilediğini görür. Böylece yönetici olunca bütünü düşünebilir. Programın adı ve süresi zincirden zincire değişir.","iliskili":["go-3-025","go-3-026","go-3-017"],"kontrol":null,"kitapDisi":true,"cizim":"lider"},{"id":"go-3-025","konu":"3.2","terim":"Çapraz eğitim","ingilizce":"Cross-training","tanim":"Bir çalışanın kendi bölümünün yanında başka bir bölümün işlerini de öğrenmesidir.","ornek":"Pazar sabahı kahvaltı yoğunluğunda ön büro görevlisi, çapraz eğitimde öğrendiği gibi restoranda masa toplamaya yardım eder.","sektor":"Çapraz eğitimli çalışan, otel yoğunken ya da ekip eksikken boşluğu doldurur. Kariyer açısından yeni bölümlere geçişin ve terfinin kapısını açar; çünkü genel müdür bütün bölümleri anlayan kişidir.","iliskili":["go-3-026","go-3-024","go-3-023"],"kontrol":null,"kitapDisi":true},{"id":"go-3-026","konu":"3.2","terim":"Departmanlar arası geçiş","ingilizce":"Cross-departmental move","tanim":"Çalışanın bir bölümde edindiği deneyimle başka bir bölüme, örneğin ön bürodan satışa ya da kat hizmetlerinden yiyecek içeceğe geçmesidir.","ornek":"Ön büroda iki yıl çalışan Kerem, gelir yönetimi ekibine geçmek istediğini müdürüne söyler; müdürü onu bir haftalığına gelir müdürünün yanına verir.","sektor":"Büyük zincirler çalışanın bölüm değiştirmesine açıktır, çünkü iyi bir çalışanı kaybetmek yerine otelin içinde tutmayı yeğler. Geçiş istiyorsan önce amirinle konuş ve deneme fırsatı iste; sessizce ayrılırsan güven sarsılır.","iliskili":["go-3-025","go-3-024","go-3-027"],"kontrol":null,"kitapDisi":true,"cizim":"ekip"},{"id":"go-3-027","konu":"3.2","terim":"Zincir içi transfer","ingilizce":"Internal transfer within a group","tanim":"Bir otel zincirinde çalışanın, aynı zincire ait başka bir şehirdeki ya da ülkedeki otele aynı veya daha üst görevle geçmesidir.","ornek":"İzmir’de bir zincir otelde çalışan görevli, aynı zincirin Dubai’deki otelinde açılan pozisyona iç başvuru yapar.","sektor":"Büyük zincirlerin çekici yanlarından biri budur: işveren değiştirmeden şehir, hatta ülke değiştirebilirsin. Birçok zincir boş kadroyu önce kendi çalışanlarına duyurur; bu yüzden hem performansın hem iyi ilişkilerin önemlidir.","iliskili":["go-3-026","go-3-028","go-3-019"],"kontrol":null,"kitapDisi":true,"cizim":"otel-bina"},{"id":"go-3-028","konu":"3.2","terim":"Yurt dışında çalışma","ingilizce":"Working abroad","tanim":"Başka bir ülkenin otelinde, o ülkenin çalışma izni kurallarına uyarak iş yapmaktır.","ornek":"Antalya’da üç yaz sezonu çalışan Hasan, Almancası ve İngilizcesiyle Avusturya’daki bir kış otelinde sezonluk iş için başvurur.","sektor":"Otelcilik dünyada en kolay taşınabilen mesleklerden biridir; çünkü işin dili ortaktır. Ama çalışma izni, resmî sözleşme ve sigorta olmadan çalışmak mağduriyete yol açar; iş ilanını okulun, resmî kurumun ya da tanınmış bir firmanın kanalından doğrula.","iliskili":["go-3-029","go-3-027","go-3-042"],"kontrol":null,"kitapDisi":true},{"id":"go-3-029","konu":"3.2","terim":"Sezonluk çalışma","ingilizce":"Seasonal work","tanim":"Yalnız turizmin yoğun olduğu aylarda, örneğin yazın kıyı otellerinde ya da kışın kayak merkezlerinde yapılan geçici işlerdir.","ornek":"Hazirandan eylüle Kemer’deki bir tatil köyünde garsonluk yapan öğrenci, okullar açılınca derslerine döner.","sektor":"Sezonluk çalışma, ilk deneyimi kazanmanın hızlı yollarındandır: kısa sürede çok konuk ve çok iş görürsün. Yazın kıyıda, kışın dağda çalışarak yılı iki sezonla geçirenler vardır; ama sözleşme ve sigortayı baştan netleştirmek gerekir.","iliskili":["go-3-028","go-3-021","go-3-020"],"kontrol":null,"kitapDisi":true},{"id":"go-3-030","konu":"3.2","terim":"Kruvaziyer kariyeri","ingilizce":"Cruise ship career","tanim":"Yolcu gemilerinde otel hizmeti, yiyecek içecek ya da eğlence alanında çalışarak mesleği sürdürmektir.","ornek":"İstanbul’da bir kruvaziyer şirketinin işe alım gününde öğrenci, ön büro ve restoran stajında kazandığı deneyimi anlatır.","sektor":"Gemi yüzen bir oteldir: kabin hizmetleri, restoran, ön büro ve eğlence ekipleri vardır. Aylarca gemide yaşayıp farklı ülkelerden mürettebatla çalışırsın; otelcilik bilgin doğrudan işe yarar, ama uzun süre evden uzak kalmak da bir gerçektir.","iliskili":["go-3-031","go-3-028","go-3-032"],"kontrol":null,"kitapDisi":true,"gorsel":"t13a-kusadasi-iki-gemi-yanyana"},{"id":"go-3-031","konu":"3.2","terim":"Hava yolu kariyeri","ingilizce":"Airline career","tanim":"Otelcilikte edinilen hizmet becerilerinin kabin ekibi, yer hizmetleri ve yolcu ilişkileri gibi hava yolu görevlerinde kullanıldığı kariyer yoludur.","ornek":"Sabah 05.30’da Sabiha Gökçen Havalimanı’nda yer hizmetleri görevlisi, geç kalmış bir yolcuyu sakin ve nazik biçimde bilet kontrolüne yönlendirir.","sektor":"Konuk hizmetinin temeli aynıdır: sakin kal, dinle, çözüm sun. Ön büroda öğrendiğin iletişim ve stres yönetimi becerisi havalimanında ve uçak kabininde de aranır; hava yolları genellikle yabancı dil düzeyine ve kıyafet standartlarına dikkat eder.","iliskili":["go-3-030","go-3-041","go-3-042"],"kontrol":null,"kitapDisi":true,"cizim":"ucak"},{"id":"go-3-032","konu":"3.2","terim":"Etkinlik yönetimi","ingilizce":"Event management","tanim":"Toplantı, kongre ve düğün gibi organizasyonları planlayıp bütçeleyerek uygulamaya koyma işidir.","ornek":"Cumartesi akşamı İstanbul’da bir otelin balo salonunda yapılan düğünde etkinlik koordinatörü salon düzenini, yemek zamanını ve müzik saatini aynı çizelgede yönetir.","sektor":"Otelin geliri yalnız odadan gelmez; toplantı ve düğünler de önemli bir gelir kaynağıdır. Etkinlik yönetimi otelin içinde de, bağımsız firmalarda da kariyer olarak açılır; ayrıntıya dikkat ve zaman planı ana beceridir.","iliskili":["go-3-030","go-3-046","go-3-043"],"kontrol":null,"kitapDisi":true,"gorsel":"t13d-ziyafet-salonu-masalar"},{"id":"go-3-033","konu":"3.2","terim":"Lüks perakende","ingilizce":"Luxury retail","tanim":"Pahalı moda, mücevher ve saat gibi ürünlerin satıldığı mağazalarda müşteriye otel kalitesinde kişisel ilgiyle hizmet verme alanıdır.","ornek":"İstanbul’da lüks bir mağazada satış danışmanı, müşteriyi kapıda adıyla karşılar; bu alışkanlığı otel resepsiyonunda edinmiştir.","sektor":"Lüks markalar otelcilik okulu mezunlarını da aday olarak değerlendirebilir; çünkü ince hizmet, sabır ve kişiye özel ilgi iki alanda da aynıdır. Otelcilik eğitiminin yalnız otelle sınırlı kalmadığını gösteren güzel bir örnektir.","iliskili":["go-3-034","go-3-035","go-3-031"],"kontrol":null,"kitapDisi":true,"gorsel":"t14e-butik-ic"},{"id":"go-3-034","konu":"3.2","terim":"Gastronomi","ingilizce":"Gastronomy","tanim":"Yemeğin yapımını, kültürünü, sunumunu ve içecekle uyumunu bütün yönleriyle inceleyen alandır.","ornek":"Gaziantep’te aşçılık okuyan öğrenci, bir otelin lokantasında yöresel baklavanın hazırlanışını öğrenir ve menüde sunum şekli önerir.","sektor":"Otelin yiyecek içecek bölümü büyük bir kariyer alanıdır: aşçı, şef, restoran müdürü ya da kendi işletmesinin sahibi olabilirsin. Gastronomi turizmi ilgi gördüğü için yöresel mutfağı iyi bilen çalışan avantaj kazanır.","iliskili":["go-3-033","go-3-035","go-3-063"],"kontrol":null,"kitapDisi":true,"gorsel":"t13e-sunumlu-tabak"},{"id":"go-3-035","konu":"3.2","terim":"Otelcilikte girişimcilik","ingilizce":"Hospitality entrepreneurship","tanim":"Kendi işini kurmak; örneğin küçük bir pansiyon, butik otel, kafe ya da seyahat acentesi açmaktır.","ornek":"Kaş’ta on yıl otellerde çalışan Murat, biriktirdiği deneyimle sekiz odalı bir pansiyon açar ve resepsiyonu da kendisi yürütür.","sektor":"Girişim sahadaki deneyimle güçlenir: temizliği, konuk şikâyetini ve satış kanallarını bilen sahip kolay kolay yanılmaz. Ama kira, vergi ve kredi gibi konularda uzmanlardan danışmanlık almak gerekir.","iliskili":["go-3-033","go-3-034","go-3-019"],"kontrol":null,"kitapDisi":true},{"id":"go-3-036","konu":"3.2","terim":"Kariyer portfolyosu","ingilizce":"Career portfolio","tanim":"Kişinin eğitim, staj, sertifika, proje ve referanslarını kanıtlarıyla bir arada topladığı dosyadır.","ornek":"Meslek lisesi son sınıf öğrencisi Aslı, staj defterini, aldığı sertifikaları ve okuldaki etkinlik organizasyonundan fotoğrafları tek bir dosyada toplar.","sektor":"Mülakatta “yapabilirim” demekle “yaptım, işte kanıtı” demek farklı etki bırakır. Portfolyoyu staja başladığın gün tutmaya başla; konuk bilgisi ve işletmenin iç belgeleri portfolyoya girmez.","iliskili":["go-3-037","go-3-038","go-3-055"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-037","konu":"3.2","terim":"Özgeçmiş (CV)","ingilizce":"Curriculum vitae (CV)","tanim":"Kişinin eğitimini, deneyimini ve becerilerini işverene kısa ve düzenli sunan, genellikle bir iki sayfalık belgedir.","ornek":"Mart ayında yaz stajı arayan öğrenci, özgeçmişine “İngilizce: orta düzey” ve “resepsiyon stajı” bilgilerini yazar; yazım hatası olmasın diye öğretmenine okutur.","sektor":"İşe alımcı özgeçmişe çok kısa bakar; ilk yarım sayfa seni anlatmalıdır. Dil düzeyini dürüstçe yaz, çünkü mülakatta o dilde konuşturulabilirsin.","iliskili":["go-3-036","go-3-039","go-3-038"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-038","konu":"3.2","terim":"Referans","ingilizce":"Reference","tanim":"Önceki bir amirin ya da öğretmenin adayın çalışma tarzı hakkında işverene verdiği olumlu görüştür.","ornek":"Staj bittikten sonra Elif, ön büro şefine “Sizi referans olarak gösterebilir miyim?” diye sorar; şef kabul eder ve iletişim bilgisini verir.","sektor":"Otelcilik küçük bir dünyadır: müdürler birbirini tanır ve işe almadan önce arar. Bu yüzden kimseyi izinsiz referans gösterme; stajda iyi bir ad bırakmak ileride sana geri döner.","iliskili":["go-3-037","go-3-039","go-3-053"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-039","konu":"3.2","terim":"İş mülakatı","ingilizce":"Job interview","tanim":"İşverenin adayla yüz yüze ya da çevrim içi konuşarak onun işe uygunluğunu ve tutumunu değerlendirdiği görüşmedir.","ornek":"Salı sabahı 10.00’da bir otelin insan kaynakları ofisinde aday ön büro görevliliği için kendini tanıtır ve zor bir konuk durumunu nasıl çözdüğünü anlatır.","sektor":"Otelcilik mülakatlarında çoğu zaman “zor bir konuk gelirse ne yaparsın?” gibi gerçek durum soruları sorulur. Dürüst ve sakin ol, örnekle cevap ver; zamanında gel, otelin bilgilerini önceden oku ve sen de bir soru sor.","iliskili":["go-3-037","go-3-038","go-3-041"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-040","konu":"3.3","terim":"Yumuşak beceriler","ingilizce":"Soft skills","tanim":"İletişim, takım çalışması ve duygusal denge gibi bir meslekte kişiyi başarılı kılan, ama sertifikayla ölçülmesi zor olan insani becerilerdir.","ornek":"Yoğun bir cuma akşamı iki ön büro görevlisi aynı kuralları biliyor; konuğu sakinleştiren ve ekip arkadaşına yardım eden görevli yumuşak becerisiyle öne çıkar.","sektor":"Teknik beceri, örneğin bir programı kullanmak, öğretilebilir ve zamanla herkesçe bilinir. Dünya otelciliğinde farkı çoğu zaman yumuşak beceri yaratır; çünkü konuk sistemi değil, seni hatırlar.","iliskili":["go-3-041","go-3-047","go-3-043"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-041","konu":"3.3","terim":"Konukla etkili iletişim","ingilizce":"Effective guest communication","tanim":"Konuğu ve ekip arkadaşını dikkatle dinleyip ne istediklerini anlayarak açık, kibar ve doğru biçimde yanıt verme becerisidir.","ornek":"Sabah 08.30’da kahvaltı salonunda konuk “Çay biraz soğuk” der; garson onu sözünü kesmeden dinler, özür diler ve sıcak çayı getirir.","sektor":"Konuk şikâyetlerinin çoğu bir iletişim kopukluğundan çıkar. Önce dinle, sonra özetle, sonra çöz. Ses tonun ve göz temasın, söylediğin kelimeler kadar etkilidir.","iliskili":["go-3-040","go-3-047","go-3-042"],"kontrol":null,"kitapDisi":true},{"id":"go-3-042","konu":"3.3","terim":"Yabancı dil","ingilizce":"Foreign language skills","tanim":"Konuğun anadiliyle ya da ortak bir dille konuşup yazarak onu rahat ettiren, iş yaşamında kullanılabilen dil becerisidir.","ornek":"Antalya’da bir ön büro görevlisi Rus bir ailenin “bebek yatağı” isteğini birkaç Rusça kelimeyle anlar, sonra İngilizceyle teyit eder.","sektor":"İngilizce otelciliğin ortak dilidir; Almanca, Rusça, Arapça ya da İspanyolca gibi ikinci bir dil seni daha değerli kılar. Dil bilmek yalnız konuşmak değil, konuğun kültürüne saygıyla yaklaşmaktır.","iliskili":["go-3-041","go-3-028","go-3-031"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"go-3-043","konu":"3.3","terim":"Takım çalışması","ingilizce":"Teamwork","tanim":"Farklı bölümlerden insanların ortak bir hedef için görevlerini paylaşarak ve birbirine destek olarak çalışmasıdır.","ornek":"Bir grup erken varınca ön büro, kat hizmetleri ve teknik servis birlikte çalışır; üç oda yarım saatte hazırlanır ve konuklar beklemez.","sektor":"Konuk oteli tek bir bütün olarak yaşar; bir halka koparsa bütün deneyim bozulur. İyi ekipler sorun çıkınca suçlu aramaz, birlikte çözmeyi öğrenir.","iliskili":["go-3-040","go-3-022","go-3-044"],"kontrol":null,"kitapDisi":true,"cizim":"ekip"},{"id":"go-3-044","konu":"3.3","terim":"Problem çözme","ingilizce":"Problem solving","tanim":"Beklenmedik bir sorunla karşılaşınca sakin kalıp durumu anlamak, çözümleri düşünmek ve yetkili kişiyle birlikte uygulamaktır.","ornek":"Akşam 19.00’da restoranda iki masa aynı saate rezerve edilmiş; garson durumu şefine bildirir, konuklardan özür diler ve on dakikada ikinci masayı hazırlar.","sektor":"Otelde sorun kaçınılmazdır; konuk otelin hatasız olmasını değil, sorunu nasıl çözdüğünü hatırlar. Çözümü bulamazsan susmak yerine amirine hızlıca söyle; bu da problem çözmenin bir parçasıdır.","iliskili":["go-3-043","go-3-045","go-3-046"],"kontrol":null,"kitapDisi":true,"cizim":"hedef-basari"},{"id":"go-3-045","konu":"3.3","terim":"Dayanıklılık","ingilizce":"Resilience","tanim":"Yoğun tempo, yorgunluk ya da zor bir konukla karşılaşıldığında sakin kalarak toparlanabilme gücüdür.","ornek":"Ağustosta Bodrum’daki otelde ön büro görevlisi, öğleden sonra zor bir konukla yaşadığı tartışmanın ardından kısa bir nefes alır ve sonraki konuğu güler yüzle karşılar.","sektor":"Otelcilikte vardiya, bayram ve tatil günlerinde çalışmak olağandır. Dayanıklı çalışan eleştiriyi kişisel almaz, dinlenmeyi ihmal etmez; zorlandığında yardım istemek de gücün bir parçasıdır.","iliskili":["go-3-044","go-3-069","go-3-047"],"kontrol":null,"kitapDisi":true,"cizim":"hedef-basari"},{"id":"go-3-046","konu":"3.3","terim":"Vardiyada zaman yönetimi","ingilizce":"Shift time management","tanim":"İşleri önem ve aciliyetine göre sıralayıp belirlenen sürede bitirebilme becerisidir.","ornek":"Sabah 07.00 vardiyasında oda görevlisi önce çıkış yapan odaları temizleyecek şekilde listesini yapar; öğleden sonra gelen konuklar hazır odayı bekler durumda kalmaz.","sektor":"Otelde zaman, konuk memnuniyetinin parçasıdır: giriş saatinde hazır olmayan oda kötü bir yoruma dönüşebilir. Zamana saygı ayrıca güvenilirlik göstergesidir; vardiyaya zamanında gelen ve işini zamanında bitiren çalışan öne çıkar.","iliskili":["go-3-044","go-3-032","go-3-056"],"kontrol":null,"kitapDisi":true},{"id":"go-3-047","konu":"3.3","terim":"Konuk karşısında duygusal zekâ","ingilizce":"Emotional intelligence in guest service","tanim":"Kendi duygularını fark edip yönetebilmek ve karşısındakinin ne hissettiğini anlayarak ona göre davranabilmektir.","ornek":"Uçuşu iptal olan konuk gece yarısı resepsiyona öfkeyle gelir; görevli konuğun yorgun ve endişeli olduğunu fark eder, tartışmak yerine önce ona oturacak yer ve su sunar.","sektor":"Konuk öfkeli gelse bile sorun çoğu zaman senden değil, yaşadığı durumdandır. Duygusal zekâsı yüksek çalışan tartışmayı büyütmez ve kendi öfkesini yönetir; bu beceri yöneticilik basamaklarında giderek daha önemli olur.","iliskili":["go-3-040","go-3-041","go-3-045"],"kontrol":null,"kitapDisi":true,"cizim":"kalp-empati"},{"id":"go-3-048","konu":"3.3","terim":"Görünüm ve duruş","ingilizce":"Personal presentation","tanim":"Üniformanın düzgünlüğü, kişisel bakım, dik duruş ve güler yüzle konuğa kendini sunuş biçimidir.","ornek":"Sabah 08.00 vardiyasından önce ön büro görevlisi aynada isim kartını, saçını ve ayakkabılarını kontrol eder, sonra omuzlarını dikleştirip resepsiyona geçer.","sektor":"Konuk sözden önce görüntüyü fark eder; düzenli görünüm “bu otel ayrıntıya özen gösteriyor” mesajı verir. Standartlar kıyafet ve bakımla ilgilidir, kimsenin yüzüyle ya da bedeniyle ilgili değildir; kuralları işe başlarken öğren.","iliskili":["go-3-040","go-3-041","go-3-049"],"kontrol":null,"kitapDisi":true,"cizim":"uniforma"},{"id":"go-3-049","konu":"3.3","terim":"Teknoloji okuryazarlığı","ingilizce":"Digital literacy","tanim":"Otelde kullanılan bilgisayar programlarını, mobil uygulamaları ve çevrim içi araçları güvenle kullanıp yeni olanları öğrenebilme becerisidir.","ornek":"Sabah 09.00’da ön büroda stajyer, otel yönetim sisteminde konuk kaydını açar ve çift rezervasyon uyarısını fark edip müdürüne bildirir.","sektor":"Yazılımlar değişir; öğrenme hızı değişmez. Yeni sistemi korkmadan öğrenen çalışan her zincirde işe yarar. Bilgisayarda hızlı olmak yetmez, konuk verisini korumayı da bilmek gerekir.","iliskili":["go-3-067","go-3-065","go-3-066"],"kontrol":null,"kitapDisi":true,"cizim":"dijital"},{"id":"go-3-050","konu":"3.3","terim":"Büyüme zihniyeti","ingilizce":"Growth mindset","tanim":"Yeteneğin doğuştan sabit olmadığını, çalışarak ve hatalarından öğrenerek gelişeceğini kabul eden düşünme biçimidir.","ornek":"Staj ilk gününde yanlış oda anahtarını veren Zeynep, “Ben bu işe yatkın değilmişim” demek yerine “Bir dahaki sefere listeyi iki kez kontrol edeceğim” der.","sektor":"Otelcilikte kimse hatasız başlamaz. Büyüme zihniyetli stajyer hatayı saklamaz, amirine söyler ve öğrenir; bu tutum amirinin ona görev verme güvenini artırır.","iliskili":["go-3-051","go-3-054","go-3-052"],"kontrol":null,"kitapDisi":true,"cizim":"grafik"},{"id":"go-3-051","konu":"3.3","terim":"Geri bildirim alma","ingilizce":"Receiving feedback","tanim":"Amirden, ekip arkadaşından ya da konuktan gelen eleştiri ve önerileri savunmaya geçmeden dinleyip gelişme fırsatına çevirme becerisidir.","ornek":"Staj sonunda ön büro şefi “Telefonda biraz daha yavaş konuş” deyince stajyer teşekkür eder, bir örnek ister ve ertesi gün yavaş konuşmayı dener.","sektor":"Dünya otelciliğinde geri bildirim yaşamın parçasıdır: konuk anketleri, gizli denetçiler ve amirler sürekli değerlendirme yapar. “Teşekkürler, uygulayacağım” diyen çalışan hem gelişir hem de yükselmeye aday olur.","iliskili":["go-3-050","go-3-052","go-3-041"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"go-3-052","konu":"3.3","terim":"Mentor (yol gösterici)","ingilizce":"Mentor","tanim":"Meslekte deneyimli olup yeni başlayan birine yol gösteren, bilgisini ve tecrübesini paylaşan kişidir.","ornek":"Bursa’daki bir otelde yaz stajı yapan Ali, ön büro şefi Hatice’ye ayda bir kahve içip kariyer planını danışır.","sektor":"İyi bir mentor sana işin yazılı olmayan kurallarını ve fırsatların nereden çıktığını anlatır. Okulundaki öğretmenin, stajdaki şefin ya da sektörden tanıdığın deneyimli biri mentorun olabilir. Mentor aramak utanılacak değil, akıllıca bir iştir.","iliskili":["go-3-050","go-3-053","go-3-051"],"kontrol":null,"kitapDisi":true,"cizim":"is-birligi"},{"id":"go-3-053","konu":"3.3","terim":"Ağ kurma","ingilizce":"Networking","tanim":"Meslekte tanışılan insanlarla düzenli ve samimi ilişki kurarak bilgi ve fırsat paylaşmaktır.","ornek":"Okulun düzenlediği kariyer gününde öğrenci, konuşmacı otel müdürüne soru sorar ve aynı gün teşekkür e-postası gönderir.","sektor":"Bazı işler duyum yoluyla bulunur: bir müdür boş kadroyu önce tanıdığı iyi çalışanlara söyler. Ağ kurmak torpil değil, iyi çalıştığını insanlara göstermektir; okulların mezun ağları ve stajdaki ekibin de senin ağındır.","iliskili":["go-3-052","go-3-038","go-3-036"],"kontrol":null,"kitapDisi":true,"gorsel":"sektor-el-sikisma"},{"id":"go-3-054","konu":"3.3","terim":"Sürekli öğrenme","ingilizce":"Lifelong learning","tanim":"Eğitimin okulla bitmediğini, meslek boyunca yeni bilgi ve beceri öğrenmeye devam edilmesi gerektiğini ifade eden yaklaşımdır.","ornek":"Beş yıldır ön büroda çalışan Mehmet, her yıl bir yabancı dil kursuna yazılır ve çevrim içi bir gelir yönetimi eğitimine katılır.","sektor":"Otelcilik hızla değişir: yeni sistemler, yeni konuk beklentileri, yeni yasalar çıkar. Üst düzey yöneticiler bile eğitim almaya devam eder; öğrenmeyi bırakan çalışan olduğu yerde kalır.","iliskili":["go-3-055","go-3-056","go-3-050"],"kontrol":null,"kitapDisi":true,"cizim":"saat-zaman"},{"id":"go-3-055","konu":"3.3","terim":"Sertifika","ingilizce":"Certificate","tanim":"Bir konuda eğitim aldığını ya da bilgisini sınavla kanıtladığını gösteren belgedir.","ornek":"Bir turizm öğrencisi ilk yardım kursundan aldığı sertifikayı staj dosyasına ekler.","sektor":"Sertifika tek başına iş getirmez, ama mülakatta kanıt olur. Türkiye’de Mesleki Yeterlilik Kurumunun yetkilendirdiği kuruluşların verdiği mesleki yeterlilik belgesi, yabancı dil sınav sertifikaları ve ilk yardım ya da hijyen eğitimleri yaygın örneklerdir. Güvenilir olup olmadığını öğretmenine danış.","iliskili":["go-3-054","go-3-036","go-3-056"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-056","konu":"3.3","terim":"Kişisel gelişim planı","ingilizce":"Personal development plan","tanim":"Kişinin güçlü ve zayıf yönlerini yazıp ulaşmak istediği hedefleri ve bunlar için atacağı adımları takvime bağladığı yazılı plandır.","ornek":"9. sınıfta Selin “İngilizcemi konuşma düzeyine çıkarmak” hedefini yazar; her hafta iki konuşma çalışması yapmayı ve yaz stajında yabancı bir konukla sohbet etmeyi planlar.","sektor":"Plan yazmak, kariyerini rastlantıya bırakmamaktır. Birçok zincir yöneticileriyle yıllık gelişim görüşmesi yapar; planı hazır olan çalışan oraya net hedeflerle gider. Hedefi ölçülebilir yaz: “İngilizce çalışacağım” yerine “Her hafta iki konuşma çalışması yapacağım” de.","iliskili":["go-3-054","go-3-055","go-3-046"],"kontrol":null,"kitapDisi":true,"cizim":"hedef-basari"},{"id":"go-3-057","konu":"3.4","terim":"Sürdürülebilir otelcilik","ingilizce":"Sustainable hospitality","tanim":"Otelin bugünkü konuğu ağırlarken doğaya, yerel halka ve kültüre zarar vermeden gelecek kuşakların da turizmden yararlanabilmesini amaçlayan işletme anlayışıdır.","ornek":"Marmaris’te bir otelin müdürü toplantıda “Bu yıl çöp ve su yönetimimizi, çalışanlarımızın yaşam koşullarını nasıl iyileştirdik?” sorusunu gündeme getirir.","sektor":"Konuklar çevreye duyarlı otelleri tercih edebiliyor; enerji ve su tasarrufu da işletme giderini düşürür. Bu yüzden sürdürülebilirlik hem etik hem ekonomik bir karardır.","iliskili":["go-3-058","go-3-060","go-3-061"],"kontrol":null,"kitapDisi":true},{"id":"go-3-058","konu":"3.4","terim":"GSTC ölçütleri","ingilizce":"GSTC Criteria","tanim":"Küresel Sürdürülebilir Turizm Konseyinin, otellerin ve turizm işletmelerinin sürdürülebilir olup olmadığını ölçmek için oluşturduğu uluslararası ortak ölçütlerdir.","ornek":"Antalya’da bir otel, bu ölçütlere dayanan bir belge için denetim ister; denetçi atık kayıtlarına, çalışan sözleşmelerine ve yerel halkla iş birliğine bakar.","sektor":"Ölçütler dört ana başlıkta toplanır: sürdürülebilir yönetim, yerel halka ekonomik ve toplumsal yarar, kültürel mirasa saygı ve çevreyi koruma. GSTC otellere doğrudan belge vermez; ölçütlere dayanan programlar ve bağımsız belgelendirme kuruluşları verir. Böylece dünyanın her yerinde “sürdürülebilir” sözü aynı ölçüye bağlanır.","iliskili":["go-3-057","go-3-059","go-3-064"],"kontrol":null,"kitapDisi":true},{"id":"go-3-059","konu":"3.4","terim":"Çevre belgeleri","ingilizce":"Environmental labels (eco-labels)","tanim":"Bir otelin ya da plajın çevreye duyarlı işletildiğini bağımsız bir kurumun belgelediği işaretlerdir.","ornek":"Bodrum’daki bir otelin girişinde Yeşil Anahtar işareti durur; resepsiyondaki görevli merak eden konuğa bu işaretin ne olduğunu kısaca açıklar.","sektor":"Yeşil Anahtar, çevreye duyarlı işletilen konaklama tesislerine verilen uluslararası bir çevre etiketidir; Yeşil Yıldız, Türkiye’de Kültür ve Turizm Bakanlığının çevreye duyarlı konaklama tesislerine verdiği belgedir; Mavi Bayrak ise plajlar, marinalar ve turizm tekneleri için verilen uluslararası bir çevre işaretidir. Ölçütlerini belgeyi veren kurumdan öğren; burada yalnız adlarını bil.","iliskili":["go-3-058","go-3-057","go-3-060"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-mavi-bayrak"},{"id":"go-3-060","konu":"3.4","terim":"Atık yönetimi ve sıfır atık","ingilizce":"Waste management and zero waste","tanim":"Otelde oluşan çöpü azaltmak, ayırmak ve yeniden kullanıma ya da geri dönüşüme kazandırmak için yapılan düzenin bütünüdür.","ornek":"Mutfakta artan sebzeler atılmak yerine ertesi günkü çorbaya ayrılır; cam, kâğıt ve plastik de ayrı kutulara atılır.","sektor":"Otelde çöpün büyük kısmı mutfaktan ve ambalajdan çıkar; gıda israfını azaltmak hem doğayı hem işletmenin kasasını korur. Türkiye’de Sıfır Atık çalışmaları kapsamında birçok işletme bu konuda düzen kurmuştur; çalışan olarak ayrıştırma talimatlarını uygulamak senin payındır.","iliskili":["go-3-057","go-3-063","go-3-062"],"kontrol":null,"kitapDisi":true,"gorsel":"sektor-geri-donusum"},{"id":"go-3-061","konu":"3.4","terim":"Otelde enerji verimliliği","ingilizce":"Hotel energy efficiency","tanim":"Aynı hizmeti daha az elektrik, yakıt ve ısı harcayarak sunma çabasıdır.","ornek":"Konuk odadan çıkıp kartını çekince ışıklar ve klima otomatik kapanır; kat görevlisi boş odada kalan ışığı da açık bırakmaz.","sektor":"Klima, aydınlatma ve sıcak su otelin başlıca enerji kalemleridir; tasarruf giderleri düşürür ve karbon ayak izini azaltır. Bazı oteller çatıya güneş paneli kurarak elektriğinin bir bölümünü kendisi üretir; yine de en ucuz enerji harcanmayan enerjidir. Çalışanın küçük alışkanlıkları, örneğin boş odada ışığı kapatmak, toplamda büyük fark yaratır.","iliskili":["go-3-057","go-3-062","go-3-058"],"kontrol":null,"kitapDisi":true},{"id":"go-3-062","konu":"3.4","terim":"Su ve çamaşır tasarrufu","ingilizce":"Water and linen saving","tanim":"Duş, temizlik ve çamaşırhane gibi alanlarda suyu azaltmak için yapılan uygulamalardır; havlunun her gün değiştirilmesini konuğun isteğine bırakmak buna örnektir.","ornek":"Banyoda “Havlunuzu askıda bırakırsanız yeniden kullanırım” yazan karta uyan kat görevlisi, askıdaki havluyu değiştirmez.","sektor":"Kuraklık riski taşıyan yerlerde su, turizmin en değerli kaynaklarındandır. Konuğa tasarruf seçeneği sunmak onu suçlu hissettirmeden iş birliği yapmasını sağlar; çalışan olarak konuğun tercihini sessizce uygulamak profesyonelliktir.","iliskili":["go-3-061","go-3-060","go-3-057"],"kontrol":null,"kitapDisi":true},{"id":"go-3-063","konu":"3.4","terim":"Yöre ürünüyle tedarik","ingilizce":"Local sourcing for hotels","tanim":"Otelin gıda, süs eşyası ve hizmet gibi ihtiyaçlarını mümkün olduğunca çevresindeki üreticilerden ve esnaftan karşılamasıdır.","ornek":"Ege’de bir otel, kahvaltı için zeytin, peynir ve balı aynı ilçedeki üreticilerden alır ve konuğa “Bu bal bu köyden” diye anlatır.","sektor":"Yerel ürün taze olur, taşıma azalır ve para yöredeki insanlarda kalır. Konuk gittiği yerin lezzetini tadınca tatilini daha iyi hatırlar; yalnız kalite ve hijyen şartlarını da karşılaması gerekir.","iliskili":["go-3-064","go-3-034","go-3-060"],"kontrol":null,"kitapDisi":true},{"id":"go-3-064","konu":"3.4","terim":"Toplulukla ilişki","ingilizce":"Community engagement","tanim":"Otelin bulunduğu yörenin insanlarıyla iş, eğitim ve sosyal konularda iyi ilişki kurup onlara fayda sağlamasıdır.","ornek":"Kapadokya’daki bir otel, köyden gençleri yaz stajına alır ve yöresel el sanatı yapan kadınların ürünlerini lobide sergiler.","sektor":"Yerel halk turizmden yarar görmezse turizme desteği azalır. Yöreden çalışan alan, çevresiyle konuşan otel yöreyi korur ve daha rahat çalışır; senin gibi bir genç için de kendi yöresinde iş bulma fırsatı demektir.","iliskili":["go-3-063","go-3-058","go-3-057"],"kontrol":null,"kitapDisi":true},{"id":"go-3-065","konu":"3.4","terim":"Mobil anahtar","ingilizce":"Mobile key","tanim":"Oda kapısını plastik kart yerine konuğun telefonuna gönderilen dijital bir anahtarla açma sistemidir.","ornek":"İzmir’deki bir otelde konuğa varışından önce oda numarası ve dijital anahtarı gönderilir; konuk resepsiyona uğramadan odasına çıkar.","sektor":"Hızlı ve temassız giriş sağlar, kart masrafını azaltır. Ama pili bitmiş telefonu olan ya da teknolojiye yabancı konuk için resepsiyon yine hazır olmalıdır; teknoloji hizmeti değiştirir, konuğa ilgiyi kaldırmaz.","iliskili":["go-3-049","go-3-068","go-3-067"],"kontrol":null,"kitapDisi":true},{"id":"go-3-066","konu":"3.4","terim":"Yapay zekâ destekli konuk hizmeti","ingilizce":"AI-assisted guest service","tanim":"Konuk sorularını sohbet robotlarıyla yanıtlamak ya da konuk tercihlerini çözümleyerek öneri sunmak gibi, hizmeti yapay zekâ araçlarıyla desteklemektir.","ornek":"Gece 02.00’de konuk otelin uygulamasına “Kahvaltı kaçta başlıyor?” yazar ve sohbet robotu anında yanıtlar; konuk “Yumurta alerjim var” yazınca robot konuyu bir çalışana yönlendirir.","sektor":"Yapay zekâ sık sorulan soruları hızla yanıtlayarak çalışana daha önemli işlere zaman bırakır. Alerji, şikâyet ve duygusal durum gibi hassas konularda karar yine insanındır; araç yanılabilir, çıktısını kontrol etmek senin görevindir.","iliskili":["go-3-049","go-3-068","go-3-067"],"kontrol":null,"kitapDisi":true},{"id":"go-3-067","konu":"3.4","terim":"Konuk bilgisi gizliliği","ingilizce":"Guest data privacy","tanim":"Konuğun adı, kimliği, iletişim bilgisi ve tercihleri gibi kişisel verilerinin yalnız gerektiği kadar tutulması ve yetkisiz kişilere verilmemesidir.","ornek":"Telefonda biri “Kuzeniyim, kimin hangi odada kaldığını söyler misiniz?” diye sorar; görevli oda numarasını ya da konuk adını söylemez, konuğa haber vermeyi önerir.","sektor":"Türkiye’de 6698 sayılı Kişisel Verilerin Korunması Kanunu (KVKK), Avrupa’da ise GDPR konuk verilerini korur. Konuk bilgisini izinsiz paylaşmak konuğun güvenliğini tehlikeye atar ve işletmeye ağır sorumluluk getirir; otelde gördüğün konuk fotoğraflarını da paylaşma.","iliskili":["go-3-049","go-3-065","go-3-066"],"kontrol":null,"kitapDisi":true,"cizim":"kitap-ogrenme"},{"id":"go-3-068","konu":"3.4","terim":"İnsan dokunuşu","ingilizce":"Human touch","tanim":"Teknoloji ne kadar gelişirse gelişsin, konuğa sıcaklık ve kişisel ilgi gösteren insani hizmetin değerini anlatan kavramdır.","ornek":"Sabah çıkış işleminde kendi kendine çıkış cihazını kullanmakta zorlanan yaşlı çifte görevli yanlarına gider, cihazı birlikte çalıştırır ve yolculuklarına iyi dilekler diler.","sektor":"Teknoloji yayıldıkça insanın sıcaklığı daha ayırt edici olur: robot kahve getirebilir ama konuğun gözüne bakıp “Nasıldı?” diye soramaz. İyi bir otel, rutin işlemleri teknolojiye emanet eder, ilgiyi insana bırakır.","iliskili":["go-3-065","go-3-066","go-3-070"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"go-3-069","konu":"3.4","terim":"Çalışan refahı","ingilizce":"Employee wellbeing","tanim":"Çalışanın bedensel, ruhsal ve sosyal olarak iyi olması için işletmenin dinlenme, adil çizelge, güvenli ortam ve saygılı davranış sağlamasıdır.","ornek":"Sıcak yemek veren personel yemekhanesi, vardiya çizelgesinin iki hafta önceden asılması ve haftalık izin günlerinin planlanması otelin çalışanına verdiği değeri gösterir.","sektor":"Yorgun ve mutsuz çalışan, konuğu mutlu edemez. Çalışanını değerli gören otel onu elinde tutar. Sen de dinlenmeyi, yasal izin haklarını ve gerekirse yardım istemeyi öğren; tükenmişlik ciddi bir sorundur.","iliskili":["go-3-045","go-3-070","go-3-068"],"kontrol":null,"kitapDisi":true,"cizim":"ekip"},{"id":"go-3-070","konu":"3.4","terim":"Hizmet zihniyeti","ingilizce":"Service mindset","tanim":"İşi yalnız görev saymak yerine, karşısındakine fayda sağlamaktan gurur duyan ve bunu içtenlikle yapan düşünme biçimidir.","ornek":"Bayram sabahı vardiyadaki kat görevlisi, tek başına kalan yaşlı konuğun odasına bir bardak çay bırakır ve “Bayramınız kutlu olsun” der.","sektor":"İngilizcede otelcilik ve ağırlama anlamında “hospitality” sözcüğü kullanılır; ana fikir insanı ağırlamaktır. Teknoloji, zincirler ve unvanlar değişir; hizmet zihniyeti kariyerinin en sağlam sermayesidir.","iliskili":["go-3-068","go-3-069","go-3-040"],"kontrol":null,"kitapDisi":true}],"sorular":[{"id":"go-3-s01","tur":"coktan-secmeli","soru":"Otelcilik okulları eğitimin önemli bir bölümünü atölye ve staja ayırır. Bunun asıl nedeni hangisidir?","secenekler":["Öğrenci kuramsal dersleri sınavda daha kolay hatırlar ve not alır.","Okul, personel ihtiyacını öğrenci emeğiyle karşılayabilir.","Hata konuk yokken yapılıp düzeltilir, iş bizzat öğrenilir.","Mezun yurt dışında çalışma izni almakta kolaylık bulur."],"dogru":2,"aciklama":"Otelcilikte hata konuğun önünde görünür; uygulamalı eğitim hatayı konuk yokken yapıp düzeltmeyi sağlar. Kuramsal derslerin hatırlanması da yararlıdır ama atölyenin asıl amacı değildir."},{"id":"go-3-s02","tur":"coktan-secmeli","soru":"Bir otelcilik okulunun ilk döneminde yönetici adayı öğrenciler servis ve mutfak uygulamalarına katılıyor. Bu programın dayandığı anlayış hangisidir?","secenekler":["Önce hizmet etmeyi öğrenme","Departmanlar arası geçiş anlayışı","Çapraz eğitim","Yönetici adayı programı"],"dogru":0,"aciklama":"Yönetici olmak isteyen kişi önce sahadaki işi kendi eliyle yapar. Yönetici adayı programı ise zincir otellerin, çalışanı bölümlerde döndürerek yetiştirdiği düzendir; okulda başlayan servis ve mutfak uygulaması bu anlayışa uyar."},{"id":"go-3-s03","tur":"coktan-secmeli","soru":"Uygulama oteliyle ilgili aşağıdakilerden hangisi yanlıştır?","secenekler":["Gerçek konuk ağırlayan bir oteldir.","Öğrenciler öğretmen gözetiminde çalışır.","Okulun, öğrenci yetiştirmek için sahip olduğu ya da işlettiği bir oteldir.","Yalnız ders için kurulmuş, konuk kabul etmeyen bir model oteldir."],"dogru":3,"aciklama":"Uygulama oteli gerçek konuk ağırlar; öğrenci işi canlı ortamda öğretmen gözetiminde öğrenir. “Konuk kabul etmeyen model otel” tanıma aykırıdır, bu yüzden yanlış olan odur."},{"id":"go-3-s04","tur":"coktan-secmeli","soru":"Aşağıdaki okul ve ülke eşleştirmelerinden hangisi doğrudur?","secenekler":["Lozan Otelcilik Okulu (EHL) – Hollanda","Cornell Nolan Otelcilik Okulu – ABD","Hotelschool The Hague – İsviçre","Glion Yüksek Eğitim Enstitüsü – Hollanda"],"dogru":1,"aciklama":"Cornell’in okulu ABD’dedir. EHL ve Glion İsviçre’de, Hotelschool The Hague ise Hollanda’dadır; çeldiricilerde ülkeler birbiriyle değiştirilmiştir."},{"id":"go-3-s05","tur":"dogru-yanlis","soru":"Öğrenci yarım gün resepsiyonda, yarım gün restoranda sahadaki işleri yapıyorsa bu staj operasyon stajıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Operasyon stajında öğrenci ön büro, kat hizmetleri, mutfak ya da servis gibi sahadaki işleri bizzat yapar. Planlama ve ekip yönetimine yaklaşılan staj ise yönetim stajıdır."},{"id":"go-3-s06","tur":"coktan-secmeli","soru":"Bir otelin eğitim sorumlusu Asyalı konuk gruplarını daha iyi tanımak için Asya turizmi üzerine akademik özet arıyor. Hotel ICON adlı oteliyle bilinen hangi okulun çalışmalarına bakması mantıklıdır?","secenekler":["Cornell Nolan Otelcilik Okulu","Lozan Otelcilik Okulu (EHL)","Hotelschool The Hague","Hong Kong PolyU SHTM okulu"],"dogru":3,"aciklama":"Hotel ICON, Hong Kong PolyU’nun hem eğitim hem araştırma için kullandığı oteldir ve okulun çalışmaları Asya turizmini anlamak isteyenlerin başvurduğu kaynaklardandır. Cornell’in uygulama oteli Statler’dir."},{"id":"go-3-s07","tur":"coktan-secmeli","soru":"Cornell’de okuyan bir öğrenci kampüsteki Statler Otel’de çalışıyor, derslerde de araştırma ve veri okuyor. Bu okulda yetişenlerden beklenen yaklaşım hangisidir?","secenekler":["Kararları yalnız en deneyimli şefin ve amirlerin sözüne göre vermek","Kararları sezgiyle birlikte araştırma ve veriyle de desteklemek","Her işi yalnız kitaplardaki kuramsal bilgiye dayandırmak","Konuk görüşlerini karar sürecine hiçbir aşamada katmamak"],"dogru":1,"aciklama":"Statler Otel öğrenciye gerçek işte çalışarak öğrenme fırsatı verir; okul ayrıca araştırma ve veriyle karar vermeyi öğretir. Yalnız kuram da, yalnız şefin sözü de bu bütüncül yaklaşıma uymaz."},{"id":"go-3-s08","tur":"coktan-secmeli","soru":"Ece, lüks otelcilik ve hizmet yönetimi alanında eğitim veren, İsviçre’de Montreux yakınındaki bir okulu araştırıyor. Hangi okuldur?","secenekler":["Glion Yüksek Eğitim Enstitüsü","Hotelschool The Hague","Hong Kong PolyU Otel ve Turizm Yönetimi Okulu","Cornell Nolan Otelcilik Okulu"],"dogru":0,"aciklama":"Glion, İsviçre’de Montreux yakınındadır ve lüks otelcilik ile hizmet yönetimiyle tanınır. Hotelschool The Hague Hollanda’da, PolyU Hong Kong’da, Cornell ise ABD’dedir."},{"id":"go-3-s09","tur":"coktan-secmeli","soru":"Aşağıdaki okullardan hangisi İsviçre merkezli değildir?","secenekler":["Lozan Otelcilik Okulu (EHL)","Les Roches Otelcilik Okulu","Hotelschool The Hague Lahey","Glion Yüksek Eğitim Enstitüsü"],"dogru":2,"aciklama":"Hotelschool The Hague Hollanda’dadır; Lahey ve Amsterdam’da yerleşkeleri bulunur. EHL, Les Roches ve Glion İsviçre merkezli okullardır."},{"id":"go-3-s10","tur":"coktan-secmeli","soru":"Kuşadası’ndaki bir otelde lisans öğrencisi ön büro müdürünün yanında vardiya çizelgesi hazırlıyor ve haftalık doluluk raporunu sunuyor. Bu hangi stajdır?","secenekler":["Operasyon stajı; sahadaki işler bizzat yapılır.","İşletmede mesleki eğitim; eğitim işletmede sürer.","Yönetici adayı programı; zincir bölümlerde döndürür.","Yönetim stajı; planlama ve ekip işine yaklaşılır."],"dogru":3,"aciklama":"Çizelge hazırlamak ve rapor sunmak planlama ve ekip yönetimine yaklaşmaktır; yönetim stajının işidir. Operasyon stajında öğrenci sahadaki işleri bizzat yapar, yönetici adayı programı ise zincir otellerin düzenlediği programdır."},{"id":"go-3-s11","tur":"coktan-secmeli","soru":"Meslek lisesi öğrencisi Elif, eğitim yılının bir bölümünü Alanya’daki bir otelin kat hizmetlerinde, kalan zamanını okulda geçiriyor. Elif’in aldığı eğitim hangisidir?","secenekler":["İşletmede mesleki eğitim","Sezonluk çalışma","Uluslararası öğrenci değişimi","Çapraz eğitim"],"dogru":0,"aciklama":"Eğitimin bir bölümünün okulda değil gerçek bir işletmede yapılması işletmede mesleki eğitimdir. Sezonluk çalışma yalnız yoğun aylarda geçici iştir; Elif ise okula da devam etmektedir."},{"id":"go-3-s12","tur":"coktan-secmeli","soru":"Ön büro önlisansından mezun olan Selin, koşulları sağlayıp turizm fakültesinde lisansa devam edecek. Selin’in yapacağı işlem hangisidir?","secenekler":["Çapraz eğitim","Dikey geçiş başvurusu","Zincir içi transfer","Departmanlar arası geçiş"],"dogru":1,"aciklama":"Önlisans mezununun lisans programına geçmesi dikey geçiştir. Zincir içi transfer ve departmanlar arası geçiş iş yaşamındaki hareketlerdir; çapraz eğitim ise başka bölümün işini öğrenmektir."},{"id":"go-3-s13","tur":"coktan-secmeli","soru":"Gece 02.00’de ön büroda asansör arızalanıyor. Vardiyadaki sorumlu teknik servisi arıyor ve bagaj görevlisinden konuklara yardım etmesini istiyor. Bu kişi kariyer merdiveninde hangi basamaktadır?","secenekler":["Stajyer","Giriş seviyesi görevli","Süpervizör","Bölüm yöneticisi"],"dogru":2,"aciklama":"Bir vardiyada işin akışını izleyip görev dağıtan ve sorun çıkınca ilk başvurulan kişi süpervizördür. Bölüm yöneticisi ise bölümün bütün işleyişinden ve bütçesinden sorumludur."},{"id":"go-3-s14","tur":"coktan-secmeli","soru":"Zincir bir otelin yönetici adayı programındaki Ece sırayla ön büro, yiyecek içecek ve satış bölümlerinde çalışıyor. Bu düzenin ona en büyük katkısı nedir?","secenekler":["Tek bölümde yıllarca uzmanlaşıp başka bölüme hiç geçmemek","Bölümlerin birbirini etkilediğini görüp bütünü düşünebilmek","Her bölümün bütçesini kendi başına belirleme yetkisi kazanmak","Yabancı dil sertifikasını daha kısa sürede almak ve kullanmak"],"dogru":1,"aciklama":"Aday her bölümde işi öğrenir ve bölümlerin birbirini nasıl etkilediğini görür; yönetici olunca bütünü düşünebilir. Tek bölümde uzmanlaşmak bu programın amacına ters düşer."},{"id":"go-3-s15","tur":"coktan-secmeli","soru":"Çapraz eğitim ile departmanlar arası geçiş arasındaki fark hangisidir?","secenekler":["Çapraz eğitimde çalışan işveren değiştirir; geçişte ise aynı işverende kalıp aynı görevi sürdürür.","Çapraz eğitimde başka bölüme kalıcı geçilir; geçişte ise yalnızca bir gün başka bölümde çalışılır.","Çapraz eğitim yalnız yöneticilere uygulanır; geçiş ise yalnız stajyerlere uygulanan bir programdır.","Çapraz eğitimde kişi kendi bölümünde kalıp başka bölümün işini öğrenir; geçişte bölüm değiştirir."],"dogru":3,"aciklama":"Çapraz eğitimde çalışan kendi bölümünde kalır ve ihtiyaç olunca başka bölümün işini de yapabilir. Departmanlar arası geçişte ise yeni bir bölüme geçer; işveren aynı kalır."},{"id":"go-3-s16","tur":"dogru-yanlis","soru":"Sezonluk bir işte sözleşme ve sigorta, sezon başladıktan sonra ilk maaş gününde konuşulabilecek ayrıntılardır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Sözleşme ve sigorta başlamadan önce netleştirilir; belirsiz sözleşme ve sigortasız çalışma sezonluk işlerde karşılaşılan ciddi sorunlardır. “Sonra konuşuruz” demek çalışanı korumasız bırakır."},{"id":"go-3-s17","tur":"coktan-secmeli","soru":"Hasan, Avusturya’daki bir kış otelinde sezonluk iş ilanı gördü. İlan bir sosyal medya hesabında yayımlanmış. Doğru yol hangisidir?","secenekler":["İlanı okul, resmî kurum ya da tanınmış firma kanalıyla doğrulatmak","Aracı kuruma pasaportunu emanet edip işlemleri ona bırakmak","Ülkeye gidip çalışma iznini yerinde halletmeyi planlamak","Ücret yüksek olduğu için başvuruyu hemen yapıp ayrıntıları sonra sormak"],"dogru":0,"aciklama":"Yurt dışında çalışmak çalışma izni, resmî sözleşme ve sigorta gerektirir; ilan bağımsız bir kanaldan doğrulanmalıdır. İzni ülkeye vardıktan sonra düşünmek ise Hasan’ı izinsiz ve korumasız bırakabilir."},{"id":"go-3-s18","tur":"coktan-secmeli","soru":"Aynı kuralları bilen iki ön büro görevlisinden biri, yoğun bir akşamda öfkeli konuğu sakinleştirip ekip arkadaşına yardım ediyor. Onu öne çıkaran beceri türü hangisidir?","secenekler":["Teknik beceri","Yönetim becerisi","Yumuşak beceri","Bilgisayar becerisi"],"dogru":2,"aciklama":"Dinlemek, sakinleştirmek ve destek olmak iletişim ve duygusal denge gibi yumuşak becerilerdir; sertifikayla ölçülmesi zordur. Kural ve program bilgisi ise teknik beceridir."},{"id":"go-3-s19","tur":"coktan-secmeli","soru":"Staj ilk gününde yanlış oda anahtarı veren Zeynep için hangi cümle büyüme zihniyetini gösterir?","secenekler":["“Ben bu işe yatkın değilmişim.”","“Bu hata bende değil, anahtar kutusunun düzensizliğinde.”","“Bir daha ön büroya yaklaşmayacağım.”","“Bir dahaki sefere listeyi iki kez kontrol edeceğim.”"],"dogru":3,"aciklama":"Büyüme zihniyeti hatayı öğrenme fırsatı sayar ve somut bir adım belirler. Hatayı kutuya yüklemek ya da kendini yetersiz ilan etmek öğrenmeyi durdurur."},{"id":"go-3-s20","tur":"dogru-yanlis","soru":"GSTC ölçütleri belirler; otele sürdürülebilirlik belgesini ise bu ölçütlere dayanarak denetleyen bağımsız kuruluşlar verir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"GSTC dünyada ortak ölçütleri oluşturan konseydir; belgeyi doğrudan vermez. Bu yüzden otellerin belgelendirmesi ölçütlere dayanan programlar ve bağımsız kuruluşlar eliyle yapılır."},{"id":"go-3-s21","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi GSTC ölçütlerinin ana başlıklarından biri değildir?","secenekler":["Sürdürülebilir yönetim","Dağıtım kanallarını çeşitlendirme","Yerel halka ekonomik ve toplumsal yarar","Çevreyi koruma"],"dogru":1,"aciklama":"GSTC ölçütleri sürdürülebilir yönetim, yerel halka yarar, kültürel mirasa saygı ve çevreyi koruma başlıklarında toplanır. Dağıtım kanalları satış stratejisi konusudur."},{"id":"go-3-s22","tur":"coktan-secmeli","soru":"Bodrum’daki bir otelin girişinde Yeşil Anahtar işareti var. Merak eden konuğa görevli bu işareti nasıl açıklamalıdır?","secenekler":["Çevreye duyarlı işletilen konaklama tesislerine verilen uluslararası bir çevre etiketidir.","Plajlar, marinalar ve turizm teknelerine verilen uluslararası bir çevre işaretidir.","Türkiye’de Kültür ve Turizm Bakanlığının verdiği ve yalnız Türk otelleri için geçerli belgedir.","GSTC’nin her otele doğrudan verdiği sürdürülebilirlik belgesidir ve bakanlıkça onaylanır."],"dogru":0,"aciklama":"Yeşil Anahtar konaklama tesisleri için uluslararası bir çevre etiketidir. Plajlar, marinalar ve turizm tekneleri için verilen işaret Mavi Bayrak’tır; Bakanlığın belgesi ise Yeşil Yıldız’dır."},{"id":"go-3-s23","tur":"coktan-secmeli","soru":"Bir otel konuğunun adı, kimliği ve tercihleri gibi kişisel bilgilerini Türkiye’de hangi kanuna göre korumak zorundadır?","secenekler":["GDPR (Avrupa’daki veri koruma düzenlemesi)","GSTC (sürdürülebilir turizm ölçütleri)","KVKK (Kişisel Verilerin Korunması Kanunu)","Yeşil Yıldız (çevre belgesi)"],"dogru":2,"aciklama":"Türkiye’de kişisel verileri KVKK korur. GDPR Avrupa’nın düzenlemesidir; GSTC ve Yeşil Yıldız ise sürdürülebilirlikle ilgilidir, kişisel veriyle ilgili değildir."},{"id":"go-3-s24","tur":"dogru-yanlis","soru":"Mobil anahtar kullanan bir otelde konuk resepsiyona hiç uğramaz; bu yüzden telefonu şarjsız ya da teknolojiye yabancı konuk için ayrıca bir çözüm düşünmeye gerek yoktur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Mobil anahtar işlemi hızlandırır ama pili bitmiş telefonu olan ya da teknolojiye yabancı konuk için resepsiyon hazır olmalıdır. Teknoloji hizmeti değiştirir, insan ilgisini kaldırmaz."},{"id":"go-3-s25","tur":"senaryo","durum":"Yaz stajının ilk haftasında Bodrum’daki otelin kat hizmetlerine verildin. Arkadaşların resepsiyonda çalışıyor; sen yatak yapıyor ve havlu taşıyorsun. Akşam “Ben boşuna okuyorum” diye düşünmeye başladın.","soru":"Ne yaparsın?","secenekler":["Süpervizöre resepsiyona geçmek istediğimi söyler, yer değişikliği için ısrar ederim.","İşim bitmese de resepsiyondaki arkadaşlarımın yanına gidip orayı öğrenmeye çalışırım.","Okul koordinatörüne staj yerimin değiştirilmesi için yazılı şikâyette bulunurum.","Süpervizöre bu bölümde ne öğrenmem gerektiğini sorar, öğrendiklerimi de not alırım."],"dogru":3,"aciklama":"Kat hizmetleri otelin temelidir; “önce hizmet etmeyi öğren” anlayışına göre sahadaki işi bilmek yönetici olmanın ilk adımıdır. Kendi görevini bırakıp başka bölümde vakit geçirmek, yer değişikliği için ısrar etmek ya da şikâyet etmek bu fırsatı kaçırtır."},{"id":"go-3-s26","tur":"senaryo","durum":"Bir otelin insan kaynakları ofisinde ilk iş mülakatındasın. Görevli “Bir hata yaptığın ve bundan ders çıkardığın bir durumu anlat” diyor. Aklına stajda yanlış oda anahtarını verdiğin gün geliyor ama bunu söylemekten çekiniyorsun.","soru":"Ne yaparsın?","secenekler":["Anahtar olayını kısaca anlatır, ondan ne öğrendiğimi söylerim.","Çok önemsiz bir hatayı seçer, ders çıkarmadan geçiştiririm.","Zor bir konuk olayını anlatır, hatanın konuktan kaynaklandığını söylerim.","Şu an aklıma bir örnek gelmediğini, sonra yazılı iletebileceğimi söylerim."],"dogru":0,"aciklama":"Mülakatta aranan hatasız olmak değil, hatadan ders çıkaran büyüme zihniyetidir; dürüst örnek ve çıkarılan ders güven verir. Hatayı konuğa yüklemek ya da konuyu geçiştirmek sorumluluktan kaçmak gibi görünür."},{"id":"go-3-s27","tur":"senaryo","durum":"Staj yaptığın otelde ön büro şefi, bir konukla telefonda hızlı ve kısa konuştuğunu ekibin önünde söylüyor. Yüzün kızarıyor ve kendini savunmak istiyorsun.","soru":"Hangisi doğru davranıştır?","secenekler":["Konuğun çok aceleci olduğunu anlatarak durumu şefe açıklarım.","Haklı bulmasam da sessiz kalır, hiçbir şey değiştirmem.","Dinler, teşekkür eder, bir örnek isteyip ertesi gün denerim.","Bir arkadaşımdan şefe benim adıma açıklama yapmasını isterim."],"dogru":2,"aciklama":"Geri bildirimi savunmaya geçmeden dinlemek gelişmenin ilk adımıdır; örnek isteyip denemek şefe seni geliştirmek istediğini gösterir. Gerekçe anlatmak savunmadır, sessiz kalıp değişmemek ise geri bildirimi boşa harcar."},{"id":"go-3-s28","tur":"senaryo","durum":"Sosyal medyada tanımadığın biri yurt dışında yüksek maaşlı bir otel işi önerisiyle yazıyor. “Yerin kapanmasın, pasaport fotoğrafını ve ilk ödemeyi hemen gönder” diyor. Heyecanlısın ama içinde bir huzursuzluk var.","soru":"Ne yaparsın?","secenekler":["Teklif sahibinden örnek bir iş sözleşmesi isteyip sözleşme gelirse ödemeyi yaparım.","Teklifi ailemle ve öğretmenimle paylaşır, ilanı resmî yoldan doğrulatırım.","Teklif sahibiyle görüntülü görüşüp ikna olursam ilk ödemeyi gönderirim.","Pasaport fotoğrafını gönderir, ödeme için ayrıntıları sonra konuşmayı denerim."],"dogru":1,"aciklama":"Peşin para, kimlik belgesi isteme ve acele ettirme dolandırıcılık işaretleridir. Doğrulama teklif edenin kendisinden değil, okul, resmî kurum ya da tanınmış bir firma gibi bağımsız bir kanaldan yapılır."},{"id":"go-3-s29","tur":"senaryo","durum":"Gece 23.00’te resepsiyonda staj yapıyorsun. Telefondaki kişi “Kuzeniyim, 312 numaralı odada kalan kişiye acil bir haber vereceğim, hangi odada olduğunu doğrular mısın?” diyor.","soru":"İlk adımın ne olur?","secenekler":["Oda numarasını doğrularım ama konuğun adını söylemem.","Bilgi vermem; arayanın adını ve numarasını alıp nöbetçi müdüre iletirim.","Bu gece konuk kalıp kalmadığını söylerim, oda numarasını söylemem.","Arayana kuzeni olduğunu gösteren bir bilgi sorar, doğru bilirse odayı söylerim."],"dogru":1,"aciklama":"Konuğun otelde kaldığını ya da hangi odada olduğunu söylemek bile kişisel veri paylaşmaktır ve konuğu tehlikeye atabilir. Arayanın bilgisini nöbetçi müdüre iletmek hem konuğu korur hem acil haberin ulaşmasını sağlar."},{"id":"go-3-s30","tur":"senaryo","durum":"Mutfakta stajyersin. Şef, artan sebzelerin ayrılıp ertesi günkü çorbaya kullanılmasını ve cam ile plastiğin ayrı kutulara atılmasını istedi. Yanındaki çalışan “Kimse bakmıyor, hepsini tek çöpe at” diyor.","soru":"Ne yaparsın?","secenekler":["Ayrıştırmayı kendi payıma düşen kadar yapar, çalışanın işine karışmam.","Şef gelene kadar atığı bir kenarda bekletir, ayrıştırmayı ona bırakırım.","Cam ve plastiği ayırır, sebze artıklarını yoğunluk bitince değerlendirmeyi düşünürüm.","Talimatı uygular, çalışana nedenini hatırlatır, ısrar ederse şefe haber veririm."],"dogru":3,"aciklama":"Sürdürülebilirlik kuralları kimse bakmasa da uygulanır; amaç denetimden kaçmak değil israfı azaltmaktır. Talimatı eksiksiz uygulamak ve sorun çıkarsa amire haber vermek hem doğru hem sakin bir yoldur; yarım uygulama israfı sürdürür."},{"id":"go-3-s31","tur":"senaryo","durum":"Sabah 10.00’da kendi kendine çıkış cihazının ekranı donuyor. Yaşlı bir konuk uçağına yetişmeye çalışırken telaşla cihazın başında bekliyor.","soru":"Ne yaparsın?","secenekler":["Cihazı yeniden başlatır, konuğa birkaç dakika beklemesini söylerim.","Konuğa resepsiyon sırasına girmesini söyler, arızayı yoğunluk bitince bildiririm.","Konuğa eşlik eder, çıkışını resepsiyonda yaptırır, arızayı amirime bildiririm.","Teknik servise haber verir, konuğa cihaz onarılınca çıkış yapabileceğini söylerim."],"dogru":2,"aciklama":"Teknoloji işlemi hızlandırır ama konuk takıldığında insan dokunuşu devreye girer. Konuk uçağa yetişmeye çalışırken beklemek ya da sıraya sokmak hizmeti bozar; eşlik edip çıkışı hemen yaptırmak ve arızayı bildirmek hem konuğu hem sistemi korur."},{"id":"go-3-s32","tur":"senaryo","durum":"Yoğun yaz sezonunda arka arkaya altı gündür çalışıyorsun, çok yorgunsun ve iki konuğa gereksiz sert cevap verdiğini fark ettin. İş yerinde kimseye bir şey söylemedin.","soru":"Ne yaparsın?","secenekler":["Yorgunluğumu amirime açıkça anlatır, vardiya ve izin için destek isterim.","Sert cevap verdiğim konuklardan özür dileyip aynı tempoda çalışmayı sürdürürüm.","Zor günlerin geçip gideceğini düşünüp sezon bitene kadar sessiz kalırım.","Vardiyamı bir arkadaşa devredip amirime haber vermeden dinlenmeye giderim."],"dogru":0,"aciklama":"Çalışan refahı işletmenin ve çalışanın ortak sorumluluğudur; yorgunluk hizmeti bozar. Durumu amire açıkça anlatıp çözüm aramak profesyoneldir. Özür dilemek iyidir ama nedeni çözmez; sessiz kalmak ya da habersiz devretmek sorunu büyütür."},{"id":"go-3-s33","tur":"coktan-secmeli","soru":"Selin yabancı dilini geliştirmek için kişisel gelişim planına hedef yazıyor. Aşağıdakilerden hangisi ilerlemesini ölçmesine en çok yardımcı olur?","secenekler":["Dilimi elimden geldiğince geliştireceğim.","Daha iyi olmak için çok çalışacağım.","Kendimi sürekli geliştireceğim.","Haftada iki kez konuşma çalışacağım."],"dogru":3,"aciklama":"Ölçülebilir hedef sayılabilir ve takvime bağlanabilir; “haftada iki konuşma çalışması” yapılıp yapılmadığı bellidir. “Elimden geldiğince”, “çok çalışacağım” gibi sözlerde hedefe ne zaman ulaşıldığı anlaşılamaz."},{"id":"go-3-s34","tur":"coktan-secmeli","soru":"Liseden sonra ön büro dalında, genellikle iki yıl süren ve uygulama ağırlıklı bir yükseköğretim seçeneği arayan öğrenci hangisine yönelmelidir?","secenekler":["Lisans (turizm fakültesi)","Dikey geçiş","Önlisans programı","Yönetici adayı programı"],"dogru":2,"aciklama":"Önlisans, liseden sonra genellikle iki yıl süren, uygulama ağırlıklı bir yükseköğretimdir. Turizm fakültesindeki lisans eğitimi ise genellikle dört yıl sürer."},{"id":"go-3-s35","tur":"coktan-secmeli","soru":"Meslek lisesi öğrencisi Ayşe, stajının bir bölümünü başka bir ülkede yapmak istiyor ve okul panosundaki Erasmus+ duyurusunu inceliyor. Ayşe’nin yararlanmak istediği olanak hangisidir?","secenekler":["Zincir içi yurt dışı transferi","Uluslararası öğrenci değişimi","Yurt dışında sezonluk çalışma","Departmanlar arası geçiş"],"dogru":1,"aciklama":"Uluslararası öğrenci değişimi, eğitimin ya da stajın bir bölümünü başka bir ülkede yapmaya olanak verir. Zincir içi transfer ise bir otel zincirinde zaten çalışan kişiler içindir."},{"id":"go-3-s36","tur":"dogru-yanlis","soru":"Stajdaki şefini iş başvurusunda referans olarak göstermek isteyen öğrencinin önce şefinden izin alması gerekir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Referans gösterilecek kişiye önceden sorulur; otelcilikte müdürler işe almadan önce referansı arayabildiği için kimse izinsiz referans gösterilmez."},{"id":"go-3-s37","tur":"coktan-secmeli","soru":"Bir otelin kat hizmetleri müdürü, bölümünün bütün işleyişinden, bütçesinden ve ekibinden sorumludur. Bu basamakta işin ağırlığı en çok hangisine kayar?","secenekler":["Konuğa tek tek oda servisi yapmaya","Yalnız kendi vardiyasındaki görevleri bitirmeye","Deneyimli birinin gözetiminde iş öğrenmeye","Konuktan çok ekibi ve rakamları yönetmeye"],"dogru":3,"aciklama":"Bölüm yöneticisi basamağında kişi konuktan çok ekibi ve rakamları yönetir. Yalnız kendi görevini bitirmek ya da gözetim altında öğrenmek, merdivenin alt basamaklarına özgüdür."},{"id":"go-3-s38","tur":"coktan-secmeli","soru":"Ön büro ve restoran stajı yapmış bir öğrenci, aylarca deniz üzerinde yaşayıp farklı ülkelerden mürettebatla kabin hizmetlerinde ve restoranda çalışmak istiyor. Hangi alan ona en uygundur?","secenekler":["Hava yolunda kabin ekibi","Kruvaziyer kariyeri","Etkinlik yönetimi","Lüks perakende"],"dogru":1,"aciklama":"Yolcu gemisi yüzen bir oteldir; kabin hizmetleri, restoran ve ön büro ekipleri vardır. Hava yolundaki kabin ekibi ise uçakta çalışır, aylarca gemide yaşamaz."},{"id":"go-3-s39","tur":"coktan-secmeli","soru":"Akşam 19.00’da restoranda iki masanın aynı saate rezerve edildiği anlaşılıyor ve garson tek başına çözüm bulamıyor. Bu durumda en doğru davranış hangisidir?","secenekler":["Durumu hemen şefine bildirip konuklardan özür dilemek","Konuklardan birine yerin dolu olduğunu söyleyip göndermek","Hatanın rezervasyonu alanda olduğunu konuklara anlatmak","Şef fark edene kadar konukları kapıda bekletmek"],"dogru":0,"aciklama":"Çözüm bulunamayınca susmak yerine amire hızlıca haber vermek de problem çözmenin parçasıdır; özür dilemek konuğu sakinleştirir. Suçlu göstermek ya da konuğu göndermek sorunu büyütür."},{"id":"go-3-s40","tur":"dogru-yanlis","soru":"Otelde görünüm standartları çalışanın yüzü ve bedeniyle ilgilidir; kıyafet ve kişisel bakım bu standartların dışında kalır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Görünüm standartları üniforma, kişisel bakım ve duruşla ilgilidir; kimsenin yüzüyle ya da bedeniyle ilgili değildir."},{"id":"go-3-s41","tur":"coktan-secmeli","soru":"Okulun kariyer gününde öğrenci, konuşmacı otel müdürüne soru soruyor ve aynı gün ona teşekkür e-postası gönderiyor. Öğrencinin yaptığı hangisidir?","secenekler":["Mentorla çalışma","Portfolyo hazırlama","Meslekte ağ kurma","Referans gösterme"],"dogru":2,"aciklama":"Ağ kurma, meslekte tanışılan insanlarla düzenli ve samimi ilişki kurmaktır. Mentorla çalışma ise deneyimli biriyle süren bir yol gösterme ilişkisidir; tek bir tanışma bunu sağlamaz."},{"id":"go-3-s42","tur":"coktan-secmeli","soru":"Ege’de bir otel, kahvaltıdaki zeytin, peynir ve balı aynı ilçedeki üreticilerden alıyor. Bu uygulamanın yararlarından biri hangisidir?","secenekler":["Ürünler hijyen denetiminden muaf tutulur.","Otel menüsünü her gün değiştirmek zorunda kalmaz.","Konuk ürünü kendisi alıp odasına götürebilir.","Taşıma azalır, para yöredeki insanlarda kalır."],"dogru":3,"aciklama":"Yöre ürünüyle tedarikte ürün taze olur, taşıma azalır ve para yörede kalır. Yerel ürün de kalite ve hijyen şartlarını karşılamak zorundadır."},{"id":"go-3-s43","tur":"dogru-yanlis","soru":"Konuk otelin sohbet robotuna yumurta alerjisi olduğunu yazarsa konunun bir çalışana yönlendirilmesi doğru bir uygulamadır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yapay zekâ sık sorulan soruları hızla yanıtlayabilir; ama alerji gibi hassas konularda karar insanındır."},{"id":"go-3-s44","tur":"coktan-secmeli","soru":"Konuk odadan çıkıp kartını çekince ışıklar ve klima kendiliğinden kapanıyor. Bu uygulama en çok hangi kavramla ilgilidir?","secenekler":["Su ve çamaşır tasarrufu","Mobil anahtar","Otelde enerji verimliliği","Atık yönetimi ve sıfır atık"],"dogru":2,"aciklama":"Enerji verimliliği, aynı hizmeti daha az elektrik harcayarak sunmaktır; boş odada ışık ve klimanın kapanması buna örnektir. Mobil anahtar yalnız kapıyı telefonla açma sistemidir."}],"siralamalar":[{"id":"go-3-r01","konu":"3.1","baslik":"Liseden lisansa: okul basamakları","yonerge":"Meslek lisesinden lisans eğitimine uzanan yolun adımlarını doğru sıraya koy.","adimlar":["Turizm meslek lisesinde meslek derslerini ve işletmede eğitimini tamamla.","Genellikle iki yıl süren, uygulama ağırlıklı bir önlisans programını bitir.","Dikey geçiş koşullarını sağlayıp lisans programına geçiş yap.","Lisans programında otel işletmeciliğini planlama ve yönetim boyutuyla öğren."],"aciklama":"Lise, önlisans ve lisans basamakları art arda gidilebilir; önlisanstan lisansa geçişin kapısı dikey geçiştir."},{"id":"go-3-r02","konu":"3.2","baslik":"Kariyer merdiveninin basamakları","yonerge":"Stajyerlikten genel müdürlüğe uzanan kariyer merdiveninin basamaklarını doğru sıraya koy.","adimlar":["Deneyimli çalışanların gözetiminde stajyer olarak mesleği öğren.","Uzun deneyim aranmayan bir giriş görevinde, örneğin resepsiyonda çalış.","Süpervizör olarak bir vardiyanın akışını izle ve ekibe görev dağıt.","Bölüm yöneticisi olarak bir bölümün bütçesinden ve ekibinden sorumlu ol.","Genel müdür olarak bölüm yöneticilerinin bağlı olduğu otel yönetimini üstlen."],"aciklama":"Her basamakta işin bir yönü öğrenilir: kendi işinden ekibin işine, oradan bir bölüme ve bütün otele uzanan bir sorumluluk büyür. Genel müdür adayları çoğunlukla önce bir bölümü başarıyla yönetmiş kişilerdir."},{"id":"go-3-r03","konu":"3.3","baslik":"Konuk sorunu: dinle, özetle, çöz","yonerge":"Konuk bir sorun bildirdiğinde izleyeceğin adımları doğru sıraya koy.","adimlar":["Sakin kal ve konuğu sözünü kesmeden dinle.","Anladığını kısaca özetleyerek konuğa doğrulat.","Olası çözümleri düşün.","Çözümü yetkili kişiyle birlikte uygula."],"aciklama":"Sorun doğru anlaşılmadan çözülemez: önce dinlenir, sonra özetlenir, sonra çözülür. Çözüm bulunamazsa susmak yerine amire hızlıca söylemek de problem çözmenin parçasıdır."},{"id":"go-3-r04","konu":"3.4","baslik":"Sürdürülebilirlik belgesine giden yol","yonerge":"Bir otelin GSTC ölçütlerine dayanan sürdürülebilirlik belgesini alma sürecini doğru sıraya koy.","adimlar":["Küresel Sürdürülebilir Turizm Konseyi uluslararası ortak ölçütleri belirler.","Otel, bu ölçütlere dayanan bir belge için denetim ister.","Denetçi atık kayıtlarını, çalışan sözleşmelerini ve yerel halkla iş birliğini inceler.","Bağımsız belgelendirme kuruluşu otele belgeyi verir."],"aciklama":"Ölçüt olmadan denetim, denetim olmadan belge olmaz. GSTC otellere doğrudan belge vermez; belgeyi ölçütlere dayanan programlar ve bağımsız kuruluşlar verir."}],"acikSorular":[{"id":"go-3-y01","konu":"3.2","soru":"Bir otelin ön bürosunda stajyer olarak işe başlayan Elif, ileride otelin genel müdürü olmak istiyor. Stajyerlikten sonra izleyebileceği üç kariyer basamağını sırasıyla yazınız ve çapraz eğitimin bu yolda ona nasıl yardımcı olacağını açıklayınız.","olcut":[{"metin":"Kariyer merdiveninin, stajyerlikten başlayıp daha sorumlu görevlere ilerleyen basamaklar olduğunu belirtir.","puan":15},{"metin":"Stajyerlikten sonraki üç basamağı (örneğin giriş seviyesi görev, süpervizör, bölüm yöneticisi) doğru sırayla yazar.","puan":30},{"metin":"Çapraz eğitimin, çalışanın kendi bölümünün yanında başka bir bölümün işlerini de öğrenmesi olduğunu açıklar.","puan":20},{"metin":"Çapraz eğitimin Elif’in bölümler arası geçişini ve genel müdür olmasını neden kolaylaştırdığını açıklar.","puan":35}],"ornek":"Kariyer merdiveni, bir çalışanın stajyerlikten başlayarak daha sorumlu görevlere ilerlediği basamaklardır. Elif önce stajyer, sonra resepsiyon görevlisi gibi giriş seviyesi bir görevde çalışır; ardından süpervizör, sonra ön büro müdürü gibi bölüm yöneticisi olur. Çapraz eğitim, çalışanın kendi bölümünün yanında başka bir bölümün işlerini de öğrenmesidir. Elif kat hizmetlerini ve satışı da tanırsa otelin bütününü anlar, bölümler arası geçiş yapabilir ve genel müdür olduğunda tüm ekibi daha iyi yönetir.","ipucu":"Genel müdürün yalnız bir bölümü değil, otelin tamamını yönettiğini düşünün; başka bölümleri tanımak neyi değiştirir?"},{"id":"go-3-y02","konu":"3.4","soru":"Sürdürülebilir otelcilik anlayışını benimseyen bir otelin yönetimi, hem gideri azaltmak hem de çevreyi korumak istiyor. Sürdürülebilir otelciliği tanımlayınız, otelin uygulayabileceği iki tasarruf uygulamasını yazınız ve bu uygulamaların sürdürülebilirlik anlayışıyla nasıl ilişkili olduğunu açıklayınız.","olcut":[{"metin":"Sürdürülebilir otelciliği, doğaya ve yerel halka zarar vermeden gelecek kuşakların da turizmden yararlanmasını amaçlayan anlayış olarak tanımlar.","puan":25},{"metin":"Birinci tasarruf uygulamasını (örneğin su ve çamaşır tasarrufu) örnekle yazar.","puan":20},{"metin":"İkinci tasarruf uygulamasını (örneğin enerji verimliliği ya da atık yönetimi) örnekle yazar.","puan":20},{"metin":"Uygulamaların hem doğayı koruduğunu hem de gelecek kuşaklara kaynak bıraktığını nedenini belirterek açıklar.","puan":35}],"ornek":"Sürdürülebilir otelcilik, bugünkü konuğu ağırlarken doğaya ve yerel halka zarar vermemeyi, gelecek kuşakların da turizmden yararlanabilmesini amaçlayan anlayıştır. Otel, havlunun her gün değiştirilmesini konuğun isteğine bırakarak su ve çamaşır tasarrufu yapabilir. İkinci olarak otel, aynı hizmeti daha az elektrikle sunmak için enerji verimliliği uygulayabilir. Bu uygulamalar kaynakların tükenmesini yavaşlattığı için doğa korunur ve gelecek kuşaklara da kullanılabilir kaynak kalır.","ipucu":"Kaynakları bugün gereğinden fazla harcarsak gelecek kuşaklara ne kalır diye düşünün; tasarruf bu soruya nasıl cevap verir?"}]},{"ders":"global-otelcilik","sinif":9,"unite":4,"baslik":"Servis Sanatı ve Dünya Mutfağı","onay":true,"kazanimlar":["Uluslararası restoran ve mutfak organizasyonunu, unvanları ve çalışma düzenini açıklar.","Dünyada kullanılan servis tarzlarını ve masa düzeni ilkelerini uygular.","Menü türlerini, dünya mutfaklarının temel kavramlarını ve gastronomi turizmini açıklar.","Beslenme tercihleri, alerjenler ve kültürel hassasiyetler karşısında doğru servisi uygular."],"soz":"Konuk yemeğin tadını hatırlar, ama onu o masaya oturtan hissi servis kurar.","dersler":[{"baslik":"Salonun Komutanları","ilk":"go-4-001"},{"baslik":"Sahibi Olan Masa","ilk":"go-4-005"},{"baslik":"Mutfakta Rütbeler","ilk":"go-4-008"},{"baslik":"Ocağın Başında","ilk":"go-4-011"},{"baslik":"Sipariş Mutfağa Nasıl Gider?","ilk":"go-4-014"},{"baslik":"Yemek Masaya Nasıl Gelir?","ilk":"go-4-019"},{"baslik":"Ev Usulünden Tepsiye","ilk":"go-4-023"},{"baslik":"Masayı Kurmak","ilk":"go-4-028"},{"baslik":"Sağdan mı, Soldan mı?","ilk":"go-4-032"},{"baslik":"Menüyü Okumak","ilk":"go-4-036"},{"baslik":"Restoranın Kişiliği","ilk":"go-4-040"},{"baslik":"Dünya Sofrasında Dört Durak","ilk":"go-4-045"},{"baslik":"Yıldızlar ve Şehirler","ilk":"go-4-049"},{"baslik":"Türk Sofrasının Mirası","ilk":"go-4-052"},{"baslik":"Tabağını Seçen Konuk","ilk":"go-4-057"},{"baslik":"Alerji Şaka Değildir","ilk":"go-4-062"},{"baslik":"Alerjide Sıra ve Acil","ilk":"go-4-065"},{"baslik":"Her Konuğa Ayrı Masa","ilk":"go-4-067"},{"baslik":"Hesap, Şikâyet, Hijyen","ilk":"go-4-071"}],"kavramlar":[{"id":"go-4-001","konu":"4.1","terim":"Restoran müdürü","ingilizce":"Restaurant manager","tanim":"Yemek salonunun açılışından kapanışına kadar servisi, ekibi ve konuk memnuniyetini yöneten kişidir.","ornek":"Cuma akşamı 19.30, Bodrum’da bir otelin restoranı: müdür salonu dolaşır, geç kalan masayı fark eder, mutfakla konuşur ve doğum günü olan masaya tatlı ikramı için garsonu yönlendirir.","sektor":"Restoran müdürü hem konuğu hem ekibi okur: bir yandan şikâyeti çözer, bir yandan vardiya planını ve stoğu izler. Otelde genellikle yiyecek içecek müdürüne bağlı çalışır ve stajyer için kariyer basamağının üst noktalarından biridir.","iliskili":["go-4-002","go-4-003"],"kontrol":null,"kitapDisi":true},{"id":"go-4-002","konu":"4.1","terim":"Maître d’hôtel","ingilizce":"Maître d'hôtel (head waiter)","tanim":"Büyük ve özenli restoranlarda yemek salonunun akışını yöneten, konukları karşılayıp masalarını belirleyen kıdemli salon sorumlusudur.","ornek":"Akşam 20.00, İstanbul’da bir otelin fine dining restoranı: maître d’ rezervasyon defterine bakar, yıl dönümünü kutlayan çifti pencere kenarına alır ve ekibe önceden haber verir.","sektor":"Unvan işletmeden işletmeye değişir; bazı yerlerde restoran müdürüyle aynı kişidir, bazı yerlerde ondan bir basamak altta çalışır. Konukla ilk ve son göz teması çoğu zaman onunladır; salonun havasını o kurar.","iliskili":["go-4-001","go-4-004"],"kontrol":null,"kitapDisi":true},{"id":"go-4-003","konu":"4.1","terim":"Host (karşılama görevlisi)","ingilizce":"Host (greeter)","tanim":"Restoran girişinde konuğu karşılayan, boş masalara bakan ve konuğu masasına götüren görevlidir.","ornek":"Sabah 08.30, Antalya’da bir resortun kahvaltı salonu: host oda numarasını sorar, listeden doğrular ve bebek arabalı aileyi kolay ulaşılır bir masaya yönlendirir.","sektor":"Konuğun restorana girince gördüğü ilk yüz hosttur; ilk izlenim burada kurulur. Doğru yerleştirme bekleme süresini kısaltır ve masaların garsonlar arasında dengeli dağılmasını sağlar.","iliskili":["go-4-002","go-4-007"],"kontrol":null,"kitapDisi":true,"cizim":"resepsiyon"},{"id":"go-4-004","konu":"4.1","terim":"Chef de rang","ingilizce":"Chef de rang (station head waiter)","tanim":"Belirli masa grubundan sorumlu olan, siparişi alıp servisi yöneten ve komiyle birlikte çalışan deneyimli garsondur.","ornek":"Akşam 21.00, Çeşme’de bir otelin restoranı: chef de rang kendi dört masasının siparişini alır, yemekleri sırayla çıkartır ve komiye hangi masanın tabaklarının kaldırılacağını söyler.","sektor":"Bazı otellerde aynı görev captain (kaptan garson) diye anılır. Klasik düzende komi, demi-chef de rang ve chef de rang basamakları vardır; her işletmede bu adlar kullanılmaz. Chef de rang kendi masalarının memnuniyetini ve gelirini sahiplenen kişidir.","iliskili":["go-4-005","go-4-006","go-4-007"],"kontrol":null,"kitapDisi":true,"cizim":"restoran-servis"},{"id":"go-4-005","konu":"4.1","terim":"Garson","ingilizce":"Waiter (server)","tanim":"Konuktan siparişi alan, yemeği ve içeceği masaya getiren ve masayı baştan sona takip eden servis görevlisidir.","ornek":"Öğle 12.30, Kapadokya’da bir otel restoranı: garson masaya gelir, günün çorbasını ve içindekileri kısaca anlatır, konuğa alerjisi olup olmadığını sorar.","sektor":"Garson restoranın en çok konuşan yüzüdür; menüyü iyi bilen garson önerisiyle satışı artırır. Dünya otelciliğinde cinsiyetten bağımsız olarak çoğu zaman server denir. Gülümsemek, doğru önermek ve konuğu yormadan hizmet etmek işin üç ayağıdır.","iliskili":["go-4-004","go-4-006"],"kontrol":null,"kitapDisi":true,"cizim":"restoran-servis"},{"id":"go-4-006","konu":"4.1","terim":"Komi (commis de rang)","ingilizce":"Commis de rang (junior waiter)","tanim":"Garsona yardım eden, masaları kuran, su ve ekmek servisi yapan ve kirli tabakları toplayan başlangıç düzeyi salon görevlisidir.","ornek":"Sabah 07.00, kahvaltı salonu: komi büfedeki boşalan tabakları yeniler, biten masaları toplar ve yeni gelecek konuk için kuveri yeniden kurar.","sektor":"Stajyerler en sık bu görevle başlar. Komi izleyerek öğrenir: konuğun nasıl oturduğunu, garsonun masaya nasıl yaklaştığını görür. Hızlı ama sessiz çalışmak burada öğrenilen ilk beceridir.","iliskili":["go-4-005","go-4-004"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-ekmek-tereyag-servisi"},{"id":"go-4-007","konu":"4.1","terim":"Servis bölgesi ve masa numaraları","ingilizce":"Service station and table numbering","tanim":"Salonun masa gruplarına ayrılıp her grubun belirli bir garsona verilmesi, masalara ve koltuklara numara verilmesi düzenidir.","ornek":"Akşam 18.45, Side’de bir otelin restoranı: salon üç bölgeye ayrılmıştır; garson 1-6 numaralı masalara bakar ve sipariş fişine masa numarasını ve koltuk sırasını yazar.","sektor":"Her masanın bir sahibi olduğunda “kimse bakmadı” durumu biter. Koltuk numarası da yemeğin doğru kişiye gitmesini sağlar; numaralama sırası işletmeden işletmeye değişir ve ekibin tamamı aynı kuralı bilmelidir.","iliskili":["go-4-003","go-4-015"],"kontrol":null,"kitapDisi":true},{"id":"go-4-008","konu":"4.1","terim":"Mutfak brigadı (brigade de cuisine)","ingilizce":"Kitchen brigade (brigade de cuisine)","tanim":"Mutfaktaki işlerin kıdem ve uzmanlık sırasına göre bölümlere ayrıldığı, askerî düzene benzeyen ekip sistemidir.","ornek":"Sabah 09.00, İstanbul’da büyük bir otelin mutfağı: sıcak kısımda bir ekip, pastanede başka bir ekip çalışır; hepsi aynı şefe bağlıdır ve herkes görevini bilir.","sektor":"Bu düzeni Fransız şef Auguste Escoffier’in sistemleştirip yaygınlaştırdığı kabul edilir ve dünya mutfaklarına yayılmıştır. Küçük otelde roller birleşir, büyük otelde tam olarak görülür; ama fikir aynıdır: herkesin bir işi vardır ve işler sırayla akar.","iliskili":["go-4-009","go-4-010","go-4-011"],"kontrol":null,"kitapDisi":true},{"id":"go-4-009","konu":"4.1","terim":"Executive chef","ingilizce":"Executive chef (head chef)","tanim":"Otelin bütün mutfaklarını yöneten, menüden maliyete, alımdan ekip eğitimine kadar her şeyden sorumlu baş aşçıdır.","ornek":"Sabah 10.00, Bodrum’da bir resort: executive chef yeni sezon menüsünü hazırlar, satın almayla yerel üretici listesini gözden geçirir ve sous chef’lere görev dağıtır.","sektor":"Executive chef günün büyük kısmını ocak başında değil, masa başında geçirir: planlama, maliyet, ekip ve kalite. Mutfak çalışanı için kariyer hedefidir; yiyecek içecek müdürüyle uyum içinde çalışır.","iliskili":["go-4-008","go-4-010"],"kontrol":null,"kitapDisi":true,"cizim":"mutfak"},{"id":"go-4-010","konu":"4.1","terim":"Sous chef","ingilizce":"Sous chef (deputy head chef)","tanim":"Executive chef’in yardımcısı olarak mutfağı günlük yöneten, şef yokken onun yerine karar veren aşçıdır.","ornek":"Akşam 18.30: servis başlamadan sous chef bölüm şeflerini toplar; bugünkü rezervasyon sayısını, özel diyet notlarını ve bitmek üzere olan malzemeleri anlatır.","sektor":"Servis anında kalite, hız ve düzeni sous chef tutar; mutfağın günlük kaptanıdır. Fransızca “sous” altında demektir. Mutfakta ilerleyen kişi için çoğu mutfakta executive chef’ten önceki son basamaktır.","iliskili":["go-4-009","go-4-011"],"kontrol":null,"kitapDisi":true,"cizim":"mutfak"},{"id":"go-4-011","konu":"4.1","terim":"Chef de partie","ingilizce":"Chef de partie (station chef)","tanim":"Mutfakta belirli bir bölümün (sos, balık, tatlı gibi) sorumlusu olan ve o bölümde çalışanları yöneten aşçıdır.","ornek":"Akşam 19.00, ızgara bölümü: sorumlu aşçı bütün siparişleri tek tek sayar, etlerin pişme derecesini kontrol eder ve commis’sine garnitürü hazırlattırır.","sektor":"Mutfakta uzmanlaşmanın başladığı basamaktır; bir bölümde ustalaşan chef de partie sonra sous chef’e yükselebilir. Klasik düzende bölümün adı görevi söyler (örn. saucier sos, pâtissier tatlı ve pasta hazırlar).","iliskili":["go-4-010","go-4-012"],"kontrol":null,"kitapDisi":true,"cizim":"mutfak"},{"id":"go-4-012","konu":"4.1","terim":"Commis (aşçı yardımcısı)","ingilizce":"Commis chef (junior cook)","tanim":"Chef de partie’nin yanında çalışarak mutfağı öğrenen, malzeme hazırlayan ve basit pişirme işlerini yapan başlangıç düzeyi aşçıdır.","ornek":"Sabah 07.30: commis sebzeleri yıkar, doğrar ve kasalara koyar; chef de partie ona bıçak tutuşunu gösterir.","sektor":"Aşçılığın ilk basamağıdır. Yaygın yol commis, chef de partie, sous chef, executive chef sırasıyla ilerler. Sabırla ve dikkatle öğrenen commis çoğu zaman farklı bölümlerde çalışarak mutfağın tamamını görür.","iliskili":["go-4-011","go-4-008"],"kontrol":null,"kitapDisi":true},{"id":"go-4-013","konu":"4.1","terim":"Mise en place (servis öncesi hazırlık)","ingilizce":"Mise en place","tanim":"Fransızca “yerli yerine koymak” anlamına gelen, servis başlamadan önce her şeyin hazır ve elinin altında olmasını sağlayan düzenli hazırlıktır.","ornek":"Akşam 17.30, Antalya’da bir otelin restoranı: servise bir saat var; garson peçeteleri katlar, tuzluk ve biberlikleri doldurur, menüleri kontrol eder. Mutfakta da soslar ve doğranmış sebzeler hazırlanır.","sektor":"Profesyoneller “hazırlık servisin yarısıdır” der. Servis anında kaybedilen her dakika konukla geçirilemeyen dakikadır. Hazırlıklı ekip sakin görünür, sakin ekip de konuğa güven verir.","iliskili":["go-4-006","go-4-012"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-mise-en-place"},{"id":"go-4-014","konu":"4.1","terim":"Adisyon","ingilizce":"Guest check (order slip)","tanim":"Restoranda masaya ait siparişlerin yazıldığı ve sonunda hesabın çıkarıldığı belgedir.","ornek":"Öğle 13.00: garson 5 numaralı masanın siparişini adisyona işler; konuk hesap isteyince kalemler yeniden yazılmak zorunda kalmaz, adisyon hazırdır.","sektor":"Yanlış yazılan tek kalem hem konuğun hem otelin hesabını bozar. Oda hesabına yazdırılan yemeklerde adisyon, ön büro hesabına doğru oda numarasıyla geçmelidir. Adisyondaki not (alerji, çocuk için ayrı tabak gibi) mutfağa da yansır.","iliskili":["go-4-015","go-4-016"],"kontrol":null,"kitapDisi":true,"cizim":"belge-form"},{"id":"go-4-015","konu":"4.1","terim":"Sipariş fişi (KOT)","ingilizce":"Kitchen order ticket (KOT)","tanim":"Garsonun aldığı siparişin, masa numarası ve notlarıyla birlikte mutfağa iletildiği fiştir.","ornek":"Akşam 20.15: garson siparişi tablete girer, sıcak kısımdaki yazıcıdan 12 numaralı masanın fişi çıkar; fişte “fıstık alerjisi” notu kırmızı kalemle işaretlenir.","sektor":"KOT mutfağın sözlü emir yerine yazılı emir almasını sağlar; karışıklık azalır. Mutfak fişi bölümlere ayırır: soğuk başlangıç, sıcak yemek, tatlı. Eksik not ya da silik yazı, yanlış tabak demektir.","iliskili":["go-4-014","go-4-016","go-4-017"],"kontrol":null,"kitapDisi":true,"cizim":"belge-form"},{"id":"go-4-016","konu":"4.1","terim":"Restoran sipariş sistemi (POS)","ingilizce":"Restaurant order system (POS)","tanim":"Siparişin dokunmatik ekrandan girildiği, mutfağa ve kasaya anında iletildiği, hesabı oluşturan yazılım ve cihaz bütünüdür.","ornek":"Akşam 21.00, İzmir’de bir şehir oteli: garson siparişi el terminaline girer, mutfak ekranında hemen belirir; hesap istendiğinde kalemler eksiksizdir.","sektor":"Sistem hangi yemeğin çok satıldığını ve hangi saatin yoğun olduğunu raporlar; şefler menü kararını buna göre verir. Otelde sistem, oda hesabına yazdırma için ön büronun yazılımıyla da bağlanır. Garsonun sistemi hızlı ve doğru kullanması gelir kaybını önler.","iliskili":["go-4-015","go-4-014"],"kontrol":null,"kitapDisi":true},{"id":"go-4-017","konu":"4.1","terim":"Servis penceresi (pass)","ingilizce":"The pass","tanim":"Hazır yemeğin mutfaktan çıktığı, kontrol edilip servise verildiği tezgâh ya da pencere hattıdır.","ornek":"Akşam 20.40: aşçı tabağı pass’e koyar, sous chef tabağın kenarındaki sosu sildirir, sıcaklığı kontrol eder; garson fişle eşleştirip tabağı alır.","sektor":"Mutfak ile salon arasındaki son kalite kapısıdır. Tabak burada soğursa konuk soğuk yemek yer; bu yüzden sıcak yemek pass’te bekletilmez ve fişle eşleşmeyen tabak götürülmez. Büyük mutfaklarda pass’i ekspeditör denen bir koordinatör yönetir.","iliskili":["go-4-015","go-4-018"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-servis-penceresi"},{"id":"go-4-018","konu":"4.1","terim":"Servis akışı","ingilizce":"Sequence of service","tanim":"Konuğun karşılanmasından hesabın ödenip uğurlanmasına kadar restoranda izlenen adımlar dizisidir.","ornek":"Akşam 19.00, Marmaris’te bir otel restoranı: konuk karşılanır, oturtulur, su ve menü gelir, sipariş alınır, yemekler sırayla çıkar, tabaklar toplanır, hesap gelir ve konuk kapıda uğurlanır.","sektor":"Hizmetin her adımı bir halkadır; bir halka atlanırsa konuk bunu hisseder. Lüks restoranlar akışı yazılı standart hâline getirir (Ünite 2’deki hizmet standardı gibi). Konuk yemeğin tadı kadar bekleme anlarını da hatırlar.","iliskili":["go-4-017","go-4-003"],"kontrol":null,"kitapDisi":true,"gorsel":"t13b-servis-tabaklar"},{"id":"go-4-019","konu":"4.2","terim":"Servis tarzı","ingilizce":"Style of service","tanim":"Yemeğin mutfaktan konuğun tabağına hangi yolla ve kimin eliyle ulaştığını belirleyen servis biçimidir.","ornek":"Aynı otelde sabah kahvaltısı büfeyle, öğle yemeği hazır tabakla, akşam yemeği fine dining salonunda masa başında servis edilir; konuk bir günde üç tarz görür.","sektor":"Tarz seçimi restoranın konseptini, fiyatını ve gereken personel sayısını belirler. Masa başı servis çok personel ister ve pahalıdır; büfe az personelle çok konuğa ulaşır. Hangi tarzda çalıştığını bilmeyen çalışan doğru davranamaz.","iliskili":["go-4-020","go-4-024","go-4-026"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-gemi-acik-bufe-servisi"},{"id":"go-4-020","konu":"4.2","terim":"Fransız servisi","ingilizce":"French service","tanim":"Yemeğin konuğun gözü önünde, çoğunlukla masaya getirilen bir servis arabasında tamamlanarak sunulduğu, çok özenli ve zaman alan servis tarzıdır.","ornek":"Akşam 21.00, İstanbul’da bir otelin fine dining salonu: garson gümüş servis kabını masaya getirir, konuğa gösterir ve yemeği masa başında tamamlayarak tabağa koyar.","sektor":"Kaynaklara göre bu tarzın adı ve ayrıntıları biraz değişir; ortak fikir, yemeğin son hazırlığının masada ve konuğun gözü önünde yapılmasıdır. En çok eğitimli personel isteyen servislerdendir, bu yüzden lüks restoranlarda görülür.","iliskili":["go-4-021","go-4-019"],"kontrol":null,"kitapDisi":true,"gorsel":"t12u-flambe-gueridon"},{"id":"go-4-021","konu":"4.2","terim":"Guéridon servisi","ingilizce":"Guéridon (trolley) service","tanim":"Yemeğin konuğun masasının yanına getirilen küçük bir servis arabasında dilimlenip hazırlandığı servis tekniğidir.","ornek":"Akşam 20.30, Ankara’da bir otelin restoranı: garson servis arabasında büyük balığı kılçığından ayırıp konuğun tabağına koyar, salatayı arabada sosla karıştırır.","sektor":"Gösterisi kadar becerisi de önemlidir: bıçak kullanımı ve temiz çalışma gerekir. Servis arabasında yapılan alevli sunumlara flambé denir; yangın riski taşıdığı için yalnız eğitimli ve yetkili servis personeli yapar, stajyer izler ve öğrenir.","iliskili":["go-4-020","go-4-022"],"kontrol":null,"kitapDisi":true},{"id":"go-4-022","konu":"4.2","terim":"Rus servisi","ingilizce":"Russian service","tanim":"Yemeğin mutfakta büyük bir servis tabağına dizildiği, garsonun bu tabaktan her konuğun önündeki boş tabağa çatal-kaşıkla porsiyon koyduğu servis tarzıdır.","ornek":"Akşam 20.00, Kapadokya’da bir otelin ziyafet salonu: garson büyük tabaktaki kuzu etini sırayla her konuğun tabağına paylaştırır.","sektor":"Büyük davetlerde ve resmî yemeklerde görülür. Yemekler aynı anda sıcak çıkabilir, ama garsonların eğitimli ve düzenli çalışması gerekir. Kaynaklara göre bu tarz farklı adlarla (örn. gümüş servis) anılabilir.","iliskili":["go-4-021","go-4-023","go-4-024"],"kontrol":null,"kitapDisi":true},{"id":"go-4-023","konu":"4.2","terim":"İngiliz servisi","ingilizce":"English service","tanim":"Yemeğin masada ev sahibi tarafından dilimlenip paylaştırıldığı, garsonun ise tabakları dağıtıp yardımcı olduğu ev usulü servis tarzıdır.","ornek":"Pazar öğle yemeği, Bursa’da bir otelin özel yemek odası: büyük kuzu kızartması masaya gelir, ev sahibi dilimleyip tabaklara koyar, garson tabakları konuklara dağıtır.","sektor":"Otelde nadir görülür; özel davet masasında ev sahibi rolü konuğa verilir. Garsonun işi ev sahibine yardımcı olmak ve rolünü bozmamaktır. Kaynaklara göre bu tarzın adı ve ayrıntıları değişebilir.","iliskili":["go-4-022","go-4-025"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-kizartilmis-hindi-dilimleme"},{"id":"go-4-024","konu":"4.2","terim":"Amerikan servisi (tabak servisi)","ingilizce":"American (plated) service","tanim":"Yemeğin mutfakta tabağa porsiyonlanıp süslendikten sonra hazır tabakla masaya getirildiği hızlı ve düzenli servis tarzıdır.","ornek":"Öğle 13.00, İzmir’de bir otelin toplantı yemeği: mutfak iki yüz kişiye aynı anda tabakları hazırlar; garsonlar tabakları kollarında taşıyıp masalara koyar.","sektor":"Otellerde ve restoranlarda en çok görülen tarzlardandır. Sunum mutfakta belirlendiği için her tabak aynı görünür. Hızlıdır, az personelle yapılabilir; masa başı gösteri sunmaz ve tabağın sıcak çıkması başarının anahtarıdır.","iliskili":["go-4-022","go-4-019"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-tabak-servisi"},{"id":"go-4-025","konu":"4.2","terim":"Aile usulü servis","ingilizce":"Family-style service","tanim":"Yemeklerin büyük kaplarda masanın ortasına konduğu ve konukların birbirine uzatarak kendi tabaklarına aldığı paylaşmalı servis türüdür.","ornek":"Akşam 20.00, Gaziantep’te bir otelin restoranı: masaya büyük bir tepsi kebap, pilav ve salata konur; aile birbirine uzatarak alır.","sektor":"Sıcak ve paylaşımcı bir hava verir; aile ve grup konuklar sever. Kaplar boşaldıkça yenilemek ve sıcak yemeği küçük çocukların uzanabileceği yere koymamak garsonun işidir.","iliskili":["go-4-023","go-4-026"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-paylasilan-yemekler"},{"id":"go-4-026","konu":"4.2","terim":"Büfe servisi tarzı","ingilizce":"Buffet-style service","tanim":"Yemeklerin bir masada topluca sergilendiği ve konukların istediklerini kendi tabaklarına aldığı self servis tarzıdır.","ornek":"Sabah 08.00, Alanya’da bir resort: kahvaltı büfesinde sıcaklar ısıtıcıda, soğuklar buzlu tezgâhta durur; büfe görevlisi boşalan kapları yeniler ve her kaba ayrı maşa koyar.","sektor":"Garson sayısını azaltır, ama büfe ekibini önemli kılar: ayrı maşa, dolu kaplar, temizlik ve yemek adı ile alerjen etiketi gerekir. Konuk kendi servisini yaptığı için bulaşma riski artar; kapların başında bir göz her zaman olmalıdır.","iliskili":["go-4-025","go-4-019"],"kontrol":null,"kitapDisi":true,"gorsel":"f3c-kahvalti-bufesi"},{"id":"go-4-027","konu":"4.2","terim":"Oda servisi teslimi","ingilizce":"In-room dining delivery","tanim":"Odaya verilen siparişin tepside ve eksiksiz biçimde konuğun odasına götürülüp masada kurularak teslim edilmesidir.","ornek":"Sabah 07.30, 512 numaralı oda: görevli kapıyı çalıp “Oda servisi” der, konuk “buyurun” deyince girer, kahvaltı tepsisini masaya kurar ve hesabı imzaya sunar.","sektor":"Konuk burada yalnızdır; tepsi onun restoranıdır. Yemek sıcak, tepsi eksiksiz, sunum düzgün olmalıdır. Konuk izin vermeden içeri girilmez ve boş tepsinin koridorda kalmaması için toplama saati konuğa sorulur.","iliskili":["go-4-019","go-4-024"],"kontrol":null,"kitapDisi":true,"gorsel":"t14f-oda-servisi-tepsi"},{"id":"go-4-028","konu":"4.2","terim":"Kuver düzeni","ingilizce":"Cover (place setting)","tanim":"Masada her konuk için hazırlanan tabak, çatal-bıçak, bardak ve peçeteden oluşan takımın belirli bir düzenle yerleştirilmesidir.","ornek":"Akşam 18.00, Beyoğlu’nda bir otelin restoranı: komi her masada dört kuver kurar; tabaklar masa kenarından eşit uzaklıkta, çatal-bıçaklar tabakla aynı hizadadır.","sektor":"Düzenli kuver konuğa daha servis başlamadan “burada özen var” der. Eksik ya da kirli bir takım konuk oturduktan sonra fark edilirse dakikalarca bekleme demektir. Takımın içeriği menüye göre değişir: çorba yoksa çorba kaşığı konmaz.","iliskili":["go-4-029","go-4-030","go-4-031"],"kontrol":null,"kitapDisi":true,"gorsel":"t14f-kuver-duzeni"},{"id":"go-4-029","konu":"4.2","terim":"Çatal-bıçak dizilişi","ingilizce":"Cutlery layout","tanim":"Çatalların tabağın soluna, bıçak ve kaşıkların sağına, kullanılacakları sıraya göre dışarıdan içeriye doğru yerleştirilmesidir.","ornek":"Akşam 19.00, üç çeşit menülü bir masa: solda dışarıdan içeriye salata çatalı ve ana yemek çatalı, sağda çorba kaşığı ve ana yemek bıçağı durur; tatlı çatal-kaşığı tabağın üstünde yatay bekler.","sektor":"Kural: ilk kullanılacak takım en dıştadır, bıçağın keskin yüzü tabağa bakar. Konuk kafası karışsa bile “dışarıdan içeriye” kuralını bilir ve rahat eder. Menü değişince takım da değişir; masa menüye göre kurulur.","iliskili":["go-4-028","go-4-030"],"kontrol":null,"kitapDisi":true,"gorsel":"t14za-catal-bicak-duzeni"},{"id":"go-4-030","konu":"4.2","terim":"Bardak yerleşimi","ingilizce":"Glassware placement (water and soft drinks)","tanim":"Su ve alkolsüz içecek bardaklarının tabağın sağ üstüne, ana yemek bıçağının hizasına yerleştirilmesidir.","ornek":"Öğle 12.00: komi su bardağını ana yemek bıçağının ucunun üstüne koyar, meyve suyu bardağını onun hemen yanına.","sektor":"Bardak konuğun sağ eline yakın durur, çünkü çoğu insan sağ eliyle alır ve uzanırken çatal-bıçağa değmez. Bardak ağızdan değil gövdesinden tutulur, parmak izi bırakmayacak biçimde parlatılır; lekeli bardak servis edilmez.","iliskili":["go-4-028","go-4-029"],"kontrol":null,"kitapDisi":true},{"id":"go-4-031","konu":"4.2","terim":"Peçete","ingilizce":"Table napkin","tanim":"Konuğun el ve ağzını silmek için kullandığı, masada tabağın üstüne ya da solunda hazır bekleyen kumaş veya kâğıt mendildir.","ornek":"Akşam 17.45: komi her tabağın ortasına bez peçeteyi yelpaze biçiminde katlayıp yerleştirir; katlama sırasında peçetenin ağza gelen yüzüne dokunmaz.","sektor":"Katlama restorana kimlik veren küçük bir imzadır; ama temiz ellerle yapılır. Konuk peçetesini düşürürse beklemeden yenisi getirilir. Bez peçetede temizlik ve ütü, kâğıtta düzgün durmak önemlidir.","iliskili":["go-4-028"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-pecete"},{"id":"go-4-032","konu":"4.2","terim":"Servis yönü","ingilizce":"Direction of service","tanim":"Yemeğin konuğun hangi tarafından getirileceğini, içeceğin ve kirli tabağın hangi yandan alınacağını belirleyen kuraldır.","ornek":"Akşam 20.00: garson yemeği konuğun solundan koyar, su sürahisiyle sağdan bardağı doldurur, işi biten tabağı sağdan alır.","sektor":"Yaygın düzende yemek soldan, içecek sağdan servis edilir, kirli tabak da sağdan alınır; ama uygulama işletmeye ve servis tarzına göre değişebilir; işletme standardı esastır. Önemli olan ekibin tamamının aynı kuralı izlemesi ve konuğun önünden uzanıp yemeğini kapatmamasıdır.","iliskili":["go-4-033","go-4-028"],"kontrol":null,"kitapDisi":true,"cizim":"restoran-servis"},{"id":"go-4-033","konu":"4.2","terim":"Tabak kaldırma","ingilizce":"Clearing plates","tanim":"Yenen yemeğin tabaklarının, masadaki herkes bitirdikten sonra sessizce ve hızla masadan alınmasıdır.","ornek":"Akşam 20.45: masadaki herkesin çatal ve bıçağı tabağa paralel yatıyor; garson tabakları sağdan alır, çatal-bıçakları tabağın üstünde toplar.","sektor":"Konuk bitirmeden tabak alınırsa “acele ettiriliyorum” hisseder. Çatal ve bıçağın tabağa paralel durması bitiş işaretidir ve garsonun gözü bunu fark eder. Kirli tabaklar konuğun önünde üst üste yığılmaz, sessizce taşınır.","iliskili":["go-4-032","go-4-018"],"kontrol":null,"kitapDisi":true,"cizim":"restoran-servis"},{"id":"go-4-034","konu":"4.2","terim":"Protokol masası","ingilizce":"Protocol (official) table","tanim":"Resmî ya da önemli konukların yer aldığı, oturma yerleri unvana ve sıraya göre önceden belirlenmiş yemek masasıdır.","ornek":"Akşam 19.30, Ankara’da bir otelde kaymakamlık yemeği: onur konuğu ev sahibinin sağına oturtulur; yer ve sıra isim kartlarıyla belirlenmiştir.","sektor":"Protokolde sıra hatası saygısızlık sayılabilir; bu yüzden masa planı davetin sahibiyle önceden kesinleştirilir. Servis genellikle önce onur konuğuna başlar. Resmî kurumların kendi protokol kuralları vardır; otel bu kuralı o kurumdan alır.","iliskili":["go-4-028","go-4-033"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-ana-masa-cicek"},{"id":"go-4-035","konu":"4.2","terim":"Alkolsüz içecek servisi","ingilizce":"Soft and hot beverage service","tanim":"Su, meyve suyu, çay ve kahve gibi alkolsüz içeceklerin doğru kapta, doğru sıcaklıkta ve düzgün biçimde masaya sunulmasıdır.","ornek":"Sabah 08.15, Kuşadası’nda bir otelin kahvaltı salonu: garson çayı ince belli bardakta tabağı ve kaşığıyla getirir, çayı biten konuğa fark ettirmeden yenisini doldurur.","sektor":"Su ve çay çoğu konuğun ilk ve en sık istediği hizmettir; boş bardak masada bırakılmaz. Sıcak içecekte fincanın kulpu konuğun sağ eline gelecek biçimde konur, tabak ve kaşık yanında olur. Ucuz görünen bu servislerde konuk, gösterilen özeni en çok fark eder.","iliskili":["go-4-030","go-4-027"],"kontrol":null,"kitapDisi":true,"gorsel":"sektor-turk-cayi"},{"id":"go-4-036","konu":"4.3","terim":"Menü bölümleri ve yemek sırası","ingilizce":"Menu courses","tanim":"Bir yemeğin başlangıç, çorba, ana yemek ve tatlı gibi yenme sırasına göre dizilmiş bölümleridir.","ornek":"Akşam 20.00, İstanbul’da bir otelin restoranı: konuk soğuk başlangıç, çorba, ızgara balık ve tatlı sırasıyla ilerler; garson her bölümden önce uygun takımı masaya koyar.","sektor":"Sıra mutfağın ritmini belirler: ana yemek başlangıç bitmeden çıkmaz, mutfak bir sonraki bölümü ona göre hazırlar. Bu sırayı bilen garson hangi takımın hazır olacağını öngörür. À la carte menüde konuk bölümleri kendisi seçer.","iliskili":["go-4-037","go-4-038"],"kontrol":null,"kitapDisi":true,"cizim":"gastronomi"},{"id":"go-4-074","konu":"4.3","terim":"À la carte menü","ingilizce":"À la carte menu","tanim":"Her yemeğin ayrı fiyatla listelendiği ve konuğun bölümleri kendi isteğine göre seçip birleştirdiği menü türüdür.","ornek":"Akşam 20.15, Kuşadası’nda bir otelin restoranı: konuk soğuk başlangıcı ve ızgara köfteyi seçer, çorba ve tatlı istemez; hesap yalnız seçtiği yemekleri içerir.","sektor":"Konuğa özgürlük verir, ama mutfağın her yemeği siparişe göre ayrı hazırlaması gerekir; bu yüzden hazırlık ve bekleme süresi set menüden uzun olabilir. Garson menüdeki yemeklerin içeriğini, alerjenlerini ve pişme süresini bilmelidir. Set menüyle (prix fixe) karşılaştırılır: orada fiyat sabittir, burada her yemek ayrı yazılır.","iliskili":["go-4-036","go-4-037"],"kontrol":null,"kitapDisi":true,"cizim":"gastronomi"},{"id":"go-4-037","konu":"4.3","terim":"Set menü (prix fixe)","ingilizce":"Set menu (prix fixe)","tanim":"Birkaç bölümden oluşan yemeklerin tek bir sabit fiyatla ve sınırlı seçenekle sunulduğu menü türüdür.","ornek":"Akşam 19.30, Antalya’da bir otel: üç çeşit set menüde konuk başlangıçta ve ana yemekte iki seçenek arasından seçer, tatlı sabittir.","sektor":"Mutfak hazırlığı ve maliyet öngörülebilir olur; konuk da fiyatı baştan bilir. O gün için hazırlanan menüye günün menüsü (menu du jour) denir. Grup yemeklerinde ve toplantı organizasyonlarında çok tercih edilir.","iliskili":["go-4-036","go-4-038"],"kontrol":null,"kitapDisi":true,"cizim":"gastronomi"},{"id":"go-4-038","konu":"4.3","terim":"Tadım menüsü","ingilizce":"Tasting menu","tanim":"Aşçının küçük porsiyonlarla hazırladığı, çok sayıda tabaktan oluşan ve şefin seçimine dayanan menü türüdür.","ornek":"Akşam 20.00, İzmir’de bir otelin fine dining restoranı: konuk altı küçük tabaktan oluşan tadım menüsünü seçer; garson her tabağı kısaca açıklar ve yemekler ağır ağır gelir.","sektor":"Tadım menüsünde yemek bir hikâye gibi anlatılır; garson menüyü iyi bilmezse tabağın değeri kaybolur. Süresi uzundur, bu yüzden rezervasyon ve zamanlama önemlidir. Menü önceden planlandığı için alerji ve diyet bilgisi rezervasyonda alınmalıdır.","iliskili":["go-4-037","go-4-040"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-ilk-tadim-cesnisi"},{"id":"go-4-039","konu":"4.3","terim":"Çocuk menüsü","ingilizce":"Children's menu","tanim":"Küçük konukların iştahına ve porsiyon ölçüsüne göre hazırlanan, sade ve dengeli yemeklerden oluşan menüdür.","ornek":"Öğle 12.30, Antalya’da bir tatil köyü: çocuk menüsünde tavuk şiş, pilav, meyve tabağı ve süt vardır; küçük bir kız çocuğu menüyü resimlerinden seçer.","sektor":"Çocuk mutlu olursa aile mutlu olur. Çocuk menüsü çoğunlukla daha az baharatlı ve küçük porsiyondur. Boyama kâğıdı ve kalem gibi küçük ikramlar aile için büyük fark yaratır; çocuğun alerjisi olup olmadığı yine anne babaya sorulur.","iliskili":["go-4-036","go-4-068"],"kontrol":null,"kitapDisi":true},{"id":"go-4-040","konu":"4.3","terim":"Fine dining (üst düzey yemek deneyimi)","ingilizce":"Fine dining","tanim":"Yüksek kaliteli malzeme, özenli sunum ve eğitimli servis ekibiyle konuğa uzun ve özel bir yemek deneyimi yaşatan restoran anlayışıdır.","ornek":"Akşam 20.30, İstanbul Boğazı’ndaki bir otelin restoranı: masa örtülü, servis masa başında, yemekler tek tek açıklanıyor ve ekip konuğun adını biliyor.","sektor":"Fine dining’de ürün kadar hizmet de satılır; bu yüzden en çok personel emeği isteyen restoran türüdür. Kariyer için çok iyi bir okuldur: ayrıntıya özen, sakin duruş ve sessiz hizmet burada öğrenilir (Ünite 2).","iliskili":["go-4-038","go-4-041"],"kontrol":null,"kitapDisi":true,"cizim":"gastronomi"},{"id":"go-4-041","konu":"4.3","terim":"Fusion mutfak","ingilizce":"Fusion cuisine","tanim":"Farklı ülke ya da bölge mutfaklarının teknik ve malzemelerinin tek bir yemekte bilinçli biçimde birleştirildiği mutfak anlayışıdır.","ornek":"Akşam 19.45, Bodrum’da bir otel: şef sushi pirincini Ege otları ve zeytinyağıyla birleştiren bir tabak sunar; menüde “Ege-Asya” bölümü açılmıştır.","sektor":"Fusion yenilik getirir, ama her birleşim başarılı olmaz; kaynak mutfakları iyi bilmeden yapılan karışım karmaşaya dönüşür. Adı tanıdık olmadığı için garson yemeği konuğa açıklamak zorundadır.","iliskili":["go-4-040","go-4-042"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-tay-spagetti-fuzyon"},{"id":"go-4-042","konu":"4.3","terim":"Çiftlikten sofraya","ingilizce":"Farm-to-table","tanim":"Yemekte kullanılan malzemelerin mümkün olduğunca yakındaki üreticiden alınıp mevsiminde kullanıldığı mutfak anlayışıdır.","ornek":"Sabah 09.00, Ayvalık’ta bir otel: şef komşu köy üreticisinden gelen zeytinyağı, domates ve peyniri günün menüsünde üreticinin adıyla yazar.","sektor":"Konuk yemeğin hikâyesini sever: kimin yetiştirdiğini bilmek tabağa değer katar. Yerel tedarik küçük üreticiyi güçlendirir ve taşıma mesafesini kısaltır; ama mevsim bitince menünün değişmesi gerekir (Ünite 3’teki yöre ürünüyle tedarik konusuna bağlanır).","iliskili":["go-4-043","go-4-041"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-ciftlik-sebze"},{"id":"go-4-043","konu":"4.3","terim":"Slow food hareketi","ingilizce":"Slow food movement","tanim":"Hızlı ve standart yemeğe karşılık, yöresel, temiz ve adil üretilmiş yemeğin keyifle yenmesini savunan, İtalya’da doğmuş uluslararası harekettir.","ornek":"Cumartesi 11.00, Alaçatı’da küçük bir otelin kahvaltısı: yöresel otlar, köy peyniri ve ev yapımı reçeller uzun masada sunulur; konuklar acele etmeden oturur.","sektor":"Slow food, “fast food”un karşıtı olarak doğdu ve yerel lezzeti korumayı amaçlar. Otel için anlamı: yöresel ürün ve geleneksel yemek, paketlenip satılabilecek bir değerdir. Yavaş şehir (Cittaslow) fikriyle akrabadır.","iliskili":["go-4-042","go-4-044"],"kontrol":null,"kitapDisi":true,"cizim":"gastronomi"},{"id":"go-4-044","konu":"4.3","terim":"Street food (sokak yemeği)","ingilizce":"Street food","tanim":"Sokakta, tezgâhta ya da küçük araçlarda satılan, çabuk hazırlanan ve ucuz yöresel yiyeceklerin genel adıdır.","ornek":"Sabah 08.00, İstanbul Eminönü: simitçi sıcak simidi tezgâha dizer; otelin konuğu resepsiyondan “en güzelini nereden alabilirim?” diye sorar.","sektor":"Street food bir şehrin gerçek lezzet haritasıdır ve konuklar bunu denemek ister. Otel konuğa hijyen konusunda yol gösterir: kalabalık, temiz ve taze üreten yerler önerilir. Bazı oteller street food konseptini kendi restoranlarına taşır.","iliskili":["go-4-043","go-4-041"],"kontrol":null,"kitapDisi":true,"gorsel":"tr-simit"},{"id":"go-4-045","konu":"4.3","terim":"Akdeniz mutfağı","ingilizce":"Mediterranean cuisine","tanim":"Zeytinyağı, sebze, baklagil, balık ve taze otların öne çıktığı, Akdeniz çevresindeki ülkelerin ortak sofra kültürüdür.","ornek":"Öğle 13.00, Bodrum’da bir otel: zeytinyağlı enginar, ızgara levrek ve otlu salata menüdedir; konuk “hafif ve taze bir şey istiyorum” demiştir.","sektor":"Sağlıklı beslenme akımı bu mutfağı sevdiği için turist ilgisi yüksektir. Türkiye’nin Ege ve Akdeniz kıyıları da bu sofra kültürünün içindedir; Ege’nin zeytinyağlıları bunun örneğidir. Yine de ülkeden ülkeye farklı tatlar vardır; hepsi “aynı yemek” değildir.","iliskili":["go-4-046","go-4-048"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-akdeniz-salatasi"},{"id":"go-4-046","konu":"4.3","terim":"Pasta (İtalyan makarnası)","ingilizce":"Pasta","tanim":"Buğday hamurundan yapılan, spagetti, penne, ravioli gibi onlarca biçimde hazırlanan ve İtalyan mutfağının temelini oluşturan yemektir.","ornek":"Akşam 19.30, Antalya’da bir otelin İtalyan restoranı: garson domates soslu penne ile kremalı fettuccine arasındaki farkı anlatır.","sektor":"İtalyan mutfağı dünyada en sevilen mutfaklardandır ve bölgeden bölgeye değişir. İtalyanca “pasta” makarna demektir, Türkçedeki pasta ile karışmasın. Konuk “al dente”, yani hafif diri pişmiş makarna isteyebilir.","iliskili":["go-4-045","go-4-048"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-pasta-makarna"},{"id":"go-4-047","konu":"4.3","terim":"Sushi (Japon mutfağı)","ingilizce":"Sushi","tanim":"Sirkeyle tatlandırılmış pirincin balık, deniz ürünü ya da sebzeyle birleştirildiği, Japon mutfağından gelen bir yemektir.","ornek":"Akşam 20.00, İstanbul’da bir otelin Uzak Doğu restoranı: garson sushi seçeneklerini, çiğ balık içermeyen sebzeli rulo seçeneğini de anlatır.","sektor":"Çiğ balık taze ve doğru saklanmış malzeme ister; gıda güvenliği ayrı titizlik gerektirir. Japon mutfağı sadelik ve sunumuyla tanınır. Soya, balık ve susam gibi alerjenler içerebileceği için garson içeriği bilmelidir.","iliskili":["go-4-046","go-4-041"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-sushi"},{"id":"go-4-048","konu":"4.3","terim":"Tapas (İspanyol küçük tabakları)","ingilizce":"Tapas","tanim":"İspanya’da küçük tabaklarda sunulan, birkaç farklı lezzetin paylaşılarak tadıldığı atıştırmalık yemeklerdir.","ornek":"Akşam 21.00, Bodrum’da bir otelin teras restoranı: masaya üç küçük tabak gelir ve konuklar aralarında bölüşür.","sektor":"Tapas küçük porsiyonlarla paylaşım kültürü yaratır; konuk çok çeşit tadar, otel de menüde esnek davranır. Bizdeki meze kültürüne benzer. Küçük tabak sayısı arttıkça sipariş takibi ve masa düzeni zorlaşır.","iliskili":["go-4-045","go-4-046"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-tapas"},{"id":"go-4-049","konu":"4.3","terim":"Michelin yıldızı","ingilizce":"Michelin star","tanim":"Yeme içme rehberi Michelin’in bir restorana verdiği, mutfağın kalitesini bir, iki ya da üç yıldızla ölçen ödüldür.","ornek":"Sabah 10.00, Bodrum’da bir otel: restoran müdürü ekibe yıldızlı restoranların temiz mutfak, tutarlı tat ve sakin servis anlayışını anlatır; hedef yıldız değil, her gün aynı kalitedir.","sektor":"Rehberin kendi anlatımına göre bir yıldız “uğramaya değer, kaliteli mutfak”, iki yıldız “yoldan sapmaya değer, çok iyi mutfak”, üç yıldız “özel bir yolculuğa değer, olağanüstü mutfak” demektir. Yıldız yalnız restoranın tabağına verilir; bir otelin restoranı da yıldız alabilir.","iliskili":["go-4-050","go-4-040"],"kontrol":null,"kitapDisi":true},{"id":"go-4-050","konu":"4.3","terim":"Bib Gourmand (uygun fiyat ödülü)","ingilizce":"Bib Gourmand","tanim":"Michelin Rehberi’nin yıldızı olmayan, iyi yemeği makul fiyata sunan restoranlara verdiği ayrı bir ödüldür.","ornek":"Öğle 13.00, İzmir’de bir otel lokantası: günlük yemekleri ve uygun fiyatıyla hem yerli hem yabancı konukla doluyor; müdür “yıldız şart değil, kalite ve değer şart” diyor.","sektor":"Adı Michelin’in maskotu Bibendum’dan gelir. Her gün gidilebilecek kaliteli ve uygun fiyatlı yemeği ödüllendirir; yani lüks tek ölçü değildir. Fiyat sınırı şehirden şehre değiştiği için sabit bir rakam yoktur.","iliskili":["go-4-049","go-4-051"],"kontrol":null,"kitapDisi":true,"cizim":"gastronomi"},{"id":"go-4-051","konu":"4.3","terim":"UNESCO gastronomi şehirleri (Türkiye)","ingilizce":"UNESCO Cities of Gastronomy (Türkiye)","tanim":"Yaratıcı Şehirler Ağı’na mutfak kültürüyle (gastronomi alanında) kabul edilen şehirlerdir; Türkiye’den Gaziantep, Hatay ve Afyonkarahisar bunlar arasındadır.","ornek":"Cuma akşamı, Gaziantep’te bir otelin lobisi: yabancı konuk “Burada gastronomi şehri olduğunu duydum, ne yemeliyim?” diye sorar; görevli baklavayı, beyranı ve kebabı anlatıp güvenilir bir lokanta önerir.","sektor":"Gaziantep baklava, kebap ve Antep fıstığıyla; Hatay künefe ve zengin sofra kültürüyle; Afyonkarahisar kaymak, lokum ve sucukla anılır. Bu unvan turisti şehre yemek için getirir; yöre yemeğini bilen çalışan yalnız otel görevlisi değil, şehrin elçisidir.","iliskili":["go-4-050","go-4-056"],"kontrol":null,"kitapDisi":true},{"id":"go-4-052","konu":"4.3","terim":"Türk kahvaltı kültürü","ingilizce":"Turkish breakfast culture","tanim":"Peynir, zeytin, yumurta, reçel ve çayın çok sayıda küçük tabakta sofraya serildiği, uzun ve paylaşmalı Türk sabah yemeği geleneğidir.","ornek":"Pazar sabahı 09.30, Cunda’da bir otelin bahçesi: masaya zeytin, beyaz peynir, domates, salatalık, bal ve kaymak, sahanda yumurta ve demli çay serilir.","sektor":"Kahvaltı, Türk sofrasının en tanınan öğünlerinden biridir ve yabancı konuk için başlı başına bir deneyimdir. Misafirperver sofranın göstergesi olarak çay boşalmadan yenilenir. Kahvaltı çoğu konuğun otelde yediği en önemli öğündür.","iliskili":["go-4-053","go-4-054"],"kontrol":null,"kitapDisi":true,"gorsel":"ek-turk-kahvaltisi"},{"id":"go-4-053","konu":"4.3","terim":"Türk kahvesi geleneği","ingilizce":"Turkish coffee culture","tanim":"Çok ince öğütülmüş kahvenin cezvede pişirilip köpüğüyle küçük fincanda sunulduğu, UNESCO somut olmayan kültürel miras listesinde yer alan içecek geleneğidir.","ornek":"Akşam yemeğinden sonra 21.30, İstanbul’da bir otelin salonu: garson orta şekerli Türk kahvesini yanında bir bardak su ve lokumla getirir.","sektor":"UNESCO bu geleneği 2013’te listeye aldı. Kahvenin şekerinin nasıl olacağı sorulur (sade, az, orta, şekerli); yanında su ve lokum sunmak yaygındır. Kahvenin sunumu otelin misafirperverliğini gösteren küçük bir imzadır.","iliskili":["go-4-052","go-4-054"],"kontrol":null,"kitapDisi":true,"gorsel":"tr-turk-kahvesi"},{"id":"go-4-054","konu":"4.3","terim":"Türk çay kültürü","ingilizce":"Turkish tea culture","tanim":"Demlikte demlenen çayın ince belli bardaklarda sunulduğu, UNESCO somut olmayan kültürel miras listesinde yer alan toplumsal ağırlama geleneğidir.","ornek":"Sabah 08.30, Rize’de bir otelin kahvaltı salonu: garson demliği çaydanlığın üstünde taze tutar, konuğa “açık mı koyu mu?” diye sorar ve bardağı buna göre doldurur.","sektor":"Çay kültürü 2022’de Azerbaycan’la ortak başvuruyla UNESCO listesine alındı. Türkiye’de çay selam, misafirperverlik ve sohbet demektir. Otelde çay kahvaltıda ve gün boyu ikram edilir; bardağı boş bırakmamak konuğa verilen değerin işaretidir.","iliskili":["go-4-053","go-4-055"],"kontrol":null,"kitapDisi":true,"gorsel":"t13d-cay-tepsisi"},{"id":"go-4-055","konu":"4.3","terim":"Lavaş ve yufka geleneği","ingilizce":"Flatbread culture (lavash and yufka)","tanim":"İnce açılan ekmek hamurunun sacda pişirildiği, birkaç kişinin birlikte hazırlayıp paylaştığı ve UNESCO somut olmayan kültürel miras listesine girmiş ekmek geleneğidir.","ornek":"Öğle 12.30, Gaziantep’te bir otelin restoranı: kebabın altında ve yanında sıcak lavaş verilir; konuk “Bu ekmek hep böyle mi yapılır?” diye sorar.","sektor":"Lavaş ve yufka gibi ince ekmekler, Türkiye’nin de aralarında olduğu birkaç ülkenin ortak başvurusuyla UNESCO listesine alındı. Sofrada yalnız bir yiyecek değil, birlikte emek vermenin ve paylaşmanın kültürü sunulur.","iliskili":["go-4-054","go-4-056"],"kontrol":null,"kitapDisi":true,"cizim":"mutfak"},{"id":"go-4-075","konu":"4.3","terim":"İskender kebap","ingilizce":"İskender kebab","tanim":"İnce dilimlenmiş et ile pide parçalarının üzerine domates sosu ve eritilmiş tereyağı dökülerek, yanında yoğurtla sunulan Bursa’ya özgü kebaptır.","ornek":"Öğle 13.00, Bursa’da bir otelin restoranı: garson tabağı masaya getirir, tereyağını konuğun gözü önünde sıcak sıcak döker ve yoğurdu yanına koyar.","sektor":"Yabancı konuk yemeğin adını duyunca merak eder; garson Bursa’dan çıktığını, üzerindeki unsurları ve sıcak servis edilmesi gerektiğini anlatabilmelidir. Pide gluten, tereyağı ve yoğurt süt içerdiği için alerjisi olan konuğa mutlaka bu bilgi verilir.","iliskili":["go-4-055","go-4-063"],"kontrol":null,"kitapDisi":true,"gorsel":"ek-iskender-kebap"},{"id":"go-4-076","konu":"4.3","terim":"Türk lokumu","ingilizce":"Turkish delight (lokum)","tanim":"Nişasta ve şekerle yapılan, fıstık, fındık ya da gül gibi katkılarla çeşitlendirilen, küçük küpler hâlinde sunulan yumuşak Türk tatlısıdır.","ornek":"Akşam 21.30, Afyonkarahisar’da bir otelin salonu: garson Türk kahvesinin yanında iki lokumu küçük tabakta getirir ve çeşitlerini kısaca anlatır.","sektor":"Lokum, Türk ikramının tanınan simgelerindendir; kahvenin yanında verildiği gibi hediye kutusunda da satılır. Fıstık, fındık gibi kuruyemişler içerdiği için alerjisi olan konuğa içeriği açıkça söylenir.","iliskili":["go-4-053","go-4-063"],"kontrol":null,"kitapDisi":true,"gorsel":"ek-lokum"},{"id":"go-4-056","konu":"4.3","terim":"Yöre ürününde coğrafi işaret","ingilizce":"Geographical indication on regional food (GI)","tanim":"Bir ürünün kalitesinin ya da ününün üretildiği yöreden geldiğini gösteren, resmî olarak tescil edilmiş işarettir.","ornek":"Sabah 10.00, Gaziantep’te bir otelin kahvaltısı: baklava kutusunda “coğrafi işaret” ibaresi var; garson konuğa bunun ne demek olduğunu anlatır.","sektor":"Türkiye’de Gaziantep baklavası ve Maraş dondurması gibi pek çok ürün bu işaretle korunur. Otelin orijinal yöre ürünü seçmesi ve doğru anlatması yöreye saygıdır; taklit ürün hem üreticiye hem konuğa haksızlıktır.","iliskili":["go-4-051","go-4-055"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-cografi-isaret-urun"},{"id":"go-4-057","konu":"4.4","terim":"Vejetaryen beslenme","ingilizce":"Vegetarian diet","tanim":"Et, tavuk ve balık yemeyen, çoğu zaman süt ürünlerini ve yumurtayı tüketen beslenme biçimidir.","ornek":"Akşam 20.00, Kapadokya’da bir otelin restoranı: konuk “et yemem, ama peynir ve yumurta olur” der; garson menüde et suyu içermeyen yemekleri gösterir.","sektor":"Vejetaryen yemekte gizli et ürünlerini unutmamak gerekir: et suyuyla yapılan çorba ya da sebze yemeği vejetaryen sayılmaz. Garson “sebzeli” yemeğin içeriğini mutfaktan öğrenir. Menüde ayrı bir vejetaryen bölüm konuğu rahatlatır.","iliskili":["go-4-058","go-4-062"],"kontrol":null,"kitapDisi":true,"gorsel":"salata"},{"id":"go-4-058","konu":"4.4","terim":"Vegan beslenme","ingilizce":"Vegan diet","tanim":"Et, balık, süt, yumurta ve bal dâhil hiçbir hayvansal ürün tüketilmeyen beslenme biçimidir.","ornek":"Sabah 08.30, İstanbul’da bir otelin kahvaltısı: vegan konuk için bitkisel süt, zeytin, domates, humus ve ekmek ayrı tabelayla işaretlenmiştir.","sektor":"Vegan yalnız “etsiz” demek değildir: tereyağı, yumurta, bal ve süt de yoktur. Kahvaltıda bitkisel süt, tatlıda bitkisel alternatif düşünmek otelin hazırlıklı olduğunu gösterir. Etiket yoksa içerik mutfağa sorulur.","iliskili":["go-4-057","go-4-059"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-vegan-tabak"},{"id":"go-4-059","konu":"4.4","terim":"Glutensiz beslenme","ingilizce":"Gluten-free diet","tanim":"Buğday, arpa ve çavdarda bulunan gluten proteininden uzak durulan, özellikle çölyak hastaları için zorunlu olan beslenme biçimidir.","ornek":"Sabah 09.00: çölyak hastası konuk kahvaltıda glutensiz ekmek istiyor; mutfak ekmeği ayrı bir tezgâhta ve ayrı bıçakla hazırlıyor.","sektor":"Çölyakta gluten bağırsağa zarar verir; bu bir tercih değil sağlık gereğidir. Ekmek ve un dışında bazı soslar, çorbalar ve bulgur pilavı gibi yiyecekler de gluten içerir. Küçük bir kırıntı bile sorun yaratabileceği için tabak ayrı hazırlanır.","iliskili":["go-4-058","go-4-063"],"kontrol":null,"kitapDisi":true},{"id":"go-4-060","konu":"4.4","terim":"Helal gıda","ingilizce":"Halal food","tanim":"İslam dininin yemek kurallarına uygun olan, domuz eti ve alkol içermeyen, etin uygun biçimde kesilmiş olduğu yiyecektir.","ornek":"Öğle 13.00, Antalya’da bir otel: yurt dışından gelen bir aile yemeklerin helal olup olmadığını soruyor; garson cevabı bilmediği için mutfaktan öğrenip geri dönüyor.","sektor":"Türkiye’de farklı ülkelerden gelen çok sayıda konuk için helal hassasiyeti önemlidir. Et, sos ve tatlıda alkol ya da domuz ürünü olup olmadığı bilinmelidir. Cevap bilinmiyorsa tahminle söylenmez, mutfağa sorulur.","iliskili":["go-4-061","go-4-067"],"kontrol":null,"kitapDisi":true,"cizim":"gastronomi"},{"id":"go-4-061","konu":"4.4","terim":"Koşer gıda","ingilizce":"Kosher food","tanim":"Yahudi inancının yemek kurallarına uygun hazırlanan, domuzu ve kabuklu deniz ürünlerini dışarıda bırakan, et ile süt ürünlerinin karıştırılmadığı yiyecektir.","ornek":"Akşam 19.00, İstanbul’da bir otel: konuk koşer yemek istiyor; ön büro isteği yiyecek içecek müdürüne iletir, müdür koşer sertifikalı hazır yemek temin edilip edilemeyeceğine bakar.","sektor":"Koşer hazırlık yalnız menüyle değil mutfak gereçleriyle de ilgilidir; sıradan bir mutfakta tam koşer hizmet vermek zordur. Bu yüzden otel dürüstçe “yapabiliriz” ya da “yapamayız” demelidir; yanlış söz konuğun inancına saygısızlıktır.","iliskili":["go-4-060","go-4-067"],"kontrol":null,"kitapDisi":true,"cizim":"gastronomi"},{"id":"go-4-062","konu":"4.4","terim":"Alerji, intolerans ve laktozsuz beslenme","ingilizce":"Food allergy, intolerance and lactose-free diet","tanim":"Bağışıklık sisteminin bir gıdaya aşırı tepki vermesi alerji, vücudun bir gıdayı sindirememesi intolerans olarak adlandırılır; alerji ağır sonuçlar doğurabildiği için ayırt edilmelidir.","ornek":"Akşam 20.15: bir konuk “süt alerjim var” derken öbürü “laktoz intoleransım var, kahveye laktozsuz süt olur mu?” diye soruyor; garson iki durumu aynı saymaz ve ikisini mutfağa ayrı iletir.","sektor":"Laktozsuz süt, sütteki şeker olan laktozdan arındırılmıştır, ama süt proteini içerir. Bu yüzden laktoz intoleransı olan konuk içebilir, süt alerjisi olan içemez. Garson ayrımı bilir, kararı mutfağa bırakır ve tahminle “olur” demez.","iliskili":["go-4-063","go-4-057"],"kontrol":null,"kitapDisi":true,"cizim":"saglik-kalp"},{"id":"go-4-063","konu":"4.4","terim":"On dört alerjen (AB listesi)","ingilizce":"The 14 major allergens (EU list)","tanim":"Avrupa Birliği kurallarında restoranlarda ve paketli gıdalarda mutlaka belirtilmesi gereken, en sık alerjik tepki yapan on dört gıda grubudur.","ornek":"Akşam 19.30: menüde tavuklu salatanın yanında “gluten, yumurta, hardal” yazıyor; hardal alerjisi olan konuk başka bir yemek seçiyor.","sektor":"Liste: gluten içeren tahıllar, kabuklular, yumurta, balık, yer fıstığı, soya, süt, sert kabuklu yemişler (fındık, ceviz gibi), kereviz, hardal, susam, sülfitler, acı bakla (lupin) ve yumuşakçalar. Hepsini ezberlemek değil, ne olduklarını ve soslarda, çorbalarda gizlenebileceklerini bilmek önemlidir. AB’nin bu kuralı 1169/2011 sayılı tüzükte yer alır. Türkiye’de de alerjenlerin etikette belirtilmesi istenir.","iliskili":["go-4-064","go-4-059"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-yer-fistigi"},{"id":"go-4-064","konu":"4.4","terim":"Alerjen bildirimi ve çapraz temas","ingilizce":"Allergen declaration and cross-contact","tanim":"Yemeğin alerjen içerdiğinin menüde ya da garsonun ağzından açıkça söylenmesi, alerjen içermeyen yemeğe alerjen bulaşmaması için alınan önlemlerdir.","ornek":"Öğle 12.45: fıstık alerjisi olan çocuk için mutfak ayrı tahta ve temiz bıçak kullanır; garson tabağı “alerjili” notuyla alır ve doğrudan çocuğun annesine verir.","sektor":"Çapraz temas: alerjenin tabağa küçücük bile bulaşması tepki yaratabilir; ayrı gereç, temiz tezgâh ve temiz yağ gerekir. Menü bilgisi yazılı ve güncel olmalıdır. Garson “sanırım yok” demez; kesin bilgiyi mutfaktan alır.","iliskili":["go-4-063","go-4-065"],"kontrol":null,"kitapDisi":true,"cizim":"mikrop"},{"id":"go-4-065","konu":"4.4","terim":"Alerjik konuğun sipariş akışı","ingilizce":"Handling an allergy order","tanim":"Alerjisi olan konuğun siparişinin sorulmasından mutfağa yazılı iletilmesine ve doğru kişiye ulaşmasına kadar izlenen güvenli adımlar dizisidir.","ornek":"Akşam 20.10: konuk “fındık alerjim var” der; garson adisyona “ALERJİ: FINDIK” yazar, şefe sözlü de haber verir, yemeği şef kontrol eder ve garson doğrudan konuğa getirir.","sektor":"Sıra: sor, yaz, söyle, doğrula, teslim et. Her halkada bir kişinin gözü hatayı yakalar. Konuk “azıcık olur” dese de alerjide pazarlık yoktur. Hata olursa saklanmaz, hemen amire bildirilir.","iliskili":["go-4-064","go-4-066"],"kontrol":null,"kitapDisi":true,"cizim":"el-yikama"},{"id":"go-4-066","konu":"4.4","terim":"Anafilaksi","ingilizce":"Anaphylaxis","tanim":"Alerjik tepkinin aniden ve tüm vücudu saran, nefes almayı ve dolaşımı bozabilen, yaşamı tehdit eden en ağır biçimidir.","ornek":"Akşam 21.00: konuk yemekten dakikalar sonra dudaklarının şiştiğini ve nefesinin daraldığını söylüyor; garson yardım ister, amire haber verir ve 112’nin aranmasını sağlar.","sektor":"Belirtiler: dudak ve yüz şişmesi, nefes darlığı, yaygın kızarıklık, baş dönmesi. Stajyerin görevi müdahale etmek değil; konuğun yanından ayrılmadan yüksek sesle yardım çağırmak, amirin hemen haberdar olmasını ve 112’nin aranmasını sağlamaktır. Müdahaleyi eğitimli kişi yapar.","iliskili":["go-4-065","go-4-062"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-otoenjektor"},{"id":"go-4-067","konu":"4.4","terim":"Yemekte kültürel hassasiyetler","ingilizce":"Cultural food sensitivities","tanim":"Konuğun inancından ya da kültüründen gelen, bazı yiyeceklerin yenmemesi, bazı yemek saatlerinin ve yeme biçimlerinin önemli olması gibi alışkanlıklara saygı göstermektir.","ornek":"Akşam 18.30, Ramazan ayında Bursa’da bir otel: iftar saati yaklaşırken restoran konuklar için su ve hurma hazırlar, iftar vaktinde ilk çorba hızla servis edilir.","sektor":"Bazı kültürlerde belirli hayvanların eti yenmez, bazı kültürlerde yemek sağ elle yenir, bazı konuklar için yemek saatleri dinî günlere göre değişir. Soru sormak ayıp değil, özendir. Bilmiyorsan kibarca sorarsın; kişiyi ülkesine göre genellemezsin.","iliskili":["go-4-060","go-4-061"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-vejetaryen-ucak-yemegi"},{"id":"go-4-068","konu":"4.4","terim":"Çocuk konuk","ingilizce":"Child guest","tanim":"Restoranda ailesiyle yemek yiyen çocuğun güvenli ve rahat edebilmesi için hazırlanan sandalye, tabak, porsiyon ve ilgi hizmetidir.","ornek":"Sabah 08.45: iki yaşındaki bir çocuk kahvaltıya geliyor; garson mama sandalyesi, kırılmaz kâse ve ılık süt getiriyor, sıcak çayı çocuğun uzanamayacağı yere koyuyor.","sektor":"Aile otelde yemek ister; çocuk mutlu değilse bütün masa gerginleşir. Mama sandalyesi, kırılmaz tabak ve sıcak yiyecekten uzak oturma burada güvenlik ve nezakettir. Çocuğun alerji bilgisi anne babaya sorulur.","iliskili":["go-4-039","go-4-069"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-bebek-mama-sandalyeleri"},{"id":"go-4-069","konu":"4.4","terim":"Yaşlı konuk","ingilizce":"Older guest","tanim":"Daha yavaş yürüyen, bazen daha zor duyan ya da gören yaşlı konuğun yemekte rahat ve onurlu hizmet almasıdır.","ornek":"Öğle 12.45: bastonlu yaşlı bir konuk büfeye yönelirken garson tabağı taşımayı önerir, menüyü büyük puntolu getirir ve masayı kapıya yakın, rahat ulaşılır bir yere ayırır.","sektor":"Yardım teklif edilir, dayatılmaz: “Yardımcı olabilir miyim?” demek kararı konuğa bırakır. Tuzsuz yemek gibi diyet ihtiyaçları sorulur. Acele ettirmek ya da çocukmuş gibi konuşmak yanlıştır.","iliskili":["go-4-068","go-4-070"],"kontrol":null,"kitapDisi":true,"gorsel":"t1a-ucuncu-yas"},{"id":"go-4-070","konu":"4.4","terim":"Özel gün masası","ingilizce":"Special occasion table","tanim":"Doğum günü, yıl dönümü, nişan gibi özel bir gün için süslenmiş ve kişiye özel ikramlar eklenmiş masadır.","ornek":"Akşam 20.00, Antalya’da bir otelin teras restoranı: evlilik yıl dönümünü kutlayan çiftin masasına mum ve çiçek konmuştur; garson tatlıyla birlikte küçük bir kart getirir.","sektor":"Özel gün konuğun hatırlayacağı anı kurar (Ünite 2’deki hatırlanan an). Ön büro ve restoran arasında rezervasyon notu zamanında aktarılır. Bazı konuklar herkesin önünde kutlanmak istemez; sürpriz öncesi sorulur.","iliskili":["go-4-069","go-4-019"],"kontrol":null,"kitapDisi":true,"gorsel":"t14f-ozel-gun-pasta"},{"id":"go-4-071","konu":"4.4","terim":"Bahşiş ve servis ücreti farkı","ingilizce":"Tip and service charge","tanim":"Konuğun memnuniyetine göre isteğe bağlı verdiği para bahşiştir; hesaba önceden eklenip menüde ya da fişte yazılan ek bedel ise servis ücretidir.","ornek":"Akşam 21.30: hesapta “servis ücreti dâhildir” yazıyor; konuk garsona ayrıca bahşiş bırakıp bırakmayacağını soruyor, garson “zorunlu değil, size kalmış” diyor.","sektor":"Konuk hesabı görmeden bu ücretin farkında olmalıdır; sürpriz ek ücret güveni zedeler, bu yüzden işletmeler ücreti menüde yazar. Dağıtım işletmeden işletmeye değişir (ortak havuz gibi). Bahşiş beklenmez ve istenmez (Ünite 2).","iliskili":["go-4-072","go-4-014"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-bahsis-kavanozu"},{"id":"go-4-072","konu":"4.4","terim":"Masada geri bildirim ve şikâyet","ingilizce":"Table-side feedback and complaints","tanim":"Yemek geldikten kısa süre sonra konuğa uğrayıp her şeyin yolunda olup olmadığını sormak ve sorun varsa hemen çözmektir.","ornek":"Akşam 20.30: garson ızgara balık geldikten iki üç dakika sonra masaya uğrar; konuk “balık biraz soğuk” deyince “hemen yenisini hazırlatayım” der ve amirine haber verir.","sektor":"Bu uğrama (check-back), konuk internete şikâyet yazmadan sorunu çözme fırsatıdır (Ünite 1’deki yorum, Ünite 2’deki telafi). Yemek iadesi tartışma değil düzeltme fırsatıdır: yemek tartışmadan yenilenir, sebep amire ve mutfağa not edilir.","iliskili":["go-4-071","go-4-018"],"kontrol":null,"kitapDisi":true},{"id":"go-4-073","konu":"4.4","terim":"Servis alanında gıda güvenliği","ingilizce":"Food safety in the service area","tanim":"Yemeğin konuğa ulaşana kadar sağlığa zarar vermeyecek biçimde saklanması, taşınması ve sunulması için uyulan kurallardır.","ornek":"Öğle 12.00: garson ellerini yıkar, saçını toplar; büfede sıcak yemek ısıtıcıda, soğuk salata buzlu tezgâhta tutulur; elinde yara olan komi bandajının üstüne eldiven takar.","sektor":"Mutfakta HACCP gibi sistemlerle yönetilen güvenlik, serviste garsonun ellerinde sürer: temiz üniforma, el yıkama, tabağın içine parmak değdirmemek, bardağın ağzına dokunmamak. Gıda zehirlenmesi yalnız bir konuğu değil, bütün oteli sarsar; kural şudur: şüphe varsa servis etme, amire söyle.","iliskili":["go-4-026","go-4-072"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-gida-termometresi"}],"sorular":[{"id":"go-4-s01","tur":"coktan-secmeli","soru":"Garson 5 numaralı masanın siparişini tablete girdi. Mutfağa giden, masa numarasını ve alerji notunu taşıyan belge hangisidir?","secenekler":["Adisyon (hesap belgesi)","Menü kartı","Sipariş fişi (KOT)","Masa planı"],"dogru":2,"aciklama":"KOT, siparişi masa numarası ve notlarıyla mutfağa yazılı iletir. Adisyon ise masanın siparişlerini toplayıp hesabı çıkarmaya yarar; mutfağa emir vermez."},{"id":"go-4-s02","tur":"coktan-secmeli","soru":"Fine dining restoranında rezervasyon defterine bakıp yıl dönümü çiftini pencere kenarına alan ve ekibi önceden uyaran kıdemli salon sorumlusu kimdir?","secenekler":["Maître d’hôtel","Host","Komi","Sous chef"],"dogru":0,"aciklama":"Maître d’hôtel salonun akışını yönetir ve masaları belirler. Host konuğu karşılayıp masasına götürür, ama salonun akışını yönetmez; komi ve sous chef ise başka görevlerin sahibidir."},{"id":"go-4-s03","tur":"coktan-secmeli","soru":"Mutfakta kıdemi düşükten yükseğe doğru gösteren doğru sıra hangisidir?","secenekler":["Chef de partie, commis, sous chef, executive chef","Commis, sous chef, chef de partie, executive chef","Commis, chef de partie, executive chef, sous chef","Commis, chef de partie, sous chef, executive chef"],"dogru":3,"aciklama":"Yaygın yol commis ile başlar, chef de partie ve sous chef basamaklarından geçerek executive chef’e uzanır. Sous chef executive chef’in yardımcısı olduğu için ondan önce gelir."},{"id":"go-4-s04","tur":"coktan-secmeli","soru":"Servise bir saat var. Garson peçeteleri katlıyor, tuzluk ve biberlikleri dolduruyor; mutfakta soslar ve doğranmış sebzeler hazırlanıyor. Bu çalışma ve amacı hangisidir?","secenekler":["Servis akışı; konuğu karşılamadan uğurlamaya adımları sırayla izlemek","Mise en place; servis anında zaman kaybetmeden konuğa yönelmek","Guéridon; yemeği masanın yanında servis arabasında hazırlamak","Pass; hazır tabağı kontrol edip servise vermek"],"dogru":1,"aciklama":"Mise en place, servisten önce her şeyi hazır ve elinin altında tutmaktır; böylece servis anında dakika kaybedilmez. Servis akışı konuğun yolculuğunu, pass ise mutfak çıkışındaki son kontrolü anlatır."},{"id":"go-4-s05","tur":"coktan-secmeli","soru":"Büyük bir davette mutfak kuzu etini büyük servis tabağına dizdi; garson bu tabaktan her konuğun önündeki boş tabağa çatal-kaşıkla porsiyon koyuyor. Bu hangi servis tarzıdır?","secenekler":["Rus servisi","Amerikan servisi (tabak servisi)","İngiliz servisi","Aile usulü servis"],"dogru":0,"aciklama":"Rus servisinde yemek servis tabağından garson eliyle konukların tabağına paylaştırılır. İngiliz servisinde yemeği ev sahibi dilimler, Amerikan servisinde tabaklar mutfakta hazırlanır, aile usulünde konuklar kendileri alır."},{"id":"go-4-s06","tur":"coktan-secmeli","soru":"İki yüz kişilik toplantı yemeğinde tabaklar mutfakta porsiyonlanıp süslenir, garsonlar da tabakları masalara koyar. Az personelle hızlı yapılabilen bu tarz hangisidir?","secenekler":["Fransız servisi","Guéridon servisi","Amerikan servisi","Büfe servisi"],"dogru":2,"aciklama":"Tabak servisinde sunum mutfakta belirlenir ve hazır tabak masaya gelir; bu yüzden hızlıdır ve kalabalık gruba uygundur. Fransız ve guéridon servisleri masa başında hazırlık ister, büfede konuk kendi tabağını doldurur."},{"id":"go-4-s07","tur":"dogru-yanlis","soru":"Su ve alkolsüz içecek bardakları tabağın sağ üstüne, ana yemek bıçağının hizasına konur; çünkü çoğu konuk sağ eliyle uzanır ve çatal-bıçağa değmez.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru: bardak konuğun sağ eline yakın durur. Bu yüzden uzanırken takımlara çarpmaz; bardak ağızdan değil gövdesinden tutulur."},{"id":"go-4-s08","tur":"coktan-secmeli","soru":"Kuver düzeni anlatılırken hangisi yanlıştır?","secenekler":["Çatallar tabağın soluna, bıçak ve kaşıklar sağına konur","Bıçağın keskin yüzü tabağa bakar","İlk kullanılacak takım en dışta durur","İlk kullanılacak takım tabağa en yakın durur"],"dogru":3,"aciklama":"Takımlar kullanılma sırasına göre dışarıdan içeriye dizilir; yani ilk kullanılan en dıştadır. Soldaki çatal, sağdaki bıçak ve kaşık ile tabağa dönük keskin yüz doğru kuver bilgileridir."},{"id":"go-4-s09","tur":"coktan-secmeli","soru":"Yaygın servis düzenine göre hangisi doğrudur?","secenekler":["Yemek sağdan, içecek soldan servis edilir; kirli tabak soldan alınır","Yemek soldan, içecek sağdan servis edilir; kirli tabak sağdan alınır","Yemek soldan, içecek soldan servis edilir; kirli tabak sağdan alınır","Yemek sağdan, içecek sağdan servis edilir; kirli tabak soldan alınır"],"dogru":1,"aciklama":"Yaygın düzende yemek soldan, içecek sağdan sunulur ve kirli tabak sağdan alınır. Yine de işletme standardı esastır; önemli olan ekibin aynı kuralı izlemesidir."},{"id":"go-4-s10","tur":"dogru-yanlis","soru":"Masada bir konuk yemeğini bitirdiğinde garson, diğerleri sürerken bile onun tabağını hemen alır; böylece konuk bekletilmez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış: tabaklar, masadaki herkes bitirdikten sonra alınır. Erken alınan tabak, geride kalan konuğa “acele ettiriliyorum” hissi verir."},{"id":"go-4-s11","tur":"coktan-secmeli","soru":"Ankara’da bir otelde kaymakamlık yemeği veriliyor. Onur konuğunun yeri ve masa planının nasıl kesinleşeceği için hangisi doğrudur?","secenekler":["Ev sahibinin soluna; plan davet sahibiyle önceden kesinleştirilir","Kapıya en yakın masaya; plan yemek günü boş yerlere göre yapılır","Ev sahibinin sağına; plan davet sahibiyle önceden kesinleştirilir","Masanın en ucuna; plan konuklar geldikçe garsonlarca belirlenir"],"dogru":2,"aciklama":"Protokol masasında onur konuğu ev sahibinin sağına oturur ve sıra isim kartlarıyla önceden belirlenir; sıra hatası saygısızlık sayılabilir. Yemek günü doğaçlama yapılan plan bu riski taşır."},{"id":"go-4-s12","tur":"coktan-secmeli","soru":"Antalya’daki bir otelde konuk üç çeşit menüde başlangıç ile ana yemekte iki seçenek arasından seçiyor, tatlı sabit; hepsi için tek fiyat ödüyor. Bu menü türü hangisidir?","secenekler":["Set menü (prix fixe)","À la carte menü","Tadım menüsü","Çocuk menüsü"],"dogru":0,"aciklama":"Birkaç bölümün tek sabit fiyatla ve sınırlı seçenekle sunulması set menüdür. À la carte menüde her yemek ayrı fiyatlıdır; tadım menüsünde ise şefin seçtiği küçük tabaklar gelir."},{"id":"go-4-s13","tur":"coktan-secmeli","soru":"Ayvalık’ta bir otelin şefi komşu köy üreticisinden aldığı zeytinyağı, domates ve peyniri mevsiminde kullanıyor ve menüde üreticinin adını yazıyor. Bu anlayış hangisidir?","secenekler":["Fusion mutfak","Slow food hareketi","Tadım menüsü","Çiftlikten sofraya"],"dogru":3,"aciklama":"Çiftlikten sofraya anlayışı, malzemeyi yakındaki üreticiden mevsiminde almak ve hikâyesini konuğa anlatmaktır. Slow food hareketi yakın bir fikirdir, ama burada ayırıcı özellik yakın üreticiden mevsimlik tedariktir."},{"id":"go-4-s14","tur":"dogru-yanlis","soru":"Bir otel kahvaltıda yöresel otları, köy peynirini ve ev yapımı reçelleri acele ettirmeden uzun bir masada sunuyor; bu uygulama slow food anlayışıyla örtüşür.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru: slow food, yöresel ve temiz yemeğin keyifle yenmesini savunur. “Fast food”un karşıtıdır; otel için yöresel ürüne değer katan bir yaklaşımdır."},{"id":"go-4-s15","tur":"dogru-yanlis","soru":"Michelin yıldızı yalnız bağımsız restoranlara verilir; bir otelin içindeki restoran yıldız alamaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış: yıldız tabağa, yani restoranın mutfağına verilir ve otelin restoranı da yıldız alabilir. Otelin oda ya da spa hizmeti ise bu ölçüte girmez."},{"id":"go-4-s16","tur":"coktan-secmeli","soru":"İzmir’deki bir otel lokantası yıldız almadı, ama günlük yemekleri ve makul fiyatıyla Michelin Rehberi’nde ayrı bir işaretle anılıyor. Bu işaret hangisidir?","secenekler":["Bir Michelin yıldızı","Bib Gourmand ödülü","Üç Michelin yıldızı","UNESCO gastronomi şehri"],"dogru":1,"aciklama":"Bib Gourmand, yıldızı olmayan ama iyi yemeği makul fiyata sunan restoranlara verilen ayrı bir ödüldür. UNESCO unvanı Michelin’e değil, Yaratıcı Şehirler Ağı’na aittir ve şehre verilir."},{"id":"go-4-s17","tur":"coktan-secmeli","soru":"Yabancı bir konuk, kaymak, lokum ve sucukla anılan bir UNESCO gastronomi şehrinde yemek yemek istiyor. Bu şehir hangisidir?","secenekler":["Afyonkarahisar","Gaziantep","Hatay","Bursa"],"dogru":0,"aciklama":"Afyonkarahisar kaymak, lokum ve sucukla anılan gastronomi şehridir. Gaziantep baklava ve kebapla, Hatay künefeyle, Bursa ise İskender kebapla tanınır."},{"id":"go-4-s18","tur":"coktan-secmeli","soru":"Akşam yemeğinden sonra bir konuk Türk kahvesi istiyor. Servis için hangisi uygundur?","secenekler":["Herkese orta şekerli yapılır; yanında süt ve kurabiye sunulur","Şekeri sorulur; yanında süt ve kurabiye sunulur","Şekeri sorulur; yanında su ve bir lokum sunulur","Herkese sade yapılır; yanında su ve lokum sunulur"],"dogru":2,"aciklama":"Kahvenin şekeri (sade, az, orta, şekerli) konuğa sorulur; yanında su ve lokum sunmak yaygındır. Şekeri sormadan yapmak konuğun tercihini yok sayar."},{"id":"go-4-s19","tur":"coktan-secmeli","soru":"UNESCO listesiyle ilgili hangi bilgi doğrudur?","secenekler":["Türk kahvesi 2022’de Azerbaycan’la ortak başvuruyla listeye alındı","Çay kültürü 2013’te Türkiye’nin tek başına yaptığı başvuruyla listeye alındı","Lavaş ve yufka geleneği yalnız Türkiye’nin başvurusuyla listeye alındı","Çay kültürü 2022’de Azerbaycan’la birlikte yapılan başvuruyla listeye alındı"],"dogru":3,"aciklama":"Türk çay kültürü 2022’de Azerbaycan’la ortak başvuruyla listeye girdi. Kahve geleneği 2013’te alındı; lavaş ve yufka ise Türkiye’nin de aralarında olduğu birkaç ülkenin ortak başvurusuyla girdi."},{"id":"go-4-s20","tur":"coktan-secmeli","soru":"Restoranlarda belirtilmesi gereken on dört alerjen listesinde (AB kuralları) aşağıdakilerden hangisi yer alır?","secenekler":["Havuç","Kereviz","Patates","Domates"],"dogru":1,"aciklama":"Kereviz listede yer alır; hardal ve susam gibi sosların ve çorbaların içinde gizlenebilir. Havuç, patates ve domates bu on dört gruptan değildir."},{"id":"go-4-s21","tur":"coktan-secmeli","soru":"Akşam 20.15’te iki konuk kahveye süt istiyor: biri süt alerjisi olan, öteki laktoz intoleransı olan konuk. Laktozsuz süt için hangisi doğrudur?","secenekler":["İkisine de verilir; laktozsuz süt süt proteini taşımaz","Yalnız alerjisi olana verilir; sorun yaratan madde laktozdur","Yalnız intoleransı olana verilir; laktozsuz süt hâlâ süt proteini taşır","İkisine de verilmez; laktozsuz süt sütten yapıldığı için her konuk için risklidir"],"dogru":2,"aciklama":"Laktozsuz sütte yalnız süt şekeri uzaklaştırılmıştır, protein durur. Bu yüzden intoleransı olan içebilir, süt alerjisi olan içemez; alerji proteine verilen tepkidir."},{"id":"go-4-s22","tur":"coktan-secmeli","soru":"Vegan bir konuk kahvaltıda hangisini yiyebilir?","secenekler":["Zeytin, domates ve humus tabağı","Sebzeli omlet","Et suyuyla yapılmış sebze çorbası","Bal ve tereyağlı ekmek"],"dogru":0,"aciklama":"Vegan beslenmede et, balık, süt, yumurta ve bal dâhil hiçbir hayvansal ürün yoktur. Omlet yumurta, çorba et suyu, ekmekteki bal ve tereyağı da hayvansal olduğu için uygun değildir."},{"id":"go-4-s23","tur":"coktan-secmeli","soru":"Çölyak hastası bir konuk için hangisi risk taşır?","secenekler":["Ayrı tezgâhta ve ayrı bıçakla hazırlanan glutensiz ekmek","Ayrı tabakta hazırlanan sade yumurta ve domates","Yalnız zeytinyağı ve limonla servis edilen domates salatası","Yanında bulgur pilavı verilen sıcak tavuk sote tabağı"],"dogru":3,"aciklama":"Bulgur buğdaydan yapılır ve gluten içerir; çölyakta gluten bağırsağa zarar verir. Ayrı hazırlanan ekmek ve tabak ise çapraz teması önleyen doğru uygulamadır."},{"id":"go-4-s24","tur":"coktan-secmeli","soru":"Bir konuk koşer yemek istiyor. Koşer yemekle ilgili hangisi doğrudur?","secenekler":["Yalnız domuz eti ve kabuklu deniz ürünlerini dışarıda bırakmak yeterlidir","Et ile süt ürünleri karıştırılmaz; mutfak gereçleri de önemlidir","Alkol içermeyen her yemek koşerdir; ayrıca gereç ve hazırlık aranmaz","Sıradan bir otel mutfağı, menüye not eklenerek tam koşer hizmet verebilir"],"dogru":1,"aciklama":"Koşerde domuz ve kabuklu deniz ürünleri dışarıda kalır, et ile süt karıştırılmaz ve gereçler de önemlidir; yalnız domuzu ve kabuklu deniz ürünlerini dışarıda bırakmak yetmez. Alkol ölçütü helal gıdaya aittir; sıradan bir mutfakta tam koşer hizmet vermek zordur."},{"id":"go-4-s25","tur":"senaryo","durum":"Akşam 20.10, restoranda garsonla çalışıyorsun. Bir konuk “Fındık alerjim var” diyor ve tatlı menüsünden bir tatlı seçiyor. Tatlının içeriğinden emin değilsin.","soru":"Ne yaparsın?","secenekler":["Alerjiyi yalnız mutfağa sözlü söyler, adisyona ayrıca bir not yazmadan siparişi iletirim.","Adisyona “ALERJİ: FINDIK” yazar, şefe de söyler; tatlıyı şef kontrol edince konuğa getiririm.","Tatlının içeriğini aşçının tahminine göre konuğa anlatır, siparişi normal fişle mutfağa iletirim.","Konuğa başka tatlı seçmesini söyler, nedenini sormadan ve not düşmeden siparişi değiştiririm."],"dogru":1,"aciklama":"Alerjide sıra şudur: sor, yaz, söyle, doğrula, teslim et. Her halkada bir kişi hatayı yakalar; sözlü kalan not ya da tahmin kaybolabilir."},{"id":"go-4-s26","tur":"senaryo","durum":"Akşam 21.00. Yemekten dakikalar sonra bir konuk dudaklarının şiştiğini ve nefesinin daraldığını söylüyor. Yanında yalnızsın, amirin salonun öbür ucunda.","soru":"İlk yapacağın şey nedir?","secenekler":["Konuğa su getirir, sakinleşip rahatlamasını beklerim ve durumu izlerim.","Acil ilacı olup olmadığını sorar, kendim kullandırmaya çalışır, amirime sonra söylerim.","Mutfağa gidip yemeğin içeriğini araştırır, sonra durumu amirime anlatırım.","Konuğun yanından ayrılmaz, yüksek sesle yardım çağırır, 112’nin aranmasını sağlarım."],"dogru":3,"aciklama":"Bu belirtiler anafilaksi olabilir ve yaşamı tehdit eder. Stajyer müdahale etmez; konuğu yalnız bırakmadan yardım çağırır ve amir ile 112’yi devreye sokar. Su ya da içerik araştırması vakit kaybettirir."},{"id":"go-4-s27","tur":"senaryo","durum":"Sabah 07.30, 512 numaralı odaya kahvaltı tepsisini götürüyorsun. Kapıyı çalıp “Oda servisi” diyorsun; içeriden “Bir dakika, giyiniyorum” sesi geliyor.","soru":"Ne yaparsın?","secenekler":["Kapıda beklerim; konuk “buyurun” deyince girip tepsiyi kurarım.","Tepsiyi kapının önüne bırakıp zili çalarak hemen ayrılırım.","Kapıyı biraz aralayıp tepsiyi içeri uzatarak bırakır, ayrılırım.","Anahtar kartıyla kapıyı açıp tepsiyi masaya bırakır, çıkarım."],"dogru":0,"aciklama":"Konuk izin vermeden odaya girilmez; yemeğin sıcak ve tepsinin eksiksiz teslimi için bekleyip izinle girmek gerekir. Kapı önüne bırakılan tepsi soğur, kartla girmek ise mahremiyeti ihlal eder."},{"id":"go-4-s28","tur":"senaryo","durum":"Akşam 20.30. Izgara balık masaya geldikten iki üç dakika sonra uğradın; konuk “Balık biraz soğuk” diyor.","soru":"Ne yaparsın?","secenekler":["Balığın mutfaktan sıcak çıktığını, soğumasının normal olduğunu anlatırım.","Balığı mutfağa götürüp mikrodalgada ısıttırır, aynı tabakla geri getiririm.","Özür diler, yenisini hazırlatacağımı söyler, amire ve mutfağa haber veririm.","Hesaptan indirim teklif eder, yemeğin yenilenmesini önermeden konuyu kapatırım."],"dogru":2,"aciklama":"Soğuk geldiğinde tartışmak yerine yemek yenilenir ve sebep amire ile mutfağa not edilir; bu telafi fırsatıdır. İndirim tek başına sorunu çözmez, ısıtmak da kaliteyi geri getirmez."},{"id":"go-4-s29","tur":"senaryo","durum":"Akşam 20.00. Bir konuk “Et yemem, ama peynir ve yumurta olur” diyor ve sebze çorbasını soruyor. Çorbada et suyu olup olmadığını bilmiyorsun.","soru":"Ne yaparsın?","secenekler":["“Sebze çorbası” adından dolayı vejetaryen olduğunu söyleyip siparişi alırım.","Çorbayı emin olamadığım için hiç önermeden konuğu başka bir yemeğe yönlendiririm.","Çorbada et parçası görünmediği için uygun olduğunu söyleyip masaya getiririm.","Mutfaktan et suyu olup olmadığını öğrenir, kesin bilgiyi sonra konuğa aktarırım."],"dogru":3,"aciklama":"Et suyuyla yapılan sebze çorbası vejetaryen sayılmaz; içerik tahminle değil mutfaktan öğrenilir. Bilgi almadan yönlendirmek de konuğa seçenek bırakmaz."},{"id":"go-4-s30","tur":"senaryo","durum":"Öğle 12.45. Bastonlu yaşlı bir konuk büfeye yöneliyor; tabağı taşımakta zorlanacağa benziyor.","soru":"Ne yaparsın?","secenekler":["Karışmam; kendi başına denemesini beklerim.","“Yardımcı olabilir miyim?” diye sorar, kabul ederse taşırım.","Tabağı elinden alır, hangi yemekleri alacağına ben karar veririm.","Yüksek sesle ve çok yavaş konuşarak büfe boyunca peşinden giderim."],"dogru":1,"aciklama":"Yardım teklif edilir, dayatılmaz; karar konuğa bırakılır. Hiç ilgilenmemek özensizlik, adına karar vermek ya da çocukmuş gibi konuşmak ise onuru zedeler."},{"id":"go-4-s31","tur":"senaryo","durum":"Akşam 21.30. Hesapta “servis ücreti dâhildir” yazıyor; konuk “Ayrıca bahşiş bırakmam gerekir mi?” diye soruyor.","soru":"Ne yaparsın?","secenekler":["Bırakması gerektiğini, yoksa ücretin ekibe dağıtılmayacağını ve hizmetin eksik kalacağını söylerim.","Servis ücretinin zaten bahşiş olduğunu, ayrıca bir şey bırakmasının yanlış olacağını söylerim.","Servis ücretinin hesaba eklenen bedel, bahşişin ise isteğe bağlı olduğunu açıklarım.","Soruyu yanıtlamadan hesabı alır, başka bir masaya yönelip konuyu geçiştiririm."],"dogru":2,"aciklama":"Servis ücreti hesaba önceden eklenen bedeldir; bahşiş ise isteğe bağlıdır. Bahşiş beklenmez ve istenmez, konuğa şeffaf bilgi verilir. Zorunluymuş gibi anlatmak güveni zedeler."},{"id":"go-4-s32","tur":"senaryo","durum":"Öğle 13.00. Yurt dışından gelen bir aile, yemeklerin helal olup olmadığını soruyor. Cevabı bilmiyorsun.","soru":"Ne yaparsın?","secenekler":["Mutfaktan öğrenip kesin bilgiyi vermek için kısa süre izin isterim.","Türkiye’de yemeklerin çoğunun helal olduğunu söyleyerek genellerim.","Menüde domuz yazmıyorsa “helaldir” der ve siparişi alırım.","“Bilmiyorum” der ve konuğu başka bir masadaki arkadaşıma yönlendiririm."],"dogru":0,"aciklama":"Helalde yalnız domuz değil alkol ve etin kesim biçimi de önemlidir; bu yüzden tahminle cevap verilmez. Mutfaktan kesin bilgi almak hem konuğa hem inancına saygıdır."},{"id":"go-4-s33","tur":"coktan-secmeli","soru":"Akşam servisinde aşçı hazır tabağı tezgâha koyuyor; sous chef tabağın kenarındaki sosu sildirip sıcaklığını kontrol ediyor, garson da tabağı fişle eşleştirip alıyor. Mutfakla salon arasındaki bu son kalite noktası hangisidir?","secenekler":["Sipariş fişi (KOT)","Restoran sipariş sistemi (POS)","Servis penceresi (pass)","Adisyon"],"dogru":2,"aciklama":"Pass, hazır yemeğin kontrol edilip servise verildiği tezgâh ya da penceredir. KOT ise siparişi mutfağa taşıyan fiştir; tabağın kontrol edildiği yer değildir."},{"id":"go-4-s34","tur":"coktan-secmeli","soru":"Bir restoranda konuklar “Bize kimse bakmadı” diye yakınıyor; bazı masalara iki garson gidiyor, bazılarına hiç gidilmiyor. Restoran müdürünün kurması gereken düzen hangisidir?","secenekler":["Salonu bölgelere ayırıp her bölgeyi bir garsona vermek","Garsonların bütün masalara sırayla uğramasını sağlamak","Bütün siparişleri yalnız hostun almasını sağlamak","Masa numaralarını kaldırıp siparişi isimle almak"],"dogru":0,"aciklama":"Servis bölgesi düzeninde her masa grubunun belirli bir sahibi olur, böylece “kimse bakmadı” durumu biter. Garsonların her masaya sırayla gitmesi ise sahipsiz masa sorununu çözmez."},{"id":"go-4-s35","tur":"coktan-secmeli","soru":"Çeşme’de bir otel restoranında deneyimli bir çalışan kendi dört masasının siparişini alıyor, yemekleri sırayla çıkartıyor ve yanındaki komiye hangi masanın tabaklarını kaldıracağını söylüyor. Bu çalışanın unvanı hangisidir?","secenekler":["Host","Sous chef","Restoran müdürü","Chef de rang"],"dogru":3,"aciklama":"Chef de rang belirli masa grubundan sorumlu, siparişi alıp servisi yöneten ve komiyle birlikte çalışan deneyimli garsondur. Restoran müdürü tek bir masa grubuna değil, bütün salona ve ekibe bakar."},{"id":"go-4-s36","tur":"dogru-yanlis","soru":"Restoran sipariş sistemi (POS) yalnız hesabı çıkarır; hangi yemeğin çok satıldığını ve hangi saatin yoğun olduğunu görmek için ayrıca elle defter tutmak gerekir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"POS siparişi mutfağa ve kasaya iletmenin yanında çok satan yemekleri ve yoğun saatleri de raporlar. Şefler menü kararlarını bu raporlara göre verebilir."},{"id":"go-4-s37","tur":"coktan-secmeli","soru":"Alanya’da bir resortun kahvaltı büfesinde konuklar yemeklerini kendileri alıyor. Büfe ekibinin bulaşma riskini azaltmak için yapması gereken hangisidir?","secenekler":["Bütün kaplar için ortak bir maşa kullanmak","Her kaba ayrı maşa koyup kapları gözetmek","Kapları ancak tamamen boşalınca yenilemek","Etiketleri kaldırıp büfeyi sade bırakmak"],"dogru":1,"aciklama":"Büfede konuk kendi servisini yaptığı için bulaşma riski artar; her kaba ayrı maşa konur ve kapların başında bir göz bulunur. Ortak maşa ise yemekler arasında bulaşmayı kolaylaştırır."},{"id":"go-4-s38","tur":"coktan-secmeli","soru":"Ankara’da bir otel restoranında garson büyük balığı, konuğun masasının yanına getirdiği küçük arabada kılçığından ayırıp tabağa koyuyor. Bu servis tekniği hangisidir?","secenekler":["Rus servisi","Aile usulü servis","Guéridon servisi","Amerikan servisi"],"dogru":2,"aciklama":"Guéridon servisinde yemek, masanın yanındaki küçük servis arabasında dilimlenip hazırlanır. Rus servisinde ise garson mutfakta hazırlanmış büyük tabaktan porsiyon dağıtır; araba kullanılmaz."},{"id":"go-4-s39","tur":"dogru-yanlis","soru":"Sıcak içecek servisinde fincan, kulpu konuğun sağ eline gelecek biçimde konur; tabağı ve kaşığı da yanında olur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Alkolsüz içecek servisinde fincanın kulpu konuğun rahatça alabilmesi için sağ eline göre çevrilir. Tabak ve kaşık da sunumun parçasıdır."},{"id":"go-4-s40","tur":"coktan-secmeli","soru":"Gaziantep’te bir otelde baklava kutusunda “coğrafi işaret” ibaresi görülüyor ve konuk bunun ne anlama geldiğini soruyor. Garsonun doğru açıklaması hangisidir?","secenekler":["Ürünün UNESCO miras listesine girdiğini gösterir","Ürünün yalnız bu otelin kendi mutfağında yapıldığını gösterir","Ürünün satış fiyatının sabitlendiğini gösterir","Ürünün ününün ve kalitesinin yöresinden geldiğini gösterir"],"dogru":3,"aciklama":"Coğrafi işaret, bir ürünün kalitesinin ya da ününün üretildiği yöreden geldiğini gösteren resmî tescildir. UNESCO listesi ise kültürel mirası tanır; ürün tescili değildir."},{"id":"go-4-s41","tur":"coktan-secmeli","soru":"Bir konuk İzmir’deki otelin fine dining restoranında, şefin seçtiği altı küçük tabaktan oluşan tadım menüsü için yer ayırtıyor. Rezervasyon sırasında mutlaka alınması gereken bilgi hangisidir?","secenekler":["Konuğun alerji ve diyet bilgisi","Konuğun hangi garsonu istediği","Konuğun otelde kaç kez kaldığı","Konuğun daha önce yediği yemekler"],"dogru":0,"aciklama":"Tadım menüsü önceden planlandığı için alerji ve diyet bilgisi rezervasyonda alınır; böylece şef tabakları buna göre hazırlar. Öteki bilgiler menünün güvenli hazırlanmasını etkilemez."},{"id":"go-4-s42","tur":"coktan-secmeli","soru":"Bodrum’da bir otelin teras restoranında masaya birkaç küçük tabak geliyor ve konuklar bunları aralarında bölüşerek tadıyor. Bizdeki meze kültürüne benzeyen bu sunumun adı nedir?","secenekler":["Sushi","Tapas","Pasta","Street food"],"dogru":1,"aciklama":"Tapas, İspanya’da küçük tabaklarda sunulan ve paylaşılarak tadılan yemeklerdir; meze kültürüne benzer. Street food ise sokakta ya da tezgâhta satılan yiyeceklerin genel adıdır."},{"id":"go-4-s43","tur":"dogru-yanlis","soru":"Servis sırasında bir salatanın tazeliğinden şüphelenen garson, konuğu bekletmemek için salatayı yine de servis eder ve durumu sonra amirine bildirir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Servis alanında gıda güvenliğinin kuralı açıktır: şüphe varsa servis edilmez ve amire söylenir. Konuğu bekletmemek, sağlığını riske atmaktan önce gelmez."},{"id":"go-4-s44","tur":"coktan-secmeli","soru":"Fıstık alerjisi olan bir çocuk için yemek hazırlanıyor. Çapraz teması önlemek için mutfağın yapması gereken hangisidir?","secenekler":["Fıstıkları yemeğin üstünden tek tek ayıklayıp çıkarmak","Yemeği öbür tabaklarla aynı yağda kızartmak","Yemeği her zamanki tezgâhta hızla hazırlamak","Yemeği ayrı tahtada ve temiz bıçakla hazırlamak"],"dogru":3,"aciklama":"Çapraz temasta alerjenin küçücük bir bulaşması bile tepki yaratabilir; bu yüzden ayrı gereç ve temiz tezgâh kullanılır. Fıstığı sonradan ayıklamak bulaşmış kalıntıyı ortadan kaldırmaz."}],"siralamalar":[{"id":"go-4-r01","konu":"4.1","baslik":"Kapıdan kapıya: restoranda bir akşam","yonerge":"Konuğun restorana girişinden uğurlanmasına kadar servis akışının adımlarını doğru sıraya koy.","adimlar":["Konuğu restoran girişinde güler yüzle karşıla.","Konuğu masasına götür ve oturt.","Masaya su ve menüyü getir.","Konuğun siparişini al.","Yemekleri sırayla masaya çıkar.","Yemek bitince tabakları sessizce topla ve konuk isteyince hesabı getir.","Konuğu kapıda uğurla."],"aciklama":"Konuk karşılanıp yerleştirildikten sonra menüyü görür ve sipariş verir; yemekler çıkar, tabaklar toplanır, hesap gelir ve konuk uğurlanır. Bir halka atlanırsa konuk bunu hisseder."},{"id":"go-4-r02","konu":"4.1","baslik":"Siparişin mutfak yolculuğu","yonerge":"Garsonun aldığı siparişin tabak olarak konuğa ulaşmasına kadar geçen adımları doğru sıraya koy.","adimlar":["Garson siparişi masa ve koltuk numarasıyla el terminaline girer.","Sipariş fişi mutfakta ilgili bölümün yazıcısından çıkar.","Aşçı fişteki yemeği hazırlayıp tabağı servis penceresine (pass) koyar.","Sous chef tabağın kenarını ve sıcaklığını kontrol eder.","Garson tabağı fişle eşleştirip bekletmeden alır.","Tabak, fişteki koltuk numarasına göre doğru konuğun önüne konur."],"aciklama":"Sipariş yazılı fişle mutfağa gider, hazır tabak servis penceresinde son kontrolden geçer; garson fişle eşleşen tabağı alır, koltuk numarası da yemeğin doğru kişiye gitmesini sağlar."},{"id":"go-4-r03","konu":"4.2","baslik":"512 numaralı odaya kahvaltı","yonerge":"Oda servisi siparişini konuğa teslim etmenin adımlarını doğru sıraya koy.","adimlar":["Kapıyı çal ve “Oda servisi” diyerek kendini tanıt.","Konuk “buyurun” deyip izin verince odaya gir.","Kahvaltı tepsisini masaya düzgünce kur.","Hesabı imzaya sun ve boş tepsinin hangi saatte toplanacağını sor."],"aciklama":"Konuk izin vermeden içeri girilmez; tepsi kurulduktan sonra hesap imzalatılır ve boş tepsi koridorda kalmasın diye toplama saati konuğa sorulur."},{"id":"go-4-r04","konu":"4.4","baslik":"Fındık alerjisi: güvenli tabak zinciri","yonerge":"Alerjisi olan konuğun siparişinde izlenen güvenli adımları doğru sıraya koy.","adimlar":["Garson sipariş alırken konuğa alerjisi olup olmadığını sorar.","Garson alerjiyi adisyona açıkça yazar ve şefe sözlü olarak da bildirir.","Mutfak yemeği ayrı tahta ve temiz bıçakla hazırlar.","Şef tabağı servise vermeden kontrol eder.","Garson tabağı alıp doğrudan alerjisi olan konuğa verir."],"aciklama":"Sor, yaz ve söyle, ayrı hazırla, doğrula, teslim et: her halkada bir kişinin gözü hatayı yakalar. Alerjide tahmin ve pazarlık yoktur."}],"acikSorular":[{"id":"go-4-y01","konu":"4.2","soru":"Bir otelin toplantı salonunda iki yüz kişiye öğle yemeği verilecek; yemeğin kısa sürede, sıcak ve her konuğa aynı görünümde sunulması isteniyor. Rus servisi ile Amerikan servisini (tabak servisi) karşılaştırınız ve bu yemek için hangisini seçeceğinizi nedenini belirterek yazınız.","olcut":[{"metin":"Rus servisinde yemeğin büyük servis tabağında getirilip garson tarafından konuğun tabağına konduğunu belirtir.","puan":20},{"metin":"Amerikan servisinde yemeğin mutfakta tabağa porsiyonlanıp hazır tabakla getirildiğini belirtir.","puan":20},{"metin":"İki servis tarzı arasında hız, düzen ya da konuğa gösterilen özen açısından bir fark söyler.","puan":20},{"metin":"Seçtiği servis tarzını yemeğin özelliklerine bağlayarak nedenini açıklar.","puan":40}],"ornek":"Rus servisinde yemek mutfakta büyük bir servis tabağına dizilir ve garson bu tabaktan her konuğun önündeki boş tabağa porsiyon koyar. Amerikan servisinde ise yemek mutfakta tabağa porsiyonlanıp süslenir ve hazır tabakla masaya getirilir. Amerikan servisi hızlı ve düzenlidir, her tabak aynı görünür; Rus servisinde ise garson porsiyonu masa başında koyduğu için eğitimli ve düzenli çalışması gerekir. İki yüz kişilik bu yemekte hız ve aynı görünüm istendiği için Amerikan servisini seçerdim, çünkü tabaklar mutfakta aynı anda hazırlanır ve masalara az personelle götürülür.","ipucu":"İki tarzda porsiyonun nerede ve kim tarafından yapıldığını düşünün; seçiminizi yemeğin istenen özelliklerine bağlayın."},{"id":"go-4-y02","konu":"4.4","soru":"Restoranda bir konuk, kendisinde fıstık alerjisi olduğunu söyleyerek yemek siparişi veriyor. Garson olarak alerjik konuğun siparişinde izleyeceğiniz üç güvenli adımı yazınız ve alerjinin neden sıradan bir tercih gibi ele alınmaması gerektiğini açıklayınız.","olcut":[{"metin":"Konuğun alerjisini garson olarak ciddiye alıp ona hangi alerjene karşı alerjisi olduğunu sorduğunu belirtir.","puan":20},{"metin":"Siparişin alerji bilgisiyle birlikte mutfağa yazılı iletilmesini bir adım olarak yazar.","puan":20},{"metin":"Alerjenin yemeğe çapraz temasla bulaşmaması için alınacak bir önlemi örnek verir.","puan":20},{"metin":"Alerjinin ağır sonuçlar doğurabildiğini, bu yüzden alerjenin tercihten ayrı ele alındığını nedenleriyle açıklar.","puan":40}],"ornek":"Önce konuğa hangi gıdaya alerjisi olduğunu sorar ve menüdeki yemeklerin alerjen bilgisini açıkça söylerim. Sipariş fişine alerjiyi yazılı olarak ekler ve mutfağa doğru kişiye ulaştığından emin olurum; böylece bilgi yanlış anlaşılmaz. Yemeğin fıstıkla temas etmemesi için ayrı araç ve ayrı yüzey kullanılmasını isterim, çünkü çapraz temas da tepkiye yol açabilir. Alerji, bir yiyeceği sevmemekten farklı olarak bağışıklık sisteminin aşırı tepki vermesidir; ağır olduğunda anafilaksi gibi yaşamı tehdit eden sonuçlar doğurabilir. Bu yüzden alerjik konuğun siparişi özellikle dikkatle ele alınır.","ipucu":"Bilginin garsondan mutfağa kadar nasıl güvenle taşınacağını ve alerjinin tehlikesini düşünün."}]},{"ders":"global-otelcilik","sinif":9,"unite":5,"baslik":"Etkinlik, Kruvaziyer ve Hava Yolu Dünyası","onay":true,"kazanimlar":["Uluslararası etkinlik ve toplantı sektörünün işleyişini ve unvanlarını açıklar.","Kruvaziyer gemisinde otelcilik departmanlarını ve çalışma düzenini açıklar.","Hava yolu yolcu hizmetlerinin ve havalimanı işleyişinin temel kavramlarını açıklar.","Destinasyon yönetimi ve deneyim turizminin uluslararası kavramlarını açıklar."],"soz":"Otelcilik yalnız binanın içinde değil; salonda, güvertede ve havalimanında da aynı misafirperverlikle sürer.","dersler":[{"baslik":"Dört Harfin Sırrı","ilk":"go-5-001"},{"baslik":"Bu Salonu Kim Satıyor?","ilk":"go-5-006"},{"baslik":"Sandalyeler Nasıl Dizilir?","ilk":"go-5-009"},{"baslik":"Her Dakika Yazılıdır","ilk":"go-5-015"},{"baslik":"Perde Arkasındaki Ortaklar","ilk":"go-5-018"},{"baslik":"Salondan Ekrana, Otelden Sahile","ilk":"go-5-022"},{"baslik":"Yüzen Otelin Mürettebatı","ilk":"go-5-024"},{"baslik":"İç Kabin mi, Balkon mu?","ilk":"go-5-030"},{"baslik":"Liman Günü, Deniz Günü","ilk":"go-5-034"},{"baslik":"Tatbikat, Vardiya ve Liman","ilk":"go-5-037"},{"baslik":"Koltuğun Adı: Sınıf","ilk":"go-5-040"},{"baslik":"Kapıdan Uçağa","ilk":"go-5-043"},{"baslik":"Yerde ve Havada Ekip","ilk":"go-5-046"},{"baslik":"Bir Bilet, İki Şirket","ilk":"go-5-049"},{"baslik":"Havalimanında Karşılama","ilk":"go-5-054"},{"baslik":"Şehrin Adı, Şehrin Markası","ilk":"go-5-057"},{"baslik":"Rota, Hikâye ve Yavaşlık","ilk":"go-5-060"},{"baslik":"Gece, Sezon ve Sınır","ilk":"go-5-065"}],"kavramlar":[{"id":"go-5-001","konu":"5.1","terim":"MICE’ın dört kolu","ingilizce":"Meetings, incentives, conferences and exhibitions (MICE)","tanim":"Şirketlerin ve kurumların düzenlediği toplantı, teşvik gezisi, konferans ve fuar gibi iş amaçlı grup etkinliklerini dört başlıkta toplayan sektör adıdır.","ornek":"İzmir’de bir ilaç şirketi yıl sonunda bayilerini üç günlüğe otele toplar: sabah toplantı, öğleden sonra ödül yemeği, akşam gala yapılır; bu bir MICE etkinliğidir.","sektor":"Etkinliğe gelenler çoğunlukla işi için seyahat eder ve masrafı çoğu zaman şirket öder; bu yüzden MICE, otelin sezon dışında da dolu kalmasını sağlayan önemli kaynaklardan biridir. Dünyada etkinlik ve toplantı yönetimi ayrı bir kariyer koludur.","iliskili":["go-5-002","go-5-003","go-5-005"],"kontrol":null,"kitapDisi":true},{"id":"go-5-002","konu":"5.1","terim":"Toplantı","ingilizce":"Meeting","tanim":"Bir şirketin ya da kurumun çalışanlarını, bayilerini veya müşterilerini belirli bir konuyu görüşmek için bir araya getirdiği, genellikle küçük ve kısa süreli buluşmadır.","ornek":"Ankara’dan gelen satış ekibi sabah 09.00’da İstanbul’daki otelin toplantı odasında yıllık hedefleri görüşür; kahve molası 10.30’da verilir.","sektor":"Toplantı etkinliklerin en küçüğüdür, ama en sık görülenidir: oda, projeksiyon, internet ve ikram hatasız hazırlanmazsa şirket oteli bir daha seçmez. Küçük toplantıyı iyi yöneten otel, sonraki büyük etkinliği de alır.","iliskili":["go-5-001","go-5-003","go-5-009"],"kontrol":null,"kitapDisi":true,"gorsel":"t14f-toplanti-masasi"},{"id":"go-5-003","konu":"5.1","terim":"Konferans ve kongre","ingilizce":"Conference and congress","tanim":"Aynı alandan çok sayıda kişinin sunum dinlemek, bilgi paylaşmak ve tanışmak için günlerce bir araya geldiği büyük toplantılardır.","ornek":"Antalya’da üç gün süren tıp kongresine yurt dışından gelen doktorlar katılır; sabah oturumları salonda, öğle yemeği otel restoranında yapılır.","sektor":"Katılımcılar yalnız salonu değil oda, yemek, kahve arası ve gece programını da kullanır; tek bir kongre, otel için günlerce dolu oda demektir. Uluslararası kongrelerin hangi şehirde yapılacağı çoğu zaman yıllar önceden, şehirlerin teklif yarıştığı bir süreçle belirlenir.","iliskili":["go-5-001","go-5-008","go-5-018"],"kontrol":null,"kitapDisi":true,"cizim":"toplanti-sunum"},{"id":"go-5-004","konu":"5.1","terim":"Ticari fuar","ingilizce":"Trade show","tanim":"Firmaların ürün ve hizmetlerini stantlarda sergilediği, alıcılarla yüz yüze görüştüğü, birkaç gün süren iş etkinliğidir.","ornek":"İstanbul’daki bir turizm fuarında acenteler, oteller ve hava yolları stant açar; fuar günlerinde çevredeki otellerin odaları fuar ziyaretçileriyle dolar.","sektor":"Fuar günlerinde şehirdeki otellerin doluluğu ve fiyatı yükselebilir; gelir müdürü fuar takvimini önceden bilir. Oteller fuarlara hem sergileyen firma hem de ziyaretçileri ağırlayan ev sahibi olarak katılır.","iliskili":["go-5-001","go-5-003","go-5-021"],"kontrol":null,"kitapDisi":true,"gorsel":"t14za-fuar-salonu-standlar"},{"id":"go-5-005","konu":"5.1","terim":"Teşvik gezisi programı","ingilizce":"Incentive programme","tanim":"Bir şirketin hedefi aşan çalışanlarını ya da bayilerini ödüllendirmek için düzenlediği gezi, yemek ve etkinliklerden oluşan özel programdır.","ornek":"Satış hedefini aşan bir ekip Bodrum’daki bir otelde üç gece ağırlanır; tekne gezisi ve kapanış gala yemeği programın en önemli iki ayağıdır.","sektor":"Konuklar ödül olarak geldiği için sıradan bir paket yetmez; her anın özel hissettirmesi beklenir. Otel için yüksek harcama ve etkileyici bir deneyim anlamına gelir; programı kurma işi çoğunlukla yerel bir DMC ile birlikte yürütülür.","iliskili":["go-5-001","go-5-019","go-5-023"],"kontrol":null,"kitapDisi":true},{"id":"go-5-006","konu":"5.1","terim":"Etkinlik yöneticisi","ingilizce":"Event manager","tanim":"Bir etkinliğin planlanmasından bitişine kadar bütçeyi, mekânı, programı ve ekibi yöneten kişidir.","ornek":"Çarşamba günü başlayacak kongrenin ilk sabahında etkinlik yöneticisi 07.00’de salonu gezer, teknik ekiple ses denemesi yapar ve kayıt masasının açılmasını sağlar.","sektor":"Etkinlik yöneticisi otelde ya da bir organizatör firmada çalışabilir; hem müşteriyle hem otelin tüm departmanlarıyla konuştuğu için iletişim ve sakin kalabilme becerisi en önemlisidir. Dünya otelciliğinde otelde başlayıp etkinlik yönetimine uzanan kariyerler yaygındır.","iliskili":["go-5-007","go-5-016","go-5-015"],"kontrol":null,"kitapDisi":true},{"id":"go-5-007","konu":"5.1","terim":"Banket satış yöneticisi","ingilizce":"Banqueting sales manager","tanim":"Otelin toplantı salonlarını, düğün ve yemekli organizasyonlarını müşterilere sunan, teklif hazırlayan ve sözleşmeyi bağlayan satış görevlisidir.","ornek":"Pazartesi 10.00’da bir banka yıl sonu yemeği için balo salonunu sorar; banket satış yöneticisi salonu gezdirir, menü seçeneklerini anlatır ve yazılı teklif gönderir.","sektor":"Mutfağın, servisin ve teknik ekibin neleri yapabileceğini bilmeden söz veremez; verdiği her söz etkinlik günü başkalarının işi olur. Doğru satılan etkinlik hem müşteriyi hem de salonu memnun eder.","iliskili":["go-5-006","go-5-015","go-5-017"],"kontrol":null,"kitapDisi":true},{"id":"go-5-008","konu":"5.1","terim":"Kongre merkezi","ingilizce":"Convention centre","tanim":"Büyük salonları, sergi alanları ve toplantı odalarıyla kongre ve fuarlar için tasarlanmış, çevresindeki otellerle birlikte çalışan özel binadır.","ornek":"İstanbul’daki bir kongre merkezinde uluslararası bir tıp kongresi yapılır; katılımcıların çoğu yakındaki otellerde kalır ve sabah merkeze servisle ya da yürüyerek gider.","sektor":"Merkez salonu sağlar, konaklamayı çevredeki oteller sağlar; şehirde kongre merkezi bulunması otellerin yıl boyu dolmasını destekler. Salon ve konaklamayı tek çatıda sunan otellere ise kongre oteli denir.","iliskili":["go-5-003","go-5-018","go-5-021"],"kontrol":null,"kitapDisi":true,"gorsel":"t13e-fuar-salonu-ust"},{"id":"go-5-009","konu":"5.1","terim":"Oturma düzeni","ingilizce":"Seating style (room set-up)","tanim":"Bir salonda masa ve sandalyelerin etkinliğin amacına göre nasıl dizildiğini anlatan genel addır.","ornek":"Aynı otel salonu sabah 09.00’da eğitim için sınıf düzeniyle, akşam 19.00’da gala yemeği için yuvarlak masalarla hazırlanır.","sektor":"Düzen kapasiteyi değiştirir: aynı salona tiyatro düzeninde çok kişi sığarken yemekli düzende daha az kişi sığar. Bu yüzden satış ekibi müşteriye yalnız salonun büyüklüğünü değil kaç kişi geleceğini ve etkinliğin amacını sorar.","iliskili":["go-5-010","go-5-011","go-5-013"],"kontrol":null,"kitapDisi":true,"cizim":"oda"},{"id":"go-5-010","konu":"5.1","terim":"Tiyatro düzeni","ingilizce":"Theatre style","tanim":"Sandalyelerin masa olmadan, sahneye ya da perdeye dönük sıralar hâlinde dizildiği düzendir.","ornek":"Belediyenin turizm tanıtım toplantısında yüzlerce kişi sahneye bakan sıralarda oturur; amaç yalnız konuşmacıyı dinlemektir.","sektor":"Oturma düzenleri arasında salona en çok kişiyi sığdıran düzendir. Masa olmadığı için yazı yazmak ya da yemek yemek zordur; bu yüzden kısa konuşmalar ve lansmanlar için seçilir.","iliskili":["go-5-009","go-5-011","go-5-003"],"kontrol":null,"kitapDisi":true,"gorsel":"sektor-konferans-salonu"},{"id":"go-5-011","konu":"5.1","terim":"Sınıf düzeni","ingilizce":"Classroom style","tanim":"Katılımcıların sahneye dönük, önlerinde dar masalar bulunan sıralarda oturduğu düzendir.","ornek":"Otelde iki günlük bir yangın eğitimi yapılır; katılımcılar not tutabilsin diye salon sınıf düzeniyle hazırlanır.","sektor":"Masa yer kapladığı için aynı salona tiyatro düzeninden daha az kişi sığar; karşılığında defter, bilgisayar ve eğitim malzemesi rahatça kullanılır. Eğitim ve seminerlerde tercih edilir.","iliskili":["go-5-009","go-5-010","go-5-012"],"kontrol":null,"kitapDisi":true,"cizim":"kitap-ogrenme"},{"id":"go-5-012","konu":"5.1","terim":"U düzeni","ingilizce":"U-shape style","tanim":"Masaların U harfi biçiminde dizildiği, ortanın boş bırakıldığı ve sunucunun açık uçta durduğu düzendir.","ornek":"Acente yöneticilerinin yarım günlük atölyesinde katılımcılar U düzeninde oturur; eğitmen ortada dolaşarak herkesle göz göze gelir.","sektor":"Herkes hem sunucuyu hem de birbirini görür, bu yüzden tartışma ve atölye çalışmaları için uygundur. Az kişi sığdırdığı için küçük gruplara önerilir.","iliskili":["go-5-009","go-5-011","go-5-002"],"kontrol":null,"kitapDisi":true,"gorsel":"t14f-u-duzeni"},{"id":"go-5-013","konu":"5.1","terim":"Banket düzeni","ingilizce":"Banquet style (round tables)","tanim":"Konukların yuvarlak masalarda, masa başına belirli sayıda kişiyle oturup yemek yediği düzendir.","ornek":"Yıl sonu galasında konuklar yuvarlak masalarda oturur ve servis ekibinin getirdiği menüyü yer.","sektor":"Yemekli ve sohbetli etkinliklerin düzenidir; kişi başına geniş alan gerektirdiği için aynı salona az kişi sığar. Masa numarası, oturma planı ve servis akışı bu düzenin ayrılmaz parçasıdır.","iliskili":["go-5-009","go-5-014","go-5-017"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-banket-duzeni"},{"id":"go-5-014","konu":"5.1","terim":"Kokteyl düzeni","ingilizce":"Reception style","tanim":"Konukların ayakta dolaşarak sohbet ettiği, tepsiyle ikram yapıldığı ve çok az sayıda masanın bulunduğu düzendir.","ornek":"Akşam 18.30’da otelin teras salonunda yeni bir markanın lansmanı yapılır; garsonlar tepsiyle içecek ve küçük lokmalar dolaştırır.","sektor":"Konuklar ayakta durduğu için çoğu oturma düzeninden daha fazla kişi sığar ve herkes birbirine kolayca yaklaşır. Tanışma ve açılış etkinliklerinde seçilir; yeterli bar noktası ve ikram planlamak başarının anahtarıdır.","iliskili":["go-5-009","go-5-013","go-5-021"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-kanape-tepsisi"},{"id":"go-5-015","konu":"5.1","terim":"Etkinlik sipariş formu (BEO)","ingilizce":"Banquet event order (BEO)","tanim":"Bir etkinliğin tarihini, salonunu, düzenini, menüsünü, saatlerini ve teknik ihtiyaçlarını tek belgede toplayıp bütün departmanlara dağıtan yazılı iş emridir.","ornek":"Cumartesi günkü düğün için BEO mutfağa, kat hizmetlerine, teknik servise ve güvenliğe gönderilir; mutfak menüyü, teknik ekip ışığı ve müziği aynı belgeden okur.","sektor":"Herkes aynı belgeden okuduğu için bilgi yanlışsa her departman yanlış hazırlanır; bu yüzden müşterinin onayı ve her değişiklik BEO üzerinde güncellenir. Dünyanın birçok otelinde aynı mantıkla kullanıldığı için bu belgeyi okumayı bilen stajyer yeni bir otele hızlı uyum sağlar.","iliskili":["go-5-007","go-5-016","go-5-017"],"kontrol":null,"kitapDisi":true,"cizim":"belge-form"},{"id":"go-5-016","konu":"5.1","terim":"Etkinlik akış çizelgesi (run of show)","ingilizce":"Run of show","tanim":"Gün boyunca kimin, ne zaman, ne yapacağını saat saat gösteren etkinlik program belgesidir.","ornek":"Kongrenin açılış gününde çizelgeye göre 08.30’da kayıt, 09.30’da açılış konuşması, 10.30’da kahve molası vardır; ikram ekibi molaya on dakika kala salonun önünde hazırdır.","sektor":"Çizelge etkinliğin ritmini korur: kahve molası geç gelirse bir sonraki oturum kayar. Ekip telsizle çizelgeyi izler ve gecikme olursa etkinlik yöneticisine bildirir.","iliskili":["go-5-006","go-5-015","go-5-021"],"kontrol":null,"kitapDisi":true,"cizim":"takvim"},{"id":"go-5-017","konu":"5.1","terim":"Garanti sayısı","ingilizce":"Guaranteed number","tanim":"Müşterinin yemekli etkinlikten kısa süre önce otele bildirdiği kesin kişi sayısıdır; otel hazırlığı buna göre yapar, çoğunlukla da eksik gelenlerin ücreti ödenmek zorundadır.","ornek":"Yarınki gala için müşteri 180 kişi bildirir; otel 180 kişilik hazırlık yapar ve 170 kişi gelse bile sözleşmeye göre 180 kişilik ücret kesilir.","sektor":"Mutfağın alışverişi, servis ekibinin sayısı ve masa planı bu sayıya göre yapılır. Son dakikada artan kişiye yetişmek zor, eksik gelen kişinin yemeği ise israftır; bu yüzden kural sözleşmede yazılıdır ve satış ekibi müşteriyle bunu baştan konuşur.","iliskili":["go-5-007","go-5-013","go-5-015"],"kontrol":null,"kitapDisi":true},{"id":"go-5-018","konu":"5.1","terim":"Profesyonel kongre organizatörü (PCO)","ingilizce":"Professional congress organiser (PCO)","tanim":"Bir derneğin ya da kurumun kongresini kayıt, program, bildiri, sponsor ve mekân işleriyle baştan sona organize eden uzman firmadır.","ornek":"Bir tıp derneği Antalya’daki kongresini bir PCO’ya emanet eder; PCO kayıtları alır, otelle salon pazarlığı yapar ve konuşmacı programını yönetir.","sektor":"Otel için PCO, tek müşteri gibi görünen ama yüzlerce kişiyi getiren bir ortaktır. Onunla iyi çalışmak, sonraki kongrelerin de aynı otelde yapılmasını sağlar.","iliskili":["go-5-019","go-5-003","go-5-020"],"kontrol":null,"kitapDisi":true},{"id":"go-5-019","konu":"5.1","terim":"Destinasyon yönetim şirketi (DMC)","ingilizce":"Destination management company (DMC)","tanim":"Bir yerin otellerini, ulaşımını, rehberlerini, restoranlarını ve etkinliklerini bilen, dışarıdan gelen grup için yerinde tüm programı kuran yerel şirkettir.","ornek":"Almanya’dan gelen bir şirketin ödül grubu için Kapadokya’daki yerel firma otelini, balon turunu ve mağara restoranındaki akşam yemeğini ayarlar.","sektor":"DMC otel için hem müşteri hem de kapı açıcıdır: yurt dışındaki şirket oteli tanımaz, ama DMC’ye güvenir. DMC ticari bir şirkettir; şehri tanıtan dernek ya da kamu kuruluşu ise destinasyon yönetim örgütüdür (DMO).","iliskili":["go-5-018","go-5-005","go-5-057"],"kontrol":null,"kitapDisi":true},{"id":"go-5-020","konu":"5.1","terim":"Sponsor","ingilizce":"Event sponsor","tanim":"Bir etkinliğin masraflarına para ya da ürünle katkıda bulunup karşılığında etkinlikte adını ve logosunu görünür kılan şirkettir.","ornek":"Kongrede kahve molası bir ilaç firmasının sponsorluğundadır; masalarda firmanın logosu bulunur ve salon girişinde firmanın standı vardır.","sektor":"Sponsorun logosu, afiş yeri ve standı için otel ile organizatör mekânda yer ayırır. Sponsor bütçeyi hafifletir, ama taleplerin sözleşmedeki kapsamı aşmaması gerekir.","iliskili":["go-5-018","go-5-021","go-5-004"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"go-5-021","konu":"5.1","terim":"Kayıt masası","ingilizce":"Registration desk","tanim":"Etkinliğe gelen katılımcının adının listede kontrol edildiği, yaka kartı ve kongre çantasının verildiği karşılama noktasıdır.","ornek":"Sabah 08.00’de kongre salonunun girişindeki masada görevli katılımcının adını listede bulur, yaka kartını verir ve salonun yolunu gösterir.","sektor":"Katılımcının etkinlikle ilk teması burasıdır; uzun kuyruk ilk izlenimi bozar. Kayıt masasında yabancı dil, hatasız yaka kartı ve sakin kalabilmek önemlidir; masa otelin resepsiyonuyla yakın çalışır.","iliskili":["go-5-003","go-5-016","go-5-006"],"kontrol":null,"kitapDisi":true,"cizim":"resepsiyon"},{"id":"go-5-022","konu":"5.1","terim":"Hibrit etkinlik","ingilizce":"Hybrid event","tanim":"Katılımcıların bir kısmının salonda bulunduğu, bir kısmının ise internetten canlı yayınla izleyip katıldığı etkinliktir.","ornek":"İstanbul’daki bir otelde yapılan eğitimde yetmiş kişi salonda oturur, başka şehirlerdeki yüzlerce kişi ekrandan izler ve soru sorar.","sektor":"Salona kamera, ses sistemi ve güçlü internet gerekir; bu yüzden teknik ekip artık etkinlik otelleri için çok önemlidir. Uzaktan katılım kongreyi dünyaya açar, ama insanlar yüz yüze tanışma ihtiyacını sürdürür.","iliskili":["go-5-003","go-5-001","go-5-009"],"kontrol":null,"kitapDisi":true,"cizim":"toplanti-sunum"},{"id":"go-5-023","konu":"5.1","terim":"Destinasyon düğünü","ingilizce":"Destination wedding","tanim":"Çiftin ve konuklarının yaşadıkları yerden başka bir yerde, tatil ile düğünü birleştirerek yaptığı düğündür.","ornek":"Londra’da yaşayan bir çift düğününü Bodrum’daki otelin bahçesinde yapar; aileleri ve arkadaşları bir hafta otelde kalır.","sektor":"Düğün tek geceyle bitmez: yakınlar günlerce kalır, yemek yer ve hizmet alır. Bu yüzden oteller düğün koordinatörü çalıştırır; çifte tek bir yetkili ile çalışma güveni verir.","iliskili":["go-5-005","go-5-013","go-5-006"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-sahil-dugunu"},{"id":"go-5-024","konu":"5.2","terim":"Gemide otel bölümü","ingilizce":"Hotel department on a cruise ship","tanim":"Kruvaziyer gemisinde seyir ve makine işlerinin dışında kalan, konukların kabin, yemek, eğlence ve hizmet ihtiyacını karşılayan, karadaki otele benzeyen bölümlerin tamamıdır.","ornek":"Akşam 19.00’da kaptan köprüsü rotayı izlerken aşağıdaki restoranlarda yüzlerce konuğa yemek servis edilir, kabin görevlileri odaları akşam düzenine geçirir.","sektor":"Gemide çalışanların büyük bölümü seyir ekibi değil otel ekibidir; ön büro, kat hizmetleri ve mutfak bilgisi gemide doğrudan işe yarar. Kruvaziyer, otelcilik öğrencisi için ülke dışında deneyim kazanmanın yollarından biridir.","iliskili":["go-5-025","go-5-029","go-5-034"],"kontrol":null,"kitapDisi":true},{"id":"go-5-025","konu":"5.2","terim":"Otel direktörü","ingilizce":"Hotel director","tanim":"Kruvaziyer gemisinde konaklama, yiyecek içecek ve konuk hizmetlerini birlikte yöneten üst düzey yöneticidir.","ornek":"Sabah 08.00’de bölüm yöneticileriyle toplanan otel direktörü gece gelen şikâyetleri ve bugünkü liman programını gözden geçirir.","sektor":"Karadaki otelin genel müdürüne benzer, ama yüzlerce, hatta binlerce kişinin yaşadığı yüzen bir şehri yönetir. Bu göreve genellikle gemide yıllarca farklı bölümlerde çalışmış kişiler gelir.","iliskili":["go-5-024","go-5-026","go-5-029"],"kontrol":null,"kitapDisi":true},{"id":"go-5-026","konu":"5.2","terim":"Misafir hizmetleri masası","ingilizce":"Guest services","tanim":"Gemide konukların soru, şikâyet, hesap ve kabin sorunlarıyla başvurduğu, karadaki resepsiyona karşılık gelen masadır.","ornek":"Gemi limandan ayrıldıktan sonra bir konuk kabin kartının çalışmadığını bildirir; masadaki görevli yeni kartı basar ve kabin görevlisine haber verir.","sektor":"Konuğun gemideki en sık uğradığı noktadır; hesap sorunları, gezi bilgileri ve duyurular burada çözülür. Ön büro deneyimi olan biri için gemide doğal giriş noktasıdır.","iliskili":["go-5-025","go-5-027","go-5-035"],"kontrol":null,"kitapDisi":true,"gorsel":"t14za-gemi-resepsiyon-masasi"},{"id":"go-5-027","konu":"5.2","terim":"Kabin görevlisi","ingilizce":"Cabin steward","tanim":"Kruvaziyer gemisinde konukların kabinlerini temizleyen, yatağı hazırlayan ve küçük isteklerini karşılayan, karadaki oda görevlisinin gemideki karşılığı olan çalışandır.","ornek":"Sabah konuk kahvaltıdayken kabin görevlisi odayı toplar; akşam yemeğinde yatağı hazırlar ve havluyu küçük bir figüre katlayıp bırakır.","sektor":"Konukla gün boyu en çok karşılaşan çalışanlardan biridir; konuğun adını bilmesi ve isteklerini hatırlaması yorumlara yansır. Birçok kabinden sorumlu olduğu için düzen ve hız çok önemlidir.","iliskili":["go-5-024","go-5-026","go-5-030"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-havlu-tavsan"},{"id":"go-5-028","konu":"5.2","terim":"Kruvaziyer direktörü","ingilizce":"Cruise director","tanim":"Gemideki gösteri, oyun, eğlence ve duyuruların programını yöneten, konukların en çok tanıdığı yüzlerden biri olan eğlence sorumlusudur.","ornek":"Akşam 21.00’de ana tiyatroda sahneye çıkan kruvaziyer direktörü yarınki liman gününün programını anlatır, ardından yarışma ve gösteriyi sunar.","sektor":"Karadaki animasyon müdürüne benzer, ama günlük anonslar, gezi bilgileri ve bütün eğlence ekibi onun üzerinden yürür. İletişim becerisi, sahne enerjisi ve yabancı dil çok önemlidir.","iliskili":["go-5-025","go-5-034","go-5-035"],"kontrol":null,"kitapDisi":true},{"id":"go-5-029","konu":"5.2","terim":"Gemide yiyecek ve içecek ekibi","ingilizce":"Food and beverage (F&B) team on board","tanim":"Gemideki ana restoranları, açık büfeyi, barları, oda servisini ve mutfağı yöneten; şef, garson ve barmenlerden oluşan ekiptir.","ornek":"Bazı gemilerde ana restoranda akşam yemeği iki oturumla verilir: 18.00 ve 20.30; mutfak her oturum için ayrı hazırlık yapar.","sektor":"Çok sayıda öğün sınırlı bir mutfakta ve denizde hazırlandığı için stok ve hijyen planı kesin olmak zorundadır. Karadaki yiyecek içecek deneyimi gemide en değerli deneyimlerden biridir.","iliskili":["go-5-024","go-5-025","go-5-036"],"kontrol":null,"kitapDisi":true},{"id":"go-5-030","konu":"5.2","terim":"İç kabin","ingilizce":"Inside cabin","tanim":"Dışarıya bakan bir pencere ya da balkonu olmayan, geminin iç bölümünde yer alan ve çoğunlukla en uygun fiyatlı olan kabin türüdür.","ornek":"Kabinde yalnız uyumak ve duş almak isteyen, günü güvertede ve gezilerde geçirecek genç bir çift iç kabini seçer.","sektor":"Fiyatı düşük tuttuğu için gemiye ilk kez binenler arasında yaygındır. Pencere olmadığı için bazı gemilerde duvardaki ekranlarla dışarıyı gösteren sistemler kullanılır.","iliskili":["go-5-031","go-5-032","go-5-033"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-gemi-ic-kabin"},{"id":"go-5-031","konu":"5.2","terim":"Deniz manzaralı kabin","ingilizce":"Ocean-view cabin","tanim":"Denize bakan sabit bir penceresi bulunan ama dışarı çıkılabilen balkonu olmayan kabin türüdür.","ornek":"Sabah uyanan konuk perdeyi açar ve geminin Kuşadası limanına yanaştığını yatağından görür.","sektor":"İç kabinden daha pahalı, balkonludan daha uygun fiyatlıdır. Doğal ışık verdiği için kabininde daha çok vakit geçirecek konuklar bu türü tercih eder.","iliskili":["go-5-030","go-5-032","go-5-034"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-deniz-manzarali-kabin"},{"id":"go-5-032","konu":"5.2","terim":"Balkonlu kabin","ingilizce":"Balcony cabin","tanim":"Dışarı açılan bir kapısı ve özel balkonu bulunan, konuğun kendi alanında açık havada oturabildiği kabin türüdür.","ornek":"Balayındaki bir çift sabah kahvesini kendi balkonunda içer; kabin servisi kahvaltıyı balkona getirir.","sektor":"Birçok yeni gemide balkonlu kabin sayısı yüksektir ve konuklar arasında ilgi görür. Balkon, kabini “benim özel odam” hissine yaklaştıran bir ayrıcalıktır.","iliskili":["go-5-031","go-5-033","go-5-027"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-balkonlu-kabin"},{"id":"go-5-033","konu":"5.2","terim":"Kruvaziyer süiti","ingilizce":"Cruise suite","tanim":"Normal kabinden daha geniş olan, ayrı oturma alanı bulunan ve çoğu zaman ek ayrıcalıklarla sunulan en üst kabin türüdür.","ornek":"Evlilik yıl dönümünü kutlayan bir aile süit ayırtır; odada karşılama meyvesi ve özel bir hoş geldiniz notu bulur.","sektor":"Süit konuklarına bazı hatlarda özel kabin görevlisi (butler), konsiyerj gibi ek hizmetler ve yalnız onlara açık bir restoran ya da salon sunulur; bu yüzden onlara sunulan hizmet standardı en yüksek tutulur.","iliskili":["go-5-030","go-5-032","go-5-027"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-gemi-suit-yatak-odasi"},{"id":"go-5-034","konu":"5.2","terim":"Liman günü ve deniz günü","ingilizce":"Port day and sea day","tanim":"Geminin limana yanaşıp konukların karaya çıkabildiği gün liman günü, gün boyu denizde seyredilen ve hiçbir limana uğranmayan gün ise deniz günüdür.","ornek":"Pazartesi Kuşadası’nda liman günüdür, konuklar Efes’e gider; salı gün boyu açık denizdedir ve gemi içi etkinlikler, havuz ve gösteriler yoğun geçer.","sektor":"Deniz gününde konuk gemiden çıkmadığı için yemek, eğlence ve hizmet talebi en yüksektir. Liman gününde gemi büyük ölçüde boşalır; kabinler temizlenir, ikmal yapılır. Çalışan iki günde de farklı tempoda çalışır.","iliskili":["go-5-035","go-5-039","go-5-028"],"kontrol":null,"kitapDisi":true},{"id":"go-5-035","konu":"5.2","terim":"Kıyı gezisi","ingilizce":"Shore excursion","tanim":"Liman gününde konukların gemiden inip rehberli tur ya da etkinlikle çevreyi gezdiği, çoğunlukla gemi şirketi aracılığıyla ayrıca satılan programdır.","ornek":"Antalya limanında gemiden inen grup otobüsle Kaleiçi’ne gider, rehberle gezer ve geminin kalkışından önce gemiye döner.","sektor":"Geminin kalkış saati kesindir: gemi şirketinin sattığı bir gezi geç dönerse gemi bekleyebilir, ama kendi başına gezen konuk için genellikle beklenmez. Bu yüzden rehber ve operasyon ekibi saatleri sıkı izler; kıyı gezileri limanın yerel turizmi için de gelir kaynağıdır.","iliskili":["go-5-034","go-5-039","go-5-026"],"kontrol":null,"kitapDisi":true,"cizim":"deniz-kumsal"},{"id":"go-5-036","konu":"5.2","terim":"Kruvaziyer ücretine dâhil olanlar","ingilizce":"What the cruise fare includes","tanim":"Gemi biletinin kabin, ana restoran yemekleri ve gösteriler gibi hizmetleri kapsadığı; özel restoran, içecek paketi, kıyı gezisi ve bahşiş gibi kalemlerin ise çoğu hatta ayrıca ücretlendirildiği fiyat mantığıdır.","ornek":"Bir hatta bilet fiyatına ana restoran yemekleri dâhildir; ama akşam özel restoranda yemek yemek isteyen konuk ayrıca ödeme yapar.","sektor":"Kruvaziyerde “her şey dâhil” anlayışı hatta göre değişir; bu yüzden neyin dâhil neyin ek olduğunu konuğa açıkça söylemek şikâyeti önler. İçecek paketi, gezi ve spa gibi ek satışlar geminin gelirinde önemli yer tutar.","iliskili":["go-5-029","go-5-035","go-5-026"],"kontrol":null,"kitapDisi":true},{"id":"go-5-037","konu":"5.2","terim":"Güvenlik tatbikatı (muster drill)","ingilizce":"Muster drill","tanim":"Acil durumda konukların cankurtaran yeleğini nasıl giyeceğini, nerede toplanacağını ve nasıl davranacağını gösteren, yolculuğun başında yapılan zorunlu güvenlik eğitimidir.","ornek":"Gemi İstanbul’dan ayrılmadan önce anons yapılır; bütün konuklar kendi toplanma noktalarına gider, görevliler yeleğin nasıl giyileceğini gösterir ve sayım yapar.","sektor":"Yolcu gemileri için bu tatbikat, deniz güvenliğine ilişkin uluslararası SOLAS sözleşmesinin gerektirdiği bir uygulamadır; yolcu güvenliğinde taviz verilmez ve tatbikata katılmayan konuğu görevliler katılmaya yönlendirir. Gemi çalışanları ise ayrıca düzenli yangın ve tahliye eğitimi alır; bu eğitim işin ayrılmaz parçasıdır.","iliskili":["go-5-038","go-5-025","go-5-027"],"kontrol":null,"kitapDisi":true},{"id":"go-5-038","konu":"5.2","terim":"Gemi personeli sözleşmesi ve çalışma düzeni","ingilizce":"Crew contract and working pattern","tanim":"Gemide çalışanların belirli aylar süren sözleşmeyle işe alındığı, bu sürede gemide kaldığı ve vardiyaların uzun, dinlenme saatlerinin sınırlı olduğu çalışma düzenidir.","ornek":"İzmir’den bir kruvaziyer şirketiyle sözleşme yapan genç bir garson, aylarca aynı gemide hafta sonu ve bayram dâhil her gün çalışır; sözleşmesi bitince eve döner.","sektor":"Kruvaziyer kariyeri yabancı dil, dünyayı görmek ve kısa sürede deneyim kazanmak açısından cazip olabilir; ama aileden uzak kalmayı, çok uzun vardiyaları ve ortak kullanılan dar kabini de içerir. Gemide çalışmanın yaş ve belge koşulları vardır; bu seçenek mezuniyetten sonra gündeme gelir. Karar vermeden önce sözleşmeyi ve çalışma saatlerini dikkatle okumak gerekir.","iliskili":["go-5-037","go-5-024","go-5-025"],"kontrol":null,"kitapDisi":true},{"id":"go-5-039","konu":"5.2","terim":"Türkiye’deki kruvaziyer limanları","ingilizce":"Cruise ports in Türkiye","tanim":"Dünya kruvaziyer gemilerinin Türkiye’de yanaştığı, İstanbul’daki Galataport, Kuşadası, Bodrum ve Antalya gibi limanlardır.","ornek":"Yunan adalarından gelen bir gemi sabah Kuşadası’na yanaşır; konuklar Efes’e gidip akşam gemiye döner ve gemi gece Bodrum’a geçer.","sektor":"Gemi konukları karaya çıkınca çevredeki rehber, restoran, çarşı ve oteli kullanır; bazı yolculuklar Türkiye’den başladığı için konuklar gemiye binmeden önce bir gece otelde de kalabilir. Kıyıdaki bir otelci kruvaziyer takvimini bilmelidir.","iliskili":["go-5-034","go-5-035","go-5-024"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-kusadasi-kruvaziyer-limani"},{"id":"go-5-040","konu":"5.3","terim":"Ekonomi sınıfı","ingilizce":"Economy class","tanim":"Uçakta en çok koltuğun bulunduğu, çoğu yolcunun bindiği ve fiyatı en uygun olan yolcu sınıfıdır.","ornek":"İstanbul–Antalya seferinde yolcuların çoğu ekonomi sınıfında oturur; küçük bir ikram verilir ve bagaj hakkı biletin türüne göre belirlenir.","sektor":"Kabin memuru için en kalabalık hizmet alanıdır; kısa sürede çok sayıda yolcuya nazik ve eşit davranmak gerekir. Otelde standart odaya benzer: temel ihtiyaçlar karşılanır, ek rahatlık ücret karşılığı sunulur.","iliskili":["go-5-041","go-5-042","go-5-045"],"kontrol":null,"kitapDisi":true,"gorsel":"sektor-ucak-kabini"},{"id":"go-5-041","konu":"5.3","terim":"Business sınıfı","ingilizce":"Business class","tanim":"Ekonomiden genellikle daha geniş koltuk, öncelikli işlem, özel yemek ve lounge gibi ayrıcalıklar sunan, daha pahalı yolcu sınıfıdır.","ornek":"Frankfurt’a iş gezisine çıkan bir yönetici business sınıfı biletle öncelikli check-in yapar, lounge’da toplantı hazırlığına bakar ve uçakta rahat bir koltukta dinlenir.","sektor":"Bu yolcular iş için sık seyahat ettiğinden zamanlarına ve rahatlıklarına önem verir. Otelde ayrıcalıklı odalarda ve üye konuk hizmetlerinde olduğu gibi hizmet standardı yüksek tutulur.","iliskili":["go-5-040","go-5-042","go-5-054"],"kontrol":null,"kitapDisi":true,"gorsel":"sektor-ucak-business"},{"id":"go-5-042","konu":"5.3","terim":"Birinci sınıf (first class)","ingilizce":"First class","tanim":"Hava yollarının sunduğu en üst sınıf olan, çoğu zaman çok geniş koltuk ya da küçük özel bölme, kişiye özel yemek ve ayrı karşılama hizmetleri bulunan sınıftır.","ornek":"Şanghay uçuşunda first class yolcusunu yer görevlisi adıyla karşılar, bagajını teslim alır ve doğrudan lounge’a götürür.","sektor":"Her hava yolu şirketinde bulunmaz; birçok şirket business sınıfını yeterince konforlu hâle getirdiği için first class sunmaz. Lüks otelde süit konuğuna verilen kişiye özel hizmete benzer bir hizmet anlayışı vardır.","iliskili":["go-5-040","go-5-041","go-5-054"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-first-class-koltuk"},{"id":"go-5-043","konu":"5.3","terim":"Biniş kartı","ingilizce":"Boarding pass","tanim":"Yolcunun adını, uçuş numarasını, kapı ve koltuk bilgisini gösteren, uçağa binmeden önce görevliye sunulan kâğıt ya da telefondaki belgedir.","ornek":"Sabah 06.15’te Sabiha Gökçen Havalimanı’nda yolcu telefondaki biniş kartının karekodunu okutur ve kapı görevlisi uçağa girişine izin verir.","sektor":"Kâğıt da olsa dijital de olsa aynı bilgiyi taşır. Otelde oda kartının konuğu odaya yönlendirmesi gibi, biniş kartı yolcuyu doğru kapıya ve koltuğa yönlendirir.","iliskili":["go-5-044","go-5-048","go-5-047"],"kontrol":null,"kitapDisi":true,"gorsel":"t13f-pasaport-biniskarti"},{"id":"go-5-044","konu":"5.3","terim":"Havalimanında check-in","ingilizce":"Airport check-in","tanim":"Yolcunun uçuş kaydının yapıldığı, bagajını teslim edip biniş kartını aldığı havalimanı işlemidir.","ornek":"Sabah 05.00’te İzmir’den uçacak yolcu kontuara gelir, kimliği kontrol edilir, bagajını bırakır ve biniş kartını alır.","sektor":"Birçok hava yolu kontuar yerine çevrim içi check-in ya da kiosk sunar; oteller de aynı mantıkla çevrim içi check-in ile resepsiyon kuyruğunu azaltır. Her iki yerde de amaç, kuyrukta bekleme süresini kısaltmaktır.","iliskili":["go-5-043","go-5-045","go-5-048"],"kontrol":null,"kitapDisi":true,"gorsel":"terminal"},{"id":"go-5-045","konu":"5.3","terim":"Bagaj hakkı ve kabin bagajı","ingilizce":"Baggage allowance and cabin baggage","tanim":"Bilet türüne göre yolcunun ücretsiz ya da ücretli getirebileceği bagaj miktarını ve yanında kabine alabileceği küçük çantayı belirleyen kurallardır.","ornek":"Ankara’dan Londra’ya bilet alan yolcu, ücretsiz bagaj hakkını biletinde görür; fazla bagaj için kontuarda ek ücret öder.","sektor":"Kurallar hava yoluna ve bilet türüne göre değişir, bu yüzden yolcuya önce biletindeki hakka bakmasını söylemek şikâyeti önler. Bell desk görevlisi, çıkış günü konuğun valizleri konusunda bu bilgiyi hatırlatabilir.","iliskili":["go-5-044","go-5-053","go-5-040"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-kabin-bagaji-etiketi"},{"id":"go-5-046","konu":"5.3","terim":"Kabin memuru","ingilizce":"Cabin crew","tanim":"Uçuş sırasında önce yolcuların güvenliğinden, sonra ikram ve rahatlığından sorumlu olan uçak ekibi üyesidir.","ornek":"Kalkıştan önce kabin memuru emniyet kemerini, oksijen maskesini ve acil çıkışları gösterir; uçuş sırasında içecek servisi yapar.","sektor":"Kabin memurunun asıl işi güvenliktir, servis ikinci plandadır. Otelcilikte öğrenilen konuk iletişimi bu mesleğe çok yakındır, ama acil durumda hızlı karar vermek için ayrıca eğitim gerekir.","iliskili":["go-5-047","go-5-048","go-5-040"],"kontrol":null,"kitapDisi":true,"cizim":"ucak"},{"id":"go-5-047","konu":"5.3","terim":"Yer hizmetleri","ingilizce":"Ground handling","tanim":"Uçak havalimanındayken yolcu, bagaj, yükleme, yakıt ikmali ve temizlik gibi işleri yerde yürüten ekiplerin yaptığı hizmetlerin tümüdür.","ornek":"Uçak İstanbul’a indiğinde yer hizmetleri bagajı boşaltır, kabinin temizlenmesi için ekibi yönlendirir ve yeni yolcuların bagajını yüklemeye hazırlanır.","sektor":"Uçağın zamanında kalkması yer hizmeti ekiplerinin uyumuna bağlıdır; tek bir bagajın geç gelmesi bile gecikme yaratabilir. Rampa ekibi uçağın etrafında, yolcu hizmetleri ekibi terminalde çalışır.","iliskili":["go-5-046","go-5-048","go-5-043"],"kontrol":null,"kitapDisi":true,"cizim":"ucak"},{"id":"go-5-048","konu":"5.3","terim":"Yolcu hizmetleri görevlisi","ingilizce":"Passenger service agent","tanim":"Kontuarda check-in yapan, kapıda biniş işlemlerini yürüten, yolcuların bilgi ve sorun taleplerini karşılayan havalimanı çalışanıdır.","ornek":"Kalkıştan bir süre önce kapıda anons yapan görevli yaşlı yolculara ve çocuklu ailelere öncelik verir, bir yolcunun koltuğunu değiştirir.","sektor":"Otelde resepsiyonistin havalimanındaki karşılığıdır: kuyruğu yönetir, gecikme ve iptallerde ilk şikâyeti dinleyen kişidir. Sakin kalmak, açık bir dille anlatmak ve yetkisini bilmek bu görevin özüdür.","iliskili":["go-5-044","go-5-051","go-5-047"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-check-in-sirasi"},{"id":"go-5-049","konu":"5.3","terim":"Kod paylaşımı","ingilizce":"Codeshare","tanim":"İki hava yolu şirketinin aynı uçuşu kendi uçuş numarasıyla satması ve yolcunun bilet aldığı şirketten farklı bir şirketin uçağında seyahat edebilmesidir.","ornek":"Yolcu Frankfurt–Antalya bileti alır; biletinde bir şirketin adı yazılıdır, ama uçağı onunla anlaşmalı başka bir şirket işletir.","sektor":"Hava yolları böylece kendi uçmadığı hatlara da bilet satabilir. Yolcu için kafa karıştırıcı olabilir: kontuar ve bazı kurallar uçağı işleten şirkete göre değişebilir. Çalışan, yolcuya biletindeki bilgilere bakmasını söyleyebilir.","iliskili":["go-5-050","go-5-052","go-5-044"],"kontrol":null,"kitapDisi":true},{"id":"go-5-050","konu":"5.3","terim":"Aktarmalı uçuş","ingilizce":"Connecting flight","tanim":"Yolcunun varış noktasına tek bir yolculuk planı içinde, bir ara havalimanında uçak değiştirerek ulaştığı uçuştur.","ornek":"Ankara’dan New York’a giden yolcu İstanbul’da uçak değiştirir; iki uçuş tek biletle alınmışsa bagaj çoğunlukla doğrudan son noktaya gider.","sektor":"Aktarma süresi kısaysa ilk uçak gecikince yolcu ikincisini kaçırabilir. Uzun aktarma bekleyen yolcular için bazı havalimanı ve hava yolları şehirde konaklama sunar; bu otel için bir fırsattır.","iliskili":["go-5-049","go-5-051","go-5-055"],"kontrol":null,"kitapDisi":true},{"id":"go-5-051","konu":"5.3","terim":"Uçuş gecikmesinde yolcu hakları","ingilizce":"Passenger rights in flight delays","tanim":"Uçak seferi uzun süre gecikince ya da iptal edilince yolcunun bilgi, ikram, yeniden yerleştirilme veya bilet iadesi isteyebileceği haklardır; ayrıntılı kurallar ülkeye ve uçuşa göre değişen düzenlemelere bağlıdır.","ornek":"Gece yarısı gecikmeli uçuşun yolcusu yer hizmetleri masasına başvurur; görevli haklarının bulunduğunu söyler ve şirketin uygulayacağı seçenekler için yetkiliye yönlendirir.","sektor":"Çalışanın bu kuralların ayrıntısını ezbere bilmesi gerekmez; yolcuya hakkı olduğunu söyler ve doğru kişiye yönlendirir. Gecikmeden dolayı gece geç gelen konuğa otelin esnek ve sıcak davranması büyük fark yaratır. Kesin bilgi için hava yolu şirketi ve ilgili resmî kurum esas alınır.","iliskili":["go-5-048","go-5-050","go-5-055"],"kontrol":null,"kitapDisi":true,"cizim":"ucak"},{"id":"go-5-052","konu":"5.3","terim":"Hava yolu ittifakı","ingilizce":"Airline alliance","tanim":"Birçok hava yolu şirketinin ortak bilet, bagaj aktarımı, lounge kullanımı ve sadakat puanı gibi konularda iş birliği yaptığı gruptur.","ornek":"Bir yolcu ittifaktaki üç ayrı şirketle seyahat eder; biletini tek şirketten alır, bagajı aktarılır ve puanlar tek hesapta toplanır.","sektor":"Dünyada başlıca üç büyük ittifak vardır: Star Alliance, SkyTeam ve oneworld. Yolcu için aktarma ve lounge kolaylığı demektir; sık uçan yolcu ittifak içinde puan biriktirerek ayrıcalık kazanır.","iliskili":["go-5-049","go-5-054","go-5-053"],"kontrol":null,"kitapDisi":true,"cizim":"ucak"},{"id":"go-5-053","konu":"5.3","terim":"Düşük maliyetli taşıyıcıda ek ücret modeli","ingilizce":"Unbundled fares on low-cost carriers","tanim":"Bilet fiyatına yalnız koltuğun dâhil edildiği; bagaj, yemek, koltuk seçimi gibi hizmetlerin ayrı ayrı ücretlendirildiği hava yolu fiyat yöntemidir.","ornek":"Düşük maliyetli bir şirketle İstanbul–Londra bileti ucuz görünür; yolcu bagaj ekleyip koltuk seçtikçe toplam fiyat artar.","sektor":"Yolcu ucuz bilet bulur, ama ek ücretleri öğrenince şaşırabilir; açık anlatım bu yüzden önemlidir. Otellerin de erken check-in gibi hizmetleri ayrı satması benzer bir mantıktır.","iliskili":["go-5-040","go-5-045","go-5-052"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"go-5-054","konu":"5.3","terim":"Havalimanı lounge","ingilizce":"Airport lounge","tanim":"Havalimanında yolcuların uçuş öncesi oturup dinlenebildiği, yiyecek içecek ve internet bulunan özel bekleme salonudur.","ornek":"Aktarma bekleyen business sınıfı yolcusu lounge’da hafif bir yemek yer, dizüstü bilgisayarıyla çalışır ve kapı açılınca ekrandan haber alır.","sektor":"Lounge küçük bir otel lobisi gibi çalışır: rahat koltuk, ikram ve sakin ortam. Girişi bilet sınıfına, üyeliğe ya da kart ayrıcalığına bağlıdır; havalimanı konukseverlik alanında otelcilik bilgisinin başka bir sahnesidir.","iliskili":["go-5-041","go-5-042","go-5-056"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-havalimani-lounge"},{"id":"go-5-055","konu":"5.3","terim":"Havalimanı transfer koordinasyonu","ingilizce":"Airport transfer coordination","tanim":"Gelen konuğun uçuş saatine göre havalimanından otele (ya da tersine) götürülmesi için aracın, şoförün ve zamanın planlanıp izlenmesidir.","ornek":"Uçuş İstanbul’a 14.10’da inecek; resepsiyon uçuş numarasından gecikmeyi izler, şoföre yeni saati bildirir ve konuğun adının yazılı olduğu tabelanın hazır olmasını sağlar.","sektor":"Uçuş saati değişirse transfer de değişir; bu yüzden konuğun uçuş numarasını önceden almak ve uçuşu izlemek gerekir. Konuğun otelle ilk teması çoğu zaman şoförle olur, bu yüzden bu iş ilk izlenimin parçasıdır.","iliskili":["go-5-050","go-5-056","go-5-051"],"kontrol":null,"kitapDisi":true},{"id":"go-5-056","konu":"5.3","terim":"Karşılama hizmeti (meet & greet)","ingilizce":"Meet and greet","tanim":"Konuğun havalimanında ya da limanda adıyla karşılanıp bagaj, kontrol ve araca binme işlemlerinde yardım edildiği kişiye özel karşılama hizmetidir.","ornek":"Gece 02.00’de İstanbul Havalimanı’nda adı yazılı tabelayı tutan görevli konuğu çıkışta karşılar, bagaj arabasını alır ve aracına götürür.","sektor":"Uzun yolculuktan yorgun gelen konuk için yabancı bir şehirde adının duyulması çok güven vericidir. Lüks otelcilikte ilk izlenim kapıdan değil, havalimanında başlayabilir.","iliskili":["go-5-054","go-5-055","go-5-043"],"kontrol":null,"kitapDisi":true},{"id":"go-5-057","konu":"5.4","terim":"Destinasyon yönetim örgütü (DMO)","ingilizce":"Destination management organisation (DMO)","tanim":"Bir şehrin ya da bölgenin turizmini tanıtan, planlayan ve işletmeleri bir araya getiren; genellikle belediye, dernek veya kamu kuruluşu yapısındaki örgüttür.","ornek":"Bir kıyı kentinin turizm derneği şehir adına fuara katılır, ortak tanıtım filmi hazırlar ve otellerle birlikte bir etkinlik takvimi yapar.","sektor":"Tek bir otel şehri tek başına tanıtamaz; DMO otelleri, restoranları ve rehberleri tek hikâyede toplar. Kongre ofisleri çoğu zaman DMO’nun bir parçasıdır ve büyük etkinlikleri şehre çekmek için çalışır.","iliskili":["go-5-019","go-5-058","go-5-059"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-turist-danisma-ofisi"},{"id":"go-5-058","konu":"5.4","terim":"Destinasyon markası","ingilizce":"Destination brand","tanim":"Bir yerin adı anıldığında ziyaretçinin zihninde oluşan imajın, vaadin ve duygunun bilinçli olarak tasarlanmış hâlidir.","ornek":"Kapadokya denince sıcak hava balonları, peribacaları ve taş oteller akla gelir; bölgenin tanıtım malzemeleri bu imajı tutarlı kullanır.","sektor":"Marka çalışması logo ve sloganla bitmez; ziyaretçinin şehir boyunca yaşayacağı tutarlı deneyimdir. Otel çalışanı da bu hikâyenin parçasıdır: şehrin vaadini yerine getirir ya da bozar.","iliskili":["go-5-057","go-5-059","go-5-060"],"kontrol":null,"kitapDisi":true,"gorsel":"tr-balon"},{"id":"go-5-059","konu":"5.4","terim":"Türkiye’nin destinasyon markası","ingilizce":"Destination brand of Türkiye","tanim":"Ülkenin turizm tanıtımında deniz ve kumu, tarihi, kültürü, gastronomiyi ve doğayı bir arada öne çıkaran ortak anlatısı ve imajıdır.","ornek":"Yurt dışındaki bir fuarda Türkiye standında hem Antalya kıyısı hem Kapadokya hem de Gaziantep mutfağı tanıtılır; mesaj, tek ülkede birçok farklı tatil seçeneği olur.","sektor":"Ülke markasının altında şehirlerin ve bölgelerin kendi markaları da bulunur. Son yıllarda ülke adı uluslararası alanda “Türkiye” yazımıyla kullanılmaktadır; yabancı konukla konuşan çalışanın bunu bilmesi faydalıdır.","iliskili":["go-5-058","go-5-057","go-5-062"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"go-5-060","konu":"5.4","terim":"Deneyim turizmi","ingilizce":"Experiential tourism","tanim":"Ziyaretçinin yalnız gezip görmekle kalmayıp yerel yaşamın içinde bir şey yaparak, deneyerek ve öğrenerek katıldığı turizm anlayışıdır.","ornek":"Kapadokya’daki bir otel konuklarına sabah çömlek atölyesi, akşam yöresel yemek yapma dersi sunar.","sektor":"Konuklar artık “ne gördüm” yerine “ne yaşadım” diye anlatıyor; deneyimi tasarlayan otel yorumlarda öne çıkar. Atölyeler otele ek gelir getirir ve yerel halka iş sağlar.","iliskili":["go-5-061","go-5-062","go-5-064"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-comlek-carki"},{"id":"go-5-061","konu":"5.4","terim":"Destinasyonda yerel rehber","ingilizce":"Local guide","tanim":"Gezilen yerde yaşayan, oranın tarihini, hikâyelerini ve gizli köşelerini bilen, ziyaretçiyi o yerin gözüyle gezdiren rehberdir.","ornek":"Mardin’de yetişmiş bir rehber konukları çarşıda gezdirir, ustalarla tanıştırır ve geleneksel bir evde çay ikram ettirir.","sektor":"Yerel rehber, destinasyonun hikâyesini kitaplardan çok yaşayarak anlattığı için deneyimi güçlendirir. Türkiye’de rehberlik için yasal belge gerekir; otel de konuğa belgeli rehberleri önermelidir.","iliskili":["go-5-060","go-5-062","go-5-063"],"kontrol":null,"kitapDisi":true,"cizim":"acente"},{"id":"go-5-062","konu":"5.4","terim":"Gastronomi rotası","ingilizce":"Gastronomy route","tanim":"Bir yörenin yemeklerini, ustalarını, pazarlarını ve üretim yerlerini sıraya koyarak ziyaretçiyi lezzet merkezli gezdiren rotadır.","ornek":"Gaziantep’te konuklar sabah beyran çorbası, öğle baklava atölyesi ve akşam yöresel restoran sırasını izler.","sektor":"Yemek, bir destinasyonun en kolay anlatılan hikâyesidir; otelin şefi yöre ürünlerini kullanarak rotanın parçası olabilir. Gaziantep’in UNESCO Yaratıcı Şehirler Ağı’na gastronomi şehri olarak alınması bu alanda bilinen bir örnektir.","iliskili":["go-5-060","go-5-063","go-5-059"],"kontrol":null,"kitapDisi":true,"cizim":"gastronomi"},{"id":"go-5-063","konu":"5.4","terim":"Kültür rotası","ingilizce":"Cultural route","tanim":"Aynı temayla bağlantılı tarihî ve kültürel yerleri sıralayan, ziyaretçiye birkaç yeri tek bir hikâye gibi gezdiren yol ya da programdır.","ornek":"Ege kıyısındaki antik kentleri sırayla gezdiren üç günlük rotada konuk her gece başka bir şehirde, başka bir otelde kalır.","sektor":"Rota birçok yeri birbirine bağladığı için konuk tek bir yerde değil, rota boyunca birden fazla otelde kalır; böylece gelir yöreye yayılır. Oteller rotaya uygun ortak paketler hazırlayabilir.","iliskili":["go-5-061","go-5-062","go-5-064"],"kontrol":null,"kitapDisi":true},{"id":"go-5-064","konu":"5.4","terim":"Yavaş turizm","ingilizce":"Slow tourism","tanim":"Ziyaretçinin acele etmeden, daha az yer gezip her yerde daha uzun kalarak yerel hayatı ve doğayı hissettiği, çevreye daha az yük bindiren turizm anlayışıdır.","ornek":"Fethiye’den başlayan bir yürüyüş rotasında konuk günde birkaç saat yürür, köy pansiyonlarında kalır ve yöresel kahvaltı yapar.","sektor":"Hızlı program yerine uzun kalış, yörede daha çok harcama ve daha az taşıma yükü getirir. Otel için konuk başına gelir artar, destinasyon için ise kalabalık dağılır.","iliskili":["go-5-060","go-5-063","go-5-067"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-yuruyus-patikasi"},{"id":"go-5-065","konu":"5.4","terim":"Gece ekonomisi","ingilizce":"Night-time economy","tanim":"Akşamdan sabaha kadar restoran, bar, konser, gece pazarı ve geceleri açık müze gibi etkinliklerin sağladığı iş ve gelirin tümüdür.","ornek":"İstanbul’da yaz akşamı konuklar Boğaz kıyısında yemek yer, müzik dinler ve açık kalan bir müzeyi gezer; oteldeki odada oturmak yerine şehre çıkarlar.","sektor":"Gün boyu gezen konuk akşam nerede vakit geçireceğini bilmezse otelde kalır; gece programı kalış süresini ve harcamayı artırır. Güvenlik, ulaşım ve gürültü yönetimi gece ekonomisinin başlıca konularıdır.","iliskili":["go-5-064","go-5-066","go-5-068"],"kontrol":null,"kitapDisi":true,"gorsel":"t14f-gece-pazari"},{"id":"go-5-066","konu":"5.4","terim":"Sezon dışı stratejisi","ingilizce":"Off-season strategy","tanim":"Yaz gibi yoğun mevsimin dışında konuk getirmek için fiyat, program ve ürün planlamasıyla doluluğu yıla yaymaya çalışma yöntemidir.","ornek":"Bodrum’daki bir otel kışın yoga haftaları ve gastronomi hafta sonları düzenler; konuk sayısı az olsa da oteli açık tutar.","sektor":"Mevsimlik işletmede çalışan kışın işsiz kalabilir; sezon dışı programlar çalışanı yıl boyu tutmaya yardımcı olur. Tek çözüm fiyatı indirmek değildir; o mevsime özel bir deneyim sunmak daha değerlidir.","iliskili":["go-5-065","go-5-067","go-5-060"],"kontrol":null,"kitapDisi":true},{"id":"go-5-067","konu":"5.4","terim":"Destinasyonun taşıma kapasitesi","ingilizce":"Destination carrying capacity","tanim":"Bir yerin doğasına, kültürüne ve halkın yaşamına zarar vermeden, ziyaretçinin memnuniyetini de düşürmeden ağırlayabileceği ziyaretçi sınırıdır.","ornek":"Tarihî bir ilçede yaz hafta sonlarında sokaklara sığılmaz, yerel halk markette kuyruk bekler; bu, belediyeyi saat ya da bilet sınırı düşünmeye iter.","sektor":"Sınır aşılınca ziyaretçi memnuniyetsiz, halk rahatsız olur ve yerin çekiciliği azalır. Bu yüzden DMO’lar ziyaretçileri farklı zamanlara ve bölgelere yaymaya çalışır; otel çalışanı da konuğu daha sakin yerlere yönlendirerek yardımcı olabilir.","iliskili":["go-5-057","go-5-064","go-5-068"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-petra-turist-kalabaligi"},{"id":"go-5-068","konu":"5.4","terim":"Ziyaretçi memnuniyeti","ingilizce":"Visitor satisfaction","tanim":"Ziyaretçinin gezi boyunca otel, ulaşım, yeme içme, güvenlik ve yerel halkla bütün temaslardan memnun kalma düzeyidir.","ornek":"Dönüşte havalimanında şehir ofisinin yaptığı kısa ankette konuk otelden memnun, ama taksilerden şikâyetçidir; sonuç belediyeye iletilir.","sektor":"Otel puanı memnuniyetin yalnız bir parçasıdır: kötü bir taksi yolculuğu da yerin geneline yazılabilir. Bu yüzden destinasyonlar yalnız otel değil, tüm gezi deneyimi için anket yapar ve sonuçları işletmelerle paylaşır.","iliskili":["go-5-067","go-5-065","go-5-057"],"kontrol":null,"kitapDisi":true}],"sorular":[{"id":"go-5-s01","tur":"coktan-secmeli","soru":"Bir ilaç şirketi, yıllık satış hedefini aşan bayilerini üç gün Bodrum’da ağırlıyor; programda tekne gezisi ve kapanış gala yemeği var. MICE’ın hangi koluna girer?","secenekler":["Ticari fuar","Konferans ve kongre","Teşvik gezisi programı","Toplantı"],"dogru":2,"aciklama":"Hedefi aşanları ödüllendirmek için düzenlenen gezi ve yemekli program teşvik (incentive) koludur. Konferans ve kongre bilgi paylaşımı için, fuar ise stantlarda ürün sergilemek için yapılır."},{"id":"go-5-s02","tur":"coktan-secmeli","soru":"Tek günlük bir şirket toplantısına göre üç günlük bir tıp kongresi otel için neden daha değerlidir?","secenekler":["Katılımcılar salonla birlikte oda ve yemeği de günlerce kullanır","Kongre katılımcıları salonu kullanır ama yemeklerini dışarıda yer","Kongre için salon kirası alınmadığından otel daha az masraf eder","Katılımcılar yalnız açılış gününde otelde bulunur"],"dogru":0,"aciklama":"Kongrenin gelirini salon kadar konaklama ve yiyecek içecek de oluşturur. Salon kirasının alınmaması ya da katılımcıların otelden uzak durması kongrenin özelliği değildir."},{"id":"go-5-s03","tur":"coktan-secmeli","soru":"Otelde iki günlük bir yangın eğitimi yapılacak ve katılımcılar not tutacak. Salon için en uygun düzen hangisidir?","secenekler":["Tiyatro düzeni","Banket düzeni","Kokteyl düzeni","Sınıf düzeni"],"dogru":3,"aciklama":"Sınıf düzeninde sahneye dönük sıralarda dar masalar bulunur, not tutmak kolaydır. Tiyatro düzeninde masa olmadığı için uzun süre not tutmak zorlaşır."},{"id":"go-5-s04","tur":"coktan-secmeli","soru":"Cumartesi günkü düğünde mutfak menüyü, teknik ekip ışık ve müziği, güvenlik de giriş düzenini aynı belgeden okusun isteniyor. Bu iş için hangi belge hazırlanır?","secenekler":["Etkinlik akış çizelgesi (run of show)","Etkinlik sipariş formu (BEO)","Garanti sayısı bildirimi","Kayıt masası listesi"],"dogru":1,"aciklama":"BEO etkinliğin salon, düzen, menü, saat ve teknik ihtiyaçlarını tek belgede toplayıp departmanlara dağıtır. Akış çizelgesi yalnız saat sırasını gösterir, menü ve düzen bilgisini taşımaz."},{"id":"go-5-s05","tur":"dogru-yanlis","soru":"Garanti sayısı bildirildiğinde otel hazırlığı o sayıya göre yapar ve daha az kişi gelse bile çoğunlukla garanti edilen sayı üzerinden ücret kesilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Mutfak ve servis garanti sayısına göre hazırlandığı için eksik gelenlerin yemeği de hazırlanmış olur; bu yüzden kural sözleşmede yazılıdır ve müşteriyle baştan konuşulur."},{"id":"go-5-s06","tur":"coktan-secmeli","soru":"Bir tıp derneği kongresinin kayıt, program, bildiri ve sponsor işlerini baştan sona yürütmesi için hangi uzman firmayla çalışır?","secenekler":["Destinasyon yönetim örgütü (DMO)","Banket satış yöneticisi","Destinasyon yönetim şirketi (DMC)","Profesyonel kongre organizatörü (PCO)"],"dogru":3,"aciklama":"PCO bir derneğin kongresini mekân seçiminden sponsora kadar organize eden firmadır. DMO bölgenin tanıtımını yapar, DMC ise gelen gruba yerinde program kurar; kongrenin bütün idaresini üstlenmez."},{"id":"go-5-s07","tur":"coktan-secmeli","soru":"Almanya’dan gelen bir şirketin ödül grubu için Kapadokya’da otel, balon turu ve akşam yemeğini ayarlayacak yerel şirket hangisidir?","secenekler":["Destinasyon yönetim şirketi (DMC)","Profesyonel kongre organizatörü (PCO)","Destinasyon yönetim örgütü (DMO)","Etkinlik yöneticisi"],"dogru":0,"aciklama":"DMC yerin otelini, ulaşımını, rehberini ve restoranını bilir; dışarıdan gelen grubun programını yerinde kurar. PCO dernek kongrelerini, DMO ise bölgenin tanıtımını yürütür."},{"id":"go-5-s08","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi hibrit etkinliği doğru anlatır?","secenekler":["Etkinlik aynı anda iki farklı otelin salonunda yapılır","Etkinlik yalnız internette yapılır, salon kullanılmaz","Katılımcıların bir kısmı salonda, bir kısmı canlı yayında olur","Aynı salon gün içinde iki farklı oturma düzeniyle kullanılır"],"dogru":2,"aciklama":"Hibrit etkinlik yüz yüze ve çevrim içi katılımı bir arada yürütür. Yalnız internetten yapılan etkinlik sanal etkinliktir; iki mekân ya da iki düzen hibrit sayılmaz."},{"id":"go-5-s09","tur":"coktan-secmeli","soru":"Kruvaziyer gemisinde seyir ve makine işleri dışında kalan; kabin, yemek, eğlence ve konuk hizmetlerini yürüten bölümün genel adı nedir?","secenekler":["Güverte (seyir) bölümü","Otel bölümü","Makine bölümü","Güvenlik bölümü"],"dogru":1,"aciklama":"Konuklara hizmet veren bu bölüm karadaki otele benzediği için gemide otel bölümü diye anılır. Güverte seyri, makine bölümü gemiyi çalışır tutmayı, güvenlik bölümü acil durumları yönetir."},{"id":"go-5-s10","tur":"coktan-secmeli","soru":"Genç bir çift kabinde yalnız uyuyup duş alacak, gününü güvertede ve gezilerde geçirecek ve en uygun fiyatı arıyor. Hangi kabini seçmeleri mantıklıdır?","secenekler":["İç kabin","Deniz manzaralı kabin","Balkonlu kabin","Kruvaziyer süiti"],"dogru":0,"aciklama":"İç kabinin penceresi yoktur ve çoğunlukla en uygun fiyatlıdır; kabinde az zaman geçirecekler için yeterlidir. Deniz manzaralı ve balkonlu kabin pencere ya da balkon için ek ücret ister."},{"id":"go-5-s11","tur":"dogru-yanlis","soru":"Deniz günü, geminin limana yanaşıp konukların karaya çıkabildiği gündür.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Gemi limana yanaştığında konuklar karaya çıkar; bu güne liman günü denir. Deniz günü, gün boyu açık denizde seyredilen ve hiçbir limana uğranmayan gündür."},{"id":"go-5-s12","tur":"coktan-secmeli","soru":"Kruvaziyerde güvenlik tatbikatı neden gemi yola çıkmadan ya da yolculuğun başında yapılır?","secenekler":["Konuklar kabinlerini ve restoranlarını kolayca bulsun diye","Kıyı gezilerinin kayıtları gemi kalkmadan tamamlansın diye","Yemek oturumlarına yerleştirme düzeni belirlensin diye","Herkes acil durumda ne yapacağını baştan öğrensin diye"],"dogru":3,"aciklama":"Acil durumda yeleğin giyilmesi ve toplanma noktası önceden öğrenilirse panik azalır. Kabin ve restoran bilgisi güvenlik tatbikatının konusu değildir."},{"id":"go-5-s13","tur":"coktan-secmeli","soru":"Bir konuk kruvaziyerde ana restoranda yemek yedi ve akşam özel bir restoranda da yemek istiyor. Çoğu hatta bu durumda ne olur?","secenekler":["Her iki restoran da biletin içinde olduğu için ek ücret alınmaz","Ana restoran yemekleri ücretlidir, özel restoran bilete dâhildir","Özel restoran, bilet fiyatına dâhil olmadığı için ayrıca ücretlendirilir","Özel restoran yalnız süit konuklarına açıktır ve ücretsizdir"],"dogru":2,"aciklama":"Çoğu hatta bilet kabini, ana restoranı ve gösterileri kapsar; özel restoran, içecek paketi ve kıyı gezisi ayrı ücretlidir. Süit konuklarına bazı ayrıcalıklar verilebilir ama bu her hat için geçerli bir kural değildir."},{"id":"go-5-s14","tur":"coktan-secmeli","soru":"Bir garson kruvaziyer şirketiyle sözleşme yaptı. Karadaki bir otelde çalışmaya göre onu ne bekler?","secenekler":["Sabit mesai bitince her akşam eve dönmek","Aylarca gemide kalmak ve uzun vardiyalarda sınırlı dinlenmek","Sezon boyunca vardiyasız ve serbest saatlerle çalışmak","Yalnız hafta içi çalışıp hafta sonlarını izinli geçirmek"],"dogru":1,"aciklama":"Gemi personeli belirli aylık sözleşmeyle çalışır, bu sürede gemide yaşar ve hafta sonu ile bayramlarda da vardiyaya girer. Her akşam eve dönmek ya da sabit hafta içi mesai kara işlerine özgüdür."},{"id":"go-5-s15","tur":"coktan-secmeli","soru":"Bir yönetici Frankfurt’a iş gezisine business sınıfı biletle gidiyor. Ekonomi sınıfına göre onu ne farklılaştırır?","secenekler":["Uçakta en çok koltuğun bulunduğu bölümde oturması","Biletinin ekonomiden daha ucuz olması","Yalnız kabin bagajı hakkının bulunması","Öncelikli check-in ve lounge kullanımı"],"dogru":3,"aciklama":"Business sınıfı daha pahalıdır ve öncelikli işlem, lounge ve geniş koltuk sunar. En çok koltuk ve en uygun fiyat ekonomi sınıfının özelliğidir."},{"id":"go-5-s16","tur":"dogru-yanlis","soru":"Kabin memuru uçuşta yalnız ikram dağıtır; yolcu güvenliği ve acil durum sorumluluğu kokpit ekibine aittir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kabin memuru önce yolcuların güvenliğinden ve acil durum işlemlerinden sorumludur; ikram ve rahatlık bunun ardından gelir. Güvenlik sorumluluğu yalnız kokpit ekibinde değildir."},{"id":"go-5-s17","tur":"coktan-secmeli","soru":"Bir yolcu bir şirketten bilet aldı ama uçağı anlaşmalı başka bir şirket işletiyor; iki şirket de aynı uçuşu kendi uçuş numarasıyla satıyor. Bu uygulamanın adı nedir?","secenekler":["Kod paylaşımı","Aktarmalı uçuş","Hava yolu ittifakı","Düşük maliyetli taşıyıcı modeli"],"dogru":0,"aciklama":"Kod paylaşımında aynı uçuş iki şirketin numarasıyla satılır. Aktarmalı uçuşta yolcu ara havalimanında uçak değiştirir; ittifak ise birçok şirketin daha geniş çaplı iş birliğidir."},{"id":"go-5-s18","tur":"coktan-secmeli","soru":"Bir yolcu üç ayrı hava yolu şirketiyle seyahat ediyor; bagajı aktarılıyor, lounge’ları kullanıyor ve puanlarını tek hesapta topluyor. Bu iş birliğinin adı nedir?","secenekler":["Kod paylaşımı","Hava yolu ittifakı","Yer hizmetleri anlaşması","Ek ücret modeli"],"dogru":1,"aciklama":"İttifak, birçok şirketin ortak bilet, bagaj aktarımı, lounge ve sadakat puanı gibi konularda iş birliğidir. Kod paylaşımı tek bir uçuşun iki şirketin numarasıyla satılmasıdır, bu kadar geniş kapsamlı değildir."},{"id":"go-5-s19","tur":"coktan-secmeli","soru":"Konuğun uçuşu 14.10’da inecekken uçuş gecikmeli görünüyor. Otel resepsiyonunun en doğru adımı hangisidir?","secenekler":["Şoförü planlanan saatte gönderip konuk gelene dek beklemesini istemek","Transferi iptal edip konuğun yeniden aramasını beklemek","Uçuşu numarasından izleyip şoföre yeni iniş saatini bildirmek","Konuğa kendi taksisini bulmasını söylemek"],"dogru":2,"aciklama":"Transfer koordinasyonu uçuşun izlenmesini ve şoförün yeni saate göre yönlendirilmesini içerir. Şoförü boşuna bekletmek zaman kaybettirir, transferi iptal etmek ise hizmeti bırakmaktır."},{"id":"go-5-s20","tur":"dogru-yanlis","soru":"Meet & greet hizmetinde konuk havalimanında ya da limanda adıyla karşılanır ve bagaj ile araca binme işlemlerinde yardım görür.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Meet & greet kişiye özel karşılama hizmetidir: tabelayla adı yazılı bir görevli konuğu çıkışta karşılar ve aracına götürür. Konuğu kendi başına bırakmak bu hizmetin tersidir."},{"id":"go-5-s21","tur":"coktan-secmeli","soru":"Bir kıyı kentinin turizm derneği şehir adına fuara katılıyor, ortak tanıtım filmi hazırlıyor ve otellerle etkinlik takvimi yapıyor. Bu kuruluş hangisidir?","secenekler":["Destinasyon yönetim şirketi (DMC)","Profesyonel kongre organizatörü (PCO)","Seyahat acentesi","Destinasyon yönetim örgütü (DMO)"],"dogru":3,"aciklama":"DMO bir yerin turizmini tanıtan ve işletmeleri bir araya getiren örgüttür. DMC gelen gruba yerinde program kurar; satış ve bilet işi yapan acente ise tanıtımı yürütmez."},{"id":"go-5-s22","tur":"coktan-secmeli","soru":"Tarihî bir ilçede yaz hafta sonlarında sokaklara sığılmıyor ve yerel halk markette kuyruk bekliyor. Bu durum hangi kavramın aşıldığını gösterir?","secenekler":["Ziyaretçi memnuniyeti","Gece ekonomisi","Sezon dışı stratejisi","Destinasyonun taşıma kapasitesi"],"dogru":3,"aciklama":"Bir yerin halkın yaşamına ve doğasına zarar vermeden ağırlayabileceği ziyaretçi sayısına taşıma kapasitesi denir; burada bu sınır aşılmıştır. Memnuniyet bunun sonucu olabilir ama durumu tanımlayan kavram kapasitedir."},{"id":"go-5-s23","tur":"senaryo","durum":"Perşembe 15.00, otelin banket ofisinde stajyersin. Cumartesi günkü düğün için müşteri aradı ve ana yemeği son dakikada değiştirmek istiyor. Banket satış yöneticisi toplantıda, mutfak ise bu değişikliği bilmiyor.","soru":"Ne yaparsın?","secenekler":["Müşteriye değişikliği kabul ettiğimi söyler, mutfağa sözlü haber veririm.","Menü değişikliğini kendim BEO’ya işler ve hemen bütün departmanlara gönderirim.","Değişikliği yazıya geçirip yöneticiye iletir, BEO’nun güncellenmesini takip ederim.","Müşteriye bu aşamada menü değişikliğinin mümkün olmadığını söyleyip görüşmeyi bitiririm."],"dogru":2,"aciklama":"Menü değişikliği yetkili kişinin onayıyla BEO’ya işlenmeli ve bütün departmanlara aynı belgeyle ulaşmalıdır. Sözlü haber unutulabilir, BEO’yu kendi başına değiştirmek yetki aşımıdır."},{"id":"go-5-s24","tur":"senaryo","durum":"Cuma 17.00, balo salonunda gala yemeği hazırlığındasın. Müşteri garanti sayısını dün 180 olarak bildirmişti; şimdi telefonda “yirmi kişi daha geliyor” diyor. Masalar ve yemek 180 kişiye göre hazırlanmış.","soru":"İlk adımın ne olur?","secenekler":["Talebi yöneticiye iletir, mutfak ve servisin yetişip yetişemeyeceğini kontrol ettiririm.","Müşteriye sorun olmadığını söyler, yirmi kişilik ek masaları hemen salona koydururum.","Garanti sayısının kesin olduğunu ve değişmeyeceğini söyleyip görüşmeyi nazikçe bitiririm.","Ek masaları önceden kurdurur, mutfağa ve servise gece vardiyasında haber veririm."],"dogru":0,"aciklama":"Garanti sayısı değişince önce mutfak ve servisin yetişip yetişemeyeceği öğrenilmeli, kararı yetkili vermelidir. Kesin söz vermek ya da talebi tümden reddetmek kontrolsüz kalır."},{"id":"go-5-s25","tur":"senaryo","durum":"Sabah 08.15, kongre salonunun girişindeki kayıt masasında stajyersin. Kuyruk uzuyor; bir katılımcının yaka kartında adı yanlış basılmış ve katılımcı bundan rahatsız.","soru":"Ne yaparsın?","secenekler":["Hatalı kartı kongre boyunca takmasını, kongre bitince yenisiyle değiştireceğimizi söylerim.","Katılımcıya kalem uzatıp kartı kendisinin düzeltmesini rica eder, sıradakine geçerim.","Hatayı kartı basan ekibe bildirir ve katılımcıyı onlara yönlendiririm.","Özür diler, doğru kartı hemen hazırlatır, kuyruktakilere kısa bir bekleme olacağını söylerim."],"dogru":3,"aciklama":"Kayıt masası ilk karşılama noktasıdır; hatayı sahiplenip hızla düzeltmek güveni korur. Hatalı kartı bırakmak ya da işi başkasına atmak katılımcıyı hoşnutsuz bırakır ve bekletir."},{"id":"go-5-s26","tur":"senaryo","durum":"Gemi İstanbul’dan ayrılmadan önce, kabin görevlisi stajyeri olarak koridordasın. Güvenlik tatbikatı anonsu verildi; bir konuk “Yorgunum, yeleği giymem, odada kalıyorum” diyor.","soru":"Ne yaparsın?","secenekler":["Konuk yorgun olduğu için kabininde kalmasına izin verir, sayımda eksik çıkarsa ilgilenirim.","Tatbikatın zorunlu olduğunu nazikçe anlatır, toplanma noktasına yönlendiririm; kabul etmezse amire bildiririm.","Konuğu tartışmaya girmeden bırakır, tatbikat için diğer kabinlere geçerim.","Tatbikat bitince yeleği kabinine götürüp konuğa tek tek kullanımını anlatırım."],"dogru":1,"aciklama":"Tatbikat gemideki herkes için zorunludur ve sayım toplanma noktasında yapılır. Katılmayan konuk acil durumda risk altındadır; bu yüzden ikna edilir, olmazsa amire bildirilir."},{"id":"go-5-s27","tur":"senaryo","durum":"Kuşadası’nda liman günü. Misafir hizmetleri masasında stajyersin; geminin kalkışına bir saat kaldı ve kendi başına gezen bir konuk hâlâ gemiye dönmedi. Konuğun telefon numarası sistemde kayıtlı.","soru":"İlk adımın ne olur?","secenekler":["Kayıtlı numarayı arar, açılmazsa kalkış saatine kadar beklerim.","Gemiyi bekletmesi için doğrudan kaptana başvururum.","Amirime hemen haber verir, kayıtlı numaradan konuğa ulaşma işini onunla birlikte yürütürüm.","Konuğun gemiyi kaçırdığını varsayıp kabinini boşaltmak için kat ekibine haber veririm."],"dogru":2,"aciklama":"Kalkış saati sınırlı olduğundan durum hemen amire bildirilir ve konuğa birlikte ulaşılmaya çalışılır. Kaptana kendi başına gitmek yetki aşımı, kabini erken boşaltmak ise erken varsayımdır."},{"id":"go-5-s28","tur":"senaryo","durum":"Gece 23.00, havalimanında yolcu hizmetleri masasında stajyersin. İstanbul uçuşu üç saattir gecikmeli ve kızgın bir yolcu “Haklarım neymiş, bana bir şey söyleyen yok” diyor.","soru":"Ne yaparsın?","secenekler":["Haklarının bulunduğunu, ayrıntıların uçuşa ve ülkeye göre değiştiğini söyler, yetkiliye yönlendiririm.","Yolcuya gecikmede hiçbir hakkı bulunmadığını söyleyip sakince beklemesini rica ederim.","Aklımdaki bir kuralı kesin bilgi gibi anlatır, ücret iadesi yapılacağını söylerim.","Yolcuyu bilgi vermeden başka bir kontuara yönlendirir, işlemi bitmiş sayarım."],"dogru":0,"aciklama":"Yolcu hakları ülkeye ve uçuşa göre değişir; stajyer kesin vaatte bulunmaz, doğru bilgiyi verecek yetkiliye yönlendirir. Hakkı yok demek yanlış bilgi, kesin vaat yetki aşımıdır."},{"id":"go-5-s29","tur":"senaryo","durum":"Gece 01.00, İstanbul’daki otelin resepsiyonunda stajyersin. Havalimanına yeni inmiş bir konuk telefonla arıyor: çıkışta şoförü göremiyor ve yorgun. Transfer işini yürüten ekip seninle birlikte çalışıyor.","soru":"Ne yaparsın?","secenekler":["Konuğa taksi tutmasını, ücretini otelin sonradan ödeyeceğini söylerim.","Şoförün birazdan geleceğini söyleyip telefonu kapatır, konuğun yeniden aramasını isterim.","Konuğu başka bir çıkışa yönlendirir, şoföre haber vermeden işi tamamlanmış sayarım.","Konuğun yerini sorar, şoförü arar ve ikisi buluşana dek konukla iletişimde kalırım."],"dogru":3,"aciklama":"Transfer, konuk şoförle buluşana dek sürer; konuğun yerini öğrenip şoföre ulaşmak ve konuğu yalnız bırakmamak ilk izlenimi korur. Ödeme vaadi yetkiyi aşar, belirsiz söz konuğu bekletir."},{"id":"go-5-s30","tur":"senaryo","durum":"Hafta sonu öğleden sonra, tarihî bir ilçedeki otelin lobisinde stajyersin. Sokaklar çok kalabalık ve bir konuk “Her yer dolu, bunaldım” diyor; yarın da ilçede kalacak.","soru":"Ne yaparsın?","secenekler":["Kalabalığın her hafta sonu böyle olduğunu, yapılacak bir şey bulunmadığını söylerim.","Daha sakin saatleri ve yerleri önerir, gerekirse amirimden bilgi alırım.","Konuğa hafta sonları bu ilçeye gelmemesini öneririm.","Kalabalığın otelin değil belediyenin sorunu olduğunu söylerim."],"dogru":1,"aciklama":"Ziyaretçi yoğunluğunun yüksek olduğu yerlerde sakin saat ve yerleri önermek konuğun memnuniyetini ve destinasyonun dengesini korur. Kalabalığı kaçınılmaz saymak ya da sorumluluğu başkasına atmak çözüm sunmaz."},{"id":"go-5-s31","tur":"coktan-secmeli","soru":"Otelin terasında yeni bir markanın tanıtımı yapılacak. Konukların ayakta dolaşıp birbiriyle tanışması, garsonların da tepsiyle küçük lokmalar dolaştırması isteniyor. Salon hangi düzende hazırlanır?","secenekler":["Banket düzeni","Kokteyl düzeni","Sınıf düzeni","U düzeni"],"dogru":1,"aciklama":"Kokteyl düzeninde konuklar ayakta dolaşır, ikram tepsiyle yapılır ve çok az masa bulunur; tanışma ve açılışlar için seçilir. Banket düzeninde ise konuklar yuvarlak masalarda oturup yemek yer."},{"id":"go-5-s32","tur":"coktan-secmeli","soru":"Belediye, yüzlerce kişinin yalnız konuşmacıyı dinleyeceği kısa bir tanıtım toplantısı yapacak ve salona olabildiğince çok kişi oturtmak istiyor. Hangi düzen seçilir?","secenekler":["Sınıf düzeni","Banket düzeni","U düzeni","Tiyatro düzeni"],"dogru":3,"aciklama":"Tiyatro düzeninde masa olmadan sahneye dönük sıralar kurulur; oturma düzenleri arasında salona en çok kişiyi bu düzen sığdırır. Sınıf düzeninde masalar yer kapladığı için daha az kişi oturur."},{"id":"go-5-s33","tur":"dogru-yanlis","soru":"Etkinlik akış çizelgesinde (run of show) her bölüm ayrı planlandığı için kahve molasının geç verilmesi sonraki oturumun saatini etkilemez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Akış çizelgesi günün ritmini saat saat korur; kahve molası geç gelirse bir sonraki oturum da kayar. Bu yüzden ekip çizelgeyi telsizle izler ve gecikmeyi etkinlik yöneticisine bildirir."},{"id":"go-5-s34","tur":"coktan-secmeli","soru":"Banket satış yöneticisi, bir müşteriye yıl sonu yemeği için söz vermeden önce özellikle neyi bilmek zorundadır?","secenekler":["Mutfağın, servisin ve teknik ekibin imkânlarını","Müşterinin geçmiş tatillerinde kaldığı otelleri","Şehirdeki kongre merkezinin salon fiyatlarını","Davetlilerin otele gelirken kullanacağı uçuşları"],"dogru":0,"aciklama":"Banket satış yöneticisinin verdiği her söz, etkinlik günü mutfağın, servisin ve teknik ekibin işi olur; bu yüzden onların neler yapabileceğini bilmeden söz veremez. Kongre merkezinin fiyatları kendi otelinin teklifini belirlemez."},{"id":"go-5-s35","tur":"coktan-secmeli","soru":"Antalya limanında iki konuk karaya çıkıyor: biri gemi şirketinin sattığı rehberli kıyı gezisine katılıyor, öteki kendi başına geziyor. İkisi de dönüşte gecikirse hangisi beklenir?","secenekler":["Gemi kalkışı erteler ve iki konuğu da bekler","Şirketin sattığı geziyi bekleyebilir, kendi gezeni genellikle beklemez","Kendi gezeni bekleyebilir, şirketin sattığı geziyi genellikle beklemez","İkisi de aynı biçimde değerlendirilir, ayrım yapılmaz"],"dogru":1,"aciklama":"Geminin kalkış saati kesindir; gemi şirketinin sattığı gezi geç dönerse gemi bekleyebilir, ama kendi başına gezen konuk için genellikle beklenmez. Bu yüzden rehber ve operasyon ekibi saatleri sıkı izler."},{"id":"go-5-s36","tur":"coktan-secmeli","soru":"Kruvaziyerde kabininde kitap okuyarak çok vakit geçirecek bir konuk doğal ışık istiyor, ama balkona ek ücret ödemek istemiyor. Ona hangi kabin türü önerilir?","secenekler":["İç kabin","Balkonlu kabin","Kruvaziyer süiti","Deniz manzaralı kabin"],"dogru":3,"aciklama":"Deniz manzaralı kabinde denize bakan sabit bir pencere vardır, ama balkon yoktur; doğal ışık verir ve balkonludan daha uygun fiyatlıdır. İç kabin daha ucuzdur, ama penceresi olmadığı için doğal ışık almaz."},{"id":"go-5-s38","tur":"coktan-secmeli","soru":"Ankara’dan New York’a tek biletle giden bir yolcu İstanbul’da uçak değiştirecek ve aktarma süresi kısa. Bu yolculukta yolcuyu en çok hangi risk bekler?","secenekler":["Bagajının Ankara’da kesin olarak kalması","İlk uçak gecikirse ikinci uçağı kaçırması","Biniş kartının ikinci uçuşta geçersiz sayılması","Biletini İstanbul’da yeniden satın alması"],"dogru":1,"aciklama":"Aktarma süresi kısaysa ilk uçağın gecikmesi, yolcunun bağlantı uçuşunu kaçırmasına yol açabilir. İki uçuş tek biletle alındığında bagaj çoğunlukla doğrudan son noktaya gider, yani Ankara’da kalması beklenmez."},{"id":"go-5-s39","tur":"coktan-secmeli","soru":"Düşük maliyetli bir şirkette İstanbul–Londra bileti çok ucuz görünüyordu. Yolcu bagaj ekleyip koltuk seçtikçe toplam fiyat yükseldi. Bunun nedeni hangisidir?","secenekler":["Uçuşun kod paylaşımıyla başka bir şirkete devredilmesi","Yolcunun bu seçimlerle business sınıfına geçirilmesi","Biletin yalnız koltuğu kapsayıp ek hizmetleri ayrı satması","Bagaj ve koltuk ücretinin yalnız aktarmalı uçuşlarda alınması"],"dogru":2,"aciklama":"Düşük maliyetli taşıyıcının ek ücret modelinde bilet fiyatına yalnız koltuk dâhildir; bagaj, yemek ve koltuk seçimi ayrı ayrı ücretlendirilir. Kod paylaşımı ise uçağı başka bir şirketin işletmesidir, fiyatı bu şekilde artırmaz."},{"id":"go-5-s40","tur":"dogru-yanlis","soru":"Havalimanı lounge’u bütün yolculara açıktır; girişte bilet sınıfı, üyelik ya da kart ayrıcalığı aranmaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Lounge özel bir bekleme salonudur; girişi bilet sınıfına, üyeliğe ya da kart ayrıcalığına bağlıdır. Bu yüzden örneğin business sınıfı yolcusu lounge’u kullanabilirken her yolcu kullanamaz."},{"id":"go-5-s41","tur":"coktan-secmeli","soru":"Bodrum’daki bir otel yalnız yazın dolduğu için kışın da konuk getirmek istiyor. Sezon dışı stratejisine en uygun adım hangisidir?","secenekler":["Kışın oteli tamamen kapatıp çalışanları göndermek","Fiyatı yarıya indirip başka hiçbir şeyi değiştirmemek","Kışa özel yoga ve gastronomi haftaları düzenlemek","Yaz programını kış aylarında da aynen uygulamak"],"dogru":2,"aciklama":"Sezon dışı stratejisinde amaç doluluğu yıla yaymaktır ve en değerli yol o mevsime özel bir deneyim sunmaktır. Yalnız fiyatı indirmek tek çözüm değildir; programı ve ürünü de mevsime göre planlamak gerekir."},{"id":"go-5-s42","tur":"coktan-secmeli","soru":"Bir Ege köyündeki otel, konuklarını zeytin toplamaya ve zeytinyağı sıkımını kendi elleriyle denemeye davet ediyor. Bu uygulama hangi turizm anlayışına örnektir?","secenekler":["Deneyim turizmi","Gece ekonomisi","Kültür rotası","Destinasyon markası"],"dogru":0,"aciklama":"Deneyim turizminde ziyaretçi yalnız gezip görmez, yerel yaşamın içinde bir şey yaparak ve deneyerek öğrenir. Kültür rotası ise aynı temaya bağlı birkaç tarihî yeri sırayla gezdiren programdır."},{"id":"go-5-s43","tur":"coktan-secmeli","soru":"Bir kıyı şehri yaz akşamları müzelerini geç saate kadar açık tutuyor, sahilde konserler düzenliyor. Gece ekonomisi açısından bunun en önemli etkisi hangisidir?","secenekler":["Konukların kalış süresini ve harcamasını artırması","Otellerin akşam yemeği servisini tümüyle gereksiz kılması","Güvenlik ve ulaşım ihtiyacını ortadan kaldırması","Konukların gündüz gezilerine katılmasını önlemesi"],"dogru":0,"aciklama":"Akşam nerede vakit geçireceğini bilen konuk şehre çıkar; gece programı kalış süresini ve harcamayı artırır. Güvenlik ve ulaşım ise ortadan kalkmaz, tersine gece ekonomisinin başlıca konularıdır."}],"siralamalar":[{"id":"go-5-r01","konu":"5.1","baslik":"Telefondaki sorudan gala gecesine","yonerge":"Banket satış yöneticisi olarak bir yıl sonu yemeğini sattığın andan etkinlik gününe kadar adımları doğru sıraya koy.","adimlar":["Bir bankanın yıl sonu yemeği için balo salonu talebini al.","Müşteriye salonu gezdir, menü seçeneklerini anlat ve yazılı teklif gönder.","Müşteriyle sözleşmeyi bağla.","Etkinliğin salonunu, düzenini, menüsünü ve saatlerini BEO’ya yazıp bütün departmanlara dağıt.","Etkinlik yaklaşınca müşteriden garanti sayısını al ve BEO’yu buna göre güncelle.","Etkinlik günü ekibi akış çizelgesine göre saat saat yönet."],"aciklama":"Satış bitmeden iş emri yazılmaz: talep, gezi ve teklif sözleşmeyle kapanır; BEO bütün departmanları hazırlar, garanti sayısı son hâlini verir, etkinlik günü akış çizelgesi ritmi korur."},{"id":"go-5-r02","konu":"5.2","baslik":"Gemideki ilk saatlerden ilk limana","yonerge":"Türkiye’den başlayan bir kruvaziyer yolculuğunda konuğun yaşadığı adımları doğru sıraya koy.","adimlar":["Yolculuğun başlayacağı liman kentinde bir gece otelde kal.","Gemiye bin.","Güvenlik tatbikatına katıl: toplanma noktana git ve cankurtaran yeleğinin nasıl giyildiğini öğren.","Gemi limana yanaşınca karaya çık ve rehberli kıyı gezisine katıl.","Geminin kalkış saatine yetişecek biçimde gemiye dön."],"aciklama":"Güvenlik tatbikatı gemi limandan ayrılmadan, yolculuğun başında yapılır; kıyı gezisi ise liman gününde olur ve geminin kalkış saati kesin olduğu için gezi gemiye zamanında dönmekle biter."},{"id":"go-5-r03","konu":"5.3","baslik":"Kontuardan koltuğa","yonerge":"Bir yolcunun havalimanına gelişinden uçuşuna kadar geçen adımları doğru sıraya koy.","adimlar":["Kontuara git; bagajını bırak ve biniş kartını al.","Kapıda görevliye biniş kartını göster ve uçağa gir.","Koltuğuna otur ve kabin memurunun güvenlik gösterimini izle.","Uçuş sırasında kabin memurunun içecek servisini al."],"aciklama":"Biniş kartı check-in’de alınır ve kapıda gösterilmeden uçağa girilmez; kabin memurunun asıl işi güvenliktir, bu yüzden güvenlik gösterimi önce, ikram sonra gelir."},{"id":"go-5-r04","konu":"5.3","baslik":"Uçuş numarasından karşılamaya","yonerge":"Otel olarak bir konuğu havalimanından alma işinin adımlarını doğru sıraya koy.","adimlar":["Rezervasyon sırasında konuğun uçuş numarasını al.","Varış günü uçuşu numarasından izle; gecikme varsa şoföre yeni iniş saatini bildir.","Konuğu havalimanında adıyla karşıla, bagajına yardım et ve araca götür."],"aciklama":"Uçuş numarası önceden alınmazsa uçuş izlenemez, uçuş izlenmezse gecikme şoföre bildirilemez; karşılama ve bagaj yardımı ise konuk indikten sonra gelir ve otelle ilk teması oluşturur."}],"acikSorular":[{"id":"go-5-y01","konu":"5.1","soru":"Bir otelin banket satış yöneticisisin. Bir banka, yıl sonu için aynı salonda sabah eğitim, akşam yemekli gala istiyor. İki etkinlik için hangi oturma düzenlerini önerirsin? Bu masalı düzenlerin aynı salona tiyatro düzeninden daha az kişi aldığını ve yemekli etkinlikte garanti sayısının neden önemli olduğunu açıklayınız.","olcut":[{"metin":"Sabah eğitimi için sınıf düzenini seçer ve notların masada alınabilmesini gerekçe gösterir.","puan":20},{"metin":"Akşam galası için banket düzenini (yuvarlak masalar) seçer.","puan":20},{"metin":"Masalı düzenlerde aynı salona tiyatro düzeninden daha az kişi sığdığını belirtir.","puan":20},{"metin":"Garanti sayısını, müşterinin etkinlikten önce bildirdiği kesin kişi sayısı olarak tanımlar.","puan":15},{"metin":"Mutfak ve servis hazırlığının bu sayıya göre yapıldığını ve eksik gelenlerin ücretinin çoğunlukla ödendiğini, bu yüzden kuralın sözleşmede yazılı olduğunu açıklar.","puan":25}],"ornek":"Sabah eğitimi için sınıf düzenini öneririm, çünkü katılımcıların önünde dar masalar olur ve rahatça not tutabilirler. Akşam galası için yuvarlak masalardan oluşan banket düzenini öneririm; konuklar masa başında yemek yer ve sohbet eder. Masalı düzenlerde kişi başına daha geniş alan gerektiği için aynı salona tiyatro düzeninden daha az kişi sığar. Garanti sayısı, müşterinin yemekten kısa süre önce bildirdiği kesin kişi sayısıdır. Mutfak alışverişi, servis ekibi ve masa planı bu sayıya göre hazırlandığı için eksik gelenlerin ücreti çoğunlukla ödenir; bu yüzden kural baştan sözleşmede yazılır.","ipucu":"Önce her etkinlikte katılımcıların ne yapacağını (not almak mı, yemek yemek mi) düşün; sonra mutfağın hazırlık yaparken neye dayandığını bul."},{"id":"go-5-y02","konu":"5.2","soru":"Bir kruvaziyer gemisinde misafir hizmetleri masasında çalışıyorsun. Bir konuk, yarın Kuşadası’nda liman günü olduğu için gemi şirketinin kıyı gezisini mi yoksa kendi başına gezmeyi mi seçmesi gerektiğini soruyor. Liman günü ile deniz gününü ayırt ederek konuğa nasıl bilgi verirsin? Açıklayınız.","olcut":[{"metin":"Liman gününü, geminin limana yanaşıp konukların karaya çıkabildiği gün olarak tanımlar.","puan":15},{"metin":"Deniz gününü, gün boyu denizde seyredilen ve hiçbir limana uğranmayan gün olarak tanımlar.","puan":15},{"metin":"Kıyı gezisinin çoğunlukla gemi şirketi aracılığıyla ayrıca satılan rehberli bir program olduğunu belirtir.","puan":20},{"metin":"Geminin kalkış saatinin kesin olduğunu ve konuğun zamanında gemiye dönmesi gerektiğini söyler.","puan":20},{"metin":"Şirketin sattığı gezi geç dönerse geminin bekleyebileceğini, kendi başına gezen konuk için genellikle beklenmeyeceğini; bu nedenle konuğu bilgilendirmenin şikâyeti ve riski önlediğini açıklar.","puan":30}],"ornek":"Liman günü, geminin Kuşadası gibi bir limana yanaşıp konukların karaya çıkabildiği gündür; deniz günü ise gün boyu açık denizde geçer ve hiçbir limana uğranmaz. Yarınki liman gününde konuk kıyı gezisi alabilir; bu, çoğunlukla gemi şirketi aracılığıyla ayrıca satılan rehberli bir programdır. Geminin kalkış saati kesindir, bu yüzden konuğa dönüş saatini net söylerim. Şirketin sattığı gezi geç dönerse gemi bekleyebilir, ama kendi başına gezen konuk için genellikle beklenmez. Konuğu bu farkla bilgilendirmek hem riski hem de sonraki şikâyetleri önler.","ipucu":"Konuk geç kalırsa geminin ne yapabileceğinin, gezinin kim tarafından düzenlendiğine göre değişip değişmediğini düşün."}]},{"ders":"global-otelcilik","sinif":9,"unite":6,"baslik":"Pazarlama, Marka ve Dijital Otelcilik","onay":true,"kazanimlar":["Hedef kitle, konumlandırma ve değer önerisi gibi pazarlama kavramlarını otel örnekleriyle açıklar.","Web sitesi, sosyal medya, yorum siteleri ve çevrim içi itibar yönetiminin otel için işleyişini açıklar.","Satış tekniklerini, ek satışı ve sadakat programlarını konuk değerine saygılı biçimde uygular.","Otelcilikte veri kullanımı, otomasyon ve kişisel verilerin korunması ilkelerini açıklar."],"soz":"Pazarlama konuğa verilen bir sözdür; veri ise o sözün emanetidir.","dersler":[{"baslik":"Bir Otel, Dört Karar","ilk":"go-6-001"},{"baslik":"Herkese Satan Kimseye Satamaz","ilk":"go-6-006"},{"baslik":"Hayalî Konuk Elif","ilk":"go-6-011"},{"baslik":"Otelin Kimliği ve Sözü","ilk":"go-6-014"},{"baslik":"Tahmin Değil Bilgi","ilk":"go-6-017"},{"baslik":"Dijital Vitrin","ilk":"go-6-021"},{"baslik":"Otel Adına Paylaşmak","ilk":"go-6-025"},{"baslik":"Yıldızlar, Yorumlar, Kriz","ilk":"go-6-028"},{"baslik":"Gerçeği Göster, İzin İste","ilk":"go-6-033"},{"baslik":"Konuk Nerede Vazgeçer?","ilk":"go-6-037"},{"baslik":"Satış mı, Hizmet mi?","ilk":"go-6-040"},{"baslik":"Sadık Konuk, Güvenilir Tavsiye","ilk":"go-6-045"},{"baslik":"Şirketler ve Kalabalıklar","ilk":"go-6-048"},{"baslik":"Otelin Elindeki Emanet","ilk":"go-6-051"},{"baslik":"Veri Konuğundur","ilk":"go-6-055"},{"baslik":"Az Veri, Kısa Süre","ilk":"go-6-058"},{"baslik":"Kilit, Kod ve Dolandırıcı","ilk":"go-6-061"},{"baslik":"Gece 02.00’de Cevap Veren","ilk":"go-6-065"},{"baslik":"Yazılım Önerir, İnsan Karar Verir","ilk":"go-6-067"}],"kavramlar":[{"id":"go-6-001","konu":"6.1","terim":"Otelde pazarlama karması (4P)","ingilizce":"Marketing mix (the 4Ps)","tanim":"Bir otelin ürün, fiyat, yer ve tutundurma kararlarını birbirine uyduran dört parçalı pazarlama çerçevesidir.","ornek":"Bodrum’da yeni açılan 12 odalı butik otel dört kararı aynı hikâyeye bağlar: sakin bir ürün, orta-üst fiyat, kendi sitesi ile iki aracı platform ve fotoğraf ağırlıklı tanıtım.","sektor":"Dünyada pazarlama dersleri bu dört parçayla başlar. Biri ötekilerle çelişirse konuk güvenmez: lüks fotoğraf, çok ucuz fiyat ve özensiz site yan yana durmaz. Hizmet sektöründe bu çerçeveye çoğu zaman insan, süreç ve fiziksel ortam da eklenir; çünkü çalışanın her davranışı da konuğun gördüğü ürünün parçasıdır.","iliskili":["go-6-002","go-6-003","go-6-005"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"go-6-002","konu":"6.1","terim":"Otel ürünü","ingilizce":"Hotel product","tanim":"Konuğun satın aldığı odanın, hizmetin, yemeğin, konumun ve atmosferin bütünüdür.","ornek":"Antalya’daki bir resortta konuk yalnız yatak almaz; karşılayan görevliyi, kahvaltıyı, plajı ve havuz başındaki huzuru da satın alır.","sektor":"Otel ürünü dokunulup rafa konamayan, yaşanarak anlaşılan bir üründür; bu yüzden çalışanın davranışı ürünün parçasıdır. Tanıtımda söylenenle yaşananın farkı güveni kırar.","iliskili":["go-6-001","go-6-016"],"kontrol":null,"kitapDisi":true},{"id":"go-6-003","konu":"6.1","terim":"Otelde fiyat kararı","ingilizce":"Pricing","tanim":"Odanın hangi bedelle ve hangi koşullarla sunulacağını belirleyen, aynı zamanda konuğa otelin değeri hakkında mesaj veren karardır.","ornek":"İstanbul’da şehir merkezindeki bir otel fuar haftasında odayı daha yüksek ve iptal koşulları net bir fiyatla sunar; sade bir pansiyonun yanında aynı fiyatı isteyemez.","sektor":"Fiyat yalnız bir sayı değil, konumlandırmanın işaretidir: lüks bir otelin çok düşük fiyatı kaliteden şüphe uyandırır. Fiyatı gelir müdürü yönetir; sen konuğa kalemleri açık ve doğru anlatırsın.","iliskili":["go-6-001","go-6-043"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"go-6-004","konu":"6.1","terim":"Otelde yer: konum ve satış kanalları","ingilizce":"Place (location and distribution)","tanim":"Konuğun oteli bulduğu ve rezervasyon yaptığı yerlerin, yani otelin konumu ile satış kanallarının toplamıdır.","ornek":"Kapadokya’daki taş otel kendi sitesinde, iki aracı platformda ve yerel acentelerde görünür; konuk hangisinden bakarsa baksın aynı bilgiyi görmelidir.","sektor":"Pazarlamada yer hem haritadaki adres hem de dağıtım kanallarıdır; Ünite 1’de gördüğün kanallar burada pazarlamanın aracı olur. Kanallar arasında farklı bilgi vermek itibar kaybettirir.","iliskili":["go-6-001","go-6-021"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-plajdaki-otel-avlusu"},{"id":"go-6-005","konu":"6.1","terim":"Tutundurma (tanıtım ve iletişim)","ingilizce":"Promotion","tanim":"Otelin varlığını duyurmak ve konuğu rezervasyona yönlendirmek için yapılan reklam, tanıtım, sosyal medya ve satış çalışmalarının tümüdür.","ornek":"Kuşadası’ndaki otel mart ayında erken rezervasyon e-postası gönderir, sosyal medyada yeni kahvaltı salonunu gösterir ve turizm fuarında stant açar.","sektor":"Pazarlamanın en görünen parçasıdır, ama zayıf ürünü kurtarmaz: kötü hizmeti reklamla gizleyemezsin, çünkü ilk yorumu yazan konuk olur. En iyi tanıtım, memnun ayrılan konuktur.","iliskili":["go-6-001","go-6-047"],"kontrol":null,"kitapDisi":true,"cizim":"megafon"},{"id":"go-6-006","konu":"6.1","terim":"Otelin hedef kitlesi","ingilizce":"Hotel target audience","tanim":"Bir otelin ürününü öncelikle sunmaya karar verdiği, benzer ihtiyaç ve alışkanlıkları olan konuk grubudur.","ornek":"Alanya’daki bir aile resortu çocuk kulübünü, sığ havuzu ve açık büfe kahvaltıyı öne çıkarır; tek başına gelen iş seyahatçisini öncelikli hedef almaz.","sektor":"Herkese hitap etmeye çalışan otel kimseye tam hitap edemez. Hedef kitle belli olunca oda tasarımından menüye, reklam dilinden personelin yaklaşımına kadar her karar kolaylaşır.","iliskili":["go-6-007","go-6-011"],"kontrol":null,"kitapDisi":true},{"id":"go-6-007","konu":"6.1","terim":"Pazar bölümlemesi","ingilizce":"Market segmentation","tanim":"Konukları seyahat amacına, yaşına, bütçesine ya da seyahat biçimine göre benzer gruplara ayırma işidir.","ornek":"İstanbul’daki bir otelin satış ekibi konukları hafta içi iş seyahatçileri, hafta sonu çiftler ve yaz aylarındaki yabancı turist grupları olarak üç bölüme ayırır.","sektor":"Aynı oda farklı bölüme farklı yoldan satılır: hafta içi şirket anlaşmasıyla, hafta sonu kampanyayla. Hangi bölümün otele ne kazandırdığı ayrı ayrı izlenir.","iliskili":["go-6-006","go-6-008","go-6-009"],"kontrol":null,"kitapDisi":true},{"id":"go-6-008","konu":"6.1","terim":"İş seyahati segmenti","ingilizce":"Business travel segment","tanim":"Çalışmak, toplantıya ya da fuara katılmak için seyahat eden ve masrafını çoğunlukla işverenin karşıladığı konuk grubudur.","ornek":"Pazartesi akşamı İzmir’deki otele gelen bir yazılım şirketi çalışanı sabah erken kahvaltı, hızlı check-out ve sağlam internet bekler.","sektor":"Hafta içi dolulukta güvence olan bu konuk çoğu zaman fiyattan çok kolaylığa bakar. Hız, sessizlik ve çalışma masası onun için çoğunlukla lüksten önemlidir.","iliskili":["go-6-007","go-6-009","go-6-048"],"kontrol":null,"kitapDisi":true},{"id":"go-6-009","konu":"6.1","terim":"Tatil segmenti","ingilizce":"Leisure travel segment","tanim":"Dinlenmek, gezmek ya da eğlenmek için kendi bütçesiyle seyahat eden konuk grubudur.","ornek":"Temmuzda Marmaris’e gelen bir çift iki hafta kalır; plaja yakın bir oda, manzara ve akşam eğlencesi arar.","sektor":"Tatilci fiyata ve deneyime duyarlıdır, tarihlerini çoğu zaman okul tatili ve bayramlara göre seçer. Hafta sonu ve yaz talebinin büyük bölümü bu gruptan gelir; yaşadığını çoğu zaman yorumla paylaşır.","iliskili":["go-6-007","go-6-008","go-6-010"],"kontrol":null,"kitapDisi":true},{"id":"go-6-010","konu":"6.1","terim":"Aile segmenti","ingilizce":"Family travel segment","tanim":"Çocuklarıyla birlikte seyahat eden, oda, yemek ve güvenlik ihtiyaçları farklı olan konuk grubudur.","ornek":"Bayram tatilinde Bolu’daki bir otele iki çocuklu bir aile gelir; yan yana odalar, çocuk menüsü ve güvenli bir oyun alanı ister.","sektor":"Kararı çoğu zaman ebeveynler verir, ama çocuğun mutluluğu yorumu da etkiler. Çocuk yatağı, mama sandalyesi ve çocuk kulübü gibi küçük hizmetler büyük fark yaratır.","iliskili":["go-6-007","go-6-009"],"kontrol":null,"kitapDisi":true},{"id":"go-6-011","konu":"6.1","terim":"Konuk kişiliği (persona)","ingilizce":"Guest persona","tanim":"Hedef konuk grubunu temsil eden, adı, işi ve beklentileri olan kurgusal bir konuk betimlemesidir.","ornek":"Satış ekibi tahtaya “Elif, mühendis, iki çocuklu; hafta sonu kaçamağı arıyor, çocuk dostu otel ve ücretsiz iptal istiyor” diye bir betimleme yazar ve kampanya metnini ona göre hazırlar.","sektor":"Persona ekibe “bu mesajı kim okuyacak?” sorusunu somut bir yüzle sorduran araçtır. Gerçek bir kişi değildir; gerçek konukların ortak özelliklerinden yazılır ve hiçbir kimlik bilgisi içermez.","iliskili":["go-6-006","go-6-012"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"go-6-012","konu":"6.1","terim":"Konumlandırma","ingilizce":"Positioning","tanim":"Otelin hedef konukların zihninde rakiplerden ayrı ve belirgin bir yer edinmesini sağlayan çalışmadır.","ornek":"Bodrum’da bir otel “yetişkinlere özel, sessiz, sahile sıfır” diye konumlanır; çocuklu aileler başka otellere yönelir.","sektor":"İyi konumlandırma otelin kime ne söylediğini netleştirir. Konumlandırma sözle değil uygulamayla kurulur: sessizlik vaat eden otelde gece yüksek sesli müzik çalıyorsa konumlandırma çöker.","iliskili":["go-6-011","go-6-013"],"kontrol":null,"kitapDisi":true},{"id":"go-6-013","konu":"6.1","terim":"Otelin değer önerisi","ingilizce":"Hotel value proposition","tanim":"Konuğa “neden bu oteli seçmeliyim?” sorusunun kısa ve inandırıcı cevabını veren, otelin sunduğu yararın açık anlatımıdır.","ornek":"Kapadokya’daki mağara otel sitesinin ilk satırına “Tarihî taş odada uyanın, balon manzaralı terasta kahvaltı edin” cümlesini koyar.","sektor":"Değer önerisi konuğa verilmiş bir sözdür ve yorumlarda sınanır. Çalışan olarak bu cümleyi bilmek, konuğa aynı şeyi söyleyebilmek ve onu gerçekten yaşatabilmektir.","iliskili":["go-6-012","go-6-015"],"kontrol":null,"kitapDisi":true},{"id":"go-6-014","konu":"6.1","terim":"Otel marka kimliği","ingilizce":"Brand identity","tanim":"Otelin adı, logosu, renkleri, dili ve davranış biçimi gibi onu başkalarından ayıran işaretlerin bütünüdür.","ornek":"Ege kıyısındaki bir otelde beyaz-mavi renkler, kısa ve samimi yazışma dili ve açık renk personel üniforması aynı kimliğin parçalarıdır.","sektor":"Kimlik sitede, tabelada, e-postada ve resepsiyondaki tonda tutarlı olmalıdır. Zincir otellerde kimlik markadan, bağımsız otelde çoğu zaman sahibinin hikâyesinden gelir.","iliskili":["go-6-015","go-6-016"],"kontrol":null,"kitapDisi":true},{"id":"go-6-015","konu":"6.1","terim":"Marka vaadi","ingilizce":"Brand promise","tanim":"Otelin konuğa “bizi seçerseniz bunu yaşarsınız” diye verdiği ve her konaklamada tutmayı üstlendiği sözdür.","ornek":"“Her konuk adıyla karşılanır” diyen otelde resepsiyonist kimliğe bakar bakmaz konuğa adıyla hitap eder.","sektor":"Marka vaadi sloganda değil, çalışanın davranışında yaşar. Vaat tutulursa güven doğar; tutulmazsa en iyi reklam bile işe yaramaz.","iliskili":["go-6-014","go-6-013"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"go-6-016","konu":"6.1","terim":"Marka deneyimi","ingilizce":"Brand experience","tanim":"Konuğun otelle kurduğu bütün temaslardan aklında kalan, markaya ilişkin toplam izlenim ve duygudur.","ornek":"İstanbul’daki bir otelin sitesini, karşılama içeceğini, odanın kokusunu ve çıkıştaki teşekkür mesajını konuk birlikte “o otel” olarak hatırlar.","sektor":"Marka standardı kâğıt üstündeki kuraldır; marka deneyimi o kuralın konuğun hissine dönüşmüş hâlidir. Stajyer dâhil herkes bu deneyimin parçasıdır.","iliskili":["go-6-014","go-6-015"],"kontrol":null,"kitapDisi":true},{"id":"go-6-017","konu":"6.1","terim":"Otelde pazar araştırması","ingilizce":"Hotel market research","tanim":"Konukların ne istediğini, rakiplerin ne yaptığını ve talebin nasıl değiştiğini düzenli bilgi toplayarak öğrenme çalışmasıdır.","ornek":"Mart ayında Antalya’daki bir resort geçen yazın konuklarına kısa bir anket gönderir ve yorum sitelerindeki sözcükleri okur; “çocuk havuzu küçük” şikâyeti öne çıkar.","sektor":"Tahminle değil bilgiyle karar vermeyi sağlar. Konuk anketi, yorum okuma ve rezervasyon verisi en ucuz araştırma yollarıdır; ankette kişisel bilgi yalnız gerektiği kadar istenir.","iliskili":["go-6-018","go-6-006"],"kontrol":null,"kitapDisi":true,"cizim":"grafik"},{"id":"go-6-018","konu":"6.1","terim":"Rakip analizi","ingilizce":"Competitor analysis","tanim":"Benzer konuğa hizmet veren otellerin ürününü, fiyatını, kanallarını ve yorumlarını inceleyip kendi oteliyle karşılaştırma işidir.","ornek":"Fethiye’deki bir otelin satış ekibi her ay üç komşu otelin kahvaltı saatini, fiyatını ve yorum puanını tabloya yazar; kendi kahvaltısının erken bittiğini görür.","sektor":"Amaç rakibi taklit etmek değil, kendi ayrımını görmektir. Bilgi yalnız herkese açık kaynaklardan toplanır; rakip adına sahte yorum yazmak ya da gizli bilgi almaya çalışmak etik dışıdır.","iliskili":["go-6-017","go-6-012"],"kontrol":null,"kitapDisi":true},{"id":"go-6-019","konu":"6.1","terim":"Yüksek sezon ve düşük sezon","ingilizce":"High season and low season","tanim":"Talebin ve fiyatların yıl içinde yükseldiği dönem yüksek sezon, düştüğü dönem düşük sezondur.","ornek":"Bodrum’daki sahil oteli temmuzda tamamen doludur; kasımda bazı bölümlerini kapatır, fiyatı düşürür ve hafta sonu paketleri satar.","sektor":"Sezon pazarlamanın takvimini belirler: yüksek sezon için erken rezervasyon, düşük sezon için paket ve kampanya hazırlanır. Şehir otellerinde sezon fuar ve iş seyahati takvimine göre değişir.","iliskili":["go-6-020","go-6-044"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-karli-otel"},{"id":"go-6-020","konu":"6.1","terim":"Otel paketi","ingilizce":"Hotel package","tanim":"Konaklamaya kahvaltı, spa ya da etkinlik gibi hizmetleri ekleyip tek fiyata sunan birleşik tekliftir.","ornek":"Kasım ayında Bursa’daki bir termal otel iki gece konaklama, kahvaltı ve termal havuz girişini tek bir “Hafta Sonu Yenilenme” paketinde satar.","sektor":"Paket, doğrudan indirim yapmadan konuğa değer ekler ve düşük sezonda talep yaratmaya yardım eder. İçeriği ve toplam fiyatı açık yazılmalıdır; konuk neyin dâhil olduğunu yanlış anlarsa şikâyet doğar.","iliskili":["go-6-019","go-6-043"],"kontrol":null,"kitapDisi":true},{"id":"go-6-021","konu":"6.2","terim":"Otel internet sitesi","ingilizce":"Hotel website","tanim":"Otelin kendi adına işlettiği, konuğun oteli tanıyıp rezervasyon yapabildiği resmî internet sayfasıdır.","ornek":"Akşam 21.00’de Eskişehir’deki bir çift telefonundan otelin sitesini açar; odaları, fiyatı ve boş tarihleri iki dakikada görüp rezervasyona geçer.","sektor":"Telefonda yavaş açılan ya da bilgisi eski olan site konuğu rakibe gönderir. Doğrudan rezervasyonda aracıya komisyon ödenmediği için site otel için çok değerli bir satış kanalıdır; yine de siteyi güncel tutmak ve duyurmak emek ister.","iliskili":["go-6-022","go-6-023"],"kontrol":null,"kitapDisi":true,"cizim":"otel-bina"},{"id":"go-6-022","konu":"6.2","terim":"Rezervasyon motoru","ingilizce":"Booking engine","tanim":"Otel sitesinde konuğun boş tarihleri görüp odayı seçerek ödemeye kadar ilerleyebildiği rezervasyon yazılımıdır.","ornek":"Konuk sitede “temmuz, iki yetişkin, bir çocuk” yazar; motor uygun odaları fiyatlarıyla sıralar, konuk birini seçip kartıyla öder.","sektor":"Motor çoğu zaman PMS ve kanal yöneticisine bağlıdır; satılan oda böylece her yerde hemen satışa kapanır. Adımı çok olan ya da hata veren motor konuğu rezervasyondan vazgeçirir.","iliskili":["go-6-021","go-6-037"],"kontrol":null,"kitapDisi":true,"cizim":"resepsiyon"},{"id":"go-6-023","konu":"6.2","terim":"Arama motoru görünürlüğü (SEO)","ingilizce":"Search engine optimisation (SEO)","tanim":"Otel sitesinin arama sonuçlarında reklam parası ödenmeden üst sıralarda çıkması için yapılan çalışmalardır.","ornek":"Pamukkale yakınındaki bir otel, sitesinde “Pamukkale’ye yakın, termal havuzlu otel” gibi konuğun gerçekten aradığı sözcükleri doğru bilgiyle kullanır.","sektor":"Konuk çoğu zaman önce arar, sonra seçer; sonuçlarda görünmeyen otel hiç düşünülmez. SEO yanıltıcı sözcüklerle değil, doğru ve güncel bilgiyle, hızlı açılan siteyle güçlenir.","iliskili":["go-6-021","go-6-024"],"kontrol":null,"kitapDisi":true,"cizim":"dijital"},{"id":"go-6-024","konu":"6.2","terim":"Harita ve yerel arama kaydı","ingilizce":"Local search listing","tanim":"Otelin harita uygulamalarında ve arama sonuçlarında adres, telefon, fotoğraf ve puanla görünen işletme sayfasıdır.","ornek":"Konuk telefondaki harita uygulamasına “Kaş otel” yazar; otelin kaydında doğru telefon, güncel fotoğraflar ve yorum puanı yer alır.","sektor":"Konuk yoldayken ya da şehirdeyken en hızlı bu sayfaya bakar. Yanlış telefon ya da eski adres kapıdan dönen konuk demektir; kaydı güncel tutmak küçük ama değerli bir iştir.","iliskili":["go-6-023","go-6-028"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-haritali-telefon"},{"id":"go-6-025","konu":"6.2","terim":"Otelin sosyal medya içeriği","ingilizce":"Hotel social media content","tanim":"Bir otelin kendi hesaplarında paylaştığı, konuğa otelin havasını gösteren fotoğraf, video ve yazılardır.","ornek":"Sabah 07.30’da Bodrum’daki otelin hesabı, şefin yeni kahvaltı tabaklarını gösteren kısa bir video paylaşır; yorumlara hesabı yöneten sorumlu yanıt verir.","sektor":"İçerik gerçeği yansıtmalıdır; olmayan bir manzarayı paylaşmak şikâyet getirir. Hesap otel adına konuşur, bu yüzden paylaşımı yetkili kişi yapar; stajyer olarak otel hesabına kendi başına bir şey yazmazsın, fikrini amirine iletirsin.","iliskili":["go-6-026","go-6-034"],"kontrol":null,"kitapDisi":true},{"id":"go-6-026","konu":"6.2","terim":"Etkileyici iş birliği (influencer)","ingilizce":"Influencer collaboration","tanim":"Otelin, sosyal medyada takipçisi olan bir kişiyle konaklama ya da ödeme karşılığı tanıtım yapmak üzere anlaşmasıdır.","ornek":"Ayvalık’taki bir otel, seyahat içeriği üreten bir hesap sahibine iki gece konaklama verir; karşılığında hesap sahibi otelle ilgili paylaşım yapar.","sektor":"İş birliği oteli yeni kitlelere gösterebilir; ama takipçinin güveni paylaşımın dürüstlüğüne bağlıdır. Takipçi sayısı tek ölçüt değildir; hesap sahibinin kitlesinin otelin hedef kitlesine uyup uymadığına bakılır ve anlaşmayı pazarlama yöneticisi yapar.","iliskili":["go-6-025","go-6-027"],"kontrol":null,"kitapDisi":true,"cizim":"is-birligi"},{"id":"go-6-027","konu":"6.2","terim":"İş birliğinin açıkça belirtilmesi","ingilizce":"Sponsored content disclosure","tanim":"Karşılığı alınmış bir paylaşımın reklam ya da iş birliği olduğunun takipçiye açıkça söylenmesidir.","ornek":"Hesap sahibi paylaşımına “iş birliği” ibaresini ekler; otel bu ibarenin yazılmasını anlaşmaya şart koymuştur.","sektor":"Türkiye’de ticari reklamlara kurallar getiren düzenlemeler vardır ve birçok ülkede de aynı ilke geçerlidir: izleyici reklamı reklam olarak bilmelidir. Gizli reklam güveni kırar ve hem otel hem de paylaşan kişi için sorun yaratır.","iliskili":["go-6-026","go-6-030"],"kontrol":null,"kitapDisi":true,"cizim":"is-birligi"},{"id":"go-6-028","konu":"6.2","terim":"Yorum puanı","ingilizce":"Review score","tanim":"Konukların yorum sitelerinde verdiği puanların ortalamasıdır.","ornek":"İzmir’deki bir otelin puanı bir hafta içinde temizlik şikâyetleri yüzünden düşer ve rezervasyonlar yavaşlar.","sektor":"Konuk karar vermeden önce çoğu zaman puana ve son yorumlara bakar. Puan bütün bölümlerin ortak karnesidir; tek bir kötü gün düzelene kadar sayfada kalabilir.","iliskili":["go-6-029","go-6-030"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"},{"id":"go-6-029","konu":"6.2","terim":"Olumsuz yoruma yanıt kuralları","ingilizce":"Rules for responding to negative reviews","tanim":"Eleştirel bir yoruma saygılı, kısa, çözüm gösteren ve kişisel bilgi vermeyen bir yanıt yazma ilkeleridir.","ornek":"Yorumda “resepsiyon ilgisizdi” yazılmış; müdür “Yaşadığınız olumsuz deneyim için üzgünüz, ekibimizle konuştuk, bir dahaki ziyaretinizde sizi daha iyi ağırlamak isteriz” diye yanıtlar.","sektor":"Yanıtı yalnız yorumu yazan değil, oteli araştıran herkes okur. Teşekkür et, özür dile, çözümü söyle; tartışma, alay ya da konuğun oda numarası ve tarihi gibi bilgilerini yazma. Yanıtı yetkili yazar; sen yorumu amirine iletirsin.","iliskili":["go-6-028","go-6-032"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"},{"id":"go-6-030","konu":"6.2","terim":"Sahte yorum","ingilizce":"Fake review","tanim":"Gerçek bir konaklamaya dayanmayan ya da karşılığında ödeme veya hediye verilerek yazdırılan yorumdur.","ornek":"Bir otel çalışanı, otelini öven beş yorumu farklı adlarla siteye yükler ya da rakip otele kötü yorum yazar.","sektor":"Bu davranış etik dışıdır; yorum siteleri sahte yorumu bulup sayfayı cezalandırabilir ve birçok ülkede hukuki yaptırımı da vardır. Konuk bir gün fark eder, kaybedilen güven geri gelmez. Sahte yorum görürsen amirine bildirirsin.","iliskili":["go-6-028","go-6-031"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"},{"id":"go-6-031","konu":"6.2","terim":"Yorumu etik biçimde isteme","ingilizce":"Asking for reviews ethically","tanim":"Konuğa deneyimini paylaşması için, karşılığında ödül vaat etmeden ve yalnız memnun olanları seçmeden hatırlatma yapmaktır.","ornek":"Çıkışta resepsiyonist her konuğa QR kodlu bir kart uzatır: “Deneyiminizi paylaşmak isterseniz bu kod sizi yorum sayfasına götürür.”","sektor":"Konuk gönüllü ve dürüst yazmalıdır. Yorum karşılığında indirim vermek ya da yalnız memnun konuğa kart uzatmak birçok yorum sitesinin kurallarına aykırıdır ve puanı gerçeğinden uzaklaştırır.","iliskili":["go-6-030","go-6-028"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"},{"id":"go-6-032","konu":"6.2","terim":"Sosyal medyada itibar krizi","ingilizce":"Social media reputation crisis","tanim":"Bir olayın kısa sürede çok kişiye yayılıp otelin adını olumsuz anılır hâle getirdiği durumdur.","ornek":"Bir konuk havuz başında yaşadığı olayı video olarak paylaşır; bir günde çok sayıda kişi izler ve otelin hesabına öfkeli yorumlar yağar.","sektor":"Böyle durumda otelin tek ağızdan, hızlı ve dürüst konuşması gerekir; bunu genel müdür ya da pazarlama yöneticisi yönetir. Çalışan olarak olay hakkında kendi hesabından yazmaz, soru gelirse yetkiliye yönlendirirsin.","iliskili":["go-6-029","go-6-025"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"},{"id":"go-6-033","konu":"6.2","terim":"Fotoğraf ve görsel dürüstlüğü","ingilizce":"Honest imagery","tanim":"Otelin sitede ve sosyal medyada gösterdiği görsellerin odanın, manzaranın ve hizmetin gerçek hâlini yansıtmasıdır.","ornek":"Sitede “deniz manzaralı” diye gösterilen odanın gerçekte otoparka bakması konuğu check-in anında hayal kırıklığına uğratır.","sektor":"Fotoğraf güzel olabilir, ama yanıltıcı olmamalıdır. Yapay zekâyla üretilmiş ya da fazlasıyla düzenlenmiş bir görsel gerçeği değiştiriyorsa dürüst sayılmaz; konuk odaya girdiğinde gördüğü fark yoruma dönüşür.","iliskili":["go-6-034","go-6-015"],"kontrol":null,"kitapDisi":true},{"id":"go-6-034","konu":"6.2","terim":"Konuk fotoğrafı izni","ingilizce":"Guest photo consent","tanim":"Otelin, konuğun görüntüsünün olduğu bir fotoğrafı ya da videoyu paylaşmadan önce konuktan izin almasıdır.","ornek":"Akşam yemeğinde doğum günü kutlaması çekilir; sosyal medya sorumlusu paylaşmadan önce konuktan izin alır.","sektor":"Konuğun görüntüsü kişisel veridir; izinsiz paylaşım mahremiyeti ve veri koruma ilkelerini zedeler; çocuk görüntülerinde özen daha da önemlidir. Stajyer olarak konuk fotoğrafı çekip paylaşmazsın; güzel bir an gördüysen yetkiliye söylersin.","iliskili":["go-6-025","go-6-056"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"},{"id":"go-6-035","konu":"6.2","terim":"E-posta bülteni","ingilizce":"Email newsletter","tanim":"Otelin kayıtlı konuklara ve abonelere yeni paket, kampanya ve haberleri düzenli e-postayla göndermesidir.","ornek":"Eylülde Çeşme’deki otel geçmiş konuklarına “sonbahar sakinliği” paketini anlatan bir e-posta gönderir.","sektor":"Pazarlamanın en düşük maliyetli yollarından biridir ve çoğu zaman tekrar konuğu getirir. Yalnız izin vermiş kişilere gönderilir; her e-postada abonelikten çıkma bağlantısı bulunur.","iliskili":["go-6-036","go-6-053"],"kontrol":null,"kitapDisi":true,"cizim":"dijital"},{"id":"go-6-036","konu":"6.2","terim":"İzinli pazarlama","ingilizce":"Permission-based marketing","tanim":"Konuğa tanıtım mesajını yalnız bu iletileri almayı açıkça kabul ettiyse göndermedir.","ornek":"Rezervasyon formunda “Kampanyalardan haberdar olmak istiyorum” kutusu boş gelir; konuk kendisi işaretlerse listeye eklenir.","sektor":"İzin bir kez verilir, ama istenirse geri alınır. Rezervasyon için verilen e-posta adresini izinsiz tanıtım listesine eklemek hem konuğu rahatsız eder hem de genellikle veri koruma ve ticari ileti kurallarına aykırıdır.","iliskili":["go-6-035","go-6-056"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"go-6-037","konu":"6.3","terim":"Satış hunisi","ingilizce":"Sales funnel","tanim":"Konuğun oteli fark etmesinden rezervasyon yapmasına kadar geçtiği ve her adımda bir kısmının vazgeçtiği, huni biçimli süreçtir.","ornek":"Yüz kişi otelin sitesine bakar, yirmisi odaları inceler, ikisi rezervasyon yapar; kaybın en büyük olduğu adım düzeltilecek yeri gösterir.","sektor":"Satışçı huniyi izleyerek konuğun nerede vazgeçtiğini görür: sitede mi, fiyatta mı, ödemede mi? Amaç her adımı kolaylaştırmaktır, konuğu zorlamak değil.","iliskili":["go-6-038","go-6-022"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"go-6-038","konu":"6.3","terim":"Konuğun ihtiyacını sorma","ingilizce":"Needs discovery","tanim":"Satışa geçmeden önce konuğun neden geldiğini ve neye önem verdiğini soru sorarak anlama adımıdır.","ornek":"Telefonda rezervasyon görevlisi “Bu seyahat tatil mi, iş mi? Kimlerle geliyorsunuz?” diye sorar ve yanıta göre sessiz bir oda önerir.","sektor":"Soru sormadan yapılan satış çoğu zaman yanlış odayı satar. İhtiyacı dinleyen satışçı doğru ürünü önerdiği için güven kazanır.","iliskili":["go-6-037","go-6-039"],"kontrol":null,"kitapDisi":true},{"id":"go-6-039","konu":"6.3","terim":"Ek satış fırsatı anları","ingilizce":"Upselling and cross-selling moments","tanim":"Rezervasyon sırasında, varış öncesi e-postada, check-in’de ve konaklama boyunca konuğa değer katacak bir üst oda ya da ek hizmet önerisi sunulabilen zaman dilimleridir.","ornek":"Rezervasyon görevlisi yıl dönümü için gelen çifte “Odaya çiçek hazırlayabiliriz” der; check-in’de resepsiyonist “Bugün deniz manzaralı oda müsait” diye önerir.","sektor":"Her anın en iyi teklifi farklıdır ve konuğun durumuna uymalıdır. Otelcilik ve Seyahat Hizmetleri dersinde gördüğün upselling (daha üst bir oda tipinin fiyat farkıyla önerilmesi) bu anlardan biridir; farklı bir hizmet önermek ise çapraz satıştır. İki durumda da teklif önce konuğun yararı ölçüsünde yapılır.","iliskili":["go-6-040","go-6-041"],"kontrol":null,"kitapDisi":true},{"id":"go-6-040","konu":"6.3","terim":"Çapraz satış","ingilizce":"Cross-selling","tanim":"Konuğa odasının yanında farklı bir hizmet, örneğin spa, akşam yemeği ya da transfer önermektir.","ornek":"Resepsiyonist iki gece kalacak çifte “Bir akşam deniz kenarındaki restoranımızda masa ayırtalım mı?” diye sorar.","sektor":"Çapraz satış oteli bir hizmetler bütünü olarak gösterir ve konuk parasını otelin dışında değil içinde harcar. İhtiyaca uymayan teklif ise rahatsız eder.","iliskili":["go-6-039","go-6-041"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"go-6-041","konu":"6.3","terim":"Konuğa değer katan satış","ingilizce":"Value-adding selling","tanim":"Satış önerisinin önce konuğun ihtiyacına yaraması, otelin kazancının da ancak bunun sonucunda gelmesi gerektiğini söyleyen ilkedir.","ornek":"Bebekle gelen aileye pahalı bir süit yerine yan yana odalar ve bebek yatağı önerilir; çünkü aileye en çok bu yarar sağlar.","sektor":"Gereksiz şey satan kısa vadede kazanır, uzun vadede yorum ve güven kaybeder. Konuk “hayır” derse ısrar edilmez; ayırttığı oda aynı güler yüzle verilir.","iliskili":["go-6-039","go-6-042"],"kontrol":null,"kitapDisi":true},{"id":"go-6-042","konu":"6.3","terim":"Aşırı vaat tuzağı","ingilizce":"Over-promising","tanim":"Satış sırasında gerçekte karşılanamayacak bir şeyi söyleyerek konuğun beklentisini fazla yükseltmektir.","ornek":"Telefonda “Odanız plaja iki adım” deyip yolun karşısındaki odayı satan görevli konuk gelince şikâyetle karşılaşır.","sektor":"Beklenti ile yaşanan arasındaki fark memnuniyeti belirler. Satışta gerçekçi vaat edip sözünden fazlasını vermek güven kazandırır; emin olmadığın bir özelliği konuğa söz verme, amirine sor.","iliskili":["go-6-041","go-6-043"],"kontrol":null,"kitapDisi":true,"cizim":"trofe-odul"},{"id":"go-6-043","konu":"6.3","terim":"Fiyat şeffaflığı","ingilizce":"Price transparency","tanim":"Konuğun ödeyeceği toplam bedeli, ek ücretler dâhil, rezervasyondan önce açıkça görmesidir.","ornek":"Sitede düşük görünen oda fiyatı, ödeme adımında ek bir hizmet bedeli eklenince yükselirse konuk kandırıldığını düşünür; baştan toplam fiyat yazılırsa bu şikâyet doğmaz.","sektor":"Gizli ücret güveni kırar ve yorumlarda sık yazılan öfke nedenlerindendir. Birçok ülkenin tüketici kuralları da fiyatın açık gösterilmesini ister.","iliskili":["go-6-003","go-6-042"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"go-6-044","konu":"6.3","terim":"Erken rezervasyon kampanyası","ingilizce":"Early booking offer","tanim":"Konuğun konaklamasından çok önce rezervasyon yapması karşılığında daha uygun fiyat sunulan kampanyadır.","ornek":"Mart sonuna kadar yapılan yaz rezervasyonlarında fiyat daha uygundur; iptal ve değişiklik koşulları fiyatın yanında açıkça yazılıdır.","sektor":"Otel erken gelir ve doluluk güvencesi kazanır, konuk daha uygun fiyat bulur. Kampanyanın tarihi, iptal ve değişiklik koşulları söylenmezse sonradan itiraz doğar.","iliskili":["go-6-019","go-6-020"],"kontrol":null,"kitapDisi":true,"cizim":"doga"},{"id":"go-6-045","konu":"6.3","terim":"Sadakat programının seviyeleri","ingilizce":"Loyalty programme tiers","tanim":"Üyeleri konaklama sayısına ya da harcamasına göre basamaklara ayıran ve üst basamağa daha fazla ayrıcalık tanıyan düzendir.","ornek":"Bir zincirin programında üye konuk yılda belli sayıda gece kaldıkça “gümüş”, sonra “altın” basamağa çıkar; altın üye, geç çıkış ve oda yükseltme gibi ayrıcalıklar kazanır.","sektor":"Basamak adları programdan programa değişir, ama mantık aynıdır. Üyenin basamağını otelin sisteminden (çoğu otelde PMS) görüp ayrıcalığını eksiksiz vermek çalışanın işidir; unutulan bir ayrıcalık sadık konuğu en çok kırar.","iliskili":["go-6-046","go-6-047"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"go-6-046","konu":"6.3","terim":"Tekrar konuk oranı","ingilizce":"Repeat guest rate","tanim":"Bir dönemde konaklayan konuklar içinde daha önce de gelmiş olanların payıdır.","ornek":"Aydın’daki bir termal otelde bu yıl 400 konuktan 100’ü daha önce de geldiyse tekrar konuk oranı %25’tir.","sektor":"Yeni konuk bulmak reklam ve komisyon harcatır; tekrar konuk pazarlamayı ucuzlatır. Oran düşüyorsa memnuniyette bir sorun olabilir.","iliskili":["go-6-045","go-6-047"],"kontrol":null,"kitapDisi":true},{"id":"go-6-047","konu":"6.3","terim":"Ağızdan ağıza pazarlama","ingilizce":"Word-of-mouth marketing","tanim":"Memnun konukların oteli arkadaşlarına, ailesine ve internette başkalarına tavsiye etmesiyle gelen tanıtımdır.","ornek":"Mardin’deki butik otelde ağırlanan çift dönüşte komşusuna “Kahvaltı terasını görmelisin” der; komşu aynı otele rezervasyon yapar.","sektor":"Parayla satın alınamayan, en güvenilir tanıtım yollarından biridir; konuk tavsiyesi çoğu zaman reklamdan daha inandırıcı bulunur. Bu yüzden her çalışanın her konuğa davranışı pazarlama sayılır.","iliskili":["go-6-005","go-6-046"],"kontrol":null,"kitapDisi":true},{"id":"go-6-048","konu":"6.3","terim":"Kurumsal müşteri satışı","ingilizce":"Corporate account sales","tanim":"Satış ekibinin şirketlerle görüşüp çalışanlarının seyahatlerinde oteli seçmelerini sağlamaya çalıştığı satış çalışmasıdır.","ornek":"Ankara’daki bir otelin satış yöneticisi bir inşaat şirketinin satın alma bölümüyle buluşup şehre gelen mühendisler için fiyatı, toplantı salonunu ve iptal koşullarını konuşur.","sektor":"Kurumsal anlaşma bu görüşmenin sonucudur. Satışçı şirketin ihtiyacını sorar ve otelin sağlayamayacağı bir şeyi vaat etmez; bu müşteri yıl boyu düzenli gelir getirebilir.","iliskili":["go-6-008","go-6-049"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"go-6-049","konu":"6.3","terim":"Grup satışı","ingilizce":"Group sales","tanim":"Düğün, tur grubu, spor takımı ya da şirket toplantısı gibi birçok odayı birlikte tutan kalabalıklara özel koşullarla satış yapmaktır.","ornek":"Bahar aylarında bir spor kulübü Belek’teki otelde bir haftalık kamp yapar; satış ekibi oda, yemek ve antrenman salonunu tek teklifte sunar.","sektor":"Tek satışla çok oda dolar, ama grubun ihtiyaçları (aynı kat, erken kahvaltı) önceden hazırlık ister. Toplantı ve etkinlik grupları da bu başlık altında satılır.","iliskili":["go-6-050","go-6-048"],"kontrol":null,"kitapDisi":true},{"id":"go-6-050","konu":"6.3","terim":"Grup oda bloğu","ingilizce":"Room block and cut-off date","tanim":"Otelin bir grup için belirli sayıda odayı belirli bir tarihe kadar ayırması, o tarihe kadar rezerve edilmeyen odaların satışa geri dönmesidir.","ornek":"Bir kongre için İzmir’deki otel elli odayı gruba ayırır; son tarih geldiğinde ayrılmayan odalar genel satışa açılır.","sektor":"Blok hem oteli hem grubu korur: otel odayı boşa tutmaz, grup üyesi odasını güvenceye alır. Son tarih kaçarsa konuk oda bulamaz ya da otel gelir kaybeder.","iliskili":["go-6-049","go-6-048"],"kontrol":null,"kitapDisi":true},{"id":"go-6-051","konu":"6.4","terim":"Konuk verisi türleri","ingilizce":"Types of guest data","tanim":"Otelin konuk hakkında topladığı kimlik, iletişim, rezervasyon, ödeme, tercih ve davranış bilgilerinin gruplarıdır.","ornek":"Bir konuk için ad ve telefon kimlik-iletişim verisidir, “tüy yastık istemez” notu tercih verisidir, en çok spayı kullanması ise davranış verisidir.","sektor":"Her veri türünün koruma düzeyi ve tutulma amacı farklıdır. Çalışan olarak bilgi toplamadan önce “bunu neden istiyorum?” diye sorarsın.","iliskili":["go-6-052","go-6-053"],"kontrol":null,"kitapDisi":true,"cizim":"veri-guvenlik"},{"id":"go-6-052","konu":"6.4","terim":"Özel nitelikli kişisel veri","ingilizce":"Sensitive personal data","tanim":"Sağlık, din, etnik köken gibi öğrenildiğinde kişiye zarar verebilecek ve bu yüzden daha sıkı korunan kişisel veri türleridir.","ornek":"Konuk “glüten alerjim var” dediğinde bu bir sağlık bilgisidir; mutfağa “glütensiz hazırlanacak” diye kısaca iletilir, tıbbi ayrıntı yayılmaz.","sektor":"Alerji notu hayat kurtarabilir, ama herkesin görmemesi gerekir: yalnız konuyu bilmesi gerekenlere, ihtiyacı kadar iletilir. Yeni bir veri toplamadan önce amirine sorarsın.","iliskili":["go-6-051","go-6-061"],"kontrol":null,"kitapDisi":true,"cizim":"veri-guvenlik"},{"id":"go-6-053","konu":"6.4","terim":"Konuk ilişkileri yazılımı (CRM)","ingilizce":"Customer relationship management (CRM)","tanim":"Konukların iletişim bilgisini, geçmiş konaklamalarını, tercihlerini ve temaslarını bir arada tutan, ilişkiyi yönetmeye yarayan yazılımdır.","ornek":"Satış ofisindeki görevli CRM’den “son iki yılda Kapadokya’da kalan, tanıtım izni vermiş” konukları listeler ve sonbahar paketini yalnız onlara gönderir.","sektor":"PMS konaklamanın işlemini, CRM ise konukla ilişkiyi tutar; birçok otelde ikisi birbirine bağlıdır. Bağlı sistemde bir yerde yanlış girilen bilgi öbürüne de gider.","iliskili":["go-6-051","go-6-054"],"kontrol":null,"kitapDisi":true,"cizim":"dijital"},{"id":"go-6-054","konu":"6.4","terim":"Kişiselleştirme ile gizlilik dengesi","ingilizce":"Personalisation versus privacy","tanim":"Konuğa özel hizmet sunarken onun hangi bilgisinin ne kadar kullanılacağını sınırlı tutma dengesidir.","ornek":"Doğum günü notu gören görevli odaya pasta bırakır; ama konuğun yaşını ya da harcamalarını başka konuklara söylemez.","sektor":"Aşırı kişiselleştirme konuğa izlendiği hissini verir; hiç yapılmaması ise soğuk bırakır. İyi otel konuğun kendi verdiği bilgiyi, verilme amacına uygun kullanır.","iliskili":["go-6-053","go-6-057"],"kontrol":null,"kitapDisi":true,"cizim":"veri-guvenlik"},{"id":"go-6-055","konu":"6.4","terim":"KVKK ve GDPR’nin ortak ilkeleri","ingilizce":"Common data protection principles (KVKK and GDPR)","tanim":"Türkiye’nin 6698 sayılı kanunu (KVKK) ile Avrupa Birliğinin veri koruma tüzüğünün (GDPR) ortak ilkeleri; verinin hukuka uygun alınması, belirli amaçla kullanılması, gerektiği kadar toplanması ve gereğinden uzun saklanmamasıdır.","ornek":"Antalya’daki otelin konuk listesinde Türk, Alman ve Rus konuklar vardır; otel hepsine aynı özenle davranır: bilgi gerektiği kadar alınır ve amacı dışında kullanılmaz.","sektor":"Ayrıntılar ülkeden ülkeye ve uygulamadan uygulamaya değişir; öğrenci olarak ilkeleri bilmen yeter. Hukuki soruları işletmenin sorumlusu yanıtlar, emin olmadığında amirine sorarsın.","iliskili":["go-6-056","go-6-057","go-6-058"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-gdpr-klavye"},{"id":"go-6-056","konu":"6.4","terim":"Açık rıza","ingilizce":"Explicit consent","tanim":"Konuğun belirli bir konuda, bilgilendirilerek ve özgür iradesiyle verdiği izindir.","ornek":"Rezervasyon formunda “Kampanya e-postaları almak istiyorum” kutusunu konuk kendisi işaretler.","sektor":"Rıza neyin için verildiğini bilerek verilmelidir ve geri alınabilir. Her veri işleme rıza gerektirmez (örneğin konaklama kaydı, yasal bir yükümlülük olduğu için tutulur), ama pazarlama izni ayrıdır ve önceden işaretlenmiş kutu geçerli rıza sayılmaz.","iliskili":["go-6-057","go-6-036"],"kontrol":null,"kitapDisi":true,"cizim":"veri-guvenlik"},{"id":"go-6-057","konu":"6.4","terim":"Amaçla sınırlılık","ingilizce":"Purpose limitation","tanim":"Bir bilginin yalnız toplanma amacı için kullanılması, başka bir iş için kullanılmamasıdır.","ornek":"Kimlik bilgisi konuk kaydı için alınmıştır; satış ekibi bu bilgiyi doğum günü kampanyası göndermek için kullanmaz.","sektor":"Konuk bir bilgiyi bir amaç için verir; başka amaca geçmek için yeniden izin gerekir. Konuğun güvenini bu ilke korur.","iliskili":["go-6-056","go-6-058"],"kontrol":null,"kitapDisi":true,"cizim":"pasaport"},{"id":"go-6-058","konu":"6.4","terim":"Gerektiği kadar veri","ingilizce":"Data minimisation","tanim":"Yalnız işin yapılması için gerekli bilginin alınması, fazlasının istenmemesidir.","ornek":"Oda ayırtmak için ad, tarih ve iletişim bilgisi yeterliyken formda meslek ve gelir sorulması gereksizdir.","sektor":"Ne kadar az veri tutulursa sızıntıda o kadar az zarar olur. Formu hazırlayan kişi her alan için “bu bilgiyi neden alıyoruz?” sorusunu yanıtlayabilmelidir.","iliskili":["go-6-057","go-6-059"],"kontrol":null,"kitapDisi":true,"cizim":"veri-guvenlik"},{"id":"go-6-059","konu":"6.4","terim":"Verinin saklama süresi","ingilizce":"Data retention period","tanim":"Kişisel verinin ne kadar süre tutulup sonra silineceğinin ya da yok edileceğinin belirlenmesidir.","ornek":"Otel, rezervasyon yapmış ama hiç gelmemiş konukların eski kayıtlarını belirlenen sürenin sonunda siler.","sektor":"Süre mevzuata ve işletmenin politikasına göre değişir; çalışan rakam ezberlemez, işletmenin kuralını uygular. Gereksiz eski veri hem yük hem risktir.","iliskili":["go-6-058","go-6-060"],"kontrol":null,"kitapDisi":true,"cizim":"saat-zaman"},{"id":"go-6-060","konu":"6.4","terim":"Konuğun kendi verisi üzerindeki hakları","ingilizce":"Data subject rights","tanim":"Kişinin otelin elindeki bilgilerini öğrenme, yanlışsa düzeltme ve belli koşullarda silinmesini isteme haklarıdır.","ornek":"Eski bir konuk e-postayla “Bende hangi bilgiler var, adresimi yanlış yazmışsınız” diye sorar; resepsiyonist kendi başına yanıt vermez, talebi sorumluya iletir.","sektor":"Bu talepler yasal bir süreçtir; çalışan bilgi vermez ya da silmez, talebi doğru kişiye yönlendirir. Hızlı ve saygılı yanıt konuğun güvenini artırır.","iliskili":["go-6-059","go-6-055"],"kontrol":null,"kitapDisi":true,"cizim":"etik-terazi"},{"id":"go-6-061","konu":"6.4","terim":"Bilmesi gereken kadar erişim","ingilizce":"Need-to-know access","tanim":"Bir çalışanın konuk verisine yalnız görevi için gerektiği ölçüde ulaşabilmesidir.","ornek":"Kat görevlisi sistemde oda durumunu görür, ama konuğun kart bilgisini görmez; kart bilgisi yalnız ödemeyle ilgilenen görevlilerin ekranında, o da çoğu zaman kısmen gizli görünür.","sektor":"Merak ya da şaka için konuk kaydına bakmak da ihlaldir; birçok sistemde kimin neye baktığı kaydedilir. Telefondaki biri bir konuğun otelde kalıp kalmadığını ya da oda numarasını sorarsa bilgi vermezsin; mesajını alıp nöbetçi müdüre iletirsin. Parolanı paylaşmaz, ekranı açık bırakmazsın.","iliskili":["go-6-052","go-6-062"],"kontrol":null,"kitapDisi":true},{"id":"go-6-062","konu":"6.4","terim":"İki adımlı doğrulama","ingilizce":"Two-step verification","tanim":"Parolaya ek olarak telefona gelen kod gibi ikinci bir kanıt isteyen giriş korumasıdır.","ornek":"Satış ofisindeki görevli e-posta hesabına girerken parolanın ardından telefonuna gelen altı haneli kodu da yazar.","sektor":"Parola çalınsa bile hesabın açılmasını zorlaştırır. Kodu hiç kimseyle, “bilgi işlemdenim” diyen biriyle bile paylaşmazsın.","iliskili":["go-6-061","go-6-063"],"kontrol":null,"kitapDisi":true,"cizim":"veri-guvenlik"},{"id":"go-6-063","konu":"6.4","terim":"Otel adına gönderilen sahte ödeme mesajı","ingilizce":"Phishing message impersonating a hotel","tanim":"Otelmiş gibi görünüp konuğu kart bilgisi vermeye ya da sahte bir bağlantıdan ödeme yapmaya çağıran dolandırıcılık mesajıdır.","ornek":"Konuk rezervasyonundan bir gün sonra mesajla “Ödemeniz başarısız, hemen bu bağlantıdan yenileyin” yazısı alır ve otele telefon ederek doğrulatır.","sektor":"Bu tür sahte mesajlara oltalama (phishing) denir; oteller de taklit edilen hedeflerdendir. Kart numarasını düz mesajla istemek güvenli değildir; şüpheli mesajı bildiren konuğa teşekkür eder, durumu amirine iletirsin. Aynı yöntemle çalışanlara da “parolanı güncelle” diyen sahte iç iletiler gelir: bağlantıya tıklamaz, yanıt vermez, amirine ve bilgi işleme bildirirsin.","iliskili":["go-6-062","go-6-064"],"kontrol":null,"kitapDisi":true,"cizim":"veri-guvenlik"},{"id":"go-6-064","konu":"6.4","terim":"Veri ihlali","ingilizce":"Data breach","tanim":"Konuk bilgilerinin izinsiz kişilerin eline geçmesi, kaybolması ya da değiştirilmesidir.","ornek":"Bir çalışan konuk listesi olan dosyayı yanlışlıkla yabancı birine e-postayla gönderir; fark eder etmez amirine bildirir.","sektor":"İhlali saklamak durumu büyütür. Bildirimin nasıl ve kimlere yapılacağını işletme mevzuata göre yürütür; çalışanın görevi fark ettiği anda durumu süslemeden amirine söylemektir.","iliskili":["go-6-063","go-6-061"],"kontrol":null,"kitapDisi":true,"cizim":"veri-guvenlik"},{"id":"go-6-065","konu":"6.4","terim":"Otel sohbet robotu","ingilizce":"Hotel chatbot","tanim":"Otelin internet sitesinde ya da mesajlaşma hattında konuğun sorularını yazılı olarak cevaplayan yapay zekâ ya da kural tabanlı programdır.","ornek":"Gece 02.00’de bir konuk “Kahvaltı kaçta başlıyor?” diye yazar; robot saati anında söyler.","sektor":"Sık sorulan soruları günün her saatinde yanıtlayarak ekibe zaman bırakır. Robot yanlış bilgi verebilir; içeriğini güncel tutmak insanların işidir ve şikâyet ya da acil durumda konuk hemen bir insana aktarılmalıdır.","iliskili":["go-6-066","go-6-069"],"kontrol":null,"kitapDisi":true},{"id":"go-6-066","konu":"6.4","terim":"İnsana devir","ingilizce":"Human handover","tanim":"Bir yazılımın ya da robotun çözemediği durumu ayırt edip konuğu bir çalışana yönlendirmesidir.","ornek":"Sohbet robotuna “Çocuğum rahatsız, doktor lazım” yazan konuk saniyeler içinde nöbetçi müdüre yönlendirilir ve müdür onu arar.","sektor":"Devir kolay ve hızlı olmalıdır; konuk aynı şeyi yeniden anlatmak zorunda kalmamalıdır. Acil durumda otomasyon beklenmez: 112 ve nöbetçi müdür hemen devreye girer.","iliskili":["go-6-065","go-6-069"],"kontrol":null,"kitapDisi":true,"cizim":"el-yikama"},{"id":"go-6-067","konu":"6.4","terim":"Algoritmik fiyat önerisi","ingilizce":"Algorithmic price recommendation","tanim":"Bir yazılımın talebe, tarihe ve rakip fiyatlarına bakarak gelir müdürüne bir oda fiyatı önermesidir.","ornek":"Yazılım cuma gecesi konser nedeniyle yüksek talep görür ve fiyat artışı önerir; gelir müdürü öneriyi inceler, uygunsa onaylar.","sektor":"Dinamik fiyatlamada kullanılan araçlardan biridir. Yazılım öneri verir, karar insandadır; hatalı veri ya da olağandışı olay yanlış öneri doğurabilir. Konuk fiyat farkını sorarsa fiyatların talebe göre değişebildiğini sakin ve dürüstçe anlatırsın, gerisini amirine bırakırsın.","iliskili":["go-6-068","go-6-069"],"kontrol":null,"kitapDisi":true,"cizim":"dijital"},{"id":"go-6-068","konu":"6.4","terim":"Yapay zekâ destekli kişisel öneri","ingilizce":"AI-powered personal recommendation","tanim":"Konuğun geçmiş tercihlerinden yola çıkarak ona uygun restoran, etkinlik ya da paket öneren yazılım özelliğidir.","ornek":"Otelin uygulamasına giren çocuklu bir aileye “Çocuk kulübü açık, akşam yemeği 19.00’da başlıyor” önerisi çıkar; çünkü yazılım rezervasyondan aile olarak geldiklerini bilir.","sektor":"Öneri konuğa yarıyorsa değerlidir; konuğun bilmediği verilerle yapılıyorsa ürkütücüdür. Hangi verinin kullanıldığı açık söylenmeli, isteyen konuk öneriyi kapatabilmelidir. Öneri yanlış da olabilir; son karar konuğundur.","iliskili":["go-6-054","go-6-067"],"kontrol":null,"kitapDisi":true,"cizim":"yapay-zeka"},{"id":"go-6-069","konu":"6.4","terim":"Otomasyonun sınırı","ingilizce":"Limits of automation","tanim":"Makinenin hızlı yapabildiği işler ile duygu, yargı ve özel durum gerektirdiği için insana kalan işler arasındaki çizgidir.","ornek":"Kiosk check-in işlemini hızla yapar; ama bebeğiyle bekleyen annenin telaşını fark edip lobide ona çay ikram edecek kişi çalışandır.","sektor":"Rutin işleri otomasyon alır; özel durum, şikâyet ve duygu gerektiren işler insana kalır. Geleceğin otelcisi hem teknolojiyi iyi kullanan hem de insanı iyi anlayan kişidir.","iliskili":["go-6-066","go-6-068"],"kontrol":null,"kitapDisi":true}],"sorular":[{"id":"go-6-s01","tur":"coktan-secmeli","soru":"Bir butik otel fotoğraflarında lüks bir ürün gösteriyor, odalarını çok düşük fiyata satıyor ve internet sitesi özensiz. Pazarlama karması (4P) açısından asıl sorun nedir?","secenekler":["Yalnızca otelin konumunun yanlış seçilmiş olması","Satış kanallarının hiç bulunmaması","Ürün, fiyat ve tutundurma kararlarının birbiriyle çelişmesi","Otel ürününün yalnız odadan ibaret sayılması"],"dogru":2,"aciklama":"Dört karar aynı hikâyeyi anlatmalıdır; lüks görüntü ile çok düşük fiyat yan yana gelince konuk güvenmez. Konum tek başına bu çelişkiyi açıklamaz."},{"id":"go-6-s02","tur":"coktan-secmeli","soru":"Alanya’daki bir aile resortu çocuk kulübünü ve sığ havuzu öne çıkarıyor, tek başına gelen iş seyahatçisini öncelikli hedef almıyor. Otel burada hangi kararı vermiştir?","secenekler":["Rakiplerin fiyatını izleyip kendi fiyatını onlarla eşitlemiştir","Konuk verisini kişiselleştirme için toplamaya başlamıştır","Yüksek sezon tarihlerini yeniden belirlemiştir","Hedef kitlesini seçmiş ve ürününü ona göre şekillendirmiştir"],"dogru":3,"aciklama":"Ürünün öncelikle kime sunulacağına karar vermek hedef kitle seçmektir. Rakip fiyatını izlemek rakip analizidir ve bu kararı anlatmaz."},{"id":"go-6-s03","tur":"coktan-secmeli","soru":"Bir otelin satış ekibi konukları hafta içi iş seyahatçileri, hafta sonu çiftler ve yaz turist grupları diye ayırıyor. Bu pazar bölümlemesi konumlandırmadan nasıl ayrılır?","secenekler":["Bölümleme konukları gruplara ayırır, konumlandırma otelin konuk zihnindeki yerini belirler","Bölümleme otelin konuk zihnindeki yerini belirler, konumlandırma konukları gruplara ayırır","İkisi de yalnız oda fiyatını belirleme çalışmasıdır","Bölümleme yalnız internet satışında, konumlandırma yalnız yüz yüze satışta yapılır"],"dogru":0,"aciklama":"Önce konuklar benzer gruplara ayrılır; konumlandırma ise otelin rakiplerden ayrı ve belirgin bir yer edinmesidir. İki kavramın görevi birbirine karıştırılmamalıdır."},{"id":"go-6-s04","tur":"coktan-secmeli","soru":"Satış ekibi kampanya hazırlamadan önce “Elif, mühendis, iki çocuklu, hafta sonu kaçamağı arıyor” diye kurgusal bir betimleme yazıyor. Bu betimleme (persona) ne işe yarar?","secenekler":["Gerçek bir konuğun bilgilerini arşivleyerek ona özel teklif hazırlamayı sağlar","Mesajı kimin okuyacağını somutlaştırıp metni ona göre yazmayı kolaylaştırır","Rakip otellerin yakın dönemdeki fiyatını tahmin etmeye yardım eder","Konuğun indirim hakkını hesaplayıp sadakat basamağına yerleştirir"],"dogru":1,"aciklama":"Persona kurgusal bir yüzdür; ekibe “bu mesajı kim okuyacak?” sorusunu somut sordurur. Gerçek kişi ya da kimlik verisi içermediği için arşiv sayılmaz."},{"id":"go-6-s05","tur":"coktan-secmeli","soru":"Bodrum’daki bir otel “yetişkinlere özel, sessiz” diye konumlanıyor, ama gece yarısına kadar yüksek sesli müzik çalıyor. Konumlandırma açısından sonuç ne olur?","secenekler":["Konumlandırma yalnızca reklamla kurulduğu için bundan etkilenmez","Sessizlik isteyen konuklar için bu bir ek avantaja dönüşür","Vaat ile yaşanan birbirini tutmadığı için konumlandırma zarar görür","Hedef kitle değiştiği için konumlandırma kendiliğinden yenilenir"],"dogru":2,"aciklama":"Konumlandırma, konuğun yaşadığıyla vaat edilenin örtüşmesiyle kurulur. Sessizlik vaadi veren otelde gürültü, en iyi reklamı bile geçersiz kılar."},{"id":"go-6-s06","tur":"coktan-secmeli","soru":"Otelin logosu, renkleri ve yazışma dili “marka kimliği”dir. Konuğun sitesinden çıkış mesajına kadar bütün temaslardan aklında kalan toplam izlenim ise hangisidir?","secenekler":["Marka vaadi","Değer önerisi","Hedef kitle","Marka deneyimi"],"dogru":3,"aciklama":"Marka deneyimi, konuğun bütün temaslarından hissettiği toplam izlenimdir. Marka vaadi ise otelin önceden verdiği sözdür; deneyim o sözün tutulup tutulmadığını gösterir."},{"id":"go-6-s07","tur":"coktan-secmeli","soru":"Bursa’daki bir termal otel kasım ayında iki gece konaklamayı kahvaltı ve termal havuz girişiyle tek fiyata satıyor. Bu paket sade bir fiyat indiriminden neden farklıdır?","secenekler":["Konaklamaya değer ekleyerek düşük sezonda talep yaratır","Odanın kalitesini biraz azaltarak maliyeti düşürmeyi amaçlar","Yalnız yüksek sezonda uygulanabilen bir fiyat kararıdır","İçeriği açıklanmadan, yalnız toplam fiyatla sunulur"],"dogru":0,"aciklama":"Paket, konaklamaya hizmet ekleyerek konuğa değer katar ve düşük sezonda talebi canlandırır. İçeriğin açık yazılması gerekir; gizli paket güven vermez."},{"id":"go-6-s08","tur":"coktan-secmeli","soru":"Bir otel, reklam parası ödemeden arama sonuçlarında üst sıralarda çıkmak için sitesinde konuğun gerçekten aradığı sözcükleri doğru bilgiyle kullanıyor. Bu çalışmanın adı nedir?","secenekler":["Harita ve yerel arama kaydı","Arama motoru görünürlüğü (SEO)","Rezervasyon motoru","E-posta bülteni"],"dogru":1,"aciklama":"SEO, sitenin reklamsız olarak arama sonuçlarında görünür olmasıdır. Yerel arama kaydı ise otelin harita uygulamalarındaki adres, telefon ve puanlı işletme sayfasıdır."},{"id":"go-6-s09","tur":"coktan-secmeli","soru":"Ayvalık’taki bir otel seyahat içeriği üreten bir hesap sahibine iki gece konaklama verip karşılığında paylaşım yaptırıyor. Paylaşım için hangisi doğru uygulamadır?","secenekler":["İş birliği olduğunun takipçiye açıkça söylenmesi","Paylaşımın daha doğal dursun diye reklam olduğunun belirtilmemesi","Hesap sahibi konaklama karşılığı aldığı için paylaşımın reklam sayılmaması","Paylaşımda yalnız olumlu sözlerin kullanılmasının gizlice şart koşulması"],"dogru":0,"aciklama":"Karşılığı alınmış paylaşımın reklam ya da iş birliği olduğu takipçiye açıkça söylenir. Konaklama da bir karşılık olduğu için “ödeme yok” diye belirtmemek doğru olmaz."},{"id":"go-6-s10","tur":"coktan-secmeli","soru":"Bir konuk yorumunda “resepsiyon ilgisizdi” yazmış. Otel yönetiminin yanıtlarından hangisi yanlıştır?","secenekler":["Yaşadığınız olumsuz deneyim için üzgünüz, ekibimizle konuştuk","Geri bildiriminiz için teşekkür ederiz, sizi daha iyi ağırlamak isteriz","Rezervasyonunuzdaki tarihi ve oda numarasını inceledik, ilgisizlik görmedik","Sizinle iletişime geçmek isteriz, çözümü birlikte konuşabiliriz"],"dogru":2,"aciklama":"Yanıt herkese açıktır; tarih ve oda numarası kişisel bilgidir ve konuğu savunmaya iterek tartışma başlatır. Doğru yanıt saygılı, kısa ve çözüm gösterendir."},{"id":"go-6-s11","tur":"coktan-secmeli","soru":"Hangisi konuktan yorum isterken izlenmesi gereken etik uygulamadır?","secenekler":["Yalnız memnun göründüğü konuklara QR kodlu kart vermek","Yorum yazan konuğa bir sonraki konaklamada indirim vaat etmek","Memnuniyetsiz konuğa şikâyetini yorum sitesine değil otelin kendi formuna yazmasını söylemek","Çıkışta her konuğa, ödül vaat etmeden, yorum sayfasına götüren QR kodlu bir kart vermek"],"dogru":3,"aciklama":"Etik istemede konuk seçilmez ve karşılığında ödül verilmez. Yalnız memnun olanı seçmek ya da memnuniyetsizi başka yöne çekmek puanı gerçek memnuniyetten yüksek gösterir."},{"id":"go-6-s12","tur":"coktan-secmeli","soru":"Sitede “deniz manzaralı” diye gösterilen oda gerçekte otoparka bakıyor. Bu durumda hangi ilke çiğnenmiştir?","secenekler":["Konuk fotoğrafı izni","Fotoğraf ve görsel dürüstlüğü","Fiyat şeffaflığı","İzinli pazarlama"],"dogru":1,"aciklama":"Görsellerin odanın gerçek hâlini yansıtması gerekir; yanıltıcı görsel konuk odaya girince hayal kırıklığına ve olumsuz yoruma dönüşür. Fiyat şeffaflığı ise toplam bedelin baştan görünmesiyle ilgilidir."},{"id":"go-6-s13","tur":"coktan-secmeli","soru":"Bir konuk rezervasyon formunda e-postasını vermiş, ama “Kampanya e-postaları almak istiyorum” kutusunu işaretlememiş. Otel bültenini ona gönderebilir mi?","secenekler":["Gönderemez; e-posta rezervasyon için alınmıştır, tanıtım için ayrı kabul gerekir","Gönderebilir; e-posta verdiği için tanıtım izni vermiş sayılır","Gönderebilir; çünkü konuk daha önce otelde konaklamıştır","Gönderebilir; yeter ki konuğa haber vermeden listeye eklenmiş olsun"],"dogru":0,"aciklama":"İzinli pazarlamada mesaj yalnız bu iletileri almayı açıkça kabul edenlere gönderilir. Rezervasyon için verilen e-posta tanıtım izni anlamına gelmez."},{"id":"go-6-s14","tur":"coktan-secmeli","soru":"Bir otel, sitesine bakanlardan odaları inceleyenlere, onlardan da rezervasyona geçenlere kadar her adımda kaç kişinin vazgeçtiğini izliyor. Bu “satış hunisi” otele ne sağlar?","secenekler":["Konukları seyahat amacına ve bütçesine göre benzer gruplara ayırır","Rakip otellerin fiyatlarını ve yorum puanlarını tek tabloda toplar","Kaybın en çok hangi adımda olduğunu gösterip düzeltilecek yeri belirler","Konuğun kişisel verisinin ne kadar süre saklanacağını belirler"],"dogru":2,"aciklama":"Huni, fark etmekten rezervasyona uzanan adımları ve her adımdaki vazgeçişi gösterir. Konukları gruplara ayırmak ise pazar bölümlemesidir."},{"id":"go-6-s15","tur":"coktan-secmeli","soru":"Telefonda “Odanız plaja iki adım” deyip yolun karşısındaki odayı satan görevli konuk gelince şikâyetle karşılaşıyor. Aşırı vaatin asıl zararı nedir?","secenekler":["Konuk bilgilerinin izinsiz kişilere geçmesi ve veri ihlali yaşanması","Beklenti ile yaşanan arasındaki farkın memnuniyetsizlik doğurması","Otelin fiyatını yasal olarak değiştirmek zorunda kalması","Rezervasyon motorunun artık çalışmaz hâle gelmesi"],"dogru":1,"aciklama":"Karşılanamayacak söz beklentiyi yükseltir; konuk gelince fark memnuniyetsizliğe ve kötü yoruma dönüşür. Sorun veri güvenliği ya da yasal fiyat sorunu değil, güven sorunudur."},{"id":"go-6-s16","tur":"coktan-secmeli","soru":"Bir termal otelde bu yıl 500 konuk ağırlanmış ve bunların 150’si daha önce de gelmiş. Tekrar konuk oranı yüzde kaçtır?","secenekler":["%70","%43","%15","%30"],"dogru":3,"aciklama":"Tekrar konuk oranı, daha önce gelmiş konukların toplam konuk sayısına bölünmesiyle bulunur: 150’yi 500’e bölünce 0,30, yani %30 çıkar. %70 ise ilk kez gelenlerin payıdır."},{"id":"go-6-s17","tur":"coktan-secmeli","soru":"Hangisi veri korumada açık rızaya bir örnektir?","secenekler":["Kutunun önceden işaretli gelmesi ve konuğun kaldırmayı unutması","Konuğun rezervasyon yaparak otelin her türlü iletişimini kabul etmiş sayılması","Formdaki “Kampanya e-postaları almak istiyorum” kutusunu konuğun kendisinin işaretlemesi","Çalışanın kolaylık olsun diye konuğu sormadan listeye eklemesi"],"dogru":2,"aciklama":"Açık rıza, konuğun bilgilendirilerek ve özgür iradesiyle verdiği izindir. Önceden işaretli kutu ya da sessizlik, bilinçli bir seçim olmadığı için rıza sayılmaz."},{"id":"go-6-s18","tur":"coktan-secmeli","soru":"Konuk, rezervasyonundan bir gün sonra otelin adıyla “Ödemeniz başarısız, bu bağlantıdan kartınızı yenileyin” mesajı alıyor. Doğru davranış hangisidir?","secenekler":["Bağlantıya tıklamadan otelin bilinen telefonunu arayıp doğrulatmak","Bağlantıya tıklayıp kart bilgisini yeniden girmek","Mesaja kart numarasını ve güvenlik kodunu yazarak yanıt vermek","Mesajı yakınlarına da iletip onların da kontrol etmesini istemek"],"dogru":0,"aciklama":"Sahte ödeme mesajları otelmiş gibi görünür ve acele ettirir. Bağlantıya tıklamadan, otelin bilinen resmî kanalıyla doğrulamak gerekir."},{"id":"go-6-s19","tur":"dogru-yanlis","soru":"Erken rezervasyon kampanyasında fiyat uygun olsa bile iptal ve değişiklik koşullarının fiyatın yanında açıkça yazılması gerekir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Uygun fiyat tek başına yeterli değildir; koşulları saklamak konuğa verilen sözü eksik bırakır ve güveni kırar."},{"id":"go-6-s20","tur":"dogru-yanlis","soru":"Sitede oda fiyatı düşük gösterilip ek hizmet bedeli yalnız ödeme adımında eklenirse, bu uygulama fiyat şeffaflığına uygundur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Fiyat şeffaflığı, toplam bedelin ek ücretler dâhil rezervasyondan önce görünmesidir. Sonradan eklenen bedel konuğun kandırıldığını düşünmesine yol açar."},{"id":"go-6-s21","tur":"dogru-yanlis","soru":"Kimlik bilgisi konuk kaydı için alınmıştır; bu yüzden satış ekibi aynı bilgiyi doğum günü kampanyası göndermek için de kullanabilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Amaçla sınırlılık ilkesine göre bilgi yalnız toplanma amacı için kullanılır. Başka bir amaç için ayrıca izin gerekir."},{"id":"go-6-s22","tur":"dogru-yanlis","soru":"Sohbet robotu çözemediği bir şikâyet ya da sağlık sorununu konuğu yeniden anlatmaya zorlamadan bir çalışana aktarmalıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Şikâyet, alerji ve acil durumda yargı ve anlayış gerekir. Hızlı insana devir, konuğun aynı şeyi baştan anlatmasını önler."},{"id":"go-6-s23","tur":"senaryo","durum":"Akşam 20.30, havuz başında stajyersin. Bir ailenin çocuğunun doğum günü kutlaması çok güzel; otelin sosyal medya hesabında paylaşılmasını istiyorsun. Hesabı pazarlama yöneticisi yönetiyor.","soru":"Ne yaparsın?","secenekler":["Videoyu çekip kendi hesabımda “harika otel” diye hemen herkese açık paylaşırım.","Videoyu çekip yüzleri bulanıklaştırır, sonra videoyu otelin resmî hesabına kendim yüklerim.","Durumu pazarlama yöneticisine söylerim; çekim ve izin işini yetkili olarak o yürütür.","Ailenin itiraz etmediğini izin sayar, hesabı yöneten arkadaşıma çekmesini söylerim."],"dogru":2,"aciklama":"Konuğun görüntüsü kişisel veridir; çekmek ve paylaşmak için konuğun açık izni ve yetkili kişinin onayı gerekir; stajyerin işi güzel anı yetkiliye iletmektir. İtiraz etmemek izin sayılmaz; bulanıklaştırmak da yetki sorununu çözmez."},{"id":"go-6-s24","tur":"senaryo","durum":"Sabah 09.30, satış ofisinde stajyersin. Yorum sitesinde “Resepsiyonist ilgisizdi” diyen yeni bir yorum görüyorsun; yorumdaki tarih senin vardiyanla aynı güne denk geliyor.","soru":"Ne yaparsın?","secenekler":["Otelin hesabından hemen “Yorum gerçeği yansıtmıyor” diye yanıt yazarım.","Yorumu ve olayı amirime anlatır, yanıtı yetkilinin yazmasını beklerim.","Yorumu yazan konuğu rezervasyon kaydından bulup özel mesajla açıklama yaparım.","Yorumun altına arkadaşımın hesabıyla “Biz çok memnun kaldık” yazdırırım."],"dogru":1,"aciklama":"Yoruma yanıtı yetkili yazar; kayıttan konuğu bulmak veri kurallarını, sahte destek yorumu ise dürüstlüğü çiğner. Olayı amire anlatmak hem dürüst hem çözüm odaklıdır."},{"id":"go-6-s25","tur":"senaryo","durum":"Öğleden sonra 15.00, satış ofisinde stajyersin. Kıdemli bir çalışan telefonunu uzatıp “Otelimiz için beş yıldızlı bir yorum yaz, puanı yükseltelim” diyor.","soru":"Ne yaparsın?","secenekler":["Kıdemli çalışan istediği için beş yıldızlı yorumu kendi telefonumdan yazarım.","Yorumu akrabamın adıyla yazarım, böylece kimin yazdığını gizlerim.","Yorumu yazarım, ama puanı dörde indirip daha inandırıcı olmasını sağlarım.","Nazikçe hayır derim, bunun sahte yorum olduğunu belirtip amirime danışırım."],"dogru":3,"aciklama":"Gerçek bir konaklamaya dayanmayan yorum sahtedir; puanı dörde indirmek ya da başka adla yazmak bunu değiştirmez. Kıdemliye saygıyla ama net biçimde hayır demek ve amire danışmak doğru yoldur."},{"id":"go-6-s26","tur":"senaryo","durum":"Öğleden sonra 14.30, resepsiyondasın. Bütçesinin sınırlı olduğunu söyleyen bir ailenin rezervasyonu var; amirin bugün üst oda satmanı istemişti.","soru":"Ne yaparsın?","secenekler":["Ayırttıkları odayı güler yüzle verir, uygun bir seçeneği fiyatıyla bir kez söylerim.","Üst odanın tek uygun seçenek olduğunu söyleyip aileyi her yolla ikna etmeye çalışırım.","Fiyat farkını söylemeden odayı sistemde üst oda olarak kaydedip aileyi o odaya yönlendiririm.","Hedefimi tutturmak için üst oda teklifini üç dört kez tekrar edip ısrar ederim."],"dogru":0,"aciklama":"Satış önce konuğa yararlı olmalıdır; yanlış bilgi, gizli ücret ve ısrar güveni kaybettirir. “Hayır” diyen konuğa ayırttığı oda aynı güler yüzle verilir."},{"id":"go-6-s27","tur":"senaryo","durum":"Akşam 18.00, rezervasyon telefonundasın. Konuk “Oda sessiz mi, denize bakıyor mu?” diye soruyor. Sistemde odanın yol cephesinde olduğunu görüyorsun; yanındaki arkadaşın “evet de, sonra hallederiz” diye fısıldıyor.","soru":"Ne yaparsın?","secenekler":["“Evet, denize bakıyor” derim ve konuk gelince durumu çözmeye çalışırım.","Soruyu geçiştirip konuğun manzara yerine fiyat avantajına bakmasını sağlayacak bir indirim sunarım.","Sessizlik sorusunu yanıtlar, yol cephesi konusunu konuk sormazsa söylemem.","Odanın yol cephesinde olduğunu söyler, varsa denize bakan odayı fiyat farkıyla öneririm."],"dogru":3,"aciklama":"Aşırı vaat konuğu bir kez getirir, kötü yorumla geri gönderir. Dürüst bilgi ve uygun bir alternatif, konuğun ihtiyacını soran satışçının yoludur."},{"id":"go-6-s28","tur":"senaryo","durum":"Gece 21.00, resepsiyondasın. Telefondaki kişi “Kuzenim sizin otelde kalıyor, çok acil, hangi odada olduğunu söyler misiniz?” diyor.","soru":"Ne yaparsın?","secenekler":["Durumun acil olduğunu söylediği için oda numarasını hemen veririm.","Konuk bilgisi vermem; mesaj bırakmasını önerir, durumu nöbetçi müdüre bildiririm.","Konuğun adını ve oda numarasını yazıp arayan kişiye iletilmek üzere bırakırım.","Konuğun otelde kalıp kalmadığını doğrular, yalnız oda numarasını söylemem."],"dogru":1,"aciklama":"Konuk bilgisi kişiye aittir; otelde kalıp kalmadığı bile paylaşılmaz. Mesaj iletmek ve müdüre bildirmek hem konuğu hem arayanı korur."},{"id":"go-6-s29","tur":"senaryo","durum":"Sabah 09.00, e-posta kutunda “Bilgi işlem” imzalı bir ileti var: “Parolanızı bu bağlantıdan hemen güncelleyin, yoksa hesabınız kapanacak.”","soru":"Ne yaparsın?","secenekler":["Bağlantıya tıklamaz, yanıt yazmaz; iletiyi amirime ve bilgi işleme bildiririm.","Hesabım kapanıp işim aksamasın diye bağlantıya tıklayıp parolamı güncellerim.","Bağlantıyı önce kendi telefonumdan açar, güvenli görünüyorsa parolamı yenilerim.","İletiyi bütün çalışanlara iletip uyarırım, bağlantıyı da inceleyebilsinler diye eklerim."],"dogru":0,"aciklama":"Acele ettirme ve bağlantı istemesi sahte ileti işaretidir; güvenli “görünmesi” bir kanıt değildir. Tıklamamak ve yetkililere bildirmek hesabı ve konuk verisini korur."},{"id":"go-6-s30","tur":"coktan-secmeli","soru":"Bir otel konuklarla ilgili şu bilgileri tutuyor. Hangisi özel nitelikli kişisel veri sayılır ve daha sıkı korunmalıdır?","secenekler":["Konuğun telefon numarası","Konuğun glüten alerjisi","Konuğun yüksek kat isteği","Konuğun en çok spayı kullanması"],"dogru":1,"aciklama":"Sağlık bilgisi özel nitelikli veridir; öğrenildiğinde kişiye zarar verebileceği için yalnız bilmesi gerekenlere, ihtiyacı kadar iletilir. Telefon kimlik-iletişim, kat isteği tercih, spa kullanımı davranış verisidir."},{"id":"go-6-s31","tur":"coktan-secmeli","soru":"Pazartesi akşamı İzmir’deki otele bir yazılım şirketi çalışanı geliyor; masrafını şirketi karşılıyor ve ertesi sabah toplantısı var. Otelin bu konuk için öncelikle öne çıkarması gereken hangisidir?","secenekler":["Akşam eğlence programı ve havuz başı etkinlikleri","Çocuk kulübü ve yan yana bağlantılı aile odaları","Erken kahvaltı, hızlı check-out ve sağlam internet","Uzun konaklama indirimi ve ücretsiz plaj transfer hizmeti"],"dogru":2,"aciklama":"İş seyahatindeki konuk çoğu zaman fiyattan ya da eğlenceden çok kolaylığa bakar; hız, sessizlik ve çalışma imkânı onun için önemlidir. Eğlence programı ve plaj transferi daha çok tatil segmentinin beklentisidir."},{"id":"go-6-s32","tur":"coktan-secmeli","soru":"Bir otel sitesinde “Odanız her zaman sessiz ve tertemiz olacak” diye vaat veriyor. Bu vaadin konukta güven yaratması en çok neye bağlıdır?","secenekler":["Sloganın sitenin her sayfasında büyük harflerle yazılmasına","Reklam bütçesinin bir sonraki sezon artırılmasına","Oda fiyatının rakip otellerden düşük tutulmasına","Çalışanların her konaklamada bunu gerçekten yaşatmasına"],"dogru":3,"aciklama":"Marka vaadi sloganda değil, çalışanın davranışında yaşar; tutulduğunda güven doğar. Vaat tutulmazsa en iyi reklam ya da en görünür slogan bile işe yaramaz."},{"id":"go-6-s33","tur":"coktan-secmeli","soru":"Fethiye’deki bir otelin satış ekibi her ay komşu otellerin fiyatını, kahvaltı saatini ve yorum puanını inceliyor. Bu rakip analizinde doğru yaklaşım hangisidir?","secenekler":["Açık kaynaklardan bilgi toplayıp kendi ayrımını görmek","Rakibin her uygulamasını aynen kopyalayıp onunla eşitlenmek","Rakip otelin çalışanlarından gizli fiyat listelerini istemek","Rakibin sayfasına farklı adlarla olumsuz yorum yazmak"],"dogru":0,"aciklama":"Rakip analizinin amacı rakibi taklit etmek değil, otelin kendi ayrımını görmektir ve bilgi yalnız herkese açık kaynaklardan toplanır. Gizli bilgi istemek ya da sahte yorum yazmak etik dışıdır."},{"id":"go-6-s34","tur":"coktan-secmeli","soru":"Bir otelin sitesindeki rezervasyon motoru PMS ve kanal yöneticisine bağlıdır. Bu bağlantı otele hangi yararı sağlar?","secenekler":["Yorum puanını kendiliğinden yükseltir","Satılan oda her kanalda hemen satışa kapanır","Konuğun kart bilgisini bütün çalışanlara gösterir","Siteyi arama sonuçlarında en üst sıraya taşır"],"dogru":1,"aciklama":"Motor PMS ve kanal yöneticisine bağlı olduğunda sitede satılan oda diğer kanallarda da hemen satışa kapanır. Arama sonuçlarında üst sıraya çıkmak ise rezervasyon motorunun değil, SEO çalışmasının işidir."},{"id":"go-6-s35","tur":"coktan-secmeli","soru":"Bir konuğun havuz başında çektiği video bir günde çok kişiye yayılıyor ve otelin hesabına öfkeli yorumlar geliyor. Bir çalışan olarak doğru davranış hangisidir?","secenekler":["Kendi hesabımdan olayın aslını anlatan uzun bir açıklama yazarım","Videoyu paylaşan konuğa özel mesaj atıp videoyu kaldırmasını isterim","Olay hakkında yazmam, bana gelen soruları yetkiliye yönlendiririm","Otelin hesabına girip öfkeli yorumları tek tek silerim"],"dogru":2,"aciklama":"İtibar krizinde otelin tek ağızdan konuşması gerekir ve bunu genel müdür ya da pazarlama yöneticisi yönetir. Çalışanın kendi hesabından açıklama yazması iyi niyetli olsa da bu tek sesi bozar."},{"id":"go-6-s36","tur":"coktan-secmeli","soru":"Konuklar otelin harita uygulamasındaki kaydında telefon numarasının yanlış olduğunu söylüyor. Bu küçük hata otel için neden önemlidir?","secenekler":["Yoldaki konuk önce bu kayda bakar, ulaşamazsa vazgeçebilir","Kanal yöneticisi bu hata yüzünden odaları satışa kapatır","Yorum puanı yalnız kayıttaki telefon bilgisine göre hesaplanır","Harita kaydı otelin resmî internet sitesinin yerini tamamen alır"],"dogru":0,"aciklama":"Konuk yoldayken ya da şehirdeyken en hızlı harita kaydına bakar; yanlış telefon ya da eski adres kapıdan dönen konuk demektir. Kanal yöneticisinin oda satışı bu kayıttaki bilgiye bağlı değildir."},{"id":"go-6-s37","tur":"coktan-secmeli","soru":"Resepsiyonist, uzun yoldan geldiğini ve çok yorulduğunu söyleyen konuğa ertesi gün için spa randevusu öneriyor. Bu öneri hangi satış türüne örnektir?","secenekler":["Upselling","Grup satışı","Kurumsal müşteri satışı","Çapraz satış"],"dogru":3,"aciklama":"Konuğa odasının yanında spa gibi farklı bir hizmet önermek çapraz satıştır. Upselling ise aynı ihtiyaç için daha üst bir oda tipini fiyat farkıyla önermektir."},{"id":"go-6-s38","tur":"coktan-secmeli","soru":"Bir zincir otelin sadakat programında altın basamaktaki bir üye check-in yapıyor. Resepsiyonistin yapması gereken hangisidir?","secenekler":["Basamağını sistemden görüp ayrıcalığını eksiksiz vermek","Ayrıcalıkları yalnız konuk kendisi sorarsa hatırlayıp vermek","Konuktan üyeliğini kanıtlayan bir belge getirmesini istemek","Üyeliği görmezden gelip standart karşılama yapmak"],"dogru":0,"aciklama":"Üyenin basamağını otelin sisteminden görüp ayrıcalığını eksiksiz vermek çalışanın işidir. Ayrıcalığı konuğun sormasına bırakmak unutulmasına yol açar; unutulan ayrıcalık sadık konuğu en çok kıran şeydir."},{"id":"go-6-s39","tur":"coktan-secmeli","soru":"Oda ayırtma formunu hazırlayan ekip, “gerektiği kadar veri” ilkesine uymak istiyor. Formda hangi alanların bulunması uygundur?","secenekler":["Ad, konaklama tarihleri, iletişim bilgisi, meslek ve aylık gelir","Ad, konaklama tarihleri ve iletişim bilgisi","Ad, meslek, medeni durum ve aylık gelir bilgisi","Sosyal medya hesabı ve meslek"],"dogru":1,"aciklama":"Oda ayırtmak için ad, tarih ve iletişim bilgisi yeterlidir; fazlası istenmez. Meslek ve gelir eklenen seçenek işe gerekmeyen bilgi topladığı için ilkeye aykırıdır."},{"id":"go-6-s40","tur":"coktan-secmeli","soru":"Bir çalışan, konuk listesinin bulunduğu bir dosyanın yanlış kişilerle paylaşıldığını fark ediyor. Doğru davranış hangisidir?","secenekler":["Dosyayı sessizce silmek","Durumu süslemeden hemen amirine bildirmek","Listedeki konukları tek tek arayıp kendisi özür dilemek","Bir sonraki haftalık toplantıyı bekleyip konuyu orada açmak"],"dogru":1,"aciklama":"Veri ihlalinde çalışanın görevi, fark ettiği anda durumu süslemeden amirine söylemektir; bildirimin kimlere nasıl yapılacağını işletme yürütür. Konukları kendi başına aramak bu süreci atlar, ihlali saklamak ise durumu büyütür."},{"id":"go-6-s41","tur":"dogru-yanlis","soru":"Telefonuna gelen iki adımlı doğrulama kodunu, kendini bilgi işlem çalışanı olarak tanıtan birine söylemek güvenlidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İki adımlı doğrulama kodu, parola çalınsa bile hesabı korur; bu yüzden hiç kimseyle, “bilgi işlemdenim” diyen biriyle bile paylaşılmaz."},{"id":"go-6-s42","tur":"dogru-yanlis","soru":"Bir kongre için ayrılan oda bloğunda, belirlenen son tarihe kadar grup üyelerince ayırtılmayan odalar genel satışa açılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Grup oda bloğu belirli bir tarihe kadar geçerlidir; o tarihe kadar rezerve edilmeyen odalar satışa geri döner. Böylece otel odayı boşa tutmamış olur."},{"id":"go-6-s43","tur":"dogru-yanlis","soru":"Algoritmik fiyat önerisinde son kararı yazılım verir; gelir müdürü önerilen fiyatı incelemeden uygular.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yazılım yalnız öneri verir, karar insandadır: gelir müdürü öneriyi inceler, uygunsa onaylar. Hatalı veri ya da olağandışı bir olay yanlış öneri doğurabilir."}],"siralamalar":[{"id":"go-6-r01","konu":"6.2","baslik":"Bir tıkla oda: rezervasyon motorunun içinde","yonerge":"Konuğun otel sitesindeki rezervasyon motorunda yaptığı rezervasyonun adımlarını doğru sıraya koy.","adimlar":["Konuk otelin sitesinde tarihleri ve kişi sayısını yazar: temmuz, iki yetişkin, bir çocuk.","Motor bu tarihlere uygun odaları fiyatlarıyla birlikte listeler.","Konuk listeden kendisine uyan odayı seçer.","Konuk kartıyla ödemeyi tamamlar.","PMS ve kanal yöneticisine bağlı motor sayesinde satılan oda bütün kanallarda satışa kapanır."],"aciklama":"Motor önce boş odayı gösterir, konuk seçip öder; oda ancak satıldıktan sonra öteki kanallarda kapanır ve böylece aynı oda iki kez satılmaz."},{"id":"go-6-r02","konu":"6.3","baslik":"Doğru teklif, doğru an","yonerge":"Bir konuğa ek satış önerisi sunulabilecek anları, konuğun yaşadığı sırayla diz.","adimlar":["Telefonda rezervasyonu alan görevli, yıl dönümü için gelen çifte odaya çiçek hazırlamayı önerir.","Otelin varıştan önce gönderdiği e-posta, konuğa ekleyebileceği hizmetleri tanıtır.","Check-in’de resepsiyonist, müsait olan deniz manzaralı odayı fiyat farkıyla önerir.","Konaklama boyunca konuğun durumuna uyan spa ya da akşam yemeği gibi bir hizmet önerilir."],"aciklama":"Ek satış fırsatları rezervasyondan başlayıp varış öncesi e-posta, check-in ve konaklama boyunca sürer; her anın teklifi konuğun o anki durumuna uymalıdır."},{"id":"go-6-r03","konu":"6.4","baslik":"Yazılım önerir, insan karar verir","yonerge":"Algoritmik fiyat önerisinin oda fiyatına dönüşme adımlarını doğru sıraya koy.","adimlar":["Yazılım talebi, tarihleri ve rakip otellerin fiyatlarını izler.","Şehirdeki konser nedeniyle cuma gecesi talebin yükseldiğini görür.","Gelir müdürüne cuma gecesi için fiyat artışı önerir.","Gelir müdürü öneriyi inceler.","Öneri uygunsa gelir müdürü yeni fiyatı onaylar."],"aciklama":"Yazılım veriye bakıp yalnız öneri verir; hatalı veri ya da olağandışı bir olay yanlış öneri doğurabileceği için fiyat ancak gelir müdürü inceleyip onayladıktan sonra değişir."}],"acikSorular":[{"id":"go-6-y01","konu":"6.2","soru":"Bir otelin yorum sitesinde konuğun yazdığı olumsuz bir yoruma yanıt vermesi gerekiyor. Yanıtta uyulması gereken iki ilkeyi yazınız ve olumsuz yorumdan sonra puanı yükseltmek için sahte yorum yazdırmanın neden yanlış olduğunu açıklayınız.","olcut":[{"metin":"Olumsuz yoruma yanıtta uyulacak ilk ilkeyi (saygılı olma, kısa yazma, çözümü gösterme ya da kişisel bilgi vermeme) belirtir.","puan":15},{"metin":"Birinciden farklı ikinci bir ilkeyi belirtir.","puan":15},{"metin":"Sahte yorumun ne olduğunu (gerçek konaklamaya dayanmayan ya da karşılık verilerek yazdırılan yorum) doğru tanımlar.","puan":20},{"metin":"Sahte yorumun neden yanlış olduğunu, konuğun güveni ve otelin itibarıyla ilişkilendirerek açıklar.","puan":50}],"ornek":"Olumsuz bir yoruma saygılı ve kısa bir yanıt yazılır; yanıtta sorunu çözmek için ne yapılacağı gösterilir ve konuğun kişisel bilgisi paylaşılmaz. Sahte yorum, gerçek bir konaklamaya dayanmayan ya da ödeme veya hediye karşılığı yazdırılan yorumdur. Bu yorum, oteli seçecek konukları yanıltır ve ortaya çıkarsa otelin güvenini ve itibarını zedeler. Bu yüzden puanı yükseltmenin doğru yolu, hizmeti düzeltmektir.","ipucu":"Yanıtı okuyan yalnız şikâyet eden konuk değil, oteli seçmeye karar veren diğer konuklardır; bunu düşünün."},{"id":"go-6-y02","konu":"6.4","soru":"Bir otelin ön büro çalışanı, konukların kimlik, iletişim ve tercih bilgilerini içeren kayıtlara tüm personelin ulaşabildiğini fark ediyor. Bu uygulamanın hangi ilkeye aykırı olduğunu yazınız, bu durumun doğurabileceği bir riski açıklayınız ve çözüm için iki önlem öneriniz. Önlemlerin konuk verisini nasıl koruduğunu da belirtiniz.","olcut":[{"metin":"Aykırı olunan ilkeyi (bilmesi gereken kadar erişim) adlandırır ve ne anlama geldiğini belirtir.","puan":20},{"metin":"Herkesin erişmesinden doğan bir riski (veri ihlali, kötüye kullanım) açıklar.","puan":20},{"metin":"Çözüm için iki farklı önlem önerir (görevine göre yetki, iki adımlı doğrulama vb.).","puan":25},{"metin":"Önerilen önlemlerin konuk verisini nasıl koruduğunu, riskle bağlantı kurarak açıklar.","puan":35}],"ornek":"Bu uygulama, çalışanın konuk verisine yalnız görevi için gerektiği ölçüde ulaşması anlamına gelen bilmesi gereken kadar erişim ilkesine aykırıdır. Herkes her kayda ulaşabilirse bilgiler izinsiz kişilerin eline geçebilir; bu bir veri ihlalidir ve konuğun güvenini sarsar. Önlem olarak her çalışana yalnız görevine uygun erişim yetkisi verilebilir. Ayrıca sisteme girişte parolaya ek olarak iki adımlı doğrulama istenebilir. Böylece konuk verisine ulaşabilenlerin sayısı azalır ve veri daha güvende olur.","ipucu":"Konuk verisine ulaşabilen kişi sayısı arttıkça neyin artacağını düşünün."}]}]`),r=JSON.parse(`[{"ders":"global-otelcilik","onay":true,"diyaloglar":[{"id":"go-d01","unite":2,"baslik":"Lobide Sıcak Karşılama","rol":"Konuk deneyimi görevlisi","sahne":"Sabah 10.00, otelin lobisi. Görevli, koridorun ucundan bebek arabasıyla gelen bir konuğu üç metre kala fark edip göz teması kuruyor ve gülümsüyor. Konuk ilk kez bu otelde kalıyor ve kahvaltı salonunu arıyor.","kavramlar":["go-2-016","go-2-011","go-2-017","go-2-018","go-2-014"],"adimlar":[{"konuk":"Günaydın.","ingilizce":"Good morning.","secenekler":[{"metin":"Günaydın! Kahvaltı salonunu mu arıyorsunuz? Koridorun sonunda.","puan":1,"tepki":"Konuk yönü öğrenir ve yoluna devam eder. Yardım var, fakat hoş geldiniz demek ve ihtiyacı konuğa sormak atlandı; sıcak karşılama yarım kaldı."},{"metin":"Günaydın efendim, hoş geldiniz. Size yardımcı olabilir miyim?","ingilizce":"Good morning, and welcome. Is there anything I can help you with?","puan":2,"tepki":"Konuk rahatlar: göz teması ve gülümseme üç metrede, sözlü selam bir buçuk metrede geldiği için kendini fark edilmiş hisseder. Bu, 10-5 kuralının ve hizmetin ilk adımının ta kendisidir."},{"metin":"Buyurun, ne lazım?","puan":0,"tepki":"Konuk geri çekilir: selam yok, gülümseme yok, hoş geldiniz yok. Karşılamanın üç adımı da atlanmıştır."}]},{"konuk":"Kahvaltı salonunu arıyorum. Bebek arabasıyla sığar mı, bilmiyorum.","ingilizce":"I'm looking for the breakfast room. I'm not sure the pushchair will fit.","secenekler":[{"metin":"Sığmaz, restoran küçük ve masalar dar. Bence odanıza getirtseniz daha rahat edersiniz.","puan":0,"tepki":"Konuk bozulur: sormadan karar verilmiş. Konuğun ihtiyacını karşılamak yerine kendi rahatını öne çıkaran cevap, öngörülü hizmetle çelişir."},{"metin":"Sığar efendim. Sizinle birlikte yürüyeyim, kapıları sizin için açık tutarım.","ingilizce":"It will fit. Let me walk with you and hold the doors open.","puan":2,"tepki":"Konuk teşekkür eder ve rahatlar. Söylemesini beklemeden yardımı teklif etmek, öngörülü hizmetin özüdür."},{"metin":"Sığar. Düz gidin, sağdaki kapı salon.","puan":1,"tepki":"Konuk yolu bulur, ancak yalnız kalır. Bilgi doğru; konuğun bebek arabası kaygısı fark edilip karşılanmadı."}]},{"konuk":"Çok teşekkürler! Bu arada ben Amara.","ingilizce":"Thank you so much! I'm Amara, by the way.","secenekler":[{"metin":"Ben de memnun oldum, hoş geldiniz. Bir şeye ihtiyacınız olursa resepsiyonda bekleriz.","puan":1,"tepki":"Konuk nazikçe gülümser. Adı öğrenilmişti, kullanılmadı; isimle hitap fırsatı kaçtı."},{"metin":"Amara Hanım, memnun oldum. Ben Elif; ne zaman ihtiyacınız olsa buradayım.","ingilizce":"Pleasure to meet you, Amara. I'm Elif; I'm here whenever you need me.","puan":2,"tepki":"Konuk gülümser: adını duymak ona tanındığı hissini verir. Adın ilk fırsatta öğrenilip doğal biçimde kullanılması isimle hitap standardıdır."},{"metin":"Adlar aklımda kalmıyor, oda numaranız yeter.","puan":0,"tepki":"Konuk geri çekilir: kendini bir numara gibi hissetmiştir. İsim bir kayıt bilgisi değil, konuğa verilen değerdir."}]},{"konuk":"Bir kahve içmek isterdim, ama bebeği bırakamam.","ingilizce":"I'd love a coffee, but I can't leave the baby.","secenekler":[{"metin":"Büfe şu köşede, arabayı park edip kendiniz alabilirsiniz.","puan":0,"tepki":"Konuk bir an düşünür, sonra kahveden vazgeçer ya da bebeği bırakmak zorunda kalır. Asıl sorun, yani bebeği bırakamaması, görülmemiştir."},{"metin":"Kahve büfesi şu köşede. İsterseniz önce sakin bir masaya geçin, oradan rahatça seçersiniz.","puan":1,"tepki":"Konuk kendine bir masa bulur, kahveyi ise yine kendisi almak zorundadır. Nezaket var; ihtiyaç sezilip karşılanmadı."},{"metin":"Siz oturun Amara Hanım, kahvenizi masanıza getireyim. Sütlü mü, sade mi olsun?","ingilizce":"Please sit down, Amara. I'll bring your coffee to the table. With milk, or black?","puan":2,"tepki":"Konuk şaşırır ve çok sevinir. Konuğu okuyup ihtiyacı söylemesini beklemeden karşılamak öngörülü hizmettir; adı kullanmak da sıcaklığı artırır."}]},{"konuk":"Zaman ne çabuk geçti, bugün ayrılıyoruz.","ingilizce":"Time flies. We're leaving today.","secenekler":[{"metin":"Çıkış işlemleri için resepsiyona uğramanız yeterli.","puan":0,"tepki":"Konuk soğuk bir veda alır ve sessizce çıkar. Uğurlama bir işlem sorusu değil, hizmetin son adımıdır; hatırlanan an çoğu zaman bitiştir."},{"metin":"Amara Hanım, sizi ağırlamak büyük keyifti. Bebeğinizle yolunuz açık olsun.","ingilizce":"Amara, it was a pleasure to have you with us. Safe travels to you and your baby.","puan":2,"tepki":"Konuk duygulanır: “Sizi unutmayacağım” der. Adla, içten bir dilekle ve acele etmeden yapılan sıcak uğurlama, konaklamanın akılda kalan son anıdır."},{"metin":"Güle güle, iyi yolculuklar dileriz. Yine bekleriz, bizi tercih ettiğiniz için teşekkürler.","puan":1,"tepki":"Konuk gülümser, veda sıradan kalır. Dilek içten, fakat ad ve kişiye özel bir söz yok."}]}]},{"id":"go-d02","unite":2,"baslik":"Gelmeyen Havalimanı Transferi","rol":"Concierge","sahne":"Öğle 12.25, lobi. Bay Henrik Larsen’in saat 12.00’de gelmesi gereken havalimanı aracı hâlâ ortada yok; uçağı 15.30’da. Konuk gergin; Concierge’in otel aracını çağırma ve küçük telafi yetkisi var.","kavramlar":["go-2-032","go-2-034","go-2-036","go-2-038","go-2-039"],"adimlar":[{"konuk":"Transferim 12.00’de gelecekti, saat 12.25 oldu. Uçağım 15.30’da!","ingilizce":"My transfer was due at twelve. It's twenty-five past, and my flight is at half past three!","secenekler":[{"metin":"Transfer şirketi geç kalmış, bu bizim hatamız değil.","puan":0,"tepki":"Konuk öfkelenir: “Kimin hatası olduğu beni ilgilendirmiyor.” Konuk, suçlunun kim olduğunu değil, sorunun çözülmesini bekler."},{"metin":"Araç yolda olmalı, hemen kontrol ediyorum; birkaç dakika içinde size haber veririm.","puan":1,"tepki":"Konuk bir an bekler, yine de gergindir. Harekete geçildi, ancak endişesi dinlenip anlaşılmadı; LEARN modelinde önce dinle ve anla gelir."},{"metin":"Sizi dinliyorum efendim. Uçuşunuza yetişmek çok önemli, endişenizi anlıyorum.","ingilizce":"I'm listening, sir. Catching your flight is very important; I understand your worry.","puan":2,"tepki":"Konuk biraz yatışır ve anlatmaya devam eder. Dinlemek ve anlamak LEARN modelinin ilk iki adımıdır; çözüm bunlardan sonra gelir."}]},{"konuk":"Bana “kesinlikle gelir” demiştiniz!","ingilizce":"You told me it would definitely come!","secenekler":[{"metin":"Ben “kesin” demedim, “gelecek” dedim.","puan":0,"tepki":"Konuk sinirlenir: “Sözcüklerle uğraşmayın.” Suçu konuğa ya da kelimelere atmak, özrü tamamen siler."},{"metin":"Haklısınız, sizi beklettik. İçtenlikle özür dilerim.","ingilizce":"You're right; we kept you waiting. I'm truly sorry.","puan":2,"tepki":"Konuk derin nefes alır ve sesini yumuşatır. Bahanesiz, “ama” demeyen özür konuğun yaşadığını kabul etmektir."},{"metin":"Özür dilerim, bugün yollar çok yoğun ve ben de elimden geleni yapıyorum.","puan":1,"tepki":"Konuk yarım bir özür duyduğunu hisseder. Özrün arkasına konan gerekçe onu zayıflatır ve konuğa suçlu kendisiymiş gibi hissettirir."}]},{"konuk":"Peki şimdi ne yapacaksınız?","ingilizce":"So what are you going to do now?","secenekler":[{"metin":"Müdürümüze sorup size döneyim.","puan":1,"tepki":"Konuk saatine bakar, zaman daralıyor. Bu iş Concierge’in kendi yetkisinde; amire sorup beklemek telafiyi geciktirir."},{"metin":"Bunu ben çözemem, transfer şirketini kendiniz arayın.","puan":0,"tepki":"Konuk sinirle bavulunu kavrar: “Siz bu işin neresindesiniz?” Sorunu sahiplenmeyip konuğa geri atmak, hizmet telafisinin tersidir."},{"metin":"Otelimizin aracını hemen çağırıyorum; gelişini ben takip edip size haber vereceğim.","ingilizce":"I'm calling the hotel's own car right now; I'll track it and keep you posted.","puan":2,"tepki":"Konuk ilk kez rahatlar. Yetkiyi kullanıp çözümü hemen başlatmak ve takibi üstlenmek hızlı telafidir."}]},{"konuk":"Bu yeni araç için ek ücret ödeyecek miyim?","ingilizce":"Will I have to pay extra for this new car?","secenekler":[{"metin":"Ücreti şimdilik odanıza ekleyelim, sonra müdürümüzle konuşursunuz.","puan":0,"tepki":"Konuk kaşlarını çatar: “Gecikme sizin, fatura benim mi?” Sorun otelden kaynaklandığında bedel konuğa yüklenmez; orantılı telafi bunu gerektirir."},{"metin":"Önce aracı yola çıkaralım ki vakit kaybetmeyin; ücret konusunu sonra rahatça konuşuruz.","puan":1,"tepki":"Konuk yola çıkabilecek olmanın rahatlığını yaşar, ücret sorusu ise havada kalır. Çözüm başladı, telafi tamamlanmadı."},{"metin":"Hayır efendim, yeni aracın ücretini otelimiz karşılıyor.","ingilizce":"No, sir; the hotel will cover the cost of the new car.","puan":2,"tepki":"Konuk hafifçe gülümser: “Bu adil.” Jestin yaşanan sorunun büyüklüğüne uygun olması orantılı telafidir; yetki sınırı içinde bunu hemen sunabilmek konuğun güvenini geri getirir."}]},{"konuk":"Havalimanındayım. Yetiştim! Neredeyse kaçırıyordum.","ingilizce":"I'm at the airport. I made it! I almost missed the flight.","secenekler":[{"metin":"Hep böyle olur, bu kadar telaşa gerek yoktu aslında.","puan":0,"tepki":"Konuk telefonu sertçe kapatır: yaşadığı endişe küçümsenmiş, aksaklık kayda geçmemiştir."},{"metin":"Çok sevindim. Yaşananı müdürümüze ve transfer ekibine ilettim; iyi yolculuklar.","ingilizce":"I'm so glad. I've passed this on to our manager and the transfer team; have a safe journey.","puan":2,"tepki":"Konuk teşekkür eder ve bu oteli tavsiye edeceğini söyler. Olayı kayda geçirmek (bildir) ve konuğa dönmek, LEARN modelinin son adımıdır; yazılmayan aksaklık yarın yeniden olur."},{"metin":"Çok sevindim, iyi yolculuklar dileriz. Bizi tercih ettiğiniz için teşekkür ederiz.","puan":1,"tepki":"Konuk kısaca teşekkür eder. Nezaket tamam; aksaklığın kaydı ve konuğa dönüş yapılmadı, sorun yarın başka bir konuğun başına gelebilir."}]}]},{"id":"go-d03","unite":2,"baslik":"Yastığınız, Kahveniz, Yıl dönümünüz","rol":"Butler","sahne":"Bir lüks otelin süit katı, ikinci konaklama günü. Butler, Madam Léa Moreau’nun tercihlerini öğrenip bunları sisteme işliyor. Konuk uzun konaklamada ve ertesi gün evlilik yıl dönümü.","kavramlar":["go-2-019","go-2-020","go-2-021","go-2-022","go-2-026"],"adimlar":[{"konuk":"Yastık bana biraz sert geldi. Ben her zaman yumuşak olanıyla uyurum.","ingilizce":"The pillow is a bit firm for me. I always sleep on a soft one.","secenekler":[{"metin":"Yastık menümüz var; birkaç çeşidi getireyim, seçiminizi profilinize de yazarım.","ingilizce":"We have a pillow menu. I'll bring a few to your room and add your choice to your profile.","puan":2,"tepki":"Konuk gülümser. Tercih hemen karşılandı ve kalıcı olarak kaydedildi; kişiselleştirme bilinen tercihe göre hizmeti uyarlamaktır."},{"metin":"Yumuşak yastık bulabilirim, yarın getiririm.","puan":1,"tepki":"Konuk teşekkür eder, geceyi sert yastıkla geçirir. Tercih yine karşılandı; yalnız geç kaldı ve kayda da geçmedi."},{"metin":"Yastıklar tüm odalarda aynı, değiştirmemiz mümkün olmuyor.","puan":0,"tepki":"Konuk hayal kırıklığına uğrar: tercihi bir istek değil, engel gibi karşılanmıştır. Kişiselleştirme, bilinen tercihe göre hizmeti uyarlamaktır."}]},{"konuk":"Sabahları kahvem yarım şekerli, yanında yulaf sütü olsun.","ingilizce":"In the mornings I take my coffee with half a sugar and oat milk.","secenekler":[{"metin":"Bunu mutfağa siz söyleyin, benim işim değil.","puan":0,"tepki":"Konuk şaşırır: “Burada kimse bilmiyor mu?” Bilgi tek kişide kalmaz; konuğun tercihi ekibe aktarılmazsa her sabah yeniden sorulur."},{"metin":"Not aldım Madam Moreau; profilinize işliyorum ki bütün ekip bilsin.","ingilizce":"Noted, Madame Moreau. I'll add it to your profile so the whole team knows.","puan":2,"tepki":"Konuk rahatlar: ertesi sabah kime denk gelirse gelsin kahvesi doğru olacak. Fark edilen tercihi profile yazıp ekiple paylaşmak tercih aktarımıdır."},{"metin":"Tamam, yarın sabah ben getiririm; kahvenizi her zaman böyle hazırlamayı hatırlarım.","puan":1,"tepki":"Konuk yetinir. Ancak ertesi gün başka bir görevli gelirse bilgi yoktur; tek kişinin hatırladığı tercih, o kişi izinli olunca kaybolur."}]},{"konuk":"Odam akşam çok güzel hazırlanmış! Kimseyi görmedim bile.","ingilizce":"My room was beautifully prepared this evening. I didn't even see anyone!","secenekler":[{"metin":"Normalde bütün odaları aynı şekilde hazırlıyoruz, sizin için ayrıca özel bir şey yapmış değiliz.","puan":0,"tepki":"Konuk soğur: “Demek özel değilmişim.” Standart hizmet güzeldir; kişiselleştirme ise konuğun özel hissetmesini sağlar."},{"metin":"Bu bizim için en büyük iltifat; yatağı yumuşak yastığınızla hazırladık.","ingilizce":"That's the best compliment we could ask for. We prepared your bed with your soft pillow.","puan":2,"tepki":"Konuk gülümser: “Biri beni düşünmüş.” Konuk görevliyi görmeden yalnız sonucu görüyorsa hizmet sessizdir; yastık tercihinin kullanılması da kişiselleştirmedir."},{"metin":"Teşekkürler, görevimiz.","puan":1,"tepki":"Konuk nazikçe başını sallar. Cevap doğru, yalnızca düz kalır; küçük özeni fark ettirme fırsatı kaçtı."}]},{"konuk":"Yarın evlilik yıl dönümümüz. Sade, sakin bir akşam istiyoruz; gösterişli bir şey değil.","ingilizce":"Tomorrow is our wedding anniversary. We'd like a quiet evening, nothing showy.","secenekler":[{"metin":"Terasa büyük bir masa kurup canlı müzik ayarlayayım; yıl dönümünüz için unutulmaz bir akşam olur.","puan":1,"tepki":"Konuk nazikçe başını sallar, gülümsemesi kaybolur. Niyet güzel; konuğun söylediği sade ve sakin akşam tercihi yok sayıldı."},{"metin":"Bizim hazır bir yıl dönümü paketimiz var; faturanıza ekleyelim, her şey dâhil.","puan":0,"tepki":"Konuk bir anda hayal kırıklığı yaşar; bir deneyim yerine satış duyar. “Wow” anı kişiye özel bir jesttir, hazır paket değil."},{"metin":"Sabah kahvenizin yanına küçük bir el yazısı not bırakayım mı?","ingilizce":"Shall I leave a small handwritten note beside your morning coffee?","puan":2,"tepki":"Konuk gülümser: sade tercihi duyulmuş, üstüne küçük ve sessiz bir jest gelmiştir. Kişiye özel, gösterişsiz bir jest konuğun sonradan anlatacağı “wow” anıdır."}]},{"konuk":"Sabah kahvem bile tam istediğim gibiydi! Bu otelde herkes beni tanıyor gibi.","ingilizce":"Even my morning coffee was just how I like it! Everyone here seems to know me.","secenekler":[{"metin":"Hakkınızda her şeyi biliyoruz, bu bizim işimiz.","puan":0,"tepki":"Konuk tedirgin olur. Konuk bilgisi yalnız hizmet için tutulur; bunu “her şeyi biliyoruz” diye söylemek güven yerine rahatsızlık verir."},{"metin":"Ekibimiz birbirini iyi bilgilendiriyor, evet; hepimiz sizin için çalışıyoruz.","puan":1,"tepki":"Konuk gülümser, merakı ise giderilmemiştir. Cevap doğru, fakat “tanındım” duygusunun nasıl oluştuğunu açıklamıyor."},{"metin":"Tercihlerinizi yalnız sizi iyi ağırlamak için ekiple paylaşırız; yıl dönümünüz kutlu olsun.","ingilizce":"We share your preferences with the team only to look after you better. Happy anniversary.","puan":2,"tepki":"Konuk teşekkür eder; kendini hem tanınmış hem güvende hisseder. Profil, tercih aktarımı ve gizlilik birlikte işlediğinde duygusal bağ oluşur."}]}]},{"id":"go-d04","unite":2,"baslik":"Dr. Tanaka’nın Sessiz İsteği","rol":"Concierge","sahne":"Akşamüstü 17.00, lobi. Japonya’dan gelen Dr. Tanaka, el uzatmak yerine hafifçe eğilerek selam veriyor. Concierge, kültür bilgisinin bir harita olduğunu, önündeki konuğun ise tek bir kişi olduğunu aklında tutuyor.","kavramlar":["go-2-042","go-2-043","go-2-044","go-2-046","go-2-047"],"adimlar":[{"konuk":"Merhaba, ben Dr. Tanaka. Rezervasyonum var.","ingilizce":"Hello, I am Dr Tanaka. I have a reservation.","secenekler":[{"metin":"Hoş geldiniz Bay Tanaka. Rezervasyonunuza hemen bakıyorum, pasaportunuz yanınızda mı?","puan":1,"tepki":"Konuk başını eğerek karşılık verir. Karşılama sıcak, yalnız kendini tanıttığı “Doktor” unvanı kullanılmadı."},{"metin":"Hiroshi, hoş geldin! Rezervasyonuna bakıyorum.","puan":0,"tepki":"Konuk bir an donar. Yeni tanışılan konuğa adıyla ve samimi hitap etmek unvanını ve ad-soyad düzenini yok saymaktır."},{"metin":"Hoş geldiniz Doktor Tanaka. Selamınıza ben de hafifçe eğilerek karşılık veriyorum.","ingilizce":"Welcome, Dr Tanaka. I return your bow with respect.","puan":2,"tepki":"Konuk memnun bir ifadeyle gülümser. Konuğun selamlaşma biçimine uymak ve unvanıyla hitap etmek kültüre saygı göstermenin ilk adımıdır."}]},{"konuk":"Odam gerçekten güzel. Yalnız sokak biraz hareketli galiba.","ingilizce":"My room is really lovely. The street seems a little busy, though.","secenekler":[{"metin":"Beğenmenize sevindim, odamızın manzarasını herkes çok sever; başka bir isteğiniz olursa söyleyin.","puan":1,"tepki":"Konuk kibarca teşekkür eder ve konuyu bir daha açmaz. İma gözden kaçtı, sorun sessizce kaldı."},{"metin":"Gürültü mü? Otelimiz çok sessizdir, bu odadan daha önce hiç şikâyet gelmedi.","puan":0,"tepki":"Konuk geri çekilir: “Anlaşıldı.” Dolaylı söylenen bir isteği reddetmek bir daha söylenmemesine yol açar."},{"metin":"Size daha sessiz bir oda ayarlayabilirim. İsterseniz birlikte bakalım mı?","ingilizce":"I can arrange a quieter room for you. Shall we look at some together?","puan":2,"tepki":"Konuk rahatlar: “Çok nazik, teşekkür ederim.” Bazı konuklar şikâyeti açıkça söylemez; ses tonuna, yüze ve sözün satır aralarına bakıp nazikçe çözüm sunmak gerekir. Bu bir eğilimdir, kural değil."}]},{"konuk":"Hafif bir şeyler yemek istiyorum. Yakında bir yer var mı?","ingilizce":"I would like something light to eat. Is there a place nearby?","secenekler":[{"metin":"Hızlıca bir şeyler atıştırmak için F&B outletimiz var, lobinin sağında.","puan":0,"tepki":"Konuk nazikçe gülümser, anlamadığını belli eder. Deyim ve kısaltma ana dili İngilizce olmayan konuğu soru sormaktan alıkoyar."},{"metin":"Hafif bir şey için kafemiz var; aşağı kata inip sağa dönün, tabelasını göreceksiniz.","puan":1,"tepki":"Konuk teşekkür eder, kafenin kaçta kapandığını bilmediği için tereddüt eder. Yön verildi, ihtiyaç duyulan saat bilgisi eksik kaldı."},{"metin":"Elbette; kafemiz aşağıda ve akşam 22.00’ye kadar açık. İsterseniz kâğıda yazayım.","ingilizce":"Of course; the café is downstairs and open until ten this evening. Shall I write it down?","puan":2,"tepki":"Konuk rahatlar ve kâğıdı memnuniyetle alır. Yavaş, kısa cümleler, deyimsiz sade İngilizce ve yazılı destek çok dilli hizmetin ustalığıdır."}]},{"konuk":"Teşekkürler. Bizim ülkede bahşiş yok; burada alışkanlık nedir, bilmiyorum.","ingilizce":"Thank you. We don't tip in my country; I'm not sure what the custom is here.","secenekler":[{"metin":"Burada genelde bahşiş verilir; vermezseniz garip olur.","puan":0,"tepki":"Konuk huzursuz olur. Bahşiş beklemek ya da konuğu mahcup etmek lüks hizmette kabul edilmez."},{"metin":"Hiç sorun değil efendim; bahşiş isteğe bağlıdır. Hizmetimiz sizin için, bahşiş için değil.","ingilizce":"No problem at all, sir; tipping is optional. Our service is for you, not for a tip.","puan":2,"tepki":"Konuk rahat bir nefes alır. Bahşiş kültürü ülkeden ülkeye değişir; lüks otelde hizmet bahşiş için değil konuk için verilir."},{"metin":"Bahşiş zorunlu değil.","puan":1,"tepki":"Konuk bilgiyi alır, ancak cevabın kuru kalması onu rahatlatmaz. Doğru söylendi; konuğun kültür farkı kaygısı sıcak biçimde karşılanmadı."}]},{"konuk":"Her şey için teşekkür ederim. Yarın erken ayrılıyorum.","ingilizce":"Thank you for everything. I leave early tomorrow.","secenekler":[{"metin":"Güle güle Bay Tanaka, iyi yolculuklar dileriz. Yarın çıkışınız için resepsiyon hazır olacak.","puan":1,"tepki":"Konuk başını eğer. Veda ilgili ve nazik, yine de genel kalır; “Doktor” unvanı ve kişiye özel dilek yok."},{"metin":"Çok yoğunuz, çıkışta resepsiyona uğrayın lütfen.","puan":0,"tepki":"Konuk sessizce uzaklaşır. Yoğunluk bahanesi konuğa değil, bize ait bir sorundur; veda aceleye getirildi."},{"metin":"Sizi ağırlamak bir onurdu Doktor Tanaka. Yolculuğunuz güvenli geçsin.","ingilizce":"It was an honour to host you, Dr Tanaka. Have a safe journey.","puan":2,"tepki":"Konuk eğilerek teşekkür eder; veda sıcak ve saygılı geçer. Unvanla hitap ve içten dilek, kültürel zekânın davranışa yansımasıdır."}]}]},{"id":"go-d05","unite":2,"baslik":"Unutulan Spa Randevusu","rol":"Konuk deneyimi görevlisi","sahne":"Öğleden sonra 14.30, lobi. Bay Marco Bellini’nin saat 14.00’teki spa randevusu kayıtlarda yok; yirmi dakika boş yere beklemiş. Konuk deneyimi görevlisi, spa başka bir departman olsa da konuğun sorununu sahipleniyor.","kavramlar":["go-2-033","go-2-031","go-2-035","go-2-037","go-2-039"],"adimlar":[{"konuk":"Bir şikâyetim var. Anlatabilir miyim?","ingilizce":"I have a complaint. May I explain?","secenekler":[{"metin":"Şikâyetleri yazılı alıyoruz; formu doldurun, e-postayla size dönüş yapılır.","puan":0,"tepki":"Konuk kaşlarını çatar: “Form mu?” Şikâyeti formalite gibi karşılamak, konuğu dinlememek demektir."},{"metin":"Elbette, sizi dinliyorum. Lütfen rahatça anlatın.","ingilizce":"Of course, I'm listening. Please take your time.","puan":2,"tepki":"Konuk oturur ve anlatmaya başlar. Şikâyet eden konuk otele iyilik yapar; HEART modelinin ilk adımı, onun sözünü kesmeden dinlemektir."},{"metin":"Bu konuda resepsiyon size daha iyi yardımcı olabilir, lütfen oraya gidin.","puan":1,"tepki":"Konuk isteksizce yürür. Konuk kendisini bir yerden bir yere gönderen kişiyi sorunun sahibi olarak görmez."}]},{"konuk":"Spa’da saat ikiye randevum vardı. Yirmi dakika bekledim, kayıtta adım yokmuş. Çok sinirlendim.","ingilizce":"I had a spa appointment at two. I waited twenty minutes and my name wasn't in the system. I'm very upset.","secenekler":[{"metin":"Bu sizin için gerçekten üzücü olmuş; beklemek ve randevunun boşa gitmesi can sıkıcı.","ingilizce":"That must have been really upsetting: waiting, and then finding the booking was lost.","puan":2,"tepki":"Konuk omuzlarını bırakır: “Evet, tam olarak bu.” Konuğun duygusunu anlamak ve dile getirmek HEART’ın ikinci adımıdır."},{"metin":"Spa ayrı bir birim olarak çalışıyor; bu konuyu spa yönetimine anlatmanız daha doğru olur.","puan":0,"tepki":"Konuk öfkeyle yükselir: “Ben otelin konuğuyum, spa’nın değil.” “Benim bölümüm değil” demek sorunu sahiplenmemektir."},{"metin":"Kaç dakika beklediğinizi not ediyorum.","puan":1,"tepki":"Konuk başını sallar, içi soğur. Kayıt tutmak iyi bir iş; ne var ki duygusu önce anlaşılmadı."}]},{"konuk":"Bu kabul edilemez!","ingilizce":"This is unacceptable!","secenekler":[{"metin":"Randevuyu spa kaydetmemiş, hata onların; bu benim sorumluluğumda değil.","puan":0,"tepki":"Konuk sert çıkar: “Bana bundan ne?” Suçu başka departmana atmak özrü ve güveni yok eder."},{"metin":"Haklısınız, bu bizim hatamız. Çok özür dilerim.","ingilizce":"You're right, this was our mistake. I'm very sorry.","puan":2,"tepki":"Konuk derin nefes alır ve sesi yumuşar. Hatayı bahanesiz kabul eden kısa özür HEART’ın üçüncü adımıdır; departman fark etmez, otel adına konuşulur."},{"metin":"Her ne kadar spa ayrı çalışıyor olsa da ben yine de özür dilerim.","puan":1,"tepki":"Konuk kabullenir gibi görünür. Özür var, fakat spa ayrı denerek konuğun yaşadığıyla araya mesafe konuldu."}]},{"konuk":"Peki ne yapacaksınız?","ingilizce":"So what will you do about it?","secenekler":[{"metin":"Yapabileceğimiz bir şey yok, randevuları spa yönetiyor.","puan":0,"tepki":"Konuk ayağa kalkar: “Anladım.” Çözüm üretmeden bırakmak, şikâyeti fırsata çevirme şansını kaçırır."},{"metin":"Size hangi saat uygun? Hemen spa’yı arayıp ayarlayayım; bitki çayı da ikramımız olsun.","ingilizce":"Which time suits you? I'll call the spa right now and arrange it; the herbal tea is on us.","puan":2,"tepki":"Konuk gülümser: “Bu iş görür.” Yetki sınırı içindeki çözümü (yeni randevu, küçük ikram) hemen sunmak ve saati konuğa sormak doğru dengedir."},{"metin":"Yeni randevu için spa’yı arayabilirsiniz; dâhili numarası resepsiyonun yanındaki listede yazıyor.","puan":1,"tepki":"Konuk iç çeker ve telefonu eline alır. Çözüm var, yük ise yine konuğun üzerinde."}]},{"konuk":"Tamam, teşekkürler. İlgilendiğiniz için memnun oldum.","ingilizce":"All right, thank you. I appreciate you taking care of this.","secenekler":[{"metin":"Rica ederim; bir dahaki sefere randevuyu siz de önceden teyit ederseniz böyle şeyler olmaz.","puan":0,"tepki":"Konuk bozulur: “Demek suç bendeydi.” Suçu sonunda konuğa atmak kazanılan güveni son cümlede bozar."},{"metin":"Rica ederim, iyi günler dilerim. Başka bir isteğiniz olursa lobideyim.","puan":1,"tepki":"Konuk kısaca gülümser. Nezaket tamam; teşekkür ve takip eksik kaldı."},{"metin":"Bize söylediğiniz için teşekkür ederim; randevudan sonra yine uğrayıp nasıl geçtiğini soracağım.","ingilizce":"Thank you for telling us; after your appointment I'll come back to ask how it went.","puan":2,"tepki":"Konuk gülümseyerek şöyle der: “Gerçekten ilgileniyorsunuz.” Teşekkür HEART’ın son adımıdır; çözümden sonra yeniden dönüp sormak telafi takibidir."}]}]},{"id":"go-d06","unite":4,"baslik":"Elli Yıllık Bir Akşam","rol":"Karşılama görevlisi (host)","sahne":"Akşam 19.00, otelin restoranının girişi. Bay ve Bayan Whitfield evliliklerinin ellinci yıl dönümü için gelmiş; Bay Whitfield yavaş yürüyor. Karşılama görevlisi (host), rezervasyon listesi ve masa planıyla girişte bekliyor.","kavramlar":["go-4-003","go-4-007","go-4-018","go-4-069","go-4-070"],"adimlar":[{"konuk":"İyi akşamlar. Whitfield adına iki kişilik rezervasyonumuz var.","ingilizce":"Good evening. We have a reservation for two under Whitfield.","secenekler":[{"metin":"Rezervasyona bakıyorum, birkaç dakika şuraya geçip bekleyebilir misiniz lütfen?","puan":1,"tepki":"Konuklar bir köşeye çekilip bekler. Doğru, fakat soğuk; servis akışının ilk adımı olan sıcak karşılama eksik kaldı."},{"metin":"İyi akşamlar, hoş geldiniz. Whitfield adına iki kişilik masanız hazır.","ingilizce":"Good evening, welcome. Your table for two under Whitfield is ready.","puan":2,"tepki":"Konuklar gülümseyip rahatlar. Restoran girişinde konuğu sıcak karşılayıp rezervasyonunu hemen bulmak host görevinin başıdır."},{"metin":"Listede adınız yok gibi, doğru yere geldiğinizden emin misiniz?","puan":0,"tepki":"Konuklar şaşırıp gerilir. Listeye dikkatle bakmadan konuğu sorgulamak güveni sarsar."}]},{"konuk":"Eşim yavaş yürüyor. Sakin bir masa olsa çok iyi olur.","ingilizce":"My husband walks slowly. A quiet table would be lovely.","secenekler":[{"metin":"Girişe yakın, basamaksız ve sakin bir masamız var. Acele yok, birlikte yavaş yürüyelim.","ingilizce":"We have a quiet table near the entrance, with no steps. There is no hurry; we'll walk slowly together.","puan":2,"tepki":"Bay Whitfield gülümseyerek başını sallar. Yaşlı konuğun hızına uyup onurunu zedelemeden yardım etmek doğru hizmettir."},{"metin":"En güzel masamız pencere kenarında, manzarası harika; yalnız oraya birkaç basamak çıkılıyor.","puan":1,"tepki":"Konuklar tereddüt eder: masa güzel, yürümesi ise zor. Konuğun söylediği ihtiyaç göz ardı edildi."},{"metin":"Sakin masa yok, barın yanındaki boş.","puan":0,"tepki":"Konuklar yüzlerini buruşturur. Konuğun açık isteğine bakmadan masa vermek ihtiyacı duymazlıktan gelmektir."}]},{"konuk":"Bugün evliliğimizin ellinci yıl dönümü.","ingilizce":"Today is our fiftieth wedding anniversary.","secenekler":[{"metin":"Çok güzel, tebrik ederim; keyifli ve huzurlu bir akşam geçirmenizi diliyorum, afiyet olsun.","puan":1,"tepki":"Konuklar teşekkür eder, içlerinden daha fazlasını beklemişlerdir. Tebrik edildi; masaya ve ekibe yansımadı."},{"metin":"Bunu rezervasyon sırasında bildirmeniz gerekirdi; şimdi ayarlamamız zor olur.","puan":0,"tepki":"Konuklar mahcup olur ve akşamın tadı kaçar. Konuğa suçu atmak, özel günün mutluluğunu bozar."},{"metin":"Elli yıl, ne güzel, tebrikler! Servis ekibine ve şefe haber veriyorum, masanız süslensin.","ingilizce":"Fifty years, how wonderful, congratulations! I'm telling the service team and the chef so your table can be decorated.","puan":2,"tepki":"Konuklar çok sevinir. Özel gün masası kişiye özel küçük ikramlarla süslenir; bilgi garsona ve mutfağa geçtiğinde ekip hazır olur."}]},{"konuk":"Bu masaya kim bakacak?","ingilizce":"Who will be looking after our table?","secenekler":[{"metin":"Bir garson arkadaşımız birazdan gelip sizinle ilgilenecek, lütfen oturup biraz bekleyin.","puan":1,"tepki":"Konuklar menüsüz bekler; garsonun kim olduğu söylenmediği için belirsizlik rahatsız eder."},{"metin":"Bu masadan Deniz sorumlu, hemen menüyü getirecek. Özel gününüzü ona da ilettim.","ingilizce":"Deniz looks after this table and will bring the menu right away. I've already told him about your special day.","puan":2,"tepki":"Konuklar güvenle oturur. Salon masa gruplarına bölünüp her grup belirli bir garsona verildiği için sorumlu kişi bellidir; bilgi onun elinde."},{"metin":"Şimdi bakarım, kimin masası olduğunu bilmiyorum.","puan":0,"tepki":"Konuklar yüz yüze bakar. Servis bölgesi bilinmiyorsa servis akışı baştan aksar."}]},{"konuk":"Her şey harikaydı, teşekkür ederiz.","ingilizce":"Everything was wonderful, thank you.","secenekler":[{"metin":"Güle güle, bizi tercih ettiğiniz için teşekkürler, yine bekleriz.","puan":1,"tepki":"Konuklar nazikçe başını eğer. Uğurlama var, hatırlanacak kişiye özel bir söz yok."},{"metin":"Taksiyi kendiniz çağırabilirsiniz, kapıda bekleyin.","puan":0,"tepki":"Konuklar yorgun adımlarla yönelir. Yaşlı konuğun çıkışta da desteğe ihtiyacı olabilir; uğurlama servis akışının son adımıdır."},{"metin":"Bay ve Bayan Whitfield, elli yıl kutlu olsun. Kapıya kadar size eşlik edeyim.","ingilizce":"Mr and Mrs Whitfield, congratulations on fifty years. Let me walk you to the door.","puan":2,"tepki":"Konuklar gülümseyip içten teşekkür eder. İsimle ve acele etmeden yapılan uğurlama akşamın son ve en akılda kalan anıdır."}]}]},{"id":"go-d07","unite":4,"baslik":"Servise On Beş Dakika Kala","rol":"Garson","sahne":"Akşam 17.45, otelin restoranı; servis 18.00’de başlayacak ve garson peçeteleri katlayıp kuverleri son kez kontrol ediyor. Beklenenden erken gelen Bayan Priya Nair kapıda duruyor; işletmede servis öncesi erken gelen konuğu oturtmak serbest.","kavramlar":["go-4-013","go-4-029","go-4-032","go-4-033","go-4-014"],"adimlar":[{"konuk":"Affedersiniz, erken geldim sanırım. Restoran açık mı?","ingilizce":"Excuse me, I think I'm early. Is the restaurant open yet?","secenekler":[{"metin":"Hazırlık yapıyoruz, görmüyor musunuz? Dışarıda bekleyin.","puan":0,"tepki":"Konuk geri çekilir. Mise en place, ekip konuğa daha çok vakit ayırsın diye vardır; konuğu uzaklaştırmak için değil."},{"metin":"Restoranımız altıda açılıyor, biraz dolaşıp altıya doğru tekrar uğrarsanız çok seviniriz.","puan":1,"tepki":"Konuk kibarca çıkıp gider. Bilgi doğru; hazırlığı bitmek üzere olan ekibin konuğu ağırlayabilecek durumda olması değerlendirilmedi."},{"metin":"Hoş geldiniz, hazırlığımız bitmek üzere. Oturun lütfen, size bir içecek getireyim.","ingilizce":"Welcome, we're nearly ready. Please take a seat and I'll bring you a drink.","puan":2,"tepki":"Konuk gülümseyerek oturur. Servis öncesi hazırlık neredeyse bitmiş olduğundan garson sakin ve konuğa ayıracak vakitle karşılar."}]},{"konuk":"Bu kadar çok çatal-bıçak! Hangisini önce kullanacağım?","ingilizce":"So many knives and forks! Which one do I use first?","secenekler":[{"metin":"Dışarıdan içeriye doğru, yemeklerin sırasına göre. Dıştaki ilk yemek içindir.","ingilizce":"Work from the outside in, following the courses. The outer one is for the first dish.","puan":2,"tepki":"Konuk gülümseyip rahatlar. Çatallar solda, bıçak ve kaşıklar sağda, kullanım sırasına göre dışarıdan içeriye dizilir."},{"metin":"Kolay olanı kullanın, fark etmez.","puan":0,"tepki":"Konuk bir an tereddüt eder. Kuver düzeni yemeğin sırasını anlatır; “fark etmez” demek bu bilgiyi yok saymaktır."},{"metin":"Dışarıdan başlayın yeter.","puan":1,"tepki":"Konuk başını sallar, emin olamaz. Yön doğru; sıraya göre kullanıldığı açıklanmadı."}]},{"konuk":"Siz hep soldan mı gelirsiniz? Bunun bir kuralı var mı?","ingilizce":"Do you always come from the left? Is there a rule for that?","secenekler":[{"metin":"Yaygın düzende yemek soldan, içecek sağdan verilir. Bizim standardımız da bu.","ingilizce":"In the usual order, food is served from the left and drinks from the right. That is our standard.","puan":2,"tepki":"Konuk ilgiyle başını sallar. Servis yönü yaygın düzene göredir, ama işletme standardı esastır; ekibin hepsi aynı kuralı izler."},{"metin":"Fark etmez, hangisi uygunsa.","puan":0,"tepki":"Konuk şaşırır. Servis yönü ekip içinde ortaktır; “fark etmez” demek standardı bilmemek anlamına gelir."},{"metin":"Hepimiz eğitimde öyle öğrendik, bir kural var işte; nedenini ben de tam bilmiyorum.","puan":1,"tepki":"Konuk meraklıdır, cevapsız kalır. Kural söylendi; nedeni ve düzeni açıklanmadı."}]},{"konuk":"Ana yemek harikaydı, ama tatlıya yer bırakmak için yavaş yiyorum, lütfen acele ettirmeyin.","ingilizce":"The main course was wonderful, but I'm eating slowly to leave room for dessert. Please don't rush me.","secenekler":[{"metin":"Tabağı alayım, mutfak yoğun.","puan":0,"tepki":"Konuk bozulur: “Ben bitirmedim.” Konuk bitirmeden tabak almak ona acele ettirildiğini hissettirir."},{"metin":"Tabağınız soğumaya başladı, isterseniz alıp mutfakta sıcak tutayım; ne dersiniz?","puan":1,"tepki":"Konuk kararsız kalır. Soru nazik; karar yine konuğa bırakıldı, oysa çatal ve bıçağın duruşu zaten cevabı verirdi."},{"metin":"Elbette, acele yok. Çatalı bıçağı paralel koyunca bitirdiğinizi anlarım.","ingilizce":"Of course, there's no hurry. When you lay your knife and fork parallel, I'll know you've finished.","puan":2,"tepki":"Konuk gülümser ve rahatlar. Tabak, herkes bitirdikten sonra ve çatal-bıçağın paralel yatmasıyla anlaşılan bitiş işaretiyle sessizce alınır."}]},{"konuk":"Tatlı mükemmeldi. Hesabı alabilir miyim?","ingilizce":"The dessert was perfect. Could I have the bill, please?","secenekler":[{"metin":"Hesabı kasadan alırsınız, ben masada bekleyemem.","puan":0,"tepki":"Konuk tedirgin olur. Adisyon masanın siparişlerini taşır; hesabı masada, konuğa yardım ederek sunmak servis akışının bir parçasıdır, konuğu başka yere yollamak akışı bozar."},{"metin":"Elbette efendim, adisyonunuzu hemen getiriyorum. Akşamınız güzel geçmiştir umarım.","ingilizce":"Of course, I'll bring your bill right away. I hope you enjoyed your evening.","puan":2,"tepki":"Konuk güler yüzle teşekkür eder. Masanın siparişleri adisyonda toplanır ve hesap oradan çıkar; hesabı masada sunmak ve kısa bir dilek eklemek akşamı iyi kapatır."},{"metin":"Kasaya gidebilirsiniz, adisyonunuz orada hazır bekliyor; iyi akşamlar.","puan":1,"tepki":"Konuk kasaya yönelir. Hesap alındı, masada teslim edilmesi gereken hizmet yarım kaldı."}]}]},{"id":"go-d08","unite":4,"baslik":"Fındık Alerjisi","rol":"Garson","sahne":"Akşam 20.10, otelin restoranı. Lena Fischer’in fındık alerjisi var; yanındaki arkadaşı Carlos’un ise süt alerjisi. Garson, siparişi alırken her iki konuğun durumunu mutfağa doğru iletmek zorunda.","kavramlar":["go-4-062","go-4-063","go-4-064","go-4-065"],"adimlar":[{"konuk":"Affedersiniz, sert kabuklu yemişlere alerjim var. Tavuklu salatada var mı?","ingilizce":"Excuse me, I have a nut allergy. Is there any in the chicken salad?","secenekler":[{"metin":"Tavuklu salata hafif bir yemek, içinde fındık olacağını sanmıyorum; rahat yiyebilirsiniz.","puan":0,"tepki":"Konuk elini kaldırır: “Lütfen mutfağa sorun.” Tahminle cevap vermek alerjide ciddi sağlık riskidir; kesin bilgi mutfaktan alınır."},{"metin":"Kesin bilgiyi şefimizden alıp hemen dönüyorum; siparişe alerji notunu yazıyorum.","ingilizce":"I'll check with the chef and come straight back; I'm writing the allergy on your order.","puan":2,"tepki":"Konuk rahatlar: “Çok teşekkür ederim.” Alerji sorusu cevaplanmadan önce yazılı not düşmek ve mutfaktan kesin bilgi almak güvenli sipariş akışının başıdır."},{"metin":"Menüdeki alerjen simgelerine bakıyorum, fındık yazmıyor; sosta olup olmadığına da bakayım.","puan":1,"tepki":"Konuk gergin bir gülümsemeyle bekler. Menü iyi bir başlangıçtır; soslar ve bulaşma ihtimali menüde yazmaz, kesin bilgi mutfaktan alınmalıdır."}]},{"konuk":"Şef sosta fındık olduğunu söylemiş. Ayıklayıp getirseniz olur mu?","ingilizce":"The chef says the sauce has nuts in it. Could you just take them off?","secenekler":[{"metin":"Şefe sorayım, ayıklayarak olur mu diye bakalım; cevabı gelince size haber vereyim.","puan":1,"tepki":"Konuk ilgiyle bekler, soru şefe götürüldüğü için içi biraz rahatlar. Ayıklamanın yetmeyeceği, küçük bir bulaşmanın bile tepki yaratabileceği ise konuğa söylenmedi."},{"metin":"Ayıklayıp getireyim, ama risk size ait.","puan":0,"tepki":"Konuk tedirgin olur. Alerjide pazarlık yoktur; sorumluluğu konuğa yüklemek profesyonel değildir, güvenli bir seçenek sunulmalıdır."},{"metin":"Ayıklamak yetmez; ufak bir bulaşma bile tepki yaratabilir. Fındıksız ve ayrı sosla hazırlatalım.","ingilizce":"Taking them off isn't enough; even a trace can cause a reaction. Let's have it prepared without nuts and with a separate sauce.","puan":2,"tepki":"Konuk onaylar: “Doğru, teşekkürler.” Alerjenin tabağa küçücük bile bulaşması tepki yaratabilir; ayrı gereç, temiz tezgâh ve fındıksız sos çapraz teması önler."}]},{"konuk":"Arkadaşımın süt alerjisi var. Kahvesine laktozsuz süt koyabilir misiniz?","ingilizce":"My friend has a milk allergy. Could you put lactose-free milk in his coffee?","secenekler":[{"metin":"Laktozsuz süt alerjisi olanlara da uygundur, arkadaşınız rahatça deneyebilir.","puan":0,"tepki":"Carlos’un yüzü gerilir. Laktozsuz süt hâlâ süt proteini içerir; süt alerjisi olanlara uygun değildir."},{"metin":"Laktozsuz süt süt alerjisine uygun değil, süt proteini içerir; bitkisel süt için mutfağa soruyorum.","ingilizce":"Lactose-free milk isn't suitable for a milk allergy because it still has milk protein; I'll ask the kitchen about plant-based milk.","puan":2,"tepki":"Carlos teşekkür eder. Laktozsuz süt yalnız laktoz intoleransı olanlara uygundur; alerji ve intoleransı ayırt edip kararı mutfağa bırakmak doğru davranıştır."},{"metin":"Laktozsuz süt olabilir, emin değilim.","puan":1,"tepki":"Carlos tereddütle gülümser. Belirsizliği dürüstçe söylemek iyi; ne var ki alerji ile intoleransın ayrımı yapılmadı ve mutfağa danışılmadı."}]},{"konuk":"Menüde “gluten, yumurta, hardal” yazıyor. Bunlar alerjen mi?","ingilizce":"The menu says 'gluten, egg, mustard'. Are those allergens?","secenekler":[{"metin":"Bunlar standart bir yazı, her menüde var; çok önemsemenize gerek yok.","puan":0,"tepki":"Konuk şaşırır ve menüye güvenini yitirir. Menüdeki alerjen yazısı, konuğun güvenliği için konmuş önemli bilgidir."},{"metin":"Evet, alerjen olarak yazılmış; hangi yemekte hangisinin olduğunu ben ezbere bilmiyorum.","puan":1,"tepki":"Konuk başını sallar, sorusu açıkta kalır. Cevap doğru; garson bu bilgiyi anlamlandırıp gerekirse mutfağa sormalıdır."},{"metin":"Evet, bunlar on dört alerjen grubundandır; emin olmadığınız yemeği bana sorun, mutfaktan öğreneyim.","ingilizce":"Yes, those are among the fourteen allergen groups; ask me about any dish you're unsure of and I'll check with the kitchen.","puan":2,"tepki":"Konuk gülümseyip rahatlar. Menüdeki alerjenler AB’nin zorunlu kıldığı on dört gruptandır; kesin bilgiyi mutfaktan alıp konuğa aktarmak garsonun işidir."}]},{"konuk":"Salatam hazır mı? Çok acıktım.","ingilizce":"Is my salad ready? I'm starving.","secenekler":[{"metin":"Hazır, tezgâhta bekliyor; boştaki bir arkadaşım getirir, nasılsa hepsi aynı tabak.","puan":0,"tepki":"Konuk tedirgin olur. Alerjik konuğun tabağı doğrudan sorumlu garsonla ve “alerjili” notuyla teslim edilir; araya yeni bir halka girmesi risk yaratır."},{"metin":"Evet, şefimiz kontrol etti; tabağı alerji notuyla kendim getiriyorum. Afiyet olsun.","ingilizce":"Yes, the chef has checked it; I'm bringing it to you myself, marked with an allergy note. Enjoy your meal.","puan":2,"tepki":"Konuk güvenle yemeği bekler. Sor, yaz, söyle, doğrula, teslim et: her halkada bir kişinin gözü hatayı yakalar."},{"metin":"Hazır olmak üzere, şef son kontrolü yapıyor; yemek birazdan masanıza gelir.","puan":1,"tepki":"Konuk bekler, tabağı kimin getireceğini bilmediği için tam rahatlayamaz. Kontrol var; doğrudan teslim halkası ise belirsiz kaldı."}]}]},{"id":"go-d09","unite":4,"baslik":"Anneannenin 80. Yaş Günü","rol":"Garson","sahne":"Pazar günü 12.00, ziyafet salonu. Bay Murat Demir, anneannesinin 80. yaş günü için 14 kişilik bir yemek planlıyor ve garsonla servis biçimini konuşuyor. Otel, dışarıdan pasta getirilmesini kabul ediyor.","kavramlar":["go-4-019","go-4-022","go-4-024","go-4-025","go-4-070"],"adimlar":[{"konuk":"Yemeklerin herkese düzenli ve zamanında gelmesini istiyorum. Siz nasıl servis edersiniz?","ingilizce":"I want everyone's food to arrive neatly and on time. How do you serve?","secenekler":[{"metin":"Her iki tarzı da yapabiliriz, hangisini isterseniz öyle olur; siz karar verin.","puan":1,"tepki":"Konuk tereddüt eder: “Peki hangisi?” Seçenek sunuldu, rehberlik edilmedi; konuk seçmek için bilgiye ihtiyaç duyar."},{"metin":"Amerikan servisi hızlı ve düzenlidir: tabaklar mutfakta hazırlanır, hepsi birlikte gelir.","ingilizce":"American service is quick and tidy: plates are prepared in the kitchen and arrive together.","puan":2,"tepki":"Konuk ilgiyle öne eğilir. Servis tarzı, yemeğin mutfaktan tabağa nasıl ulaşacağını belirler; Amerikan servisi hazır tabakla hızlı ve düzenli gelir."},{"metin":"Hepsi aynı, hiç fark etmez.","puan":0,"tepki":"Konuk şüphelenir. Servis tarzları farklı sonuçlar verir; fark etmediğini söylemek önemli bir seçimi küçümsemektir."}]},{"konuk":"Anneannem sekseninde ve az yer. Ne kadar isteyeceğine kendisi karar verebilir mi?","ingilizce":"My grandmother is eighty and eats little. Can she decide how much she wants?","secenekler":[{"metin":"Rus servisinde garson büyük tabaktan istediği kadar koyar; miktarı anneanneye sorarım.","ingilizce":"In Russian service the waiter serves from a large platter as much as she would like; I'll ask her how much.","puan":2,"tepki":"Konuk gülümser: “Tam istediğim.” Rus servisinde garson büyük servis tabağından her konuğun tabağına porsiyon koyar; böylece miktar konuğa göre ayarlanabilir."},{"metin":"Herkese aynı miktar gelir, kuralımız bu.","puan":0,"tepki":"Konuk bozulur. Servis tarzına göre porsiyon uyarlanabilir; “kuralımız bu” demek konuğu dinlememektir."},{"metin":"Hazır tabakta porsiyon aynı olur; isterseniz mutfağa sorup küçük porsiyon mümkün mü bakarız.","puan":1,"tepki":"Konuk kararsız bakar. Cevap dürüst; anneannenin ihtiyacına uygun bir yol net biçimde önerilmedi."}]},{"konuk":"Tatlıyı aile usulü getirelim; masanın ortasına koyup birbirimize uzatalım.","ingilizce":"Let's have dessert family-style: put it in the middle of the table and pass it around.","secenekler":[{"metin":"Aile usulü servis evlerde olur, bizim restoranda bu şekilde servis yapılmaz.","puan":0,"tepki":"Konuk şaşırır. Aile usulü servis, büyük kapları masanın ortasına koyarak paylaşmaya dayanan geçerli bir servis türüdür."},{"metin":"Olur, aile usulü yapabiliriz; yalnız mutfak her tatlıyı ayrı tabakta hazırlamış olabilir, ona bakmam gerek.","puan":1,"tepki":"Konuk karışır. Önerilen düzen kabul edildi; gerekçe belirsiz kaldı ve konuk bilgilendirilmedi."},{"metin":"Güzel fikir; tatlıyı büyük bir kapta masanın ortasına koyarım, yanına küçük tabaklar bırakırım.","ingilizce":"Lovely idea; I'll put the dessert in a large dish in the middle of the table, with small plates.","puan":2,"tepki":"Konuk sevinir: “Aile gibi olacak.” Aile usulü servis, paylaşmaya dayanır; konuklar kapları birbirine uzatarak kendi tabaklarına alır."}]},{"konuk":"Bir de pasta getirmek istiyoruz. Masayı biraz süsleyebilir miyiz?","ingilizce":"We'd also like to bring a cake. Could we decorate the table a little?","secenekler":[{"metin":"Süsleme bizim işimiz değil, kendiniz getirin.","puan":0,"tepki":"Konuk kaşlarını kaldırır. Özel gün masasını süslemek ve ikramlarla kişiye özel kılmak otelin işidir."},{"metin":"Pastayı getirebilirsiniz, masayı da süsleriz; servis zamanını sizinle netleştirelim.","ingilizce":"You're welcome to bring the cake and we'll decorate the table; let's agree on when to serve it.","puan":2,"tepki":"Konuk teşekkür eder. Özel gün masası süsleme ve kişiye özel ikramla hazırlanır; zamanlamayı konukla konuşmak sürprizi bozmadan düzen sağlar."},{"metin":"Süsleyebiliriz, pastayı da getirebilirsiniz; ayrıntılara o gün yaklaşınca birlikte bakarız.","puan":1,"tepki":"Konuk memnun, fakat endişelidir. Olumlu cevap ayrıntı olmadan güven vermez."}]},{"konuk":"Tamam, siz karar verin. Hepsi yazılı olacak mı?","ingilizce":"All right, you decide. Will everything be in writing?","secenekler":[{"metin":"Notlarımı alırım, o gün ekibe de söylerim; yazılı bir plan gerekirse sonra bakarız.","puan":1,"tepki":"Konuk yetinir, emin olamaz. Not alınmış; konuğa onay için geri dönüş sözü verilmedi."},{"metin":"Elbette. Notlarımı ziyafet amirimize iletiyorum; yazılı planı o size gönderecek.","ingilizce":"Of course. I'm passing my notes to our banquet manager, who will send you the written plan.","puan":2,"tepki":"Konuk rahatlar ve teşekkür eder. Yazılı plan hem konuğun hem ekibin aynı planı bildiğini gösterir; ekip aynı tarzı izlediğinde servis düzenli olur."},{"metin":"Yazıya gerek yok, o günü biz hallederiz.","puan":0,"tepki":"Konuk tedirgin olur. Yazılı plan ekibin ve konuğun beklentilerinin örtüşmesini sağlar; sözle yetinmek hata riskini artırır."}]}]},{"id":"go-d10","unite":4,"baslik":"Odaya Vegan Kahvaltı","rol":"Butler","sahne":"Sabah 07.30, süit katı. Butler, Bayan Nora Eklund’un oda servisi siparişini alıyor; konuk vegan ve süt ürünü, yumurta, bal ya da tereyağı yemiyor. Kahvaltı tepsisi odasına götürülecek.","kavramlar":["go-4-027","go-4-058","go-4-035","go-4-073"],"adimlar":[{"konuk":"Günaydın. Vegan bir kahvaltı rica ediyorum; süt, yumurta, bal ve tereyağı olmasın.","ingilizce":"Good morning. I'd like a vegan breakfast, please: no milk, eggs, honey or butter.","secenekler":[{"metin":"Bal ve tereyağı vejetaryen için uygundur, çok önemli değil.","puan":0,"tepki":"Konuk sertçe düzeltir: “Hayır, vegan.” Vegan yalnız etsiz değildir; süt, yumurta, bal ve tereyağı da yoktur."},{"metin":"Elbette, mutfağa “vegan” notu yazıyorum. Kahvenizi hangi bitkisel sütle istersiniz?","ingilizce":"Of course, I'm adding a 'vegan' note for the kitchen. Which plant-based milk would you like in your coffee?","puan":2,"tepki":"Konuk gülümseyerek yulaf sütünü seçer. Vegan beslenmeyi tanıyıp mutfağa net not yazmak ve bitkisel süt seçeneğini sunmak hazırlıklı olmayı gösterir."},{"metin":"Etsiz bir kahvaltı hazırlatırım; mutfağa kahvaltının et içermemesi gerektiğini söylerim.","puan":1,"tepki":"Konuk tereddüt eder: “Süt ve yumurta yok demiştim.” Vegan ile etsiz aynı değildir."}]},{"konuk":"Biraz bekler misiniz? Henüz hazır değilim.","ingilizce":"Could you wait a moment? I'm not ready yet.","secenekler":[{"metin":"Tepsi soğuyor, ben içeri girip bırakayım.","puan":0,"tepki":"Konuk telaşlanır. Konuğun izni olmadan odaya girilmez; oda onun alanıdır."},{"metin":"Kapıyı aralık bırakıp tepsiyi sessizce içeri koyayım mı? Siz hazırlanırken kahvaltı soğumasın.","puan":1,"tepki":"Konuk şaşırır. Konuk hazır değil dediği hâlde içeri girmeyi önermek özenli görünse de saygısızlıktır; hazır olduğunu konuk kendisi söyler."},{"metin":"Tabii efendim, kapının önünde bekliyorum. Hazır olduğunuzda haber verin.","ingilizce":"Of course, madam. I'll wait outside the door. Please let me know when you're ready.","puan":2,"tepki":"Konuk teşekkür eder ve birkaç dakika sonra seslenir. Oda servisinde konuk izin vermeden içeri girilmez, bekleme saygıdır."}]},{"konuk":"Bu vegan mı? Tereyağına benziyor, ama etiketi yok.","ingilizce":"Is this vegan? It looks like butter, but it has no label.","secenekler":[{"metin":"Mutfağa hemen soruyorum; onay gelene kadar lütfen yemeyin.","ingilizce":"I'm asking the kitchen right now; please don't eat it until it's confirmed.","puan":2,"tepki":"Konuk teşekkür eder. Etiketsiz üründe içerik mutfaktan öğrenilmeden söylenmez; tahmin yerine doğrulamak konuğun inancına ve sağlığına saygıdır."},{"metin":"Bitkisel bir sürülebilir yağa benziyor, yine de kesin söyleyemem.","puan":1,"tepki":"Konuk tedirgin olur. Dürüst bir cevap; yine de emin olunmayan üründe mutfağa sormak gerekir."},{"metin":"Mutfakta bunlar genelde bitkisel yağdır, rahatça yiyebilirsiniz.","puan":0,"tepki":"Konuk rahatlar, oysa bilgi yanlış olabilir. Emin olunmayan içerik hakkında tahmin yürütmek hem inanç hem sağlık riski taşır."}]},{"konuk":"Çayım biraz ılık gelmiş.","ingilizce":"My tea has arrived rather lukewarm.","secenekler":[{"metin":"Oda servisinde çay yolda biraz soğur, normal.","puan":0,"tepki":"Konuk hayal kırıklığına uğrar. Sıcak içecek sıcak, soğuk içecek soğuk sunulmalıdır; yolda soğumak bahane değildir."},{"metin":"İsterseniz mutfağa söyleyeyim; hazır olunca size yeni bir çay getirirler.","puan":1,"tepki":"Konuk kabul eder, ardından beklemek zorunda kalır. Çözüm teklifi var; özür ve hızlı çözüm yok."},{"metin":"Özür dilerim efendim. Hemen sıcak bir demlik getiriyorum.","ingilizce":"I'm sorry, madam. I'll bring a fresh hot pot of tea right away.","puan":2,"tepki":"Konuk gülümser: “Teşekkürler.” Çay gibi içecekler doğru sıcaklıkta sunulmalı; sorunu hemen çözmek ve özür dilemek yemek güvenliğinin bir parçasıdır."}]},{"konuk":"Kahvaltıyı yavaş yiyeceğim.","ingilizce":"I'm going to take my time over breakfast.","secenekler":[{"metin":"Bitirince tepsiyi koridora bırakabilirsiniz, görevlilerimiz gelip alır; afiyet olsun, keyifli kahvaltılar.","puan":1,"tepki":"Konuk kabul eder, koridordaki tepsiyi düşünür. Pratik görünür; boş tepsinin koridorda kalması ise lüks oda servisi standardına uygun değil."},{"metin":"Ne zaman almamızı istersiniz? Size uygun saatte uğrarım, tepsiyi koridora çıkarmayın.","ingilizce":"When would you like us to collect it? I'll come at a time that suits you, so there's no need to put it in the corridor.","puan":2,"tepki":"Konuk memnun gülümser. Toplama saatini konuğa sormak, boş tepsinin koridorda kalmasını önler ve odada rahatlığını korur."},{"metin":"Tepsiyi yarın sabah almaya gelirim.","puan":0,"tepki":"Konuk şaşırır. Gün boyu odada kalan tepsi hem düzensizlik hem hijyen sorunudur."}]}]},{"id":"go-d11","unite":5,"baslik":"Eğitim Salonu İçin Doğru Düzen","rol":"Etkinlik koordinatörü","sahne":"Salı sabahı, otelin satış ofisi. Bir sigorta şirketinin eğitim yöneticisi önümüzdeki ay yapılacak iki günlük bir eğitim için salon ayırtmak istiyor. Düzen, yemek ve kişi sayısı konusunda henüz hiçbir şey kesin değil.","kavramlar":["go-5-009","go-5-011","go-5-012","go-5-015","go-5-017"],"adimlar":[{"konuk":"Merhaba, önümüzdeki ay çalışanlarımıza iki günlük bir eğitim yapacağız. Salonu nasıl hazırlayacaksınız?","ingilizce":"Hello, we're holding a two-day training course for our staff next month. How will you set up the room?","secenekler":[{"metin":"Hoş geldiniz. Önce kaç kişi geleceğini ve eğitimin nasıl yürüyeceğini öğrenebilir miyim?","ingilizce":"Welcome. May I ask how many people are coming and how the training will run?","puan":2,"tepki":"Konuk rahatlar: “Kırk kişiyiz, herkes not tutacak.” Düzen salonun büyüklüğüne göre değil, kişi sayısına ve etkinliğin amacına göre seçilir; bu yüzden önce soru sorulur."},{"metin":"Salonumuz çok geniş, rahatça sığarsınız. Düzeni sonra konuşuruz.","puan":1,"tepki":"Konuk kararsız kalır: “Ama nasıl dizileceğini bilmem gerek.” Salonun büyüklüğü tek başına yetmez; kişi sayısı ve amaç sorulmadan düzen belirlenemez."},{"metin":"Biz her etkinlikte tiyatro düzeni kuruyoruz, size de öyle yaparız.","puan":0,"tepki":"Konuk itiraz eder: “Ama herkes yazı yazacak.” Düzen etkinliğin amacına göre seçilir; tiyatro düzeninde masa olmadığı için yazı yazmak zordur."}]},{"konuk":"Kırk kişiyiz. Herkes not tutacak, bilgisayarlarını da kullanacak.","ingilizce":"There will be forty of us. Everyone will take notes and use their laptops.","secenekler":[{"metin":"Tiyatro düzeni kuralım, oturma düzenleri arasında en çok kişi o düzende sığar.","puan":1,"tepki":"Konuk gülerek karşılık verir: “Sandalyeye sığarız, bilgisayar dizimizde kalır.” Tiyatro düzeni çok kişi sığdırır; masa olmadığı için yazı yazmayı zorlaştırır."},{"metin":"Kokteyl düzeni uygun olur; ayakta daha rahat edersiniz.","puan":0,"tepki":"Konuk şaşırır: “İki gün ayakta mı yazacağız?” Kokteyl düzeni tanışma ve açılış etkinlikleri içindir; çok az masa bulunur, uzun bir eğitime uygun değildir."},{"metin":"O zaman sınıf düzenini öneririm; herkesin önünde bir masa olur.","ingilizce":"Then I'd suggest a classroom-style set-up, so everyone has a table for notes and laptops.","puan":2,"tepki":"Konuk onaylar. Sınıf düzeni sahneye dönük sıralar ve önlerinde masalar demektir; eğitim ve seminerlerde bu yüzden tercih edilir."}]},{"konuk":"İkinci gün on iki kişilik bir atölye çalışması var; herkes tartışacak. Orada ne önerirsiniz?","ingilizce":"On the second day there's a workshop for twelve people, and everyone will want to discuss. What would you suggest there?","secenekler":[{"metin":"Banket düzeni önerelim; tartışmak için salona çok kişi sığar.","puan":0,"tepki":"Konuk şaşırır. Yuvarlak masalı banket düzeni yemek için kurulur ve kişi başına geniş alan ister; bu yüzden aynı salona az kişi sığar."},{"metin":"Küçük grup için U düzeni uygun: herkes hem sunucuyu hem birbirini görür.","ingilizce":"For a small group, a U-shape set-up works well. Everyone can see the presenter and each other, so discussion is easier.","puan":2,"tepki":"Konuk memnun olur. U düzeni tartışma ve atölye çalışması için uygundur; az kişi sığdırdığı için de küçük gruplara önerilir."},{"metin":"Sınıf düzeniyle devam edelim, salonu ikinci gün için baştan düzenlemek hem zaman alır hem zor olur.","puan":1,"tepki":"Konuk kabul eder, bir not da düşer: sıralarda oturanlar birbirinin ensesini görür. Çalışır; tartışma için U düzeni daha uygundur."}]},{"konuk":"Bu konuştuklarımız mutfağa ve teknik ekibinize nasıl ulaşacak? Herkes aynı şeyi bilsin istiyorum.","ingilizce":"How will everything we've discussed reach your kitchen and technical team? I want everyone to know the same thing.","secenekler":[{"metin":"Hepsini etkinlik sipariş formuna (BEO) yazıp onayınızla her departmana dağıtırım.","ingilizce":"I'll put everything in the banquet event order, get your approval and send the same document to every department.","puan":2,"tepki":"Konuk güvenir. BEO bütün bilgiyi tek yazılı belgede toplar; her departman aynı kaynaktan okuduğu için karışıklık çıkmaz."},{"metin":"Mutfağa ve teknik servise sözlü olarak iletirim.","puan":1,"tepki":"Konuk endişelenir: “Yanlış anlaşılırsa?” Sözlü bilgi unutulur ya da değişir; bütün departmanların okuyacağı yazılı bir belge gerekir."},{"metin":"Her departmanla siz ayrı ayrı konuşursanız daha doğru olur.","puan":0,"tepki":"Konuk bozulur: “Ben otelin içinde koordinasyon mu yapacağım?” Her departman başka bilgiyle hazırlanabilir; tek belgeyle koordine etmek otelin işidir."}]},{"konuk":"Öğle yemeğini de sizde yiyeceğiz. Kişi sayısını son güne bırakabilir miyim? Bazıları gelmeyebilir.","ingilizce":"We'll have lunch at your hotel too. Can I leave the final number until the last day? Some people might not come.","secenekler":[{"metin":"Sayıyı mümkün olduğunca erken bildirmeniz iyi olur; kesin kuralı sonra konuşuruz.","puan":1,"tepki":"Konuk not alır, ama kuralı öğrenmez. Garanti sayısının ne zaman ve nasıl bildirileceği baştan, sözleşmeyle söylenmeliydi."},{"metin":"Gelmeyen kişiler için hiçbir ücret almayız, kaç kişi gelmezse gelmesin sorun değil.","puan":0,"tepki":"Konuk sevinir, ama bu yanlış bir söz: garanti sayısı bildirildikten sonra eksik gelenlerin ücreti çoğunlukla ödenir. Yanlış söz sonra anlaşmazlığa yol açar."},{"metin":"Yemekten kısa süre önce kesin, yani garanti sayısını bildirmeniz gerekir; bunu sözleşmeye yazalım.","ingilizce":"You will need to confirm a guaranteed number shortly before the meal; let us put that in the contract.","puan":2,"tepki":"Konuk durumu anlar ve not alır. Garanti sayısı kuralı sözleşmede yazılıdır; mutfak ve servis bu sayıya göre hazırlandığı için baştan konuşulması anlaşmazlığı önler."}]},{"konuk":"Çok aydınlandım, teşekkürler. Bundan sonrası nasıl ilerleyecek?","ingilizce":"That's very helpful, thank you. What happens next?","secenekler":[{"metin":"Şimdilik bir şey yazmayalım, eğitim günü gelince bakarız.","puan":0,"tepki":"Konuk kaygılanır. Yazılı belge olmazsa kimse neyin söz verildiğini bilemez; her şey BEO ve sözleşmede yazılı olmalıdır."},{"metin":"Bugün düzeni ve tarihleri içeren yazılı teklifi e-postanıza göndereceğim.","ingilizce":"I'll email you a written quote today with the set-up and dates.","puan":2,"tepki":"Konuk gülümser ve elini uzatır. Yazılı teklif konuşulanları belgeye bağlar ve müşteriye güven verir."},{"metin":"Yönetimimize durumu iletirim, uygun olduğumuzda size bir geri dönüş yaparız.","puan":1,"tepki":"Konuk ilgisini yitirir: “Ne zaman?” Belirsiz bir söz müşteriyi rakibe yöneltebilir; zamanı ve adımı açıkça söylemek gerekir."}]}]},{"id":"go-d12","unite":5,"baslik":"Kruvaziyerde Kabin Sorusu","rol":"Misafir hizmetleri görevlisi","sahne":"Gemi İstanbul’dan ayrılalı bir gün oldu; yarın Kuşadası’na yanaşacak. İlk kez kruvaziyere binen bir konuk misafir hizmetleri masasına gelip kabiniyle ilgili sorular soruyor.","kavramlar":["go-5-026","go-5-030","go-5-031","go-5-032","go-5-034"],"adimlar":[{"konuk":"Merhaba, iç kabin aldık, ama kabinimizde pencere yok. Bu normal mi?","ingilizce":"Hello, we booked an inside cabin, but there's no window. Is that normal?","secenekler":[{"metin":"Evet, iç kabinler geminin iç bölümünde olduğu için pencere ya da balkonları yoktur.","ingilizce":"Yes, inside cabins are in the inner part of the ship, so they have no window or balcony.","puan":2,"tepki":"Konuk “Anladım” der ve rahatlar. İç kabin dışarıya bakmayan, çoğunlukla en uygun fiyatlı kabin türüdür; nedenini bilmek şaşkınlığı azaltır."},{"metin":"Evet, bu normal; kabinle ilgili ayrıntıları kabin görevlinize de sorabilirsiniz, o yardımcı olur.","puan":1,"tepki":"Konuk başını sallar, yine de sorusunun karşılığını tam bulamamıştır. Bilgi doğru; ilk soruya sıcak ve açıklayıcı yanıt verilmedi, iç kabinin ne olduğu anlatılmadı."},{"metin":"Hayır, bu bir hata. Hemen balkonlu bir kabine geçelim, fark ücreti yok.","puan":0,"tepki":"Konuk umutlanır, sonra hayal kırıklığı yaşar. İç kabinde pencere olmaması hata değildir; üstelik yetki alanının dışındaki bir değişiklik sözü vermek de yanlıştır."}]},{"konuk":"Anladım. Biz kabinde çok vakit geçirmeyiz, ama sabahları dışarıyı görmek isterdik. Başka kabin türleri var mı?","ingilizce":"I see. We don't spend much time in the cabin, but we'd like to see outside in the morning. Are there other cabin types?","secenekler":[{"metin":"Evet, başka kabin türleri de var; ayrıntıları ve fiyatları tam bilmiyorum, kabin görevlisine veya broşüre bakabilirsiniz.","puan":1,"tepki":"Konuk yönlendirilmemiş kalır. Kabin türlerini bilmek bu masanın işinin parçasıdır; ayrıntıyı bilmeyen görevli en azından araştırıp konuğa dönmelidir."},{"metin":"Deniz manzaralı kabinlerin hepsinde balkon vardır, fiyatları da iç kabinle aynıdır; merak etmeyin.","puan":0,"tepki":"Konuk sevinir, ama sonra gerçeği öğrenir. Deniz manzaralı kabinde balkon yoktur, yalnız sabit pencere vardır; fiyatları da farklıdır. Yanlış bilgi güveni bozar."},{"metin":"Deniz manzaralı kabinde sabit bir pencere, balkonlu kabinde kendi balkonunuz var; müsaitliğe bakıp fiyat farkını söyleyeyim.","ingilizce":"A sea-view cabin has a fixed window and a balcony cabin has its own balcony; let me check availability and tell you the price difference.","puan":2,"tepki":"Konuk ilgilenir ve bütçesini düşünmeye başlar. Deniz manzaralı kabinde pencere, balkonlu kabinde dışarı çıkılan bir balkon vardır; farkı doğru anlatmak konuğun karar vermesini kolaylaştırır."}]},{"konuk":"Yarın Kuşadası’nda olacağımızı biliyorum. O gün gemide ve karada neler olur?","ingilizce":"I know we'll be in Kuşadası tomorrow. What happens that day, on board and ashore?","secenekler":[{"metin":"Yarın deniz günü; gemiden hiç inmeyeceksiniz.","puan":0,"tepki":"Konuk şaşırır: “Ama Kuşadası’na yanaşıyoruz!” Liman gününde gemi yanaşır ve konuklar karaya çıkabilir; deniz günü ise hiçbir limana uğranmayan gündür."},{"metin":"Yarın liman günü: gemi yanaşır ve karaya çıkabilirsiniz; gezi bilgisi bu masada.","ingilizce":"Tomorrow is a port day: the ship docks and you can go ashore; you can get excursion information at this desk.","puan":2,"tepki":"Konuk planını yapmaya başlar. Liman gününde konuk karaya çıkar, deniz gününde gemide kalır; gezi bilgileri ve duyurular misafir hizmetleri masasında çözülür."},{"metin":"Yarın liman günü, karaya çıkabilirsiniz; gemide o gün neler olacağını bilmiyorum, programa bakmanız gerekir.","puan":1,"tepki":"Konuk teşekkür eder, bilgi eksik kalır. Gezi bilgisi bu masanın en sık sorulan konularındandır; bilgi ya verilmeli ya da kısa sürede öğrenilmelidir."}]},{"konuk":"Bir de kabin kartım çalışmıyor, kapıyı açamadım.","ingilizce":"One more thing: my cabin card isn't working and I couldn't open the door.","secenekler":[{"metin":"Çok özür dilerim. Hemen yeni kartınızı basıyorum ve kabin görevlimize haber veriyorum.","ingilizce":"I'm very sorry about that. I'll print you a new card right away and let your cabin steward know.","puan":2,"tepki":"Konuk rahatlar ve teşekkür eder. Kabin kartı sorunları bu masada çözülür: görevli yeni kartı basar ve kabin görevlisine haber verir."},{"metin":"Kartı kabin görevlinize götürün, kapınızın yanındaki telefondan da ulaşabilirsiniz; o halleder.","puan":1,"tepki":"Konuk başka bir yere gitmek zorunda kalır. Kart sorunu için gemideki başvuru noktası bu masadır; konuğu yönlendirmek yerine sorunu burada çözmek gerekir."},{"metin":"Kartı yanlış kullanıyorsunuz, herkes açabiliyor.","puan":0,"tepki":"Konuk bozulur. Suçlayıcı ve karşılaştıran bir cevap konuğu savunmaya iter; önce özür dilenir, sonra sorun çözülür."}]},{"konuk":"Teşekkürler, çok yardımcı oldunuz.","ingilizce":"Thank you, you've been very helpful.","secenekler":[{"metin":"Rica ederim, iyi günler dilerim.","puan":1,"tepki":"Konuk teşekkür edip ayrılır. Kısa yanıt kaba değildir, sıcaklık da taşımaz; kapanışta konuğa ulaşabileceği bir kapı açık bırakılır."},{"metin":"Bir daha böyle bir sorun olursa lütfen bize gelmeyin, doğrudan kabin görevlinize söyleyin.","puan":0,"tepki":"Konuk kırılır. Gemide konuğun en sık uğradığı nokta bu masadır; başvuruyu geri çevirmek konukseverliğe aykırıdır."},{"metin":"Rica ederim, iyi yolculuklar; bu masaya her zaman uğrayabilirsiniz.","ingilizce":"You are welcome. Enjoy your cruise; please come back to this desk whenever you need anything.","puan":2,"tepki":"Konuk gülümseyerek ayrılır. Sıcak bir kapanış, konuğa sorununu kolayca iletebileceği hissini verir."}]}]},{"id":"go-d13","unite":5,"baslik":"Uçakta Kalkıştan Önce","rol":"Kabin memuru","sahne":"Kalkışa on beş dakika var ve yolcular yerlerini alıyor. Ekonomi sınıfında ilk kez uçan bir yolcu büyük çantasıyla koridorda duruyor; biniş kartını elinde sıkıyor.","kavramlar":["go-5-040","go-5-041","go-5-043","go-5-045","go-5-046"],"adimlar":[{"konuk":"Merhaba, çantam üstteki dolaba sığmıyor. Ne yapmalıyım?","ingilizce":"Hello, my bag won't fit in the overhead locker. What should I do?","secenekler":[{"metin":"Çantayı şimdilik koridora bırakın, kalkıştan sonra bakarız.","puan":0,"tepki":"Yolcu çantayı bırakır, ama koridor kapanır. Kabin memuru önce güvenliği düşünür; kalkıştan önce yolu tıkayan eşya olamaz."},{"metin":"Önce biletinizdeki kabin bagajı hakkına bakalım; uymuyorsa yer hizmetleriyle çözeriz.","ingilizce":"Let's check your ticket's cabin baggage allowance first; if the bag doesn't meet it, we'll sort it out with the ground team.","puan":2,"tepki":"Yolcu rahatlar. Kabin bagajı kuralları hava yoluna ve bilet türüne göre değişir; önce bilet hakkına bakmak şikâyeti önler."},{"metin":"Çantayı koltuğunuzun altına sıkıştırmayı deneyin, sığmazsa biraz zorlayın; olur biter, kalkışa az kaldı.","puan":1,"tepki":"Yolcu bunu dener, çanta ayak önünü kapatır. Kabin memurunun asıl işi güvenliktir; geçici çözüm yetmez."}]},{"konuk":"Tamam, çantam yer hizmetleriyle çözüldü. Koltuğum 23C, nerede?","ingilizce":"OK, the ground team sorted out my bag. My seat is 23C; where is it?","secenekler":[{"metin":"Biniş kartınıza bakalım, koltuk numaranız orada yazıyor. Sizi yirmi üçüncü sıraya kadar götüreyim.","ingilizce":"Let's look at your boarding pass; your seat number is printed on it. I'll walk you to row 23.","puan":2,"tepki":"Yolcu teşekkür eder. Biniş kartı yolcunun adını, uçuş numarasını ve koltuk bilgisini gösterir; yolcuya eşlik etmek ilk uçuşta güven verir."},{"metin":"Koltuk numaraları üstteki levhalarda yazıyor, sıraların numaralarını okuyun, 23C’yi bulursunuz.","puan":1,"tepki":"Yolcu çaresiz kalır. Yönlendirme doğru; hizmet yok, oysa ilk kez uçan biri için bir adım yürümek çok şey demektir."},{"metin":"Boş bir koltuk bulun, hangisine oturduğunuz fark etmez.","puan":0,"tepki":"Yolcu karışıklık çıkarır. Koltuk numarası biniş kartında yazılıdır; başkasının koltuğuna oturmak karışıklığa yol açar."}]},{"konuk":"Teşekkürler. Business sınıfı daha geniş görünüyor. Oraya geçebilir miyim?","ingilizce":"Thank you. The business class seats look more spacious. Could I move there?","secenekler":[{"metin":"Hayır, olmaz; business koltuğuna geçemezsiniz, lütfen kendi koltuğunuzda oturun.","puan":1,"tepki":"Yolcu bozulur. Cevap doğru; neden açıklanmadı, kısa ve soğuk ret konuğu kırar."},{"metin":"Boş koltuk varsa geçin, kimse görmez.","puan":0,"tepki":"Yolcu geçer, ama sonra sorun çıkar. Sınıf bilete bağlıdır; kuralı esnetmek hem diğer yolcular hem hava yolu için haksızlıktır."},{"metin":"Üzgünüm, koltuğunuz bilet sınıfınıza göre ayrılıyor; business daha geniş ve daha pahalı bir bilettir.","ingilizce":"I'm sorry, your seat depends on your ticket class; business is more spacious and more expensive.","puan":2,"tepki":"Yolcu anlayış gösterir. Yolcu sınıfları bilet türüne göre ayrılır; business sınıfı daha geniş koltuk ve ek ayrıcalık sunan, daha pahalı sınıftır."}]},{"konuk":"İlk kez uçuyorum ve biraz korkuyorum. Acil bir durum olursa ne olur?","ingilizce":"It's my first flight and I'm a bit nervous. What happens in an emergency?","secenekler":[{"metin":"Merak etmeyin, her şey yolunda.","puan":1,"tepki":"Yolcu kısa bir an rahatlar, korkusu yerinde durur. Güven verici bir cümle yetmez; acil durum bilgisi hiç anlatılmadı."},{"metin":"Endişelenmeyin; kalkıştan önce kemeri, oksijen maskesini ve acil çıkışları göstereceğiz.","ingilizce":"Don't worry; before take-off we'll show you the seat belt, the oxygen mask and the emergency exits.","puan":2,"tepki":"Yolcu derin bir nefes alır. Kabin memurunun asıl görevi güvenliktir; gösterinin neleri kapsadığını anlatmak yolcuyu sakinleştirir."},{"metin":"Her şey yolunda, hiç düşünmeyin; gösteriyi izlemenize de gerek yok.","puan":0,"tepki":"Yolcu biraz rahatlar, gösteriyi atlar. Güvenlik gösterisi herkesin izlemesi gereken bir bilgidir; yolcuyu rahatlatmak için atlanamaz."}]},{"konuk":"Havalandık! Bir içecek alabilir miyim, bir de battaniye?","ingilizce":"We're airborne! Could I have a drink and a blanket, please?","secenekler":[{"metin":"Tabii, hemen getiriyorum. Ne içmek istersiniz?","ingilizce":"Of course, I'll bring them right away. What would you like to drink?","puan":2,"tepki":"Yolcu gülümser. Güvenlik sağlandıktan sonra ikram ve rahatlık kabin memurunun işidir; nazik ve hızlı hizmet uçuşu güzelleştirir."},{"metin":"Servis arabası sizin sıranıza gelince içeceğinizi getiririm, battaniye için de biraz bekleyin.","puan":1,"tepki":"Yolcu bekler, kendini ihmal edilmiş hisseder. Sıraya uymak doğru; sıcak bir açıklama ve süre bilgisi eksik kaldı."},{"metin":"Bu kadar çok istekle ilgilenemem, başka yolcuyla konuşun.","puan":0,"tepki":"Yolcu üzülür. Kabin memuru ikramdan sorumludur; küçük bir isteği geri çevirmek konuk iletişimine aykırıdır."}]},{"konuk":"Uçuş çok rahattı, teşekkürler. İniyoruz sanırım.","ingilizce":"The flight was very comfortable, thank you. I think we're landing.","secenekler":[{"metin":"Rica ederim, inerken ayağınıza ve el bagajınıza dikkat edin; iyi günler.","puan":1,"tepki":"Yolcu teşekkür eder. Güvenlik uyarısı yerinde; vedada sıcaklık eksik kaldı."},{"metin":"Koltuğunuzu boşaltın ve çabuk inin, uçağı temizleyeceğiz.","puan":0,"tepki":"Yolcu bozulur. Yolcuyu acele ettirmek kabalıktır; vedayı sıcak yapmak mesleğin parçasıdır."},{"metin":"Biz teşekkür ederiz. Sizi tekrar aramızda görmek isteriz; iyi günler dileriz.","ingilizce":"Thank you. We'd love to welcome you on board again; have a lovely day.","puan":2,"tepki":"Yolcu mutlu ayrılır. Sıcak bir veda, ilk uçuş deneyimini olumlu bir anıya çevirir."}]}]},{"id":"go-d14","unite":5,"baslik":"Gece Yarısı Havalimanı Karşılaması","rol":"Konuk ilişkileri görevlisi","sahne":"Gece 02.00, havalimanı varış salonu. Otel adına karşılamaya gelen görevli konuğun adının yazılı olduğu tabelayı tutuyor. Konuğun uçuşu üç saat gecikti; resepsiyon uçuşu baştan beri izliyordu.","kavramlar":["go-5-055","go-5-056"],"adimlar":[{"konuk":"Merhaba, ben Bay Carter. Uçak üç saat gecikti, çok yorgunum.","ingilizce":"Hello, I'm Mr Carter. The flight was three hours late and I'm exhausted.","secenekler":[{"metin":"Uçuşunuzun geciktiğini bilmiyordum, şoförü şimdi arıyorum.","puan":0,"tepki":"Bay Carter kaşlarını çatar: “Bu saatte beklemek mi?” Uçuş numarasından gecikmeyi izlemek ve şoföre bildirmek transfer koordinasyonunun parçasıdır."},{"metin":"Hoş geldiniz Bay Carter, geçmiş olsun; uçuşunuzu takip ediyorduk, sizi bekliyorduk.","ingilizce":"Welcome, Mr Carter, I'm sorry about the delay; we were tracking your flight, so we've been expecting you.","puan":2,"tepki":"Bay Carter’ın yüzü yumuşar. Resepsiyon uçuş saatini izlediği için transfer yeni saate göre hazır; gecikmeli geceyi sıcak karşılamak büyük fark yaratır."},{"metin":"Hoş geldiniz. Gecikmeler olur, hava yolları hep böyle, ne yapalım; neyse ki sağ salim geldiniz.","puan":1,"tepki":"Bay Carter başını sallar. Cümle nazik görünür, umursamazlık da taşır; yorgun konuk ilgi bekler."}]},{"konuk":"İki büyük valizim var, çok ağırlar.","ingilizce":"I have two big suitcases, and they're very heavy.","secenekler":[{"metin":"Valizlerinizi ben alayım. Bagaj arabasıyla birlikte aracınıza götürelim.","ingilizce":"Let me take your suitcases. We'll take them to your car together on a luggage trolley.","puan":2,"tepki":"Bay Carter minnetle gülümser. Meet & greet hizmeti konuğa bagaj ve araca binme işlemlerinde yardım etmeyi kapsar."},{"metin":"Bagaj arabası şurada, valizlerinizi oraya koyup getirirseniz ben yanınızda yürürüm.","puan":1,"tepki":"Bay Carter arabayı kendisi iter. Karşılama hizmeti yalnız yol göstermek değildir; yorgun konuğun yükünü almak beklenir."},{"metin":"Bagaj taşımak benim işim değil.","puan":0,"tepki":"Bay Carter bozulur. Kişiye özel karşılama bagaj ve araca binme yardımını da içerir; konuk bu anı otelin ilk izlenimi olarak hatırlar."}]},{"konuk":"Aracımız nerede? Çıkışta taksi mi bulacağız?","ingilizce":"Where is our car? Will we find a taxi outside?","secenekler":[{"metin":"Taksi durağı çıkış kapısının hemen yanında, orada kolayca bir taksi bulursunuz.","puan":0,"tepki":"Bay Carter şaşırır: “Bizim transferimiz yoktu mu?” Rezervasyonlu transfer varken konuğu durağa yollamak planlamayı bozar."},{"metin":"Aracınız hazır olmalı, şoförü arayıp nerede beklediğini öğreneyim.","puan":1,"tepki":"Bay Carter beklemeyi kabul eder, içi rahat değildir. Transfer uçuş saatine göre önceden planlanıp izlendiği için araç yeri baştan bilinmelidir."},{"metin":"Özel aracınız çıkışta hazır, şoförünüz bekliyor. Sizi doğrudan oraya götürüyorum.","ingilizce":"Your private car is waiting outside, and your driver is ready. I'll take you straight there.","puan":2,"tepki":"Bay Carter rahat bir nefes alır. Gelen konuğun aracı, şoförü ve zamanı uçuş saatine göre planlanır; konuğun otelle ilk teması çoğu zaman şoförle olur."}]},{"konuk":"Cuma günü dönüş uçuşum var. Beni havalimanına da yine siz götürür müsünüz?","ingilizce":"I fly back on Friday. Will you take me to the airport as well?","secenekler":[{"metin":"Dönüşte karşılama olmaz, taksi bulursunuz.","puan":0,"tepki":"Bay Carter hayal kırıklığına uğrar. Transfer iki yönlüdür ve konuğun uçuşuna göre planlanır; yanlış bilgi vermek güvensizlik yaratır."},{"metin":"Elbette; dönüş uçuş numaranızı ve saatinizi alayım, aracı ona göre planlarız.","ingilizce":"Of course; may I take your return flight number and time? We will plan the car around it.","puan":2,"tepki":"Bay Carter rahatlar. Transfer havalimanından otele olduğu kadar otelden havalimanına da planlanır; uçuş saati değişirse transfer de değişir."},{"metin":"Bunu resepsiyona sorabilirsiniz, dönüş transferleri orada kaydediliyor; onlar bakar.","puan":1,"tepki":"Bay Carter gönülsüzce kabul eder. Konu doğru yere yönlendirildi; konuğun sorusu ise cevapsız kaldı, bilgiyi hemen almak daha iyi olurdu."}]},{"konuk":"Çok teşekkür ederim. Yorgunluğum geçti sayılır.","ingilizce":"Thank you very much. I almost don't feel tired any more.","secenekler":[{"metin":"Rica ederim Bay Carter; resepsiyonumuz sizi bekliyor, iyi geceler.","ingilizce":"My pleasure, Mr Carter; our front desk is expecting you. Good night.","puan":2,"tepki":"Bay Carter gülümseyerek araca biner. Havalimanında başlayan sıcak ilgi otele varmadan ilk izlenimi güzel kılar."},{"metin":"Rica ederim, iyi uykular dilerim; otele varınca resepsiyon sizi karşılar.","puan":1,"tepki":"Bay Carter başını sallar. Nezaket tamam; ad ve içten bir hoş geldiniz olmadığı için gece yarısı karşılamanın sıcaklığı vedada eksik kalır."},{"metin":"Bir dahaki sefere daha erken gelin, beklemek zorunda kalmayalım.","puan":0,"tepki":"Bay Carter kırılır. Gecikme konuğun suçu değildir; suçlayıcı bir veda tüm hizmeti gölgeler."}]}]},{"id":"go-d15","unite":5,"baslik":"Hayalinizdeki Düğün","rol":"Etkinlik koordinatörü","sahne":"Pazartesi öğleden sonra, otelin bahçesi. Londra’da yaşayan bir çift düğün mekânına bakmak için otele gelmiş ve bahçede duruyor. Yakınlarının çoğu yurt dışından gelecek; çift salon, yemek ve kişi sayısı konusunda yönlendirilmeyi bekliyor.","kavramlar":["go-5-013","go-5-014","go-5-015","go-5-017","go-5-023"],"adimlar":[{"konuk":"Merhaba, düğünümüzü sizin bahçenizde yapmak istiyoruz. Yakınlarımızın çoğu yurt dışından gelecek.","ingilizce":"Hello, we'd like to hold our wedding in your garden. Most of our relatives will be travelling from abroad.","secenekler":[{"metin":"Tebrikler. Düğün salonumuzun fiyat listesini ve kapasite bilgilerini hemen e-postayla göndereyim.","puan":1,"tepki":"Çift biraz soğuk karşılar. Fiyat listesi gerekli; ancak önce çiftin hayali ve ihtiyacı dinlenmeli."},{"metin":"Uzaktan gelen düğünlerde organizasyon zor oluyor; başka bir otele bakmanız daha rahat olabilir.","puan":0,"tepki":"Çift terslenmiş hisseder. Destinasyon düğünü otel için günlerce dolu oda ve harcama demektir; müşteriyi geri çevirmek konukseverliğe aykırıdır."},{"metin":"Tebrikler! Ben tek yetkiliniz olarak bütün planı sizinle yürüteceğim; önce hayalinizi dinleyeyim.","ingilizce":"Congratulations! I'll be your single contact for the whole plan; first, tell me about your dream day.","puan":2,"tepki":"Çift rahatlar ve gülümser. Destinasyon düğünü tek geceyle bitmez; tek bir yetkiliyle çalışmak çifte güven verir."}]},{"konuk":"Akşam yemeğini yuvarlak masalarda, öncesinde ise bahçede ayakta bir karşılama istiyoruz.","ingilizce":"We'd like round tables for the dinner, and a standing welcome drink in the garden beforehand.","secenekler":[{"metin":"Bahçedeki kokteyl düzeninde de herkes yuvarlak masalarda oturup yemek yer.","puan":0,"tepki":"Çift şaşırır. Kokteyl düzeninde çok az masa bulunur ve konuklar ayakta dolaşır; yuvarlak masada yemek banket düzenidir."},{"metin":"Güzel plan: bahçede kokteyl düzeniyle tanışırsınız, sonra salonda banket düzeniyle yemek yersiniz.","ingilizce":"Lovely plan: you can mingle in a reception-style set-up in the garden, then dine banquet-style in the hall.","puan":2,"tepki":"Çift onaylar. Kokteyl düzeni ayakta sohbet ve tepsiyle ikram içindir; banket düzeni yuvarlak masalarda yemek içindir ve kişi başına geniş alan ister."},{"metin":"Olur, tanışma da yemek de aynı salonda yuvarlak masalarla yapılır, böylece kimse yer değiştirmek zorunda kalmaz.","puan":1,"tepki":"Çift kabul eder, bahçe karşılaması ise düşer. Çalışır; ayakta tanışma ile yemek farklı düzenlerdir."}]},{"konuk":"Yaklaşık yüz yirmi kişi davet edeceğiz, ama kaç kişinin geleceğini son güne kadar bilemeyiz.","ingilizce":"We'll invite about a hundred and twenty people, but we won't know how many will come until the last day.","secenekler":[{"metin":"Yemekten kısa süre önce garanti sayısını bildirmeniz gerekir; bunu sözleşmeye yazalım.","ingilizce":"You'll need to confirm the guaranteed number shortly before the dinner; let's write that into the contract.","puan":2,"tepki":"Çift durumu anlar. Garanti sayısı baştan konuşulduğu için sonradan anlaşmazlık çıkmaz; mutfak ve servis bu sayıya göre hazırlanır."},{"metin":"Sayıyı yaklaşık söyleyebilirsiniz; kesin sayı kuralını yazılı teklifte netleştiririz.","puan":1,"tepki":"Çift rahatlar; kural ise sonraya kalır. Garanti sayısı baştan konuşulursa düğün günü anlaşmazlık çıkmaz."},{"metin":"Sayı önemli değil, mutfak her zaman fazla hazırlar.","puan":0,"tepki":"Çift sevinir, ama sonra şaşırır. Mutfak garanti sayısına göre hazırlanır; fazla hazırlık israf, eksik hazırlık sorun yaratır."}]},{"konuk":"Müzik, çiçek, menü... Her şeyi kime söylemeliyiz? Herkes aynı şeyi bilsin istiyoruz.","ingilizce":"Music, flowers, the menu... Who should we tell everything to? We want everyone to know the same thing.","secenekler":[{"metin":"Hepsini kendi not defterime yazıyorum, günü yaklaşınca da mutfağa, DJ’e ve çiçekçiye tek tek anlatırım.","puan":1,"tepki":"Çift tereddüt eder. Yazılı ortak belge olmazsa bilgi unutulabilir ya da yanlış aktarılabilir."},{"metin":"Menüyü mutfağa, müziği DJ’e kendiniz söylersiniz.","puan":0,"tepki":"Çift şaşırır: “Biz koordinasyonu mu yapacağız?” Her şeyi tek belgede toplayıp departmanlara dağıtmak otelin işidir."},{"metin":"Hepsini tek bir etkinlik sipariş formuna (BEO) yazarım; onayınızla herkes aynı belgeden çalışır.","ingilizce":"I'll put everything in a single banquet event order; once you approve it, everyone works from the same document.","puan":2,"tepki":"Çift rahat bir nefes alır. BEO bütün bilgiyi tek belgede toplar; herkes aynı kaynaktan okuduğu için kimse yanlış hazırlanmaz."}]},{"konuk":"Çok rahatladık, teşekkürler. Bundan sonrası nasıl ilerleyecek?","ingilizce":"We feel so much better, thank you. What happens next?","secenekler":[{"metin":"Merak etmeyin, hepsi olur. Yazılı bir şeye gerek yok.","puan":0,"tepki":"Çift tedirgin olur. Yazılı belge olmazsa neyin söz verildiği belli olmaz; her şey BEO ve sözleşmede yazılı olmalıdır."},{"metin":"Bahçeyi şimdi birlikte gezelim, sonra yazılı teklifi ve sözleşme taslağını göndereyim.","ingilizce":"Let's walk through the garden together now, and then I'll send you the written quote and draft contract.","puan":2,"tepki":"Çift mutlulukla ayrılır. Yazılı teklif ve sözleşme, konuşulanları belgeye bağlar ve güven verir."},{"metin":"Yönetimimizle konuşup size döneriz, birkaç gün bize zaman verin.","puan":1,"tepki":"Çift ne zaman haber alacağını bilemez. Belirsiz söz müşteriyi rakibe yöneltebilir; zamanı ve adımı açıkça söylemek gerekir."}]}]},{"id":"go-d16","unite":6,"baslik":"Olumsuz Yorum Telefonda","rol":"Konuk ilişkileri görevlisi","sahne":"Perşembe öğleden sonra, konuk ilişkileri masasında telefon çalıyor. Geçen hafta otelde kalan bir konuk odasındaki klimanın bir gün boyunca bozuk kaldığını ve bunu bir yorum sitesine yazdığını söylüyor. Yazdığı yoruma henüz yanıt gelmemiş.","kavramlar":["go-6-028","go-6-029","go-6-042"],"adimlar":[{"konuk":"Merhaba, geçen hafta sizde kaldım. Odamdaki klima bozuktu ve düzelmesi bir gün sürdü. Bunu yorum sitesine yazdım, ama kimse cevap vermedi.","ingilizce":"Hello, I stayed with you last week. The air conditioning in my room was broken and it took a day to fix. I wrote about it on a review site, but nobody has replied.","secenekler":[{"metin":"Bunları yaşadığınız için çok üzgünüm, bize bildirdiğiniz için teşekkür ederim; adınızı alabilir miyim?","ingilizce":"I'm very sorry you went through that, and thank you for letting us know; may I take your name?","puan":2,"tepki":"Konuk sakinleşir ve bilgilerini verir. Önce özür dilemek ve teşekkür etmek eleştiriyi çözüme çeviren ilk adımdır."},{"metin":"Yorumunuzu yöneticimize iletmem için sizi onunla görüştürebilirim, bir dakika bekler misiniz?","puan":1,"tepki":"Konuk sabırla bekler. Yönlendirme yerinde; özür ve ilgi gösterilmeden yapıldığı için konuk dinlenmemiş hisseder."},{"metin":"Yorum sitesine bakmıyorum; klimalar zaman zaman bozulur, bu kadar büyütmeye gerek yok.","puan":0,"tepki":"Konuk öfkelenir: “Beni yalanlıyor musunuz?” Eleştirel konuğa küçümseyici yanıt vermek ve yorumu görmezden gelmek sorunu büyütür; puan bütün bölümlerin ortak karnesidir."}]},{"konuk":"Yorumuma resmî bir cevap yazacak mısınız? Başkaları da okuyacak.","ingilizce":"Will you write an official reply to my review? Other people will read it too.","secenekler":[{"metin":"Yorumunuzu yöneticimize iletirim, ama yanıt yazılıp yazılmayacağını ve ne zaman yazılacağını ben bilemem.","puan":1,"tepki":"Konuk tereddüt eder. Yorumu iletmek doğru adım; süreci konuğa açıkça anlatmak gerekir, belirsiz söz güveni zayıflatır."},{"metin":"Yanıtı ben yazarım: oda numaranızı ve tarihinizi de yazıp ne olduğunu anlatırım.","puan":0,"tepki":"Konuk tedirgin olur. Yanıtı yetkili yazar, çalışan yazmaz; üstelik oda numarası ve tarih gibi kişisel bilgiler herkese açık yanıtta yer almaz."},{"metin":"Yorumunuzu yöneticimize iletiyorum; yanıtı yetkili yöneticimiz yazar, ben süreci takip edeceğim.","ingilizce":"I'm passing your review to our manager; the authorised manager writes the reply, and I'll follow up on the process.","puan":2,"tepki":"Konuk teşekkür eder. Yanıtı yalnız yorumu yazan değil, oteli araştıran herkes okur; yetkili yazar, çalışan yorumu amirine iletir ve kişisel bilgi yazılmaz."}]},{"konuk":"Başkalarının okuyacağı yerde benimle tartışmayacaksınız değil mi?","ingilizce":"You won't argue with me where everyone can read it, will you?","secenekler":[{"metin":"Yorumunuz abartılıysa herkese gerçeği göstermek için sert bir yanıt yazılır.","puan":0,"tepki":"Konuk bozulur. Sert ya da alaycı yanıt, yorumu okuyan herkesin otele güvenini azaltır; saygılı kalmak yanıt kurallarının temelidir."},{"metin":"Hayır; yanıtımızda tartışmak yerine teşekkür eder, özür diler ve çözümü yazarız.","ingilizce":"No; in our reply we'll thank you, apologise and set out the solution rather than argue.","puan":2,"tepki":"Konuk rahatlar. Olumsuz yoruma verilen yanıt saygılı, kısa ve çözüm gösteren olmalıdır; tartışma ya da alay yanıtı okuyan herkesin gözünde oteli küçültür."},{"metin":"Tartışmayız elbette, yalnız otelin de haklı olduğu yerleri açıkça yazıp herkese göstereceğiz.","puan":1,"tepki":"Konuk yeniden gerilir. “Haklı olmak” vurgusu yanıtı savunmaya çevirir; amaç haklılığı kanıtlamak değil, çözümü göstermektir."}]},{"konuk":"Peki bir daha geldiğimde klima yine bozulur mu? Garanti verebilir misiniz?","ingilizce":"And if I come back, will the air conditioning break again? Can you guarantee it won't?","secenekler":[{"metin":"Garanti vermem doğru olmaz; şikâyetinizi teknik servise aktarıyorum, sonucu size bildirecekler.","ingilizce":"It wouldn't be right to guarantee that; I'm passing your complaint to the technical team, and they will let you know the outcome.","puan":2,"tepki":"Konuk dürüst yanıtı takdir eder. Karşılanamayacak söz vermek aşırı vaat tuzağıdır; gerçekçi söz verip sözünden fazlasını vermek güven kazandırır."},{"metin":"Teknik servise sorarım, ancak size dönüş yapabileceğimi şimdiden söylemem mümkün değil.","puan":1,"tepki":"Konuk hayal kırıklığına uğrar. Konuyu aktarmak iyi; sonucun konuğa bildirileceğini söylememek eksik bir ilgidir."},{"metin":"Kesinlikle tekrarlanmaz, bizim odalarımızda klima arızası olmaz, garanti ederim.","puan":0,"tepki":"Konuk bir an sevinir. Karşılanamayacak bir şeyi söylemek aşırı vaat tuzağıdır; olay tekrarlanırsa güven tamamen kaybolur."}]},{"konuk":"Anladım, teşekkürler. Umarım bir dahaki sefere daha iyi olur.","ingilizce":"I see, thank you. I hope it goes better next time.","secenekler":[{"metin":"Rica ederim, geçmiş olsun; umarım bir dahaki ziyaretiniz daha güzel geçer, iyi günler.","puan":1,"tepki":"Konuk telefonu kapatır. Nezaket tamam; sıcaklık az, geri bildirimin değerli olduğu söylenmedi."},{"metin":"Sorunu çözersek yorumu silmenizi veya puanı yükseltmenizi rica ederiz.","puan":0,"tepki":"Konuk rahatsız olur. Çözümün karşılığında yorumun silinmesini istemek baskıdır; amaç konuğu memnun etmektir, yorumu kaldırtmak değil."},{"metin":"Biz teşekkür ederiz, geri bildiriminiz bize çok yardımcı oluyor.","ingilizce":"Thank you; your feedback really helps us.","puan":2,"tepki":"Konuk yumuşar ve telefonu olumlu bir tonda kapatır. Yorumdaki eleştiriye saygılı kalmak otelin puanını ve itibarını korumanın ilk adımıdır."}]}]},{"id":"go-d17","unite":6,"baslik":"Sadakat Programı Üyeliği","rol":"Konuk ilişkileri görevlisi","sahne":"Cuma akşamı, otelin lobisi. Üçüncü kez kalan bir konuk check-out yaparken otelin üyelik programı hakkında bilgi istiyor. Konuk kişisel bilgilerinin nasıl kullanılacağı konusunda da biraz tedirgin.","kavramlar":["go-6-036","go-6-045","go-6-056","go-6-058"],"adimlar":[{"konuk":"Bu otele üçüncü gelişim. Bir üyelik programınız var mı, bir yararı olur mu?","ingilizce":"This is my third stay with you. Do you have a membership programme, and would it benefit me?","secenekler":[{"metin":"Fazla bir yararı yok, rezervasyon yaptırmanız yeter.","puan":0,"tepki":"Konuk şaşırır. Sadakat programı sık gelen konuğu ödüllendirmek içindir; yararsız diye geçiştirmek hem konuğu hem oteli kaybettirir."},{"metin":"Evet, programımız var; konaklama sayınıza ya da harcamanıza göre basamak atlar, ayrıcalıklarınız artar.","ingilizce":"Yes, we do; you move up a tier according to your stays or spending, and your benefits grow.","puan":2,"tepki":"Konuk ilgiyle dinler. Sadakat programı üyeleri konaklama sayısına ya da harcamaya göre basamaklara ayırır; üst basamak daha fazla ayrıcalık demektir."},{"metin":"Var, resepsiyondan formu alıp doldurun, programın nasıl işlediğini sonra kendiniz görürsünüz.","puan":1,"tepki":"Konuk isteksiz kalır. Programın nasıl işlediği anlatılmadan formu doldurtmak, üyeliğin değerini göstermez."}]},{"konuk":"Üye olursam hangi basamaktan başlarım, ayrıcalıklar ne zaman başlar?","ingilizce":"If I join, which tier would I start in, and when do the benefits begin?","secenekler":[{"metin":"Kaydınızla ilk basamaktan başlarsınız; konaklamanıza ve harcamanıza göre yükselirsiniz.","ingilizce":"You start at the first tier when you register, and you move up with your stays and spending.","puan":2,"tepki":"Konuk ilgiyle dinler. Sadakat programında üyeler konaklama sayısına ya da harcamaya göre basamaklara ayrılır; baştan nasıl yükseleceğini bilmek üyeliğin değerini gösterir."},{"metin":"Basamaklar programa göre değişiyor, ayrıntıları internet sitemizden okuyabilirsiniz.","puan":1,"tepki":"Konuk hoşnutsuz kalır. Programın başlangıç koşullarını anlatmak çalışanın işidir; konuğu siteye göndermek ilgisizliktir."},{"metin":"Üyeler arasında basamak farkı yok, herkes aynı ayrıcalıkları alır.","puan":0,"tepki":"Konuk şaşırır. Üye basamakları farklıdır ve üst basamağa daha fazla ayrıcalık tanınır; yanlış bilgi programın amacını ortadan kaldırır."}]},{"konuk":"Üyelik için hangi bilgilerimi vermem gerekir? Sürekli reklam e-postası gelmesini de istemem.","ingilizce":"Which of my details would you need for membership? I also don't want to receive adverts by email all the time.","secenekler":[{"metin":"Üyelik için gerekli bilgileri alırız; e-postayla ilgili ayrıntıyı tam bilmiyorum, forma bakarsınız.","puan":1,"tepki":"Konuk yarım bir yanıt alır. Veri kısmı doğru; e-posta izni baştan sorulmadığı için konuk hâlâ tedirgin kalır."},{"metin":"Hepsini isteriz, e-postayı da otomatik açarız; çıkmak isterseniz kendiniz bulursunuz.","puan":0,"tepki":"Konuk geri çekilir: “Ben izin vermedim.” Gerekenden fazla veri istemek ve tanıtım iznini kendiliğinden açmak açık rıza ve izinli pazarlama ilkelerine aykırıdır."},{"metin":"Yalnız üyelik için gerekli bilgileri alırız; tanıtım e-postası ise ancak siz isterseniz gönderilir.","ingilizce":"We only take the details we need for your membership; promotional emails are sent only if you ask for them.","puan":2,"tepki":"Konuk rahatlar. Gerektiği kadar veri alınır ve tanıtım mesajı yalnız açıkça kabul edene gönderilir; açık rıza bilgilendirilerek ve özgür iradeyle verilen izindir."}]},{"konuk":"Başka bir otelin programında üst basamaktaydım, ama geç çıkış verilmedi. Sizde bu garanti mi?","ingilizce":"At another hotel's programme I was in a higher tier, but they didn't give me a late check-out. Is it guaranteed with you?","secenekler":[{"metin":"Elbette garanti, üye olunca her gelişinizde istediğiniz saatte geç çıkış yaparsınız.","puan":0,"tepki":"Konuk bir an sevinir. Karşılanamayacak söz vermek aşırı vaat tuzağıdır; geç çıkış müsaitliğe bağlıdır ve tutulmayan söz sadık konuğu kırar."},{"metin":"Geç çıkış müsaitliğe bağlıdır, tutamayacağım söz vermem; nasıl işlediğini size yazılı vereyim.","ingilizce":"Late check-out depends on availability and I won't promise what I can't keep; I'll give you in writing how it works.","puan":2,"tepki":"Konuk sakinleşir ve dürüst yanıtı takdir eder. Karşılanamayacak söz vermemek aşırı vaat tuzağından kaçınmaktır; koşulları yazılı vermek beklentiyi netleştirir."},{"metin":"Başka otelin programını bilemem; bizde geç çıkış verilir diye düşünüyorum, kesin değil.","puan":1,"tepki":"Konuk kararsız kalır. Dürüstçe bilmediğini söylemek iyi; ancak koşullar araştırılmadığı için konuğa net bilgi verilmedi."}]},{"konuk":"Tamam, üye olmak istiyorum. Teşekkür ederim.","ingilizce":"All right, I'd like to join. Thank you.","secenekler":[{"metin":"Biz teşekkür ederiz, aramıza hoş geldiniz. Sizi yeniden ağırlamayı dört gözle bekliyoruz.","ingilizce":"Thank you; welcome to our programme. We look forward to welcoming you again.","puan":2,"tepki":"Konuk gülümseyerek ayrılır. Sıcak bir karşılama, üyeliğin ilk gününden güven verir."},{"metin":"Peki, şu formu doldurup resepsiyondaki sepete bırakın, kaydınızı sonra yaparız.","puan":1,"tepki":"Konuk formu doldurur, kendini fazla önemsenmiş hissetmez. Üyeliği teşekkür ve sıcaklıkla başlatmak gerekir."},{"metin":"Üye olmazsanız bir dahaki gelişinizde ayrıcalık veremeyiz, iyi düşünün.","puan":0,"tepki":"Konuk rahatsız olur. Baskıyla üye yapmak izin ilkesine aykırıdır; üyelik özgür iradeyle seçilir."}]}]},{"id":"go-d18","unite":6,"baslik":"Nazik Bir Oda Yükseltme Teklifi","rol":"Rezervasyon görevlisi","sahne":"Salı sabahı, rezervasyon masasında telefon çalıyor. Arayan konuk iki kişilik standart oda ayırtmak istiyor. Görevli konuğa yararlı olacaksa bir üst oda önerebilecek; ama konuğun ihtiyacını öğrenmeden satışa geçmek istemiyor.","kavramlar":["go-6-038","go-6-039","go-6-041","go-6-042","go-6-043"],"adimlar":[{"konuk":"Merhaba, haziranın ilk haftası için iki kişilik standart bir oda ayırtmak istiyorum.","ingilizce":"Hello, I'd like to reserve a standard double room for the first week of June.","secenekler":[{"metin":"Hemen yazıyorum. İsterseniz bir üst odamızı da önereyim, fiyat farkı çok değil.","puan":1,"tepki":"Konuk duraksar: “Neden önerdiniz?” İhtiyaç öğrenilmeden yapılan teklif konuğa yararlı olmayabilir; önce sormak gerekir."},{"metin":"Standart oda yerine doğrudan en üst süitimizi öneririm, herkes onu çok sever.","puan":0,"tepki":"Konuk rahatsız olur. Konuğun ihtiyacını sormadan en pahalıyı satmak konuğa değil, otelin kazancına bakar."},{"metin":"Memnuniyetle yardımcı olurum. Bu seyahat tatil mi, iş mi, yoksa özel bir vesileyle mi?","ingilizce":"I'd be glad to help. Is this trip for leisure, business or a special occasion?","puan":2,"tepki":"Konuk samimiyetle açılır. Satışa geçmeden önce konuğun neden geldiğini sormak doğru odayı önermenin ilk adımıdır."}]},{"konuk":"Evet, yıl dönümümüz. Sakin ve romantik bir şey istiyoruz.","ingilizce":"Yes, it's our anniversary. We'd like something quiet and romantic.","secenekler":[{"metin":"Kutlu olsun! Üst odayı almazsanız yıl dönümü sıradan geçer, kesin almalısınız.","puan":0,"tepki":"Konuk bozulur. Konuğu suçluluğa iten baskılı satış değer katan satış ilkesine aykırıdır."},{"metin":"Yıl dönümünüz kutlu olsun! Çiçek ve deniz manzaralı bir üst oda önerebilirim; farkı söyleyeyim, siz karar verin.","ingilizce":"Happy anniversary! I can suggest flowers and a sea-view upgrade; let me tell you the difference, and you decide.","puan":2,"tepki":"Konuk gülümser. Yıl dönümü gibi bir vesile, çiçek ve üst oda gibi ek önerilerin en uygun anıdır; teklif ihtiyaca uyar ve karar konuğa bırakılır."},{"metin":"Kutlu olsun. Bence standart oda size yeter, üst oda için fazla para vermenize gerek yok, değil mi?","puan":1,"tepki":"Konuk kısa cevap verir. Teklif yapılmadı, konuğun ihtiyacına uygun bir değer de eklenmedi; fırsat kaçtı."}]},{"konuk":"Üst odanın fiyat farkı ne kadar olur? Sonradan ek ücret çıkar mı?","ingilizce":"How much more is the higher room? Will there be extra charges later?","secenekler":[{"metin":"Sistemden hemen bakıyorum; fark ve ek ücretler dâhil toplamı şimdi söyleyeyim.","ingilizce":"Let me check the system right now; I'll tell you the difference and the full total, extra charges included, straight away.","puan":2,"tepki":"Konuk güvenle başını sallar. Fiyat şeffaflığı konuğun ödeyeceği toplam bedeli ek ücretler dâhil rezervasyondan önce görmesidir."},{"metin":"Oda farkını söyleyebilirim, ek ücretlerden emin değilim; onları ayrıca sorarsınız.","puan":1,"tepki":"Konuk tedirgin kalır. Fark söylendi; toplam bedel, ek ücretler dâhil, rezervasyondan önce açıkça söylenmediği için güven eksik kalır."},{"metin":"Fiyat farkı fazla değil, ek ücretleri ödeme adımında görürsünüz.","puan":0,"tepki":"Konuk kandırılmış hisseder. Sonradan görülen ücret güveni kırar ve yorumlarda sık yazılan öfke nedenlerindendir; toplam bedel rezervasyondan önce açıkça söylenmelidir."}]},{"konuk":"Üst odanın balkonundan deniz tam görünüyor mu, yoksa yandan mı?","ingilizce":"From the balcony of the higher room, is the sea fully visible or only from the side?","secenekler":[{"metin":"Kayıtta deniz manzaralı yazıyor, balkondan tam göründüğünü sanıyorum, kesin bir şey söyleyemem.","puan":1,"tepki":"Konuk yine de tedirgin kalır. Tahmin bilgi yerine geçmez; emin olunmayan konuda amire danışmak gerekir."},{"metin":"Deniz tam karşınızda, sanki plajın içindesiniz; balkondan her şey harika görünür!","puan":0,"tepki":"Konuk heyecanlanır, sonra odayı görünce hayal kırıklığı yaşayabilir. Gerçekte karşılanamayacak bir şey söylemek aşırı vaattir ve şikâyete yol açar."},{"metin":"Bu ayrıntıdan emin değilim, söz vermek istemem; yöneticime danışıp doğru bilgiyi vereyim.","ingilizce":"I'm not sure about that detail, and I don't want to promise something I can't confirm. Let me ask my manager and give you the correct information.","puan":2,"tepki":"Konuk dürüstlüğü takdir eder. Emin olunmayan bir özellik için söz vermemek aşırı vaat tuzağından kaçınmanın yoludur; amire danışılır."}]},{"konuk":"Anladım. O zaman şimdilik standart oda kalsın, bütçemiz sınırlı.","ingilizce":"I see. Then let's keep the standard room for now; our budget is limited.","secenekler":[{"metin":"Bir kez daha düşünün; üst odayı almazsanız pişman olabilirsiniz.","puan":0,"tepki":"Konuk bunalır. Konuk “hayır” dediğinde ısrar etmek satışı bozar ve güveni yok eder."},{"metin":"Çiçek isterseniz fiyatıyla birlikte söyleyeyim, yoksa yalnız odanızı ayırıyorum.","ingilizce":"If you'd like flowers I'll tell you the price, otherwise I'll simply book your room.","puan":2,"tepki":"Konuk teşekkür eder. Konuk hayır derse ısrar edilmez; oda aynı güler yüzle ayrılır, çiçek ise fiyatıyla birlikte ve karar konuğa bırakılarak sunulur."},{"metin":"Peki, standart oda yazıldı; rezervasyon onayınız e-postanıza gelecek, iyi günler dilerim.","puan":1,"tepki":"Konuk teşekkür eder, sıcaklık eksik kalır. Rezervasyon doğru yapıldı; çiçek konusu ve içten bir kapanış unutuldu."}]}]},{"id":"go-d19","unite":6,"baslik":"Doğrudan mı, Aracı Platform mu?","rol":"Rezervasyon görevlisi","sahne":"Çarşamba günü öğleden sonra, rezervasyon hattı. Bir konuk oteli aracı bir platformda gördüğünü, ama doğrudan rezervasyon yapmak mı daha iyi diye karar veremediğini söylüyor. Otelin kendi sitesi konuğun telefonunda yavaş açılmış.","kavramlar":["go-6-004","go-6-021","go-6-022","go-6-043"],"adimlar":[{"konuk":"Merhaba, otelinizi bir aracı platformda buldum. Sizden doğrudan rezervasyon yapmakla arasında bir fark var mı?","ingilizce":"Hello, I found your hotel on an intermediary platform. Is there a difference between booking through you directly and through them?","secenekler":[{"metin":"İki yoldan da yapabilirsiniz; doğrudan rezervasyonda otel komisyon ödemez ve sizinle biz ilgileniriz.","ingilizce":"You can book either way; when you book directly, the hotel pays no commission and we look after you ourselves.","puan":2,"tepki":"Konuk rahatlar. Otelin kendi satış kanalı olan doğrudan rezervasyonda aracı komisyonu yoktur; ama aracılar da otelin satış kanallarındandır, bu yüzden dürüst anlatmak gerekir."},{"metin":"Aslında büyük bir fark yok, ikisi de aynı konaklama; hangisinden isterseniz oradan yapın, sonuç değişmez.","puan":1,"tepki":"Konuk kararsız kalır. Konuk için fark küçük olabilir; otel için doğrudan rezervasyonda komisyon ödenmez ve bunu bilmek konuğun kararına yardım eder."},{"metin":"O platform pek güvenilir değil, oradan hiç rezervasyon yapmasanız daha iyi.","puan":0,"tepki":"Konuk şaşırır. Aracı platformlar otelin satış kanallarındandır; kanalı karalamak yanlış ve haksız bir yargıdır."}]},{"konuk":"Platformdaki fiyatla sizin sitedeki fiyat aynı mı?","ingilizce":"Is the price on the platform the same as the one on your website?","secenekler":[{"metin":"Fiyatlar sitemizde yazıyor, oraya bakıp platformdakiyle kendiniz karşılaştırırsınız.","puan":1,"tepki":"Konuk isteksiz kalır. Yön doğru; konuğun sorusu cevapsız kaldı, oysa telefonda bilgi vermek hizmetin parçasıdır."},{"metin":"Bizim sitemiz her zaman en ucuzdur, platformdakinden daha ucuza alırsınız, bakmanıza gerek yok, garanti ederim.","puan":0,"tepki":"Konuk ikna olur, ama sonra karşılaştırır. Doğrulanamayacak bir fiyat vaadi aşırı vaattir; kanallar arasında bilgi tutarlı olmalıdır."},{"metin":"Kanallar arasında farklı bilgi vermemeye özen gösteririz; toplam bedeli ek ücretler dâhil söyleyeyim.","ingilizce":"We take care not to give different information across channels; let me tell you the total including any extra charges.","puan":2,"tepki":"Konuk memnun olur. Konuk hangi kanala bakarsa baksın aynı bilgiyi görmelidir; fiyat şeffaflığı toplam bedelin ek ücretler dâhil baştan görülmesidir."}]},{"konuk":"Sitenizi açtım, ama telefonumda çok yavaş çalıştı, rezervasyonu yarım bıraktım.","ingilizce":"I opened your website, but it was very slow on my phone, so I gave up halfway through the booking.","secenekler":[{"metin":"Sitemiz mükemmel çalışıyor, telefonunuzun interneti zayıf olabilir; tekrar deneyin.","puan":0,"tepki":"Konuk alınır. Siteyi savunup konuğu haksız çıkarmak, güveni bozar ve rezervasyonu kaybettirir."},{"metin":"Teşekkür ederim, geri bildirimi yöneticime ileteceğim; rezervasyonu şimdi telefonda tamamlayalım.","ingilizce":"Thank you for telling me; I'll pass your feedback to my manager, and let's complete the booking by phone now.","puan":2,"tepki":"Konuk teşekkür eder. Yavaş açılan ya da hata veren site konuğu rezervasyondan vazgeçirir; geri bildirimi iletmek ve konuğu kaybetmemek doğru adımdır."},{"metin":"Rezervasyonu şimdi telefonda birlikte tamamlayalım, sizi yarıda bırakmayalım.","puan":1,"tepki":"Konuk rezervasyonu tamamlar. Konuk kaybedilmedi; yavaş açılan siteyle ilgili geri bildirim ise yöneticiye iletilmedi, sorun başka konukları da vazgeçirecek."}]},{"konuk":"Tamam, telefonda yapalım. Temmuzun ilk haftası için iki yetişkin ve bir çocuğa uygun oda var mı?","ingilizce":"All right, let's do it by phone. Is there a room for two adults and a child in the first week of July?","secenekler":[{"metin":"Bakıyorum; uygun odaları ve her birinin toplam bedelini söyleyeyim, seçtiğinizi hemen ayırırım.","ingilizce":"Let me check; I'll tell you the available rooms and the full price of each, and I'll reserve your choice right away.","puan":2,"tepki":"Konuk ilgiyle dinler. Rezervasyon motoru gibi, uygun odaları fiyatlarıyla sıralamak ve seçileni hemen ayırmak konuğun işini kolaylaştırır."},{"metin":"Tarihleri ve kişi sayısını not alayım, uygun odaları kontrol edip size en kısa sürede e-postayla dönerim.","puan":1,"tepki":"Konuk bekleyeceğini düşünür. Telefonda uygun odaya bakmak mümkünken e-postaya ertelemek, konuğu rakibe yöneltebilir."},{"metin":"Her tarihte boş oda vardır, bakmaya gerek yok.","puan":0,"tepki":"Konuk rahatlar, ama sonra sorun çıkar. Müsaitliğe bakmadan söz vermek çift satışa ve şikâyete yol açar; boş tarihler sistemden görülür."}]},{"konuk":"Harika, teşekkür ederim. Bir dahaki sefere de sizi arayabilir miyim?","ingilizce":"Great, thank you. May I call you again next time?","secenekler":[{"metin":"Tamam, arayabilirsiniz; numaramız sitede yazıyor, rezervasyon yapmak isterseniz bakın.","puan":1,"tepki":"Konuk kısa bir yanıt alır. Kapı açık bırakıldı; sıcaklık yok ve onay bilgisi verilmedi."},{"metin":"Aramak yerine hep platformdan alın, benim işim artıyor.","puan":0,"tepki":"Konuk şaşırır ve kırılır. Konuğu işi artıyor diye geri çevirmek doğrudan kanalın değerini de yok sayar."},{"metin":"Elbette, sizi tekrar ağırlamaktan memnuniyet duyarız; onayınızı e-postanıza gönderiyorum.","ingilizce":"Of course, we'd be delighted to welcome you again; I'm sending your confirmation to your email.","puan":2,"tepki":"Konuk memnun ayrılır. Doğrudan ilişki kuran konuk tekrar gelme olasılığı yüksek bir konuktur; yazılı onay da güveni pekiştirir."}]}]},{"id":"go-d20","unite":1,"baslik":"Oda Yok, Rezervasyon Var","rol":"Resepsiyonist","sahne":"Gece 22.30, otelin resepsiyonu. Bay Daniel Okafor üç gecelik onaylı rezervasyonuyla geliyor; ama otel bu gece iptalleri hesaplayıp fazladan rezervasyon aldığı için sistemde boş oda kalmamış. Nöbetçi müdür binada.","kavramlar":["go-1-036","go-1-037","go-1-039","go-1-066"],"adimlar":[{"konuk":"İyi akşamlar, Daniel Okafor adına üç gece için rezervasyonum var.","ingilizce":"Good evening, I have a reservation for three nights under Daniel Okafor.","secenekler":[{"metin":"Pasaportunuzu ve rezervasyon onayınızı alabilir miyim, işlemlere hemen başlayalım, çok yorgun görünüyorsunuz?","puan":1,"tepki":"Konuk pasaportunu uzatır. İşlem başlar ama selam ve hoş geldiniz atlandığı için ilk izlenim soğuk kalır."},{"metin":"İyi akşamlar Bay Okafor, hoş geldiniz. Rezervasyonunuza hemen bakıyorum, bir dakika lütfen.","ingilizce":"Good evening, Mr Okafor, and welcome. Let me check your reservation right away; one moment, please.","puan":2,"tepki":"Konuk rahatlar. Rezervasyon otel yönetim sisteminde (PMS) aranır; karşılayıp sonra kontrol etmek varış adımının doğru başlangıcıdır."},{"metin":"Bu gece otel dolu, size oda veremeyiz.","puan":0,"tepki":"Konuk şaşırır ve sinirlenir: rezervasyon bile aranmadan verilen kesin ret, konuğu suçlu çıkarır."}]},{"konuk":"Bir sorun mu var? Biraz endişeli görünüyorsunuz.","ingilizce":"Is there a problem? You look a little worried.","secenekler":[{"metin":"Evet efendim, bu gece beklediğimizden fazla konuk var ve odanızı veremiyoruz. Çok özür dilerim; nöbetçi müdürümüzle çözüm bulacağız.","ingilizce":"Yes, I am afraid we have more guests tonight than expected, so we cannot give you your room. I am very sorry; the duty manager and I will find a solution.","puan":2,"tepki":"Konuk hayal kırıklığına uğrar ama dürüstlüğe saygı duyar. Fazla rezervasyon bilinçli bir hesaptır; sorun doğrudan söylenir ve çözüm sözü verilir."},{"metin":"Siz geç kaldınız, odanız başkasına verildi.","puan":0,"tepki":"Konuk öfkelenir: haksız suçlama yapılmıştır. Onaylı rezervasyonu olan konuk geç kalmış sayılmaz; hata otelin."},{"metin":"Biraz yoğunluk var efendim, endişelenmeyin, birazdan her şeyi hallederiz ve size de en kısa sürede haber veririz.","puan":1,"tepki":"Konuk huzursuz bekler. Gerçek söylenmediği için güven zedelenir; fazla rezervasyon yüzünden oda yok, bunu açıkça belirtmek gerekirdi."}]},{"konuk":"Peki ne yapacaksınız? Yarın sabah önemli bir toplantım var.","ingilizce":"So what are you going to do? I have an important meeting tomorrow morning.","secenekler":[{"metin":"Nöbetçi müdürü arıyorum, çözümü o size söyler; lütfen biraz bekleyin.","puan":1,"tepki":"Müdür gelir ama konuk yine bekler. Çözümün ne olduğunu kendisi anlatabilecekken resepsiyonist bilgiyi geri tuttu."},{"metin":"Kendiniz yakında bir otel bulun ve faturayı bana getirin, sonra bakarız.","puan":0,"tepki":"Konuk bozulur: yük konuğa atıldı. Onaylı konuğu başka otele yerleştirmek ve masrafı karşılamak otelin işidir."},{"metin":"Nöbetçi müdürümüzle sizi benzer ya da daha iyi bir otele yerleştiriyoruz; konaklama ve ulaşım masrafı bize ait.","ingilizce":"Together with our duty manager, we will place you in a similar or better hotel, and we will cover your accommodation and transport.","puan":2,"tepki":"Konuk sakinleşir. Konuğu başka otele yerleştirmek ve masrafı üstlenmek bu durumun standart çözümüdür; yönetim kararını nöbetçi müdür verir."}]},{"konuk":"Orası gerçekten bu otelden aşağı değil, değil mi?","ingilizce":"That hotel is not worse than this one, is it?","secenekler":[{"metin":"Daha ucuz bir yer buldum, aşağı yukarı aynı sayılır, siz yine de fazla takılmayın, bir gece zaten.","puan":0,"tepki":"Konuk itiraz eder. Alternatif otel benzer ya da daha iyi olmalıdır; ucuza kaçmak kuralı çiğner."},{"metin":"Aynı sınıfta ya da daha iyisini seçtik, içiniz rahat olsun. Adresi ve ulaşım bilgisini size yazılı vereyim.","ingilizce":"We have chosen one of the same standard or better, so please do not worry. Let me give you the address and travel details in writing.","puan":2,"tepki":"Konuk güveni geri kazanır. Benzer ya da daha iyi seçim sözü yazılı bilgiyle desteklenir."},{"metin":"Bence iyidir, ben içeriyi hiç görmedim.","puan":1,"tepki":"Konuk kararsız kalır. Dürüst ama güven vermez; seçimin ölçütü açıklanmalıydı."}]},{"konuk":"Anlıyorum. Böyle bir durumda bu kadar ilgilendiğiniz için sağ olun.","ingilizce":"I understand. Thank you for taking such good care of me in a situation like this.","secenekler":[{"metin":"Anlayışınız için teşekkür ederim Bay Okafor, sıkıntı için tekrar özür dilerim. İyi geceler.","ingilizce":"Thank you for your understanding, Mr Okafor, and I apologise again for the trouble. Good night.","puan":2,"tepki":"Konuk gülümseyerek ayrılır. Ad, özür ve teşekkürle kapanan veda, sorunlu bir geceyi de iyi bir anıya çevirebilir."},{"metin":"Yorumlarda bu konuyu yazmazsanız çok sevinirim, bizim için çok önemli; iyi geceler.","puan":0,"tepki":"Konuk rahatsız olur: yoruma baskı kurmak etik dışıdır, üstelik özür dilemeyi unutturur."},{"metin":"Rica ederim, iyi geceler, şimdi dinlenin.","puan":1,"tepki":"Konuk teşekkür eder ve çıkar. Veda kibar ama özür ve anlayış için teşekkür eksik."}]}]},{"id":"go-d21","unite":1,"baslik":"Sabah Uçağı, Çift Yazılan Hesap","rol":"Gece denetçisi","sahne":"Gece 01.30, resepsiyon. Bayan Sofia Marin sabah 05.00 uçağına yetişmek için hesabını şimdi görmek istiyor. Gece denetçisi günün hesaplarını kontrol ederken akşam yemeğinin hesaba iki kez işlendiğini fark ediyor.","kavramlar":["go-1-065","go-1-039","go-1-007","go-1-066"],"adimlar":[{"konuk":"Merhaba, sabah beşte uçağım var. Hesabımı şimdi görebilir miyim?","ingilizce":"Hello, my flight is at five this morning. Could I see my bill now?","secenekler":[{"metin":"Merhaba Bayan Marin. Hesabınızı hemen açıyorum, birlikte kontrol edelim.","ingilizce":"Hello, Ms Marin. I am opening your bill now; let us check it together.","puan":2,"tepki":"Konuk rahatlar. Hesabı konukla birlikte gözden geçirmek, hatayı baştan yakalatır."},{"metin":"Gece vardiyasında hesap işlemi yapmıyoruz, sabah bakarsınız.","puan":0,"tepki":"Konuk telaşlanır: erken uçağı olan konuğa işlem reddedilmiştir. Gece denetçisi bu saatlerde de hesaplarla ilgilenir."},{"metin":"Tabii, hesabınızı hemen yazdırıp size veriyorum, sabah erken çıkacağınız için zaman kaybetmeyelim.","puan":1,"tepki":"Konuk hesabı alır. Hız iyi, ama kontrol yapılmadan verilen hesapta hata kalabilir."}]},{"konuk":"Burada akşam yemeği iki kez yazılmış görünüyor.","ingilizce":"It looks as if the dinner has been charged twice.","secenekler":[{"metin":"Siz yanlış hatırlıyorsunuzdur, hesap doğru.","puan":0,"tepki":"Konuk öfkelenir: kontrol edilmeden itiraz edilmiştir. Hataları düzeltmek gece denetçisinin görevidir."},{"metin":"Haklısınız, iki kez işlenmiş. Kontrol etmek benim görevim; hatayı şimdi düzeltiyorum, özür dilerim.","ingilizce":"You are right, it has been entered twice. Checking is my job, so I will correct it now. I am sorry.","puan":2,"tepki":"Konuk rahatlar. Hatayı hemen kabul edip düzeltmek, gece denetçisinin günün hesaplarını doğru kapatma sorumluluğuna uygundur."},{"metin":"Bunu sabah gelen ekibe not edeyim, onlar hesabı düzeltip size e-postayla gönderirler, bu gece yapabileceğim bir şey yok.","puan":1,"tepki":"Konuk sinirlenir: uçağı sabah beşte, ekip ise sabah gelecek. Şimdi yapılabilecek düzeltme bekletilmiş olur."}]},{"konuk":"Düzeltildiğinden nasıl emin olacağım?","ingilizce":"How can I be sure it has been corrected?","secenekler":[{"metin":"Düzeltmeyi yaptım, merak etmeyin, bana güvenebilirsiniz; iki kez bakmama gerek yok.","puan":1,"tepki":"Konuk tam ikna olmaz. Sözle yetinmek yerine yeni hesabı göstermek daha güven verir."},{"metin":"Sistem hata yapmaz, ekranda her şey doğru görünüyor, bence yanlış anlıyorsunuz.","puan":0,"tepki":"Konuk huzursuzlaşır: az önce hata bulundu. Sistem verileri insan girdiği için hata olabilir."},{"metin":"Yeni hesabı yazdırıp satır satır birlikte okuyalım; yemek tek satırda görünecek.","ingilizce":"Let me print the new bill and read it through line by line with you. The dinner will appear only once.","puan":2,"tepki":"Konuk gülümser. Düzeltilmiş hesabı birlikte okumak, doğru çıkışın son kontrolüdür."}]},{"konuk":"Bu sıkıntı için otelden bir jest bekleyebilir miyim?","ingilizce":"Can I expect a goodwill gesture from the hotel for this trouble?","secenekler":[{"metin":"Tamam, size otelden iki gece bedava yazarım.","puan":0,"tepki":"Konuk şaşırır ama söz geçersizdir. Bu tür kararlar yönetimin yetkisindedir; yetkisiz söz vermek zarar getirir."},{"metin":"Anlayışınız için teşekkürler. Karar yetkisi nöbetçi müdürümüzde; durumu hemen kendisine iletiyorum.","ingilizce":"Thank you for your understanding. The duty manager decides on that, and I am informing them straight away.","puan":2,"tepki":"Konuk kabul eder. Yetkisi olmayan personel konuyu karar yetkisi olan nöbetçi müdüre yönlendirir."},{"metin":"Ben böyle bir şey yapamam efendim, sabah yönetime yazılı bir talepte bulunursanız bakarlar.","puan":1,"tepki":"Konuk geri çekilir. Doğru ama kapıyı kapatan cevap; kimin karar vereceği söylenmedi."}]},{"konuk":"Teşekkür ederim, uçağıma yetişmem lazım.","ingilizce":"Thank you, I must catch my flight.","secenekler":[{"metin":"Rica ederim Bayan Marin, hesabınız doğru ve kapalı. Güvenli yolculuklar, yine bekleriz.","ingilizce":"You are welcome, Ms Marin. Your bill is correct and settled. Safe travels, and we hope to see you again.","puan":2,"tepki":"Konuk memnun ayrılır. Hesabın kapandığını söylemek ve adla uğurlamak çıkış aşamasını tamamlar."},{"metin":"İyi yolculuklar, hoşça kalın.","puan":1,"tepki":"Konuk teşekkür eder. Veda kısa ve soğuk; hesap kapanışı belirtilmedi."},{"metin":"Havalimanında geç kalırsanız bizim suçumuz değil.","puan":0,"tepki":"Konuk kızar: ayrılışta kaba söz son izlenim olur."}]}]},{"id":"go-d22","unite":1,"baslik":"Şirket İçin Özel Fiyat","rol":"Rezervasyon görevlisi","karsi":"Şirket asistanı","sahne":"Salı sabahı, rezervasyon hattı. Bir şirketin asistanı Elena Petrova arıyor; şirket çalışanları sık sık şehre geliyor ve yıl boyunca bu otelde kalmak istiyor. Asistan fiyatlar ve rezervasyon yolları konusunda kararsız.","kavramlar":["go-1-030","go-1-034","go-1-032","go-1-026","go-1-031"],"adimlar":[{"konuk":"Merhaba, çalışanlarımız sık sık şehre geliyor. Yıl boyunca kalmak için özel bir fiyat olur mu?","ingilizce":"Hello, our employees visit the city often. Could we have a special rate for the whole year?","secenekler":[{"metin":"Güncel fiyat listemizi e-postayla göndereyim, istediğiniz tarihlere göre kendiniz bakarsınız, sonra tekrar konuşuruz.","puan":1,"tepki":"Asistan listeyi alır, ancak özel fiyat sorusu cevapsız kalır. Kurumsal anlaşma teklif edilmeliydi."},{"metin":"Günaydın. Kurumsal anlaşma yapabiliriz: özel fiyat önceden belirlenir ve yıl boyunca geçerli olur. Ne sıklıkla geliyorlar?","ingilizce":"Good morning. We can set up a corporate rate agreement: a special rate agreed in advance for the whole year. How often do they visit?","puan":2,"tepki":"Asistan ilgilenir. Kurumsal anlaşma tam bu ihtiyacı karşılar; sıklığı sormak teklifi şirkete uyarlamaya yarar."},{"metin":"Bizde özel fiyat uygulaması yok, internet sitemizdeki güncel fiyatlara bakıp oradan ayırtmanız en doğrusu olur.","puan":0,"tepki":"Asistan hayal kırıklığına uğrar: yıl boyu gelen şirkete kurumsal anlaşmayı hiç anlatmamak fırsat kaçırmaktır."}]},{"konuk":"Sitenizde fiyat her gün değişiyor. Bizim fiyatımız da değişecek mi?","ingilizce":"The price on your website changes every day. Will our rate change too?","secenekler":[{"metin":"Sitedeki fiyat talebe göre değişir; buna dinamik fiyatlama denir. Kurumsal fiyat ise sözleşmede önceden belirlenir.","ingilizce":"The website price changes with demand; that is called dynamic pricing. A corporate rate is fixed in advance in the contract.","puan":2,"tepki":"Asistan rahatlar. Dinamik fiyat talep ve doluluğa göre değişir; kurumsal fiyat ise sözleşmeyle önceden belirlenir."},{"metin":"Hayır, sizin fiyatınız da siteyle birlikte her gün değişir, bunu bilmenizde fayda var.","puan":0,"tepki":"Asistan şaşırır: anlaşma anlamını yitirir. Kurumsal fiyat önceden sabitlenir."},{"metin":"Sabit bir fiyat olabilir diye düşünüyorum ama ayrıntıları tam bilmiyorum, müdüre sorarım.","puan":1,"tepki":"Asistan bekler. Dürüst ama eksik; farkı açıklamak güven verirdi."}]},{"konuk":"Bir arkadaşım aynı odayı bir rezervasyon sitesinde daha ucuza görmüş. Neden?","ingilizce":"A friend saw the same room cheaper on a booking website. Why?","secenekler":[{"metin":"Bazen sitelere indirim veririz ama herkese söylemeyiz, bu yüzden fark çıkmış olabilir.","puan":0,"tepki":"Asistan güvenini yitirir. Aynı oda, tarih ve koşulda her kanalda aynı fiyat ilkesine aykırı ve dürüst olmayan bir cevaptır."},{"metin":"Aynı oda, tarih ve koşulda fiyatın her kanalda aynı olması ilkemizdir; buna oran paritesi denir. Hangi tarihleri gördüklerini söylerseniz bakarım.","ingilizce":"The same room, dates and conditions should show the same price on every channel; that is rate parity. Tell me which dates they saw and I will check.","puan":2,"tepki":"Asistan teşekkür eder. Oran paritesi ilkesi açıklanır ve olası farkın araştırılması önerilir."},{"metin":"Rezervasyon sitesi kendi fiyatını koyuyor, bizi ilgilendirmez, isterseniz doğrudan bize yazın.","puan":1,"tepki":"Asistan sorusunun geçiştirildiğini hisseder. Kanallardaki fiyat farkı oteli ilgilendirir."}]},{"konuk":"Peki doğrudan sizden ayırtmak mı, sitelerden mi daha iyi?","ingilizce":"So is it better to book directly with you or through the websites?","secenekler":[{"metin":"İkisi de olur, aslında pek bir fark yok, hangisi size kolay geliyorsa onu kullanın.","puan":1,"tepki":"Asistan karar veremez. Fark vardır: doğrudan rezervasyon aracısızdır."},{"metin":"Siz yine de sitelerden ayırtın, çünkü orada bize komisyon geliyor ve bu bizim için daha kârlı.","puan":0,"tepki":"Asistan şaşırır: komisyonu otel öder, almaz. Bu bilgi yanlıştır."},{"metin":"Doğrudan rezervasyonda aracı olmadığı için otel komisyon ödemez; bu yüzden doğrudan ilişkiyi değerli buluruz.","ingilizce":"With a direct booking there is no intermediary, so the hotel pays no commission. That is why we value direct bookings.","puan":2,"tepki":"Asistan anlar. Aracı kanaldan gelen satışta otel komisyon öder; doğrudan rezervasyon bu bedeli doğurmaz."}]},{"konuk":"Tamam, ikna oldum. Anlaşma taslağını e-postayla gönderir misiniz?","ingilizce":"All right, you have convinced me. Could you email the draft agreement?","secenekler":[{"metin":"Tabii, taslağı e-postanıza hemen gönderiyorum. Sorularınız olursa buradayım; teşekkür ederim Bayan Petrova.","ingilizce":"Of course, I am sending the draft to your email now. If you have any questions, I am here. Thank you, Ms Petrova.","puan":2,"tepki":"Asistan memnun kapatır. Yazılı sözleşme, ad ve açık kapı bırakan kapanış anlaşmayı sağlamlaştırır."},{"metin":"Gönderirim ama bir iki gün sürebilir, yoğunluk var; haftaya bakarsınız.","puan":1,"tepki":"Asistan kabul eder. Olumlu ama sıcaklık ve net bir sonraki adım eksik."},{"metin":"Yazılı bir şey göndermeyiz, sözle anlaşırız; telefonda konuşmak yeterli olur.","puan":0,"tepki":"Asistan geri çekilir: kurumsal anlaşma bir sözleşmedir, yazılı olmalıdır."}]}]},{"id":"go-d23","unite":3,"baslik":"Stajın İlk Sabahı","rol":"Stajyer","karsi":"Süpervizör","sahne":"Sabah 06.45, otelin kahvaltı servisi. Operasyon stajının ilk günü; stajyer üniformasını giymiş, süpervizörün karşısında bekliyor. Süpervizör vardiyayı ve görev dağılımını anlatacak.","kavramlar":["go-3-011","go-3-020","go-3-022","go-3-051"],"adimlar":[{"konuk":"Günaydın, hoş geldin. Bugün benimle çalışacaksın; önce kahvaltı büfesini kuracağız.","ingilizce":"Good morning, welcome. You will work with me today; we will set up the breakfast buffet first.","secenekler":[{"metin":"Günaydın! Ben büfeyi daha önce kurmadım, nasıl yapacağımı bana adım adım gösterir misiniz?","ingilizce":"Good morning! I haven't set up a buffet before. Could you show me step by step?","puan":2,"tepki":"Süpervizör memnun olur: stajyer deneyimli çalışanların gözetiminde öğrenir, bilmediğini söylemek bu yüzden doğru bir başlangıçtır."},{"metin":"Günaydın. Tamam, kurarım.","puan":1,"tepki":"Süpervizör işi bırakır ama stajyerin ne bildiği belli olmaz; yanlış kurulursa düzeltme zamanı kalmayabilir."},{"metin":"Ben büfeyi biliyorum, bana bir şey anlatmanıza gerek yok; siz başka işlerinize bakın, ben hallederim.","puan":0,"tepki":"Süpervizör kaşlarını çatar: stajyer öğrenmek için oradadır, gözetimi reddetmek hem güveni hem öğrenmeyi bozar."}]},{"konuk":"Bir şeyi çözemezsen önce bana gel; vardiyada sorun çıkınca ilk başvurulan kişi benim.","ingilizce":"If you can't sort something out, come to me first. I'm the first person to ask when a problem comes up during the shift.","secenekler":[{"metin":"Tamam, gerekirse sorarım.","puan":1,"tepki":"Süpervizör başını sallar; ama stajyerin hangi durumda geleceği belirsiz kalır, sorun büyüyene kadar beklenebilir."},{"metin":"Anladım, teşekkür ederim. Bir sorun görürsem çözmeye çalışarak zaman kaybetmeden hemen size gelirim.","ingilizce":"Understood, thank you. If I see a problem, I won't waste time trying to fix it alone; I'll come to you straight away.","puan":2,"tepki":"Süpervizör rahatlar: görev dağıtan ve işin akışını izleyen kişiye erken haber vermek, sorunu büyümeden çözmenin yoludur."},{"metin":"Önce kendim çözmeye çalışırım, size ancak iş bozulursa gelirim.","puan":0,"tepki":"Süpervizör uyarır: sorun çıkınca ilk başvurulan kişi süpervizördür; haber vermeyi geciktirmek küçük bir sorunu büyütebilir."}]},{"konuk":"Peynir tabaklarını dizmişsin ama etiketleri ters koymuşsun. Bunu düzeltelim.","ingilizce":"You've arranged the cheese plates, but the labels are the wrong way round. Let's fix that.","secenekler":[{"metin":"Haklısınız, özür dilerim. Hemen düzeltiyorum.","puan":1,"tepki":"Süpervizör düzeltmeyi kabul eder; savunmaya geçilmedi ama hatanın nedeni ve bir daha nasıl önleneceği konuşulmadı."},{"metin":"Etiketler zaten küçük, kimse fark etmez.","puan":0,"tepki":"Süpervizör ciddileşir: geri bildirimi savunmaya geçerek karşılamak, hatadan öğrenme fırsatını kaçırmaktır."},{"metin":"Teşekkürler, fark etmemiştim. Etiketleri düzeltirim; bir dahaki sefere tabakları koymadan önce kontrol ederim.","ingilizce":"Thank you, I hadn't noticed. I'll fix the labels, and next time I'll check them before I put the plates out.","puan":2,"tepki":"Süpervizör gülümser: eleştiriyi savunmadan dinleyip gelişme fırsatına çevirmek, stajyerin en değerli becerisidir."}]},{"konuk":"Güzel, düzelttin. Şimdi bir konuk kahvesini dökmüş; masayı sen mi temizlersin, ben mi bakayım?","ingilizce":"Good, you've fixed it. A guest has spilled their coffee. Would you like to clean the table, or shall I?","secenekler":[{"metin":"Ben temizlerim. Konuğa üzüldüğümüzü söyleyip masayı hızla toparlarım; yeni kahve için size haber veririm.","ingilizce":"I'll clean it. I'll tell the guest we're sorry, tidy the table quickly, and let you know about a fresh coffee.","puan":2,"tepki":"Süpervizör onaylar: stajyer gözetim altında işi alır, sahada gerçekten iş yapar ve bilmediği kararı süpervizöre bırakır."},{"metin":"Siz bakın, ben büfeye devam edeyim.","puan":0,"tepki":"Süpervizör şaşırır: stajyer sahada iş yaparak öğrenmek için oradadır; kendisine açıkça önerilen görevi geri çevirmek bu amaca aykırıdır."},{"metin":"Ben bakarım, hemen bir bezle silerim.","puan":1,"tepki":"Süpervizör başını sallar; iş üstlenilir ama konuğa ne söyleneceği ve yeni kahve konusu düşünülmemiştir."}]},{"konuk":"Vardiya bitti. Bugün nasıl geçti, yarın neyi geliştirmek istersin?","ingilizce":"The shift is over. How did it go, and what would you like to improve tomorrow?","secenekler":[{"metin":"Her şey iyiydi, geliştirmem gereken bir şey yok; ben bu işi zaten biliyorum, yarın da aynı şekilde yaparım.","puan":0,"tepki":"Süpervizör ikna olmaz: bir stajyerin ilk günü hatasız geçmez; geri bildirimi baştan kapatmak öğrenmeyi durdurur."},{"metin":"Çok şey öğrendim. Yarın tabak düzenine ve etiketlere dikkat edeceğim; sizden de geri bildirim isterim.","ingilizce":"I learned a lot. Tomorrow I'll focus on plate arrangement and labelling, and I'd welcome your feedback.","puan":2,"tepki":"Süpervizör memnun kalır: stajyer hatasından öğrendiğini gösteriyor ve geri bildirimi kendisi istiyor; bu, gelişmeye açık olmanın işaretidir."},{"metin":"İyiydi, sağ olun.","puan":1,"tepki":"Süpervizör nazikçe not alır; fakat ne öğrenildiği ve neyin geliştirileceği söylenmediği için gün geri bildirimsiz kapanır."}]}]},{"id":"go-d24","unite":3,"baslik":"Oda Numarasını Sormak","rol":"Resepsiyonist","sahne":"Akşam 20.30, otelin resepsiyonu. Giriş seviyesi görevde çalışan yeni bir resepsiyonist telefona bakıyor. Arayan, otelde kalan bir arkadaşının oda numarasını öğrenmek istiyor.","kavramlar":["go-3-021","go-3-041","go-3-067","go-3-022"],"adimlar":[{"konuk":"İyi akşamlar, arkadaşım Sofia Rossi sizde kalıyor. Oda numarasını söyler misiniz?","ingilizce":"Good evening. My friend Sofia Rossi is staying with you. Could you tell me her room number?","secenekler":[{"metin":"Sofia Hanım 412 numarada, buyurun.","puan":0,"tepki":"Arayan memnun görünür, ama konuğun bilgisini yetkisiz birine vermek gizliliği ihlal eder; kişisel veriler yalnız gerektiği kadar tutulur ve paylaşılmaz."},{"metin":"İyi akşamlar. Konuk bilgisi paylaşamıyorum; isterseniz adınızı ve mesajınızı alayım, bu isimde bir konuğumuz varsa iletirim.","ingilizce":"Good evening. I'm afraid I can't share guest information, but I can take a message and pass it on if we have a guest by that name.","puan":2,"tepki":"Arayan anlayış gösterir: oda numarası verilmeden iletişim kurulur, konuğun gizliliği korunur ve arayan da yardımsız kalmaz."},{"metin":"Üzgünüm, bilgi veremem.","puan":1,"tepki":"Gizlilik korunur ama arayana başka bir yol önerilmediği için iletişim soğuk kalır; konuşmanın amacı arayanı da dinlemektir."}]},{"konuk":"Ama çok acil, onu görmem gerek. Lütfen söyleyin.","ingilizce":"But it's urgent, I really need to see her. Please just tell me.","secenekler":[{"metin":"Ayrıntı veremem ama durumu süpervizörüme aktarıp size geri dönüş yapmasını isteyebilirim; mesajınızı da not ederim.","puan":1,"tepki":"Arayan biraz sakinleşir; süpervizöre başvurmak doğru, ama mesajın hemen iletileceği söylenmediği için aciliyete karşılık yarım kalır."},{"metin":"Anladım, ısrar ettiğinize göre yalnızca kat numarasını söyleyeyim.","puan":0,"tepki":"Arayan bir adım ilerler; gizlilikte kısmi bilgi de bilgidir ve baskıyla verilen küçük bilgi, kuralı çiğnemenin ilk adımıdır."},{"metin":"Aciliyetinizi anlıyorum, ama kurallarımız konuk bilgisini paylaşmamıza izin vermiyor. Mesajınızı hemen ileteyim.","ingilizce":"I understand it's urgent, but our policy doesn't let us share guest details. I'll pass your message on right away.","puan":2,"tepki":"Arayan kabul eder: nazik ama kararlı bir ret hem gizliliği korur hem konuk iletişimini sürdürür."}]},{"konuk":"Peki, şunu iletin: “Lobide seni bekliyorum.” Telefon numaram da şu.","ingilizce":"All right, please pass this on: 'I'm waiting for you in the lobby.' Here is my number too.","secenekler":[{"metin":"Mesajınız “Lobide seni bekliyorum”, numaranız da yanında. Doğru mu? İlgili konuğa şimdi ileteceğim.","ingilizce":"Your message is 'I'm waiting for you in the lobby', with your number. Is that correct? I'll pass it on to the guest now.","puan":2,"tepki":"Arayan rahatlar: mesajı geri okumak, dikkatle dinleyip doğru anlamanın kanıtıdır."},{"metin":"Tamam.","puan":1,"tepki":"Mesaj alınır ama arayan emin olamaz; mesajı tekrarlayıp doğrulamak konukla iletişimde güven verir."},{"metin":"Mesajı aldım. Konuğun kaç gün daha kalacağını size söyleyeyim mi?","puan":0,"tepki":"Arayan fırsatı kaçırmaz: konaklama süresi de konuğun kişisel bilgisidir ve yetkisiz birine sorulmamalıdır."}]},{"konuk":"Teşekkürler. Ben de bir otelde çalışıyorum; konuk bilgisini nasıl koruyorsunuz?","ingilizce":"Thank you. I work in a hotel too. How do you protect guest information?","secenekler":[{"metin":"Bilgileri sistemde tutuyoruz, daha fazlasını bilmiyorum.","puan":1,"tepki":"Arayan dürüst bir yanıt alır ama giriş seviyesinde bile temel ilkeyi bilmek beklenir."},{"metin":"Konuk bilgisi yalnız gerektiği kadar tutulur ve yetkisiz kişilere verilmez; bu yüzden sizden de bilgi vermedim.","ingilizce":"We keep guest information only as far as needed, and we never give it to unauthorised people.","puan":2,"tepki":"Arayan takdir eder: gizliliği kendi cümleleriyle açıklamak mesleki bilgisini gösterir."},{"metin":"Gizli bir şey yok, herkesin bilgisi sistemde duruyor; isteyen gelip bakabilir, biz de engel olmuyoruz.","puan":0,"tepki":"Arayan huzursuz olur: konuk kayıtları yetkisiz kişilere açık değildir; yanlış bilgi vermek hem yanıltıcı hem tehlikelidir."}]},{"konuk":"Çok sağ olun, iyi akşamlar.","ingilizce":"Thank you very much, good evening.","secenekler":[{"metin":"Ben teşekkür ederim, iyi akşamlar! Mesajınızı ilgili konuğa hemen iletiyorum.","ingilizce":"Thank you, good evening! I'm passing your message on to the guest straight away.","puan":2,"tepki":"Arayan memnuniyetle kapatır: yapılacak işi söylemek ve güler yüzlü veda hizmeti tamamlar."},{"metin":"Tamam, hoşça kalın.","puan":0,"tepki":"Arayan soğukluğu fark eder: kısa ve ilgisiz bir kapanış, doğru yapılan işi gölgeler."},{"metin":"Rica ederim. İyi akşamlar dilerim.","puan":1,"tepki":"Konuşma kibar biter; ama mesajın iletileceğini söylemek güven verirdi."}]}]},{"id":"go-d25","unite":3,"baslik":"Çalışmayan Mobil Anahtar","rol":"Resepsiyonist","sahne":"Gece 23.15, otelin resepsiyonu. Konuk, telefonuna gelen mobil anahtarla oda kapısını açamıyor ve resepsiyona geliyor. Yorgun, biraz da gergin.","kavramlar":["go-3-065","go-3-068","go-3-044","go-3-047"],"adimlar":[{"konuk":"Telefondaki anahtar kapıyı açmıyor. Yarım saattir koridordayım!","ingilizce":"The key on my phone won't open the door. I've been in the corridor for half an hour!","secenekler":[{"metin":"Mobil anahtar bazen çalışmaz, bu normal; telefonlarla ilgili bir şey yapamayız, bekleyip tekrar deneyin.","puan":0,"tepki":"Konuk öfkelenir: sorunu normal göstermek ve çözüm aramamak hem duyguyu yok sayar hem hizmeti reddeder."},{"metin":"Çok üzgünüm, sizi yormuş olmalı. Birlikte çözelim; telefonunuzdaki anahtara bakabilir miyim?","ingilizce":"I'm so sorry, that must have been tiring. Let's sort it out together. May I look at the key on your phone?","puan":2,"tepki":"Konuk sakinleşir: önce duyguyu fark etmek, sonra çözümü birlikte aramak duygusal zekânın ve problem çözmenin ilk adımıdır."},{"metin":"Üzgünüm. Bir bakayım.","puan":1,"tepki":"Konuk biraz rahatlar; ama duygusuna karşılık verilmedi ve ne yapılacağı söylenmedi."}]},{"konuk":"Uygulamayı açtım ama “bağlantı yok” yazıyor. Telefonum internete bağlı değil galiba.","ingilizce":"I opened the app but it says 'no connection'. I don't think my phone is online.","secenekler":[{"metin":"Önce telefonunuzun internetini açalım. Olmazsa yeni bir oda kartı hazırlarım, merak etmeyin.","ingilizce":"Let's turn on your phone's data first. If that doesn't work, I'll prepare a new room card, so please don't worry.","puan":2,"tepki":"Konuk güvende hisseder: sakin kalıp önce nedeni anlamak, sonra yedek çözüm sunmak problem çözmenin sırasıdır."},{"metin":"Sorun sizin telefonunuzda, benim yapabileceğim bir şey yok.","puan":0,"tepki":"Konuk haksızlığa uğramış hisseder: sorumluluğu konuğa atmak, çözümü de bırakmaktır."},{"metin":"İnterneti açmayı deneyin, olmazsa kart hazırlarız.","puan":1,"tepki":"Konuk çözüm yolu alır ama sıcak bir ilgi görmez; yorgun konuğa eşlik önerilmedi."}]},{"konuk":"İnternet açıldı ama anahtar hâlâ görünmüyor. Çok yorgunum, yatmak istiyorum.","ingilizce":"My data is on but the key still doesn't show. I'm exhausted and I just want to go to bed.","secenekler":[{"metin":"Kartı hazırlıyorum, birkaç dakika bekleyin.","puan":1,"tepki":"Konuk beklemeyi kabul eder; çözüm var ama yorgun konuğa eşlik önerilmedi, insani ilgi eksik kaldı."},{"metin":"Kartı yarın sabah hazırlarım, bu gece idare edin.","puan":0,"tepki":"Konuk çileden çıkar: sorunu ertelemek konuğu koridorda bırakmak demektir ve hizmet zihniyetine aykırıdır."},{"metin":"Anlıyorum, yorgunsunuz. Yeni kartı şimdi hazırlıyorum ve odanıza kadar eşlik edip kapıyı birlikte deneyelim.","ingilizce":"I understand you're tired. I'm preparing a new card now, and I'll walk you to your room so we can try the door together.","puan":2,"tepki":"Konuk teşekkür eder: teknoloji tıkandığında insan dokunuşu devreye girer ve konuk yalnız bırakılmaz."}]},{"konuk":"Kapı açıldı, sağ olun. Teknoloji bazen işleri zorlaştırıyor.","ingilizce":"The door's open, thank you. Technology makes things harder sometimes.","secenekler":[{"metin":"Rica ederim. Yarın mobil anahtarı sizinle yeniden kurabiliriz; şimdi iyi dinlenmeler dilerim.","ingilizce":"You're welcome. We can set up the mobile key again with you tomorrow. For now, I hope you rest well.","puan":2,"tepki":"Konuk gülümser: mobil anahtar kolaylıktır, ama sorun çıktığında konuğa sıcak davranan insan hizmeti asıl fark yaratır."},{"metin":"Evet, bu yüzden ben mobil anahtarı sevmiyorum.","puan":0,"tepki":"Konuk şaşırır: otelin kullandığı sistemi küçümsemek profesyonel değildir; amaç konuğu rahatlatmaktır."},{"metin":"Rica ederim. İyi geceler.","puan":1,"tepki":"Konuk memnun ayrılır ama sıcaklık sınırlı kalır; mobil anahtarın yarın nasıl düzeltileceği söylenmedi."}]}]}]}]`);export{t};